window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["社会法"] = {"gongyishiyejuanzengfa":[{"i":1,"n":"第一条","txt":"为了鼓励捐赠，规范捐赠和受赠行为，保护捐赠人、受赠人和受益人的合法权益，促进公益事业的发展，制定本法。"},{"i":2,"n":"第二条","txt":"自然人、法人或者其他组织自愿无偿向依法成立的公益性社会团体和公益性非营利的事业单位捐赠财产，用于公益事业的，适用本法。"},{"i":3,"n":"第三条","txt":"本法所称公益事业是指非营利的下列事项："},{"i":4,"n":"第四条","txt":"捐赠应当是自愿和无偿的，禁止强行摊派或者变相摊派，不得以捐赠为名从事营利活动。"},{"i":5,"n":"第五条","txt":"捐赠财产的使用应当尊重捐赠人的意愿，符合公益目的，不得将捐赠财产挪作他用。"},{"i":6,"n":"第六条","txt":"捐赠应当遵守法律、法规，不得违背社会公德，不得损害公共利益和其他公民的合法权益。"},{"i":7,"n":"第七条","txt":"公益性社会团体受赠的财产及其增值为社会公共财产，受国家法律保护，任何单位和个人不得侵占、挪用和损毁。"},{"i":8,"n":"第八条","txt":"国家鼓励公益事业的发展，对公益性社会团体和公益性非营利的事业单位给予扶持和优待。"},{"i":9,"n":"第九条","txt":"自然人、法人或者其他组织可以选择符合其捐赠意愿的公益性社会团体和公益性非营利的事业单位进行捐赠。捐赠的财产应当是其有权处分的合法财产。"},{"i":10,"n":"第十条","txt":"公益性社会团体和公益性非营利的事业单位可以依照本法接受捐赠。"},{"i":11,"n":"第十一条","txt":"在发生自然灾害时或者境外捐赠人要求县级以上人民政府及其部门作为受赠人时，县级以上人民政府及其部门可以接受捐赠，并依照本法的有关规定对捐赠财产进行管理。"},{"i":12,"n":"第十二条","txt":"捐赠人可以与受赠人就捐赠财产的种类、质量、数量和用途等内容订立捐赠协议。捐赠人有权决定捐赠的数量、用途和方式。"},{"i":13,"n":"第十三条","txt":"捐赠人捐赠财产兴建公益事业工程项目，应当与受赠人订立捐赠协议，对工程项目的资金、建设、管理和使用作出约定。"},{"i":14,"n":"第十四条","txt":"捐赠人对于捐赠的公益事业工程项目可以留名纪念；捐赠人单独捐赠的工程项目或者主要由捐赠人出资兴建的工程项目，可以由捐赠人提出工程项目的名称，报县级以上人民政府批准。"},{"i":15,"n":"第十五条","txt":"境外捐赠人捐赠的财产，由受赠人按照国家有关规定办理入境手续；捐赠实行许可证管理的物品，由受赠人按照国家有关规定办理许可证申领手续，海关凭许可证验放、监管。"},{"i":16,"n":"第十六条","txt":"受赠人接受捐赠后，应当向捐赠人出具合法、有效的收据，将受赠财产登记造册，妥善保管。"},{"i":17,"n":"第十七条","txt":"公益性社会团体应当将受赠财产用于资助符合其宗旨的活动和事业。对于接受的救助灾害的捐赠财产，应当及时用于救助活动。基金会每年用于资助公益事业的资金数额，不得低于国家规定的比例。"},{"i":18,"n":"第十八条","txt":"受赠人与捐赠人订立了捐赠协议的，应当按照协议约定的用途使用捐赠财产，不得擅自改变捐赠财产的用途。如果确需改变用途的，应当征得捐赠人的同意。"},{"i":19,"n":"第十九条","txt":"受赠人应当依照国家有关规定，建立健全财务会计制度和受赠财产的使用制度，加强对受赠财产的管理。"},{"i":20,"n":"第二十条","txt":"受赠人每年度应当向政府有关部门报告受赠财产的使用、管理情况，接受监督。必要时，政府有关部门可以对其财务进行审计。"},{"i":21,"n":"第二十一条","txt":"捐赠人有权向受赠人查询捐赠财产的使用、管理情况，并提出意见和建议。对于捐赠人的查询，受赠人应当如实答复。"},{"i":22,"n":"第二十二条","txt":"受赠人应当公开接受捐赠的情况和受赠财产的使用、管理情况，接受社会监督。"},{"i":23,"n":"第二十三条","txt":"公益性社会团体应当厉行节约，降低管理成本，工作人员的工资和办公费用从利息等收入中按照国家规定的标准开支。"},{"i":24,"n":"第二十四条","txt":"公司和其他企业依照本法的规定捐赠财产用于公益事业，依照法律、行政法规的规定享受企业所得税方面的优惠。"},{"i":25,"n":"第二十五条","txt":"自然人和个体工商户依照本法的规定捐赠财产用于公益事业，依照法律、行政法规的规定享受个人所得税方面的优惠。"},{"i":26,"n":"第二十六条","txt":"境外向公益性社会团体和公益性非营利的事业单位捐赠的用于公益事业的物资，依照法律、行政法规的规定减征或者免征进口关税和进口环节的增值税。"},{"i":27,"n":"第二十七条","txt":"对于捐赠的工程项目，当地人民政府应当给予支持和优惠。"},{"i":28,"n":"第二十八条","txt":"受赠人未征得捐赠人的许可，擅自改变捐赠财产的性质、用途的，由县级以上人民政府有关部门责令改正，给予警告。拒不改正的，经征求捐赠人的意见，由县级以上人民政府将捐赠财产交由与其宗旨相同或者相似的公益性社会团体或者公益性非营利的事业单位管理。"},{"i":29,"n":"第二十九条","txt":"挪用、侵占或者贪污捐赠款物的，由县级以上人民政府有关部门责令退还所用、所得款物，并处以罚款；对直接责任人员，由所在单位依照有关规定予以处理；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"在捐赠活动中，有下列行为之一的，依照法律、法规的有关规定予以处罚；构成犯罪的，依法追究刑事责任："},{"i":31,"n":"第三十一条","txt":"受赠单位的工作人员，滥用职权，玩忽职守，徇私舞弊，致使捐赠财产造成重大损失的，由所在单位依照有关规定予以处理；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"本法自1999年9月1日起施行。"}],"junrenbaoxianfa":[{"i":1,"n":"第一条","txt":"为了规范军人保险关系，维护军人合法权益，促进国防和军队建设，制定本法。"},{"i":2,"n":"第二条","txt":"国家建立军人保险制度。"},{"i":3,"n":"第三条","txt":"军人保险制度应当体现军人职业特点，与社会保险制度相衔接，与经济社会发展水平相适应。"},{"i":4,"n":"第四条","txt":"国家促进军人保险事业的发展，为军人保险提供财政拨款和政策支持。"},{"i":5,"n":"第五条","txt":"中国人民解放军军人保险主管部门负责全军的军人保险工作。国务院社会保险行政部门、财政部门和军队其他有关部门在各自职责范围内负责有关的军人保险工作。"},{"i":6,"n":"第六条","txt":"军人依法参加军人保险并享受相应的保险待遇。"},{"i":7,"n":"第七条","txt":"军人因战、因公死亡的，按照认定的死亡性质和相应的保险金标准，给付军人死亡保险金。"},{"i":8,"n":"第八条","txt":"军人因战、因公、因病致残的，按照评定的残疾等级和相应的保险金标准，给付军人残疾保险金。"},{"i":9,"n":"第九条","txt":"军人死亡和残疾的性质认定、残疾等级评定和相应的保险金标准，按照国家和军队有关规定执行。"},{"i":10,"n":"第十条","txt":"军人因下列情形之一死亡或者致残的，不享受军人伤亡保险待遇："},{"i":11,"n":"第十一条","txt":"已经评定残疾等级的因战、因公致残的军人退出现役参加工作后旧伤复发的，依法享受相应的工伤待遇。"},{"i":12,"n":"第十二条","txt":"军人伤亡保险所需资金由国家承担，个人不缴纳保险费。"},{"i":13,"n":"第十三条","txt":"军人退出现役参加基本养老保险的，国家给予退役养老保险补助。"},{"i":14,"n":"第十四条","txt":"军人退役养老保险补助标准，由中国人民解放军总后勤部会同国务院有关部门，按照国家规定的基本养老保险缴费标准、军人工资水平等因素拟订，报国务院、中央军事委员会批准。"},{"i":15,"n":"第十五条","txt":"军人入伍前已经参加基本养老保险的，由地方社会保险经办机构和军队后勤（联勤）机关财务部门办理基本养老保险关系转移接续手续。"},{"i":16,"n":"第十六条","txt":"军人退出现役后参加职工基本养老保险的，由军队后勤（联勤）机关财务部门将军人退役养老保险关系和相应资金转入地方社会保险经办机构，地方社会保险经办机构办理相应的转移接续手续。"},{"i":17,"n":"第十七条","txt":"军人退出现役后参加新型农村社会养老保险或者城镇居民社会养老保险的，按照国家有关规定办理转移接续手续。"},{"i":18,"n":"第十八条","txt":"军人退出现役到公务员岗位或者参照公务员法管理的工作人员岗位的，以及现役军官、文职干部退出现役自主择业的，其养老保险办法按照国家有关规定执行。"},{"i":19,"n":"第十九条","txt":"军人退出现役采取退休方式安置的，其养老办法按照国务院和中央军事委员会的有关规定执行。"},{"i":20,"n":"第二十条","txt":"参加军人退役医疗保险的军官、文职干部和士官应当缴纳军人退役医疗保险费，国家按照个人缴纳的军人退役医疗保险费的同等数额给予补助。"},{"i":21,"n":"第二十一条","txt":"军人退役医疗保险个人缴费标准和国家补助标准，由中国人民解放军总后勤部会同国务院有关部门，按照国家规定的缴费比例、军人工资水平等因素确定。"},{"i":22,"n":"第二十二条","txt":"军人入伍前已经参加基本医疗保险的，由地方社会保险经办机构和军队后勤（联勤）机关财务部门办理基本医疗保险关系转移接续手续。"},{"i":23,"n":"第二十三条","txt":"军人退出现役后参加职工基本医疗保险的，由军队后勤（联勤）机关财务部门将军人退役医疗保险关系和相应资金转入地方社会保险经办机构，地方社会保险经办机构办理相应的转移接续手续。"},{"i":24,"n":"第二十四条","txt":"军人退出现役后参加新型农村合作医疗或者城镇居民基本医疗保险的，按照国家有关规定办理。"},{"i":25,"n":"第二十五条","txt":"国家为随军未就业的军人配偶建立养老保险、医疗保险等。随军未就业的军人配偶参加保险，应当缴纳养老保险费和医疗保险费，国家给予相应的补助。"},{"i":26,"n":"第二十六条","txt":"随军未就业的军人配偶随军前已经参加社会保险的，由地方社会保险经办机构和军队后勤（联勤）机关财务部门办理保险关系转移接续手续。"},{"i":27,"n":"第二十七条","txt":"随军未就业的军人配偶实现就业或者军人退出现役时，由军队后勤（联勤）机关财务部门将其养老保险、医疗保险关系和相应资金转入地方社会保险经办机构，地方社会保险经办机构办理相应的转移接续手续。"},{"i":28,"n":"第二十八条","txt":"随军未就业的军人配偶达到国家规定的退休年龄时，按照国家有关规定确定退休地，由军队后勤（联勤）机关财务部门将其养老保险关系和相应资金转入退休地社会保险经办机构，享受相应的基本养老保险待遇。"},{"i":29,"n":"第二十九条","txt":"地方人民政府和有关部门应当为随军未就业的军人配偶提供就业指导、培训等方面的服务。"},{"i":30,"n":"第三十条","txt":"军人保险基金包括军人伤亡保险基金、军人退役养老保险基金、军人退役医疗保险基金和随军未就业的军人配偶保险基金。各项军人保险基金按照军人保险险种分别建账，分账核算，执行军队的会计制度。"},{"i":31,"n":"第三十一条","txt":"军人保险基金由个人缴费、中央财政负担的军人保险资金以及利息收入等资金构成。"},{"i":32,"n":"第三十二条","txt":"军人应当缴纳的保险费，由其所在单位代扣代缴。"},{"i":33,"n":"第三十三条","txt":"中央财政负担的军人保险资金，由国务院财政部门纳入年度国防费预算。"},{"i":34,"n":"第三十四条","txt":"军人保险基金按照国家和军队的预算管理制度，实行预算、决算管理。"},{"i":35,"n":"第三十五条","txt":"军人保险基金实行专户存储，具体管理办法按照国家和军队有关规定执行。"},{"i":36,"n":"第三十六条","txt":"军人保险基金由中国人民解放军总后勤部军人保险基金管理机构集中管理。"},{"i":37,"n":"第三十七条","txt":"军人保险基金应当专款专用，按照规定的项目、范围和标准支出，任何单位和个人不得贪污、侵占、挪用，不得变更支出项目、扩大支出范围或者改变支出标准。"},{"i":38,"n":"第三十八条","txt":"军队后勤（联勤）机关财务部门和地方社会保险经办机构应当建立健全军人保险经办管理制度。"},{"i":39,"n":"第三十九条","txt":"军队后勤（联勤）机关财务部门应当为军人及随军未就业的军人配偶建立保险档案，及时、完整、准确地记录其个人缴费和国家补助，以及享受军人保险待遇等个人权益记录，并定期将个人权益记录单送达本人。"},{"i":40,"n":"第四十条","txt":"军人保险信息系统由中国人民解放军总后勤部负责统一建设。"},{"i":41,"n":"第四十一条","txt":"中国人民解放军总后勤部财务部门和中国人民解放军审计机关按照各自职责，对军人保险基金的收支和管理情况实施监督。"},{"i":42,"n":"第四十二条","txt":"军队后勤（联勤）机关、地方社会保险行政部门，应当对单位和个人遵守本法的情况进行监督检查。"},{"i":43,"n":"第四十三条","txt":"军队后勤（联勤）机关财务部门和地方社会保险经办机构及其工作人员，应当依法为军队单位和军人的信息保密，不得以任何形式泄露。"},{"i":44,"n":"第四十四条","txt":"任何单位或者个人有权对违反本法规定的行为进行举报、投诉。"},{"i":45,"n":"第四十五条","txt":"军队后勤（联勤）机关财务部门、社会保险经办机构，有下列情形之一的，由军队后勤（联勤）机关或者社会保险行政部门责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分；造成损失的，依法承担赔偿责任："},{"i":46,"n":"第四十六条","txt":"贪污、侵占、挪用军人保险基金的，由军队后勤（联勤）机关责令限期退回，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":47,"n":"第四十七条","txt":"以欺诈、伪造证明材料等手段骗取军人保险待遇的，由军队后勤（联勤）机关和社会保险行政部门责令限期退回，并依法给予处分。"},{"i":48,"n":"第四十八条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"军人退出现役后参加失业保险的，其服现役年限视同失业保险缴费年限，与入伍前和退出现役后参加失业保险的缴费年限合并计算。"},{"i":50,"n":"第五十条","txt":"本法关于军人保险权益和义务的规定，适用于人民武装警察；中国人民武装警察部队保险基金管理，按照中国人民武装警察部队资金管理体制执行。"},{"i":51,"n":"第五十一条","txt":"本法自2012年7月1日起施行。"}],"laodonghetongfa":[{"i":1,"n":"第一条","txt":"为了完善劳动合同制度，明确劳动合同双方当事人的权利和义务，保护劳动者的合法权益，构建和发展和谐稳定的劳动关系，制定本法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的企业、个体经济组织、民办非企业单位等组织（以下称用人单位）与劳动者建立劳动关系，订立、履行、变更、解除或者终止劳动合同，适用本法。"},{"i":3,"n":"第三条","txt":"订立劳动合同，应当遵循合法、公平、平等自愿、协商一致、诚实信用的原则。"},{"i":4,"n":"第四条","txt":"用人单位应当依法建立和完善劳动规章制度，保障劳动者享有劳动权利、履行劳动义务。"},{"i":5,"n":"第五条","txt":"县级以上人民政府劳动行政部门会同工会和企业方面代表，建立健全协调劳动关系三方机制，共同研究解决有关劳动关系的重大问题。"},{"i":6,"n":"第六条","txt":"工会应当帮助、指导劳动者与用人单位依法订立和履行劳动合同，并与用人单位建立集体协商机制，维护劳动者的合法权益。"},{"i":7,"n":"第七条","txt":"用人单位自用工之日起即与劳动者建立劳动关系。用人单位应当建立职工名册备查。"},{"i":8,"n":"第八条","txt":"用人单位招用劳动者时，应当如实告知劳动者工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬，以及劳动者要求了解的其他情况；用人单位有权了解劳动者与劳动合同直接相关的基本情况，劳动者应当如实说明。"},{"i":9,"n":"第九条","txt":"用人单位招用劳动者，不得扣押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。"},{"i":10,"n":"第十条","txt":"建立劳动关系，应当订立书面劳动合同。"},{"i":11,"n":"第十一条","txt":"用人单位未在用工的同时订立书面劳动合同，与劳动者约定的劳动报酬不明确的，新招用的劳动者的劳动报酬按照集体合同规定的标准执行；没有集体合同或者集体合同未规定的，实行同工同酬。"},{"i":12,"n":"第十二条","txt":"劳动合同分为固定期限劳动合同、无固定期限劳动合同和以完成一定工作任务为期限的劳动合同。"},{"i":13,"n":"第十三条","txt":"固定期限劳动合同，是指用人单位与劳动者约定合同终止时间的劳动合同。"},{"i":14,"n":"第十四条","txt":"无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。"},{"i":15,"n":"第十五条","txt":"以完成一定工作任务为期限的劳动合同，是指用人单位与劳动者约定以某项工作的完成为合同期限的劳动合同。"},{"i":16,"n":"第十六条","txt":"劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动者在劳动合同文本上签字或者盖章生效。"},{"i":17,"n":"第十七条","txt":"劳动合同应当具备以下条款："},{"i":18,"n":"第十八条","txt":"劳动合同对劳动报酬和劳动条件等标准约定不明确，引发争议的，用人单位与劳动者可以重新协商；协商不成的，适用集体合同规定；没有集体合同或者集体合同未规定劳动报酬的，实行同工同酬；没有集体合同或者集体合同未规定劳动条件等标准的，适用国家有关规定。"},{"i":19,"n":"第十九条","txt":"劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。"},{"i":20,"n":"第二十条","txt":"劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。"},{"i":21,"n":"第二十一条","txt":"在试用期中，除劳动者有本法第三十九条和第四十条第一项、第二项规定的情形外，用人单位不得解除劳动合同。用人单位在试用期解除劳动合同的，应当向劳动者说明理由。"},{"i":22,"n":"第二十二条","txt":"用人单位为劳动者提供专项培训费用，对其进行专业技术培训的，可以与该劳动者订立协议，约定服务期。"},{"i":23,"n":"第二十三条","txt":"用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。"},{"i":24,"n":"第二十四条","txt":"竞业限制的人员限于用人单位的高级管理人员、高级技术人员和其他负有保密义务的人员。竞业限制的范围、地域、期限由用人单位与劳动者约定，竞业限制的约定不得违反法律、法规的规定。"},{"i":25,"n":"第二十五条","txt":"除本法第二十二条和第二十三条规定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。"},{"i":26,"n":"第二十六条","txt":"下列劳动合同无效或者部分无效："},{"i":27,"n":"第二十七条","txt":"劳动合同部分无效，不影响其他部分效力的，其他部分仍然有效。"},{"i":28,"n":"第二十八条","txt":"劳动合同被确认无效，劳动者已付出劳动的，用人单位应当向劳动者支付劳动报酬。劳动报酬的数额，参照本单位相同或者相近岗位劳动者的劳动报酬确定。"},{"i":29,"n":"第二十九条","txt":"用人单位与劳动者应当按照劳动合同的约定，全面履行各自的义务。"},{"i":30,"n":"第三十条","txt":"用人单位应当按照劳动合同约定和国家规定，向劳动者及时足额支付劳动报酬。"},{"i":31,"n":"第三十一条","txt":"用人单位应当严格执行劳动定额标准，不得强迫或者变相强迫劳动者加班。用人单位安排加班的，应当按照国家有关规定向劳动者支付加班费。"},{"i":32,"n":"第三十二条","txt":"劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，不视为违反劳动合同。"},{"i":33,"n":"第三十三条","txt":"用人单位变更名称、法定代表人、主要负责人或者投资人等事项，不影响劳动合同的履行。"},{"i":34,"n":"第三十四条","txt":"用人单位发生合并或者分立等情况，原劳动合同继续有效，劳动合同由承继其权利和义务的用人单位继续履行。"},{"i":35,"n":"第三十五条","txt":"用人单位与劳动者协商一致，可以变更劳动合同约定的内容。变更劳动合同，应当采用书面形式。"},{"i":36,"n":"第三十六条","txt":"用人单位与劳动者协商一致，可以解除劳动合同。"},{"i":37,"n":"第三十七条","txt":"劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同。劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。"},{"i":38,"n":"第三十八条","txt":"用人单位有下列情形之一的，劳动者可以解除劳动合同："},{"i":39,"n":"第三十九条","txt":"劳动者有下列情形之一的，用人单位可以解除劳动合同："},{"i":40,"n":"第四十条","txt":"有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同："},{"i":41,"n":"第四十一条","txt":"有下列情形之一，需要裁减人员二十人以上或者裁减不足二十人但占企业职工总数百分之十以上的，用人单位提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见后，裁减人员方案经向劳动行政部门报告，可以裁减人员："},{"i":42,"n":"第四十二条","txt":"劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同："},{"i":43,"n":"第四十三条","txt":"用人单位单方解除劳动合同，应当事先将理由通知工会。用人单位违反法律、行政法规规定或者劳动合同约定的，工会有权要求用人单位纠正。用人单位应当研究工会的意见，并将处理结果书面通知工会。"},{"i":44,"n":"第四十四条","txt":"有下列情形之一的，劳动合同终止："},{"i":45,"n":"第四十五条","txt":"劳动合同期满，有本法第四十二条规定情形之一的，劳动合同应当续延至相应的情形消失时终止。但是，本法第四十二条第二项规定丧失或者部分丧失劳动能力劳动者的劳动合同的终止，按照国家有关工伤保险的规定执行。"},{"i":46,"n":"第四十六条","txt":"有下列情形之一的，用人单位应当向劳动者支付经济补偿："},{"i":47,"n":"第四十七条","txt":"经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。"},{"i":48,"n":"第四十八条","txt":"用人单位违反本法规定解除或者终止劳动合同，劳动者要求继续履行劳动合同的，用人单位应当继续履行；劳动者不要求继续履行劳动合同或者劳动合同已经不能继续履行的，用人单位应当依照本法第八十七条规定支付赔偿金。"},{"i":49,"n":"第四十九条","txt":"国家采取措施，建立健全劳动者社会保险关系跨地区转移接续制度。"},{"i":50,"n":"第五十条","txt":"用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。"},{"i":51,"n":"第五十一条","txt":"企业职工一方与用人单位通过平等协商，可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项订立集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。"},{"i":52,"n":"第五十二条","txt":"企业职工一方与用人单位可以订立劳动安全卫生、女职工权益保护、工资调整机制等专项集体合同。"},{"i":53,"n":"第五十三条","txt":"在县级以下区域内，建筑业、采矿业、餐饮服务业等行业可以由工会与企业方面代表订立行业性集体合同，或者订立区域性集体合同。"},{"i":54,"n":"第五十四条","txt":"集体合同订立后，应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。"},{"i":55,"n":"第五十五条","txt":"集体合同中劳动报酬和劳动条件等标准不得低于当地人民政府规定的最低标准；用人单位与劳动者订立的劳动合同中劳动报酬和劳动条件等标准不得低于集体合同规定的标准。"},{"i":56,"n":"第五十六条","txt":"用人单位违反集体合同，侵犯职工劳动权益的，工会可以依法要求用人单位承担责任；因履行集体合同发生争议，经协商解决不成的，工会可以依法申请仲裁、提起诉讼。"},{"i":57,"n":"第五十七条","txt":"经营劳务派遣业务应当具备下列条件："},{"i":58,"n":"第五十八条","txt":"劳务派遣单位是本法所称用人单位，应当履行用人单位对劳动者的义务。劳务派遣单位与被派遣劳动者订立的劳动合同，除应当载明本法第十七条规定的事项外，还应当载明被派遣劳动者的用工单位以及派遣期限、工作岗位等情况。"},{"i":59,"n":"第五十九条","txt":"劳务派遣单位派遣劳动者应当与接受以劳务派遣形式用工的单位（以下称用工单位）订立劳务派遣协议。劳务派遣协议应当约定派遣岗位和人员数量、派遣期限、劳动报酬和社会保险费的数额与支付方式以及违反协议的责任。"},{"i":60,"n":"第六十条","txt":"劳务派遣单位应当将劳务派遣协议的内容告知被派遣劳动者。"},{"i":61,"n":"第六十一条","txt":"劳务派遣单位跨地区派遣劳动者的，被派遣劳动者享有的劳动报酬和劳动条件，按照用工单位所在地的标准执行。"},{"i":62,"n":"第六十二条","txt":"用工单位应当履行下列义务："},{"i":63,"n":"第六十三条","txt":"被派遣劳动者享有与用工单位的劳动者同工同酬的权利。用工单位应当按照同工同酬原则，对被派遣劳动者与本单位同类岗位的劳动者实行相同的劳动报酬分配办法。用工单位无同类岗位劳动者的，参照用工单位所在地相同或者相近岗位劳动者的劳动报酬确定。"},{"i":64,"n":"第六十四条","txt":"被派遣劳动者有权在劳务派遣单位或者用工单位依法参加或者组织工会，维护自身的合法权益。"},{"i":65,"n":"第六十五条","txt":"被派遣劳动者可以依照本法第三十六条、第三十八条的规定与劳务派遣单位解除劳动合同。"},{"i":66,"n":"第六十六条","txt":"劳动合同用工是我国的企业基本用工形式。劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。"},{"i":67,"n":"第六十七条","txt":"用人单位不得设立劳务派遣单位向本单位或者所属单位派遣劳动者。"},{"i":68,"n":"第六十八条","txt":"非全日制用工，是指以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过四小时，每周工作时间累计不超过二十四小时的用工形式。"},{"i":69,"n":"第六十九条","txt":"非全日制用工双方当事人可以订立口头协议。"},{"i":70,"n":"第七十条","txt":"非全日制用工双方当事人不得约定试用期。"},{"i":71,"n":"第七十一条","txt":"非全日制用工双方当事人任何一方都可以随时通知对方终止用工。终止用工，用人单位不向劳动者支付经济补偿。"},{"i":72,"n":"第七十二条","txt":"非全日制用工小时计酬标准不得低于用人单位所在地人民政府规定的最低小时工资标准。"},{"i":73,"n":"第七十三条","txt":"国务院劳动行政部门负责全国劳动合同制度实施的监督管理。"},{"i":74,"n":"第七十四条","txt":"县级以上地方人民政府劳动行政部门依法对下列实施劳动合同制度的情况进行监督检查："},{"i":75,"n":"第七十五条","txt":"县级以上地方人民政府劳动行政部门实施监督检查时，有权查阅与劳动合同、集体合同有关的材料，有权对劳动场所进行实地检查，用人单位和劳动者都应当如实提供有关情况和材料。"},{"i":76,"n":"第七十六条","txt":"县级以上人民政府建设、卫生、安全生产监督管理等有关主管部门在各自职责范围内，对用人单位执行劳动合同制度的情况进行监督管理。"},{"i":77,"n":"第七十七条","txt":"劳动者合法权益受到侵害的，有权要求有关部门依法处理，或者依法申请仲裁、提起诉讼。"},{"i":78,"n":"第七十八条","txt":"工会依法维护劳动者的合法权益，对用人单位履行劳动合同、集体合同的情况进行监督。用人单位违反劳动法律、法规和劳动合同、集体合同的，工会有权提出意见或者要求纠正；劳动者申请仲裁、提起诉讼的，工会依法给予支持和帮助。"},{"i":79,"n":"第七十九条","txt":"任何组织或者个人对违反本法的行为都有权举报，县级以上人民政府劳动行政部门应当及时核实、处理，并对举报有功人员给予奖励。"},{"i":80,"n":"第八十条","txt":"用人单位直接涉及劳动者切身利益的规章制度违反法律、法规规定的，由劳动行政部门责令改正，给予警告；给劳动者造成损害的，应当承担赔偿责任。"},{"i":81,"n":"第八十一条","txt":"用人单位提供的劳动合同文本未载明本法规定的劳动合同必备条款或者用人单位未将劳动合同文本交付劳动者的，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。"},{"i":82,"n":"第八十二条","txt":"用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。"},{"i":83,"n":"第八十三条","txt":"用人单位违反本法规定与劳动者约定试用期的，由劳动行政部门责令改正；违法约定的试用期已经履行的，由用人单位以劳动者试用期满月工资为标准，按已经履行的超过法定试用期的期间向劳动者支付赔偿金。"},{"i":84,"n":"第八十四条","txt":"用人单位违反本法规定，扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者本人，并依照有关法律规定给予处罚。"},{"i":85,"n":"第八十五条","txt":"用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金："},{"i":86,"n":"第八十六条","txt":"劳动合同依照本法第二十六条规定被确认无效，给对方造成损害的，有过错的一方应当承担赔偿责任。"},{"i":87,"n":"第八十七条","txt":"用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。"},{"i":88,"n":"第八十八条","txt":"用人单位有下列情形之一的，依法给予行政处罚；构成犯罪的，依法追究刑事责任；给劳动者造成损害的，应当承担赔偿责任："},{"i":89,"n":"第八十九条","txt":"用人单位违反本法规定未向劳动者出具解除或者终止劳动合同的书面证明，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。"},{"i":90,"n":"第九十条","txt":"劳动者违反本法规定解除劳动合同，或者违反劳动合同中约定的保密义务或者竞业限制，给用人单位造成损失的，应当承担赔偿责任。"},{"i":91,"n":"第九十一条","txt":"用人单位招用与其他用人单位尚未解除或者终止劳动合同的劳动者，给其他用人单位造成损失的，应当承担连带赔偿责任。"},{"i":92,"n":"第九十二条","txt":"违反本法规定，未经许可，擅自经营劳务派遣业务的，由劳动行政部门责令停止违法行为，没收违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得的，可以处五万元以下的罚款。"},{"i":93,"n":"第九十三条","txt":"对不具备合法经营资格的用人单位的违法犯罪行为，依法追究法律责任；劳动者已经付出劳动的，该单位或者其出资人应当依照本法有关规定向劳动者支付劳动报酬、经济补偿、赔偿金；给劳动者造成损害的，应当承担赔偿责任。"},{"i":94,"n":"第九十四条","txt":"个人承包经营违反本法规定招用劳动者，给劳动者造成损害的，发包的组织与个人承包经营者承担连带赔偿责任。"},{"i":95,"n":"第九十五条","txt":"劳动行政部门和其他有关主管部门及其工作人员玩忽职守、不履行法定职责，或者违法行使职权，给劳动者或者用人单位造成损害的，应当承担赔偿责任；对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":96,"n":"第九十六条","txt":"事业单位与实行聘用制的工作人员订立、履行、变更、解除或者终止劳动合同，法律、行政法规或者国务院另有规定的，依照其规定；未作规定的，依照本法有关规定执行。"},{"i":97,"n":"第九十七条","txt":"本法施行前已依法订立且在本法施行之日存续的劳动合同，继续履行；本法第十四条第二款第三项规定连续订立固定期限劳动合同的次数，自本法施行后续订固定期限劳动合同时开始计算。"},{"i":98,"n":"第九十八条","txt":"本法自2008年1月1日起施行。"}],"laodongfa":[{"i":1,"n":"第一条","txt":"为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。"},{"i":3,"n":"第三条","txt":"劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。"},{"i":4,"n":"第四条","txt":"用人单位应当依法建立和完善规章制度，保障劳动者享有劳动权利和履行劳动义务。"},{"i":5,"n":"第五条","txt":"国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。"},{"i":6,"n":"第六条","txt":"国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。"},{"i":7,"n":"第七条","txt":"劳动者有权依法参加和组织工会。"},{"i":8,"n":"第八条","txt":"劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。"},{"i":9,"n":"第九条","txt":"国务院劳动行政部门主管全国劳动工作。"},{"i":10,"n":"第十条","txt":"国家通过促进经济和社会发展，创造就业条件，扩大就业机会。"},{"i":11,"n":"第十一条","txt":"地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。"},{"i":12,"n":"第十二条","txt":"劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。"},{"i":13,"n":"第十三条","txt":"妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。"},{"i":14,"n":"第十四条","txt":"残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。"},{"i":15,"n":"第十五条","txt":"禁止用人单位招用未满十六周岁的未成年人。"},{"i":16,"n":"第十六条","txt":"劳动合同是劳动者与用人单位确立劳动关系、明确双方权利和义务的协议。"},{"i":17,"n":"第十七条","txt":"订立和变更劳动合同，应当遵循平等自愿、协商一致的原则，不得违反法律、行政法规的规定。"},{"i":18,"n":"第十八条","txt":"下列劳动合同无效："},{"i":19,"n":"第十九条","txt":"劳动合同应当以书面形式订立，并具备以下条款："},{"i":20,"n":"第二十条","txt":"劳动合同的期限分为有固定期限、无固定期限和以完成一定的工作为期限。"},{"i":21,"n":"第二十一条","txt":"劳动合同可以约定试用期。试用期最长不得超过六个月。"},{"i":22,"n":"第二十二条","txt":"劳动合同当事人可以在劳动合同中约定保守用人单位商业秘密的有关事项。"},{"i":23,"n":"第二十三条","txt":"劳动合同期满或者当事人约定的劳动合同终止条件出现，劳动合同即行终止。"},{"i":24,"n":"第二十四条","txt":"经劳动合同当事人协商一致，劳动合同可以解除。"},{"i":25,"n":"第二十五条","txt":"劳动者有下列情形之一的，用人单位可以解除劳动合同："},{"i":26,"n":"第二十六条","txt":"有下列情形之一的，用人单位可以解除劳动合同，但是应当提前三十日以书面形式通知劳动者本人："},{"i":27,"n":"第二十七条","txt":"用人单位濒临破产进行法定整顿期间或者生产经营状况发生严重困难，确需裁减人员的，应当提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见，经向劳动行政部门报告后，可以裁减人员。"},{"i":28,"n":"第二十八条","txt":"用人单位依据本法第二十四条、第二十六条、第二十七条的规定解除劳动合同的，应当依照国家有关规定给予经济补偿。"},{"i":29,"n":"第二十九条","txt":"劳动者有下列情形之一的，用人单位不得依据本法第二十六条、第二十七条的规定解除劳动合同："},{"i":30,"n":"第三十条","txt":"用人单位解除劳动合同，工会认为不适当的，有权提出意见。如果用人单位违反法律、法规或者劳动合同，工会有权要求重新处理；劳动者申请仲裁或者提起诉讼的，工会应当依法给予支持和帮助。"},{"i":31,"n":"第三十一条","txt":"劳动者解除劳动合同，应当提前三十日以书面形式通知用人单位。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，劳动者可以随时通知用人单位解除劳动合同："},{"i":33,"n":"第三十三条","txt":"企业职工一方与企业可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项，签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。"},{"i":34,"n":"第三十四条","txt":"集体合同签订后应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。"},{"i":35,"n":"第三十五条","txt":"依法签订的集体合同对企业和企业全体职工具有约束力。职工个人与企业订立的劳动合同中劳动条件和劳动报酬等标准不得低于集体合同的规定。"},{"i":36,"n":"第三十六条","txt":"国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。"},{"i":37,"n":"第三十七条","txt":"对实行计件工作的劳动者，用人单位应当根据本法第三十六条规定的工时制度合理确定其劳动定额和计件报酬标准。"},{"i":38,"n":"第三十八条","txt":"用人单位应当保证劳动者每周至少休息一日。"},{"i":39,"n":"第三十九条","txt":"企业因生产特点不能实行本法第三十六条、第三十八条规定的，经劳动行政部门批准，可以实行其他工作和休息办法。"},{"i":40,"n":"第四十条","txt":"用人单位在下列节日期间应当依法安排劳动者休假："},{"i":41,"n":"第四十一条","txt":"用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。"},{"i":42,"n":"第四十二条","txt":"有下列情形之一的，延长工作时间不受本法第四十一条规定的限制："},{"i":43,"n":"第四十三条","txt":"用人单位不得违反本法规定延长劳动者的工作时间。"},{"i":44,"n":"第四十四条","txt":"有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬："},{"i":45,"n":"第四十五条","txt":"国家实行带薪年休假制度。"},{"i":46,"n":"第四十六条","txt":"工资分配应当遵循按劳分配原则，实行同工同酬。"},{"i":47,"n":"第四十七条","txt":"用人单位根据本单位的生产经营特点和经济效益，依法自主确定本单位的工资分配方式和工资水平。"},{"i":48,"n":"第四十八条","txt":"国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。"},{"i":49,"n":"第四十九条","txt":"确定和调整最低工资标准应当综合参考下列因素："},{"i":50,"n":"第五十条","txt":"工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。"},{"i":51,"n":"第五十一条","txt":"劳动者在法定休假日和婚丧假期间以及依法参加社会活动期间，用人单位应当依法支付工资。"},{"i":52,"n":"第五十二条","txt":"用人单位必须建立、健全劳动安全卫生制度，严格执行国家劳动安全卫生规程和标准，对劳动者进行劳动安全卫生教育，防止劳动过程中的事故，减少职业危害。"},{"i":53,"n":"第五十三条","txt":"劳动安全卫生设施必须符合国家规定的标准。"},{"i":54,"n":"第五十四条","txt":"用人单位必须为劳动者提供符合国家规定的劳动安全卫生条件和必要的劳动防护用品，对从事有职业危害作业的劳动者应当定期进行健康检查。"},{"i":55,"n":"第五十五条","txt":"从事特种作业的劳动者必须经过专门培训并取得特种作业资格。"},{"i":56,"n":"第五十六条","txt":"劳动者在劳动过程中必须严格遵守安全操作规程。"},{"i":57,"n":"第五十七条","txt":"国家建立伤亡事故和职业病统计报告和处理制度。县级以上各级人民政府劳动行政部门、有关部门和用人单位应当依法对劳动者在劳动过程中发生的伤亡事故和劳动者的职业病状况，进行统计、报告和处理。"},{"i":58,"n":"第五十八条","txt":"国家对女职工和未成年工实行特殊劳动保护。"},{"i":59,"n":"第五十九条","txt":"禁止安排女职工从事矿山井下、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。"},{"i":60,"n":"第六十条","txt":"不得安排女职工在经期从事高处、低温、冷水作业和国家规定的第三级体力劳动强度的劳动。"},{"i":61,"n":"第六十一条","txt":"不得安排女职工在怀孕期间从事国家规定的第三级体力劳动强度的劳动和孕期禁忌从事的劳动。对怀孕七个月以上的女职工，不得安排其延长工作时间和夜班劳动。"},{"i":62,"n":"第六十二条","txt":"女职工生育享受不少于九十天的产假。"},{"i":63,"n":"第六十三条","txt":"不得安排女职工在哺乳未满一周岁的婴儿期间从事国家规定的第三级体力劳动强度的劳动和哺乳期禁忌从事的其他劳动，不得安排其延长工作时间和夜班劳动。"},{"i":64,"n":"第六十四条","txt":"不得安排未成年工从事矿山井下、有毒有害、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。"},{"i":65,"n":"第六十五条","txt":"用人单位应当对未成年工定期进行健康检查。"},{"i":66,"n":"第六十六条","txt":"国家通过各种途径，采取各种措施，发展职业培训事业，开发劳动者的职业技能，提高劳动者素质，增强劳动者的就业能力和工作能力。"},{"i":67,"n":"第六十七条","txt":"各级人民政府应当把发展职业培训纳入社会经济发展的规划，鼓励和支持有条件的企业、事业组织、社会团体和个人进行各种形式的职业培训。"},{"i":68,"n":"第六十八条","txt":"用人单位应当建立职业培训制度，按照国家规定提取和使用职业培训经费，根据本单位实际，有计划地对劳动者进行职业培训。"},{"i":69,"n":"第六十九条","txt":"国家确定职业分类，对规定的职业制定职业技能标准，实行职业资格证书制度，由经备案的考核鉴定机构负责对劳动者实施职业技能考核鉴定。"},{"i":70,"n":"第七十条","txt":"国家发展社会保险事业，建立社会保险制度，设立社会保险基金，使劳动者在年老、患病、工伤、失业、生育等情况下获得帮助和补偿。"},{"i":71,"n":"第七十一条","txt":"社会保险水平应当与社会经济发展水平和社会承受能力相适应。"},{"i":72,"n":"第七十二条","txt":"社会保险基金按照保险类型确定资金来源，逐步实行社会统筹。用人单位和劳动者必须依法参加社会保险，缴纳社会保险费。"},{"i":73,"n":"第七十三条","txt":"劳动者在下列情形下，依法享受社会保险待遇："},{"i":74,"n":"第七十四条","txt":"社会保险基金经办机构依照法律规定收支、管理和运营社会保险基金，并负有使社会保险基金保值增值的责任。"},{"i":75,"n":"第七十五条","txt":"国家鼓励用人单位根据本单位实际情况为劳动者建立补充保险。"},{"i":76,"n":"第七十六条","txt":"国家发展社会福利事业，兴建公共福利设施，为劳动者休息、休养和疗养提供条件。"},{"i":77,"n":"第七十七条","txt":"用人单位与劳动者发生劳动争议，当事人可以依法申请调解、仲裁、提起诉讼，也可以协商解决。"},{"i":78,"n":"第七十八条","txt":"解决劳动争议，应当根据合法、公正、及时处理的原则，依法维护劳动争议当事人的合法权益。"},{"i":79,"n":"第七十九条","txt":"劳动争议发生后，当事人可以向本单位劳动争议调解委员会申请调解；调解不成，当事人一方要求仲裁的，可以向劳动争议仲裁委员会申请仲裁。当事人一方也可以直接向劳动争议仲裁委员会申请仲裁。对仲裁裁决不服的，可以向人民法院提起诉讼。"},{"i":80,"n":"第八十条","txt":"在用人单位内，可以设立劳动争议调解委员会。劳动争议调解委员会由职工代表、用人单位代表和工会代表组成。劳动争议调解委员会主任由工会代表担任。"},{"i":81,"n":"第八十一条","txt":"劳动争议仲裁委员会由劳动行政部门代表、同级工会代表、用人单位方面的代表组成。劳动争议仲裁委员会主任由劳动行政部门代表担任。"},{"i":82,"n":"第八十二条","txt":"提出仲裁要求的一方应当自劳动争议发生之日起六十日内向劳动争议仲裁委员会提出书面申请。仲裁裁决一般应在收到仲裁申请的六十日内作出。对仲裁裁决无异议的，当事人必须履行。"},{"i":83,"n":"第八十三条","txt":"劳动争议当事人对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。一方当事人在法定期限内不起诉又不履行仲裁裁决的，另一方当事人可以申请人民法院强制执行。"},{"i":84,"n":"第八十四条","txt":"因签订集体合同发生争议，当事人协商解决不成的，当地人民政府劳动行政部门可以组织有关各方协调处理。"},{"i":85,"n":"第八十五条","txt":"县级以上各级人民政府劳动行政部门依法对用人单位遵守劳动法律、法规的情况进行监督检查，对违反劳动法律、法规的行为有权制止，并责令改正。"},{"i":86,"n":"第八十六条","txt":"县级以上各级人民政府劳动行政部门监督检查人员执行公务，有权进入用人单位了解执行劳动法律、法规的情况，查阅必要的资料，并对劳动场所进行检查。"},{"i":87,"n":"第八十七条","txt":"县级以上各级人民政府有关部门在各自职责范围内，对用人单位遵守劳动法律、法规的情况进行监督。"},{"i":88,"n":"第八十八条","txt":"各级工会依法维护劳动者的合法权益，对用人单位遵守劳动法律、法规的情况进行监督。"},{"i":89,"n":"第八十九条","txt":"用人单位制定的劳动规章制度违反法律、法规规定的，由劳动行政部门给予警告，责令改正；对劳动者造成损害的，应当承担赔偿责任。"},{"i":90,"n":"第九十条","txt":"用人单位违反本法规定，延长劳动者工作时间的，由劳动行政部门给予警告，责令改正，并可以处以罚款。"},{"i":91,"n":"第九十一条","txt":"用人单位有下列侵害劳动者合法权益情形之一的，由劳动行政部门责令支付劳动者的工资报酬、经济补偿，并可以责令支付赔偿金："},{"i":92,"n":"第九十二条","txt":"用人单位的劳动安全设施和劳动卫生条件不符合国家规定或者未向劳动者提供必要的劳动防护用品和劳动保护设施的，由劳动行政部门或者有关部门责令改正，可以处以罚款；情节严重的，提请县级以上人民政府决定责令停产整顿；对事故隐患不采取措施，致使发生重大事故，造成劳动者生命和财产损失的，对责任人员依照刑法有关规定追究刑事责任。"},{"i":93,"n":"第九十三条","txt":"用人单位强令劳动者违章冒险作业，发生重大伤亡事故，造成严重后果的，对责任人员依法追究刑事责任。"},{"i":94,"n":"第九十四条","txt":"用人单位非法招用未满十六周岁的未成年人的，由劳动行政部门责令改正，处以罚款；情节严重的，由市场监督管理部门吊销营业执照。"},{"i":95,"n":"第九十五条","txt":"用人单位违反本法对女职工和未成年工的保护规定，侵害其合法权益的，由劳动行政部门责令改正，处以罚款；对女职工或者未成年工造成损害的，应当承担赔偿责任。"},{"i":96,"n":"第九十六条","txt":"用人单位有下列行为之一，由公安机关对责任人员处以十五日以下拘留、罚款或者警告；构成犯罪的，对责任人员依法追究刑事责任："},{"i":97,"n":"第九十七条","txt":"由于用人单位的原因订立的无效合同，对劳动者造成损害的，应当承担赔偿责任。"},{"i":98,"n":"第九十八条","txt":"用人单位违反本法规定的条件解除劳动合同或者故意拖延不订立劳动合同的，由劳动行政部门责令改正；对劳动者造成损害的，应当承担赔偿责任。"},{"i":99,"n":"第九十九条","txt":"用人单位招用尚未解除劳动合同的劳动者，对原用人单位造成经济损失的，该用人单位应当依法承担连带赔偿责任。"},{"i":100,"n":"第一百条","txt":"用人单位无故不缴纳社会保险费的，由劳动行政部门责令其限期缴纳；逾期不缴的，可以加收滞纳金。"},{"i":101,"n":"第一百零一条","txt":"用人单位无理阻挠劳动行政部门、有关部门及其工作人员行使监督检查权，打击报复举报人员的，由劳动行政部门或者有关部门处以罚款；构成犯罪的，对责任人员依法追究刑事责任。"},{"i":102,"n":"第一百零二条","txt":"劳动者违反本法规定的条件解除劳动合同或者违反劳动合同中约定的保密事项，对用人单位造成经济损失的，应当依法承担赔偿责任。"},{"i":103,"n":"第一百零三条","txt":"劳动行政部门或者有关部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。"},{"i":104,"n":"第一百零四条","txt":"国家工作人员和社会保险基金经办机构的工作人员挪用社会保险基金，构成犯罪的，依法追究刑事责任。"},{"i":105,"n":"第一百零五条","txt":"违反本法规定侵害劳动者合法权益，其他法律、行政法规已规定处罚的，依照该法律、行政法规的规定处罚。"},{"i":106,"n":"第一百零六条","txt":"省、自治区、直辖市人民政府根据本法和本地区的实际情况，规定劳动合同制度的实施步骤，报国务院备案。"},{"i":107,"n":"第一百零七条","txt":"本法自1995年1月1日起施行。"}],"yiliaobaozhangfa":[{"i":1,"n":"第一条","txt":"为了维护公民的医疗保障合法权益，规范医疗保障关系，优化医疗保障服务，健全多层次全民医疗保障体系，推动医疗保障工作高质量发展，落实健康优先发展战略、推进健康中国建设，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事医疗保障相关的筹资运行、待遇支付、公共服务、基金使用、监督管理等活动，适用本法；本法未作规定的，适用《中华人民共和国社会保险法》等法律、行政法规的有关规定。"},{"i":3,"n":"第三条","txt":"医疗保障工作坚持中国共产党的领导，坚持以人民为中心，遵循覆盖全民、统筹城乡、公平统一、安全规范、多层次、可持续的原则。医疗保障水平应当与经济社会发展水平相适应。"},{"i":4,"n":"第四条","txt":"公民有依法参加基本医疗保险的权利和义务，按照规定享受相应的医疗保障待遇。"},{"i":5,"n":"第五条","txt":"县级以上人民政府加强对医疗保障工作的领导，强化医疗保障能力建设，促进医疗、医保、医药协同发展和治理，统筹协调、研究解决医疗保障工作中的重大问题。"},{"i":6,"n":"第六条","txt":"国务院医疗保障行政部门在职责范围内负责全国的医疗保障管理工作。国务院其他有关部门在各自职责范围内负责有关的医疗保障工作。"},{"i":7,"n":"第七条","txt":"国家加强医疗保障法律法规和医疗保障知识的宣传教育，引导公民树立和践行健康管理理念，提高健康素养、医疗保障法治意识和参保意识。"},{"i":8,"n":"第八条","txt":"国家建立健全以基本医疗保险为主体的多层次全民医疗保障体系。"},{"i":9,"n":"第九条","txt":"基本医疗保险包括职工基本医疗保险和城乡居民基本医疗保险。国家逐步完善基本医疗保险制度，加强统筹协调，促进公平统一。"},{"i":10,"n":"第十条","txt":"职工应当参加职工基本医疗保险。职工基本医疗保险费由用人单位和职工共同缴纳。"},{"i":11,"n":"第十一条","txt":"未参加职工基本医疗保险且未享有国家其他医疗保障的公民应当参加城乡居民基本医疗保险。"},{"i":12,"n":"第十二条","txt":"国家建立健全参保长效机制，优化参保服务，完善激励约束措施，促进参保人员连续参保。"},{"i":13,"n":"第十三条","txt":"基本医疗保险为参保人员提供公平适度的待遇保障，待遇标准由省、自治区、直辖市人民政府医疗保障行政部门、财政部门按照国家规定确定，或者指导统筹地区人民政府医疗保障行政部门、财政部门按照国家规定确定。基本医疗保险的待遇标准应当有利于分级诊疗体系的发展。"},{"i":14,"n":"第十四条","txt":"职工应当参加生育保险。生育保险费由用人单位缴纳，职工不缴纳。生育保险费与职工基本医疗保险费统一征缴。生育保险基金与职工基本医疗保险基金合并建账。"},{"i":15,"n":"第十五条","txt":"生育保险参保人员按照国家规定享受生育医疗费用和生育津贴待遇，其未就业配偶按照国家规定享受生育医疗费用待遇，所需资金从职工基本医疗保险基金中支付。"},{"i":16,"n":"第十六条","txt":"职工大额医疗费用补助对职工基本医疗保险参保人员发生的高额医药费用予以进一步保障。居民大病保险对城乡居民基本医疗保险参保人员发生的高额医药费用予以进一步保障。"},{"i":17,"n":"第十七条","txt":"对符合医疗救助条件的困难人员给予相应的医疗救助。医疗救助的对象、方式和标准，依照有关医疗救助的法律、法规规定执行。"},{"i":18,"n":"第十八条","txt":"国家鼓励发展商业健康保险、与医疗保障有关的慈善捐赠、医疗互助等，满足多样化健康保障需求。"},{"i":19,"n":"第十九条","txt":"医疗保障基金包括基本医疗保险基金、医疗救助基金等。"},{"i":20,"n":"第二十条","txt":"税务机关应当按照规定征缴基本医疗保险费（含生育保险费）。基本医疗保险基金纳入社会保障基金财政专户管理。"},{"i":21,"n":"第二十一条","txt":"医疗救助基金通过财政预算、社会捐赠等多渠道筹集，实行专项管理、专账核算，纳入社会保障基金财政专户管理。"},{"i":22,"n":"第二十二条","txt":"基本医疗保险基金管理遵循以收定支、收支平衡的原则，确保基金稳定、可持续运行。"},{"i":23,"n":"第二十三条","txt":"基本医疗保险基金支付范围由国务院医疗保障行政部门组织制定。"},{"i":24,"n":"第二十四条","txt":"国务院医疗保障行政部门应当对纳入支付范围的基本医疗保险药品、医用耗材、医疗服务项目等目录组织开展循证医学和经济性评价。评价结果应当作为确定、调整基本医疗保险基金支付范围的依据。"},{"i":25,"n":"第二十五条","txt":"国务院医疗保障行政部门组织制定基本医疗保险基金支付范围、组织开展循证医学和经济性评价时，应当听取国务院卫生健康、中医药、疾病预防控制、药品监督管理、发展改革、民政、人力资源社会保障、工业和信息化、财政、市场监督管理等部门的意见，并采取适当方式听取医疗机构、药品经营单位、相关企业、专家和参保人员的意见。"},{"i":26,"n":"第二十六条","txt":"国家建立并完善药品、医用耗材集中采购制度。"},{"i":27,"n":"第二十七条","txt":"发生重大传染病疫情等紧急情况时，国务院医疗保障行政部门在听取国务院卫生健康、中医药、疾病预防控制、药品监督管理、工业和信息化等部门意见的基础上，可以会同国务院财政部门提出对基本医疗保险基金支付范围的临时调整方案，报国务院批准后实施。"},{"i":28,"n":"第二十八条","txt":"基本医疗保险实行医疗机构、药品经营单位定点管理。"},{"i":29,"n":"第二十九条","txt":"国家建立健全医疗保障公共服务体系，规范统一医疗保障公共服务事项清单，提高服务标准化、规范化、便利化水平，实现医疗保障公共服务城乡全覆盖。"},{"i":30,"n":"第三十条","txt":"医疗保障经办机构开展参保登记、关系转移、个人权益记录、待遇核定和支付、查询和咨询服务、医疗保障服务协议管理、核定国家规定情形的应缴费额等工作。"},{"i":31,"n":"第三十一条","txt":"医疗保障经办机构应当建立健全集体协商谈判机制，与符合条件的医疗机构、药品经营单位签订医疗保障服务协议，规范医药服务行为，合理确定定点医药机构的医疗保障基金预算金额和拨付时限，明确双方违反服务协议的行为及其责任。医疗保障行政部门应当加强对服务协议订立、履行等情况的监督。"},{"i":32,"n":"第三十二条","txt":"医疗保障行政部门、医疗保障经办机构建立健全基本医疗保险、职工大额医疗费用补助、居民大病保险、医疗救助等相衔接的医药费用直接结算机制，推行联网结算，提升结算效率。"},{"i":33,"n":"第三十三条","txt":"医疗保障经办机构应当加强对定点医药机构医疗保障基金使用相关制度、政策的培训和指导。"},{"i":34,"n":"第三十四条","txt":"定点医药机构应当按照医疗保障基金使用管理等要求，严格执行实名就医、购药管理规定，按照诊疗规范提供合理、必要的医药服务，遵守药品、医疗器械信息化追溯制度。"},{"i":35,"n":"第三十五条","txt":"参保人员应当持本人社会保障卡或者医保电子凭证就医、购药。参保人员有权要求定点医药机构依法如实出具费用单据和诊疗相关资料。"},{"i":36,"n":"第三十六条","txt":"医疗保障行政部门通过医疗保障信息平台实现数据有效有序共享、运用。"},{"i":37,"n":"第三十七条","txt":"县级以上人民政府应当向本级人民代表大会常务委员会报告医疗保障基金的收支、管理、监督检查等情况，依法接受监督。"},{"i":38,"n":"第三十八条","txt":"医疗保障行政部门应当加强对医疗保障经办机构、用人单位、定点医药机构等单位和参保人员等个人遵守医疗保障法律、法规情况的监督检查。"},{"i":39,"n":"第三十九条","txt":"医疗保障行政部门应当加强与卫生健康、药品监督管理等有关部门的信息共享、分工协作，建立沟通协调、联合检查、联合通报、案件移送等机制。"},{"i":40,"n":"第四十条","txt":"医疗保障行政部门依法履行职责，实施监督检查，有权采取下列措施："},{"i":41,"n":"第四十一条","txt":"医疗保障行政部门建立智能监督管理制度，对医疗保障基金使用情况实施动态智能监控。"},{"i":42,"n":"第四十二条","txt":"国家鼓励公民、法人和其他组织对医疗保障工作进行监督。"},{"i":43,"n":"第四十三条","txt":"医疗保障行政部门、税务机关、医疗保障经办机构、定点医药机构等单位及其工作人员对从事医疗保障相关工作中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息，依法负有保密义务。"},{"i":44,"n":"第四十四条","txt":"医疗保障行政部门应当建立定点医药机构及其工作人员、用人单位、参保人员等的信用管理制度。"},{"i":45,"n":"第四十五条","txt":"国家工作人员在医疗保障工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":46,"n":"第四十六条","txt":"医疗保障经办机构及其工作人员有下列情形之一的，由医疗保障行政部门责令改正；给医疗保障基金造成损失的，依法承担赔偿责任；对负有责任的领导人员和直接责任人员依法给予处分："},{"i":47,"n":"第四十七条","txt":"定点医药机构未建立并执行医疗保障基金使用内部控制制度的，被检查单位和个人拒绝、阻碍检查或者谎报、瞒报的，由医疗保障行政部门责令改正，并可以约谈有关负责人；拒不改正的，处一万元以上五万元以下的罚款。"},{"i":48,"n":"第四十八条","txt":"定点医药机构违法使用医疗保障基金的，由医疗保障行政部门责令改正，并可以约谈有关负责人；造成医疗保障基金损失的，责令退回，处造成损失金额一倍以上二倍以下的罚款；拒不改正或者造成严重后果的，责令其暂停相关责任部门或者人员六个月以上一年以下涉及医疗保障基金使用的医药服务。"},{"i":49,"n":"第四十九条","txt":"以欺诈、伪造证明材料或者其他手段骗取医疗保障基金支出的，由医疗保障行政部门责令退回，处骗取金额二倍以上五倍以下的罚款；属于医疗保障经办机构的，还应当对其负有责任的领导人员和直接责任人员依法给予处分；属于定点医药机构的，还应当责令其暂停相关责任部门或者人员六个月以上一年以下涉及医疗保障基金使用的医药服务，直至由医疗保障经办机构解除医疗保障服务协议；属于参保人员的，还应当采取暂停其医药费用联网结算三个月至十二个月、限制其接受服务的定点医药机构范围等管理约束措施。"},{"i":50,"n":"第五十条","txt":"定点医药机构违反本法规定，造成医疗保障基金重大损失或者严重不良社会影响的，对其法定代表人或者主要负责人依法给予处分，五年内禁止其从事定点医药机构管理活动。"},{"i":51,"n":"第五十一条","txt":"隐匿、转移、侵占、挪用医疗保障基金的，由医疗保障行政部门、财政部门、审计机关按照各自职责责令追回；有违法所得的，没收违法所得；对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":52,"n":"第五十二条","txt":"医疗保障行政部门、税务机关、医疗保障经办机构、定点医药机构等单位及其工作人员违反本法规定的保密义务，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":53,"n":"第五十三条","txt":"违反本法规定，给有关单位或者个人造成损害的，依法承担民事责任。"},{"i":54,"n":"第五十四条","txt":"商业健康保险、与医疗保障有关的慈善捐赠、医疗互助等依照有关法律、法规规定执行。"},{"i":55,"n":"第五十五条","txt":"国家建立健全长期护理保险制度。长期护理保险的筹资运行、待遇保障、基金使用、监督管理等的具体办法，由国务院医疗保障行政部门会同国务院有关部门参照本法有关基本医疗保险的规定制定。"},{"i":56,"n":"第五十六条","txt":"本法自2027年1月1日起施行。"}],"weixianhuaxuepinanquanfa":[{"i":1,"n":"第一条","txt":"为了加强危险化学品的安全管理，预防和减少危险化学品事故，保障人民群众身体健康、生命安全和财产安全，保护生态环境，制定本法。"},{"i":2,"n":"第二条","txt":"危险化学品生产、储存、使用、经营和运输的安全管理，适用本法。"},{"i":3,"n":"第三条","txt":"本法所称危险化学品，是指具有毒害、腐蚀、爆炸、燃烧、助燃等性质，对人体、设施、生态环境具有危害的剧毒化学品和其他化学品。"},{"i":4,"n":"第四条","txt":"危险化学品安全管理工作坚持中国共产党的领导。"},{"i":5,"n":"第五条","txt":"生产、储存、使用、经营、运输危险化学品的企业、学校、科研机构、医疗机构、检测机构、检验机构等单位（以下统称危险化学品单位）应当实行全员安全生产责任制，构建安全风险分级管控和隐患排查治理双重预防机制，加强安全生产标准化、信息化建设，其主要负责人对本单位的危险化学品安全生产工作全面负责。"},{"i":6,"n":"第六条","txt":"任何单位和个人不得生产、使用、经营国家禁止生产、使用、经营的危险化学品。"},{"i":7,"n":"第七条","txt":"对危险化学品的生产、储存、使用、经营、运输实施安全监督管理的有关部门（以下统称负有危险化学品安全监督管理职责的部门），依照下列规定履行职责："},{"i":8,"n":"第八条","txt":"负有危险化学品安全监督管理职责的部门依法进行监督检查，可以采取下列措施："},{"i":9,"n":"第九条","txt":"县级以上人民政府应当建立危险化学品安全监督管理工作协调机制，支持、督促负有危险化学品安全监督管理职责的部门依法履行职责，协调、解决危险化学品安全监督管理工作中的重大问题。"},{"i":10,"n":"第十条","txt":"任何单位和个人对违反本法规定的行为或者事故隐患，有权向负有危险化学品安全监督管理职责的部门举报或者报告。县级以上人民政府及其有关部门对举报违法行为或者报告重大事故隐患的有功人员依法给予奖励，并对举报人、报告人的信息进行严格保密。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府负有危险化学品安全监督管理职责的部门应当加强危险化学品信息化监管，对危险化学品实行电子标识和全生命周期信息化管理和监控。"},{"i":12,"n":"第十二条","txt":"国家鼓励危险化学品单位采用有利于提高安全保障水平的先进技术、工艺、设备以及自动控制系统，鼓励对危险化学品实行专门储存、统一配送、集中销售。"},{"i":13,"n":"第十三条","txt":"生产、储存、使用、经营危险化学品的单位应当按照国家有关规定对危险化学品重大危险源登记建档，进行定期检测、评估、监控，制定应急预案，建立重大危险源安全责任制，并将重大危险源的储存数量、储存地点、管理人员的情况及有关安全措施、应急措施报所在地县级人民政府应急管理部门、消防救援机构和有关部门备案；在港区内储存的，报港口行政管理部门、消防救援机构和有关部门备案。"},{"i":14,"n":"第十四条","txt":"各级人民政府及其有关部门应当采取多种形式，加强危险化学品安全法律法规和危险化学品安全知识宣传普及工作，促进全社会危险化学品安全意识的提升。"},{"i":15,"n":"第十五条","txt":"对在危险化学品安全工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":16,"n":"第十六条","txt":"国家对危险化学品的生产、储存实行统筹规划、合理布局。"},{"i":17,"n":"第十七条","txt":"化工园区应当由省、自治区、直辖市人民政府或者其授权的部门认定公布并定期复核。"},{"i":18,"n":"第十八条","txt":"新建、扩建危险化学品生产建设项目应当进入化工园区，与其他行业生产装置配套建设的项目和符合国家规定的其他项目除外。"},{"i":19,"n":"第十九条","txt":"化工园区应当至少每三年开展一次整体性安全风险评估，提出消除、降低、管控安全风险的对策措施并有效实施。"},{"i":20,"n":"第二十条","txt":"化工园区与城市建成区、人员密集场所、重要设施、敏感目标等应当保持符合相关法律、法规规定和国家标准要求的安全距离。"},{"i":21,"n":"第二十一条","txt":"县级以上地方人民政府应当加强危险化学品运输安全保障，对涉及危险化学品储存、装卸、运输的物流园区、集中停车区域，以及高速公路服务区的加油站、加气站等进行规划。"},{"i":22,"n":"第二十二条","txt":"危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施，与下列场所、设施、区域的安全距离应当符合国家有关规定："},{"i":23,"n":"第二十三条","txt":"危险化学品建设项目应当由应急管理部门进行安全条件审查。"},{"i":24,"n":"第二十四条","txt":"危险化学品建设项目和危险化学品港口建设项目的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。"},{"i":25,"n":"第二十五条","txt":"危险化学品建设项目和危险化学品港口建设项目安全设施的设计人、设计单位应当对安全设施设计负责。在安全设施设计中应当提出保障安全的措施建议。"},{"i":26,"n":"第二十六条","txt":"危险化学品建设项目的安全设施设计应当报所在地设区的市级以上人民政府应急管理部门审查。具体办法由国务院应急管理部门制定。"},{"i":27,"n":"第二十七条","txt":"施工单位必须按照批准的安全设施设计施工，并对安全设施的工程质量和施工安全负责。实行工程监理的危险化学品建设项目，建设单位应当对安全设施施工一并委托监理。"},{"i":28,"n":"第二十八条","txt":"生产、储存危险化学品的单位在公共区域埋地、地面和架空的危险化学品输送管道及其附属设施的安全管理，应当符合法律、行政法规的规定和国家标准、行业标准的要求。"},{"i":29,"n":"第二十九条","txt":"危险化学品生产企业主要负责人（包括法定代表人、实际控制人、实际负责人）和安全生产管理人员应当具备相应的安全生产知识和管理能力，并经应急管理部门考核合格。"},{"i":30,"n":"第三十条","txt":"危险化学品生产企业进行生产前，应当依照有关安全生产许可法律、行政法规的规定，取得危险化学品安全生产许可证。"},{"i":31,"n":"第三十一条","txt":"危险化学品生产企业、进口企业应当提供与其生产、进口的危险化学品相符的中文化学品安全技术说明书，并在危险化学品包装（包括外包装件，下同）上粘贴、印刷或者拴挂与包装内危险化学品相符的中文化学品安全标签。化学品安全技术说明书和化学品安全标签应当符合国家标准的要求。"},{"i":32,"n":"第三十二条","txt":"危险化学品的包装应当符合法律、行政法规、规章的规定和国家标准、行业标准的要求。"},{"i":33,"n":"第三十三条","txt":"生产列入国家实行生产许可证制度的工业产品目录的危险化学品包装物、容器的企业，应当依照有关工业产品生产许可法律、行政法规的规定，取得工业产品生产许可证；其生产的危险化学品包装物、容器经具有相应资质的检验机构检验合格，方可出厂销售。"},{"i":34,"n":"第三十四条","txt":"生产、储存危险化学品的企业应当建立安全风险分级管控制度，开展安全风险辨识评估，按照安全风险分级采取相应的管控措施。"},{"i":35,"n":"第三十五条","txt":"生产、储存危险化学品的企业应当建立包括工艺操作、特殊作业、设备管理、储存条件、开停车和检维修、变更等全部生产作业环节在内的过程安全管理制度，明确责任人、岗位职责和操作规程，并组织有效实施。"},{"i":36,"n":"第三十六条","txt":"生产、储存危险化学品的企业应当按照国家标准或者行业标准装备自动控制系统和安全仪表系统，建立安全风险监测预警系统，并与政府有关部门实现互联互通。"},{"i":37,"n":"第三十七条","txt":"生产、储存危险化学品的单位，应当根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相应的监测、监控、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、中和、防潮、防雷、防静电、防腐、防泄漏以及防护围堤或者隔离操作等安全设施、设备，并按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养，保证安全设施、设备的正常使用。"},{"i":38,"n":"第三十八条","txt":"生产、储存危险化学品的单位，应当在其作业场所设置通信、报警装置，并保证处于适用状态。"},{"i":39,"n":"第三十九条","txt":"生产、储存危险化学品的企业，应当委托具备国家规定的资质条件的机构，对本企业的安全生产条件每三年进行一次安全评价，提出安全评价报告。安全评价报告的内容应当包括对安全生产条件存在的问题进行整改的方案和整改完成后的结论性意见。安全评价报告应当按照规定向社会公开。"},{"i":40,"n":"第四十条","txt":"生产、储存剧毒化学品或者国务院公安部门规定的可用于制造爆炸物品的危险化学品（以下简称易制爆危险化学品）的单位，应当如实记录其生产、储存的剧毒化学品、易制爆危险化学品的品种、数量、流向，并采取必要的安全防范措施，防止剧毒化学品、易制爆危险化学品丢失或者被盗；发现剧毒化学品、易制爆危险化学品丢失或者被盗的，应当立即向当地公安机关报告；公安机关应当根据实际情况及时通报应急管理等有关部门。"},{"i":41,"n":"第四十一条","txt":"危险化学品应当储存在专用仓库、专用场地或者专用储存室、储存专柜（以下统称专用储存场所）内，并由专人负责管理；剧毒化学品以及储存数量构成重大危险源的其他危险化学品，应当在专用储存场所内单独存放，实行双人收发、双人保管制度，收发记录的保存期限不得少于三年。"},{"i":42,"n":"第四十二条","txt":"储存危险化学品的单位应当建立危险化学品出入库核查、登记制度。"},{"i":43,"n":"第四十三条","txt":"危险化学品专用储存场所应当符合国家标准、行业标准的要求，并设置明显的标志。储存剧毒化学品、易制爆危险化学品的专用储存场所，应当按照国家有关规定设置相应的实体防范、技术防范设施。"},{"i":44,"n":"第四十四条","txt":"研制开发单位进行危险化学品新工艺、新技术、新产品开发，应当加强研制开发过程的安全管理，确保研制开发过程安全，不得将未经小试、中试、工业化试验的新工艺、新技术直接用于工业化生产。"},{"i":45,"n":"第四十五条","txt":"生产、储存危险化学品的单位整体或者部分转产、停产、停业、解散的，应当采取有效措施，及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，不得丢弃危险化学品；处置方案应当报所在地县级人民政府应急管理、工业和信息化、生态环境部门和公安机关、消防救援机构备案。应急管理部门应当会同生态环境主管部门和公安机关、消防救援机构对处置情况进行监督检查，发现未按照规定处置的，应当责令其立即处置。"},{"i":46,"n":"第四十六条","txt":"县级以上人民政府有关部门应当依照职责分工，加强对企业、学校、科研机构、医疗机构、检测机构、检验机构等单位使用危险化学品的监督管理。"},{"i":47,"n":"第四十七条","txt":"使用危险化学品的单位的使用条件（包括工艺）应当符合法律、行政法规的规定和国家标准、行业标准的要求，并根据所使用的危险化学品的种类、危险特性以及使用量和使用方式，建立健全使用危险化学品的安全管理规章制度和安全操作规程，保证危险化学品的安全使用。"},{"i":48,"n":"第四十八条","txt":"使用国家规定种类的危险化学品从事生产并且使用量达到规定数量的化工企业（属于危险化学品生产企业的除外，下同），应当依照本法的规定取得危险化学品安全使用许可证。"},{"i":49,"n":"第四十九条","txt":"申请危险化学品安全使用许可证的化工企业，除应当符合本法第四十七条的规定外，还应当具备下列条件："},{"i":50,"n":"第五十条","txt":"申请危险化学品安全使用许可证的化工企业，应当向所在地设区的市级人民政府应急管理部门提出申请，并提交其符合本法第四十九条规定条件的证明材料。设区的市级人民政府应急管理部门应当依法进行审查，自收到证明材料之日起二十个工作日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品安全使用许可证；不予批准的，书面通知申请人并说明理由。"},{"i":51,"n":"第五十一条","txt":"使用危险化学品的单位应当将其作业场所使用的化学品安全技术说明书和化学品安全标签提供给从业人员，并加强培训教育，告知从业人员正确使用的方法和在紧急情况下应当采取的措施。"},{"i":52,"n":"第五十二条","txt":"本法第三十七条、第三十八条、第四十条第一款、第四十五条关于生产、储存危险化学品的单位的规定，适用于使用危险化学品的单位；第三十四条、第三十五条、第三十六条、第三十九条关于生产、储存危险化学品的企业的规定，适用于使用危险化学品从事生产的企业。"},{"i":53,"n":"第五十三条","txt":"国家对危险化学品经营（包括仓储经营，下同）实行许可制度。未经许可，任何单位和个人不得经营危险化学品。危险化学品经营企业不得向未经许可从事危险化学品生产、经营活动的企业采购危险化学品。"},{"i":54,"n":"第五十四条","txt":"从事危险化学品经营的企业应当具备下列条件："},{"i":55,"n":"第五十五条","txt":"从事剧毒化学品、易制爆危险化学品经营的企业，应当向所在地设区的市级人民政府应急管理部门提出申请。从事其他危险化学品经营的企业，应当向所在地县级人民政府应急管理部门提出申请；有储存设施且储存数量构成重大危险源的，应当向所在地设区的市级人民政府应急管理部门提出申请。申请人应当提交其符合本法第五十四条规定条件的证明材料。设区的市级人民政府应急管理部门或者县级人民政府应急管理部门应当依法进行审查，并按照规定对申请人的经营场所、储存设施进行现场核查。自收到证明材料之日起二十个工作日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品经营许可证；不予批准的，书面通知申请人并说明理由。"},{"i":56,"n":"第五十六条","txt":"危险化学品经营企业储存危险化学品的，应当遵守本法第三章关于储存危险化学品的规定。危险化学品商店内只能存放民用小包装的危险化学品。"},{"i":57,"n":"第五十七条","txt":"危险化学品生产企业、经营企业在销售危险化学品时，应当向购买单位或者个人提供符合法律、行政法规规定和国家标准、行业标准要求的化学品安全技术说明书，不得经营没有化学品安全技术说明书或者化学品安全标签的危险化学品，不得擅自更改化学品安全技术说明书或者化学品安全标签。"},{"i":58,"n":"第五十八条","txt":"依法取得危险化学品安全生产许可证、危险化学品安全使用许可证或者危险化学品经营许可证的企业，凭相应的许可证件购买剧毒化学品、易制爆危险化学品。民用爆炸物品、烟花爆竹、武器装备科研生产企业凭相应许可证购买易制爆危险化学品。"},{"i":59,"n":"第五十九条","txt":"申请取得剧毒化学品购买许可证，申请人应当向所在地县级人民政府公安机关提交下列材料："},{"i":60,"n":"第六十条","txt":"危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当查验本法第五十八条第一款、第二款规定的相关许可证件或者证明文件，不得向不具有相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品。对持剧毒化学品购买许可证购买剧毒化学品的，应当按照许可证载明的品种、数量销售。"},{"i":61,"n":"第六十一条","txt":"危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当如实记录购买单位的名称、地址，经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途。销售记录以及经办人的身份证明复印件、相关许可证件复印件或者证明文件的保存期限不得少于三年。"},{"i":62,"n":"第六十二条","txt":"使用剧毒化学品、易制爆危险化学品的单位不得出借、转让其购买的剧毒化学品、易制爆危险化学品；因转产、停产、搬迁、关闭等确需转让的，应当向具有本法第五十八条第一款、第二款规定的相关许可证件或者证明文件的单位转让，并在转让后三日内将所转让的剧毒化学品、易制爆危险化学品品种、数量以及流向信息报所在地县级人民政府公安机关备案。"},{"i":63,"n":"第六十三条","txt":"禁止在互联网上销售、购买剧毒化学品、易制爆危险化学品。"},{"i":64,"n":"第六十四条","txt":"通过道路、水路运输按照危险货物管理的危险化学品，应当遵守本法和有关法律、行政法规、国务院交通运输主管部门关于危险货物道路、水路运输安全的规定。"},{"i":65,"n":"第六十五条","txt":"从事危险化学品道路运输、水路运输的，应当向市场监督管理部门办理登记手续，并分别依照有关道路运输、水路运输的法律、行政法规的规定，取得危险货物道路运输许可、相应危险货物水路运输许可或者办理备案手续。"},{"i":66,"n":"第六十六条","txt":"危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员应当经交通运输主管部门考核合格，取得从业资格。具体办法由国务院交通运输主管部门制定。"},{"i":67,"n":"第六十七条","txt":"运输危险化学品，应当根据危险化学品的危险特性采取相应的安全防护措施，并配备必要的防护用品和应急救援器材、装备、设备和物资。"},{"i":68,"n":"第六十八条","txt":"通过道路运输危险化学品，应当按照运输车辆的核定载质量装载危险化学品，不得超载。"},{"i":69,"n":"第六十九条","txt":"通过道路运输危险化学品，应当按照要求配备押运人员，并保证所运输的危险化学品处于押运人员的监控之下。具体办法由国务院交通运输主管部门会同有关部门制定。"},{"i":70,"n":"第七十条","txt":"未经公安机关批准，运输危险化学品的车辆不得进入危险化学品运输车辆限制通行的区域。危险化学品运输车辆限制通行的区域由县级人民政府公安机关划定或者会同有关部门划定，并设置明显的标志。"},{"i":71,"n":"第七十一条","txt":"通过道路运输剧毒化学品，托运人应当向运输始发地或者目的地县级人民政府公安机关申请剧毒化学品道路运输通行证。"},{"i":72,"n":"第七十二条","txt":"剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况的，驾驶人员、押运人员应当立即采取相应的警示措施和安全措施，并向当地公安机关报告。公安机关接到报告后，应当根据实际情况立即向交通运输、应急管理、生态环境、卫生健康部门通报。有关部门应当采取必要的应急处置措施。"},{"i":73,"n":"第七十三条","txt":"海事管理机构应当根据危险化学品的种类和危险特性，确定船舶运输危险化学品的安全运输条件。"},{"i":74,"n":"第七十四条","txt":"禁止通过内河封闭水域运输剧毒化学品。"},{"i":75,"n":"第七十五条","txt":"国务院交通运输主管部门应当根据危险化学品的危险特性，对通过内河运输本法第七十四条规定以外的危险化学品（以下简称通过内河运输危险化学品）实行分类管理，对各类危险化学品的运输方式、包装规范和安全防护措施等分别作出规定并监督实施。"},{"i":76,"n":"第七十六条","txt":"通过内河运输危险化学品，应当使用依法取得危险货物适装证书的运输船舶。水路运输企业应当针对所运输的危险化学品的危险特性，制定运输船舶危险化学品事故应急救援预案，并为运输船舶配备充足、有效的应急救援器材、装备、设备和物资。"},{"i":77,"n":"第七十七条","txt":"通过内河运输危险化学品，危险化学品包装物的材质、型式、强度以及包装方法应当符合水路运输相关包装规范的要求。国务院交通运输主管部门对单船运输的危险化学品数量有限制性规定的，承运人应当按照规定安排运输数量。"},{"i":78,"n":"第七十八条","txt":"用于危险化学品运输作业的内河码头、泊位应当符合国家有关安全规范，与饮用水取水口保持国家规定的安全距离。有关管理单位应当制定码头、泊位危险化学品事故应急预案，并为码头、泊位配备充足、有效的应急救援器材、装备、设备和物资。"},{"i":79,"n":"第七十九条","txt":"船舶载运危险化学品进出内河港口，应当依照法律、行政法规的规定向海事管理机构报告。海事管理机构接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报港口行政管理部门。"},{"i":80,"n":"第八十条","txt":"载运危险化学品的船舶在内河航行、装卸或者停泊，应当悬挂专用的警示标志，按照规定显示专用信号。"},{"i":81,"n":"第八十一条","txt":"载运危险化学品的船舶在内河航行，应当遵守法律、行政法规和国家其他有关饮用水水源和自然保护地保护的规定。内河航道发展规划应当与依法经批准的饮用水水源保护区划定方案和自然保护地总体规划相协调。"},{"i":82,"n":"第八十二条","txt":"托运危险化学品，托运人应当向承运人提交电子或者纸质的危险货物托运清单，说明所托运的危险化学品的种类、数量、危险特性以及发生危险情况的应急处置措施，提供化学品安全技术说明书，并按照国家有关规定对所托运的危险化学品妥善包装，在危险化学品包装上粘贴、印刷或者拴挂与包装内危险化学品相符的化学品安全标签，并保证随时可查。"},{"i":83,"n":"第八十三条","txt":"托运人不得在托运的普通货物中夹带危险化学品，不得将危险化学品匿报或者谎报为普通货物托运。"},{"i":84,"n":"第八十四条","txt":"通过铁路、航空运输危险化学品的安全管理，依照有关铁路、航空运输的法律、行政法规、规章的规定执行。"},{"i":85,"n":"第八十五条","txt":"国家实行危险化学品登记制度，为危险化学品安全管理以及危险化学品事故预防和应急救援提供技术、信息支持。"},{"i":86,"n":"第八十六条","txt":"危险化学品生产企业、进口企业应当向国务院应急管理部门负责危险化学品登记的机构（以下简称危险化学品登记机构）办理危险化学品登记。"},{"i":87,"n":"第八十七条","txt":"国家对研究开发、试产试销过程中的低量低释放、低暴露的危险化学品等免予登记。免予登记的具体办法由国务院应急管理部门会同工业和信息化、公安、生态环境、农业农村、卫生健康、海关等部门制定。"},{"i":88,"n":"第八十八条","txt":"危险化学品登记机构应当将危险化学品登记信息数据与工业和信息化、公安、自然资源、生态环境、交通运输、农业农村、卫生健康、海关、市场监督管理、能源、军事机关等单位共享。"},{"i":89,"n":"第八十九条","txt":"新化学物质环境管理登记，依照有关生态环境保护的法律、行政法规、规章的规定执行。"},{"i":90,"n":"第九十条","txt":"县级以上地方人民政府应急管理部门应当会同工业和信息化、公安、生态环境、交通运输、卫生健康、市场监督管理等部门，根据本地区实际情况，制定危险化学品事故应急预案，报本级人民政府批准，并依法向社会公布。"},{"i":91,"n":"第九十一条","txt":"危险化学品单位应当做好应急准备工作，健全应急管理制度，制定本单位危险化学品事故应急预案，依法建立专职或者兼职应急救援队伍，配备必要的应急救援器材、装备、设备和物资，并定期组织应急救援演练，提高从业人员的应急处置能力。生产经营规模较小的，可以不建立应急救援队伍，但应当指定兼职的应急救援人员，并可以与邻近的应急救援队伍签订应急救援协议。"},{"i":92,"n":"第九十二条","txt":"县级以上地方人民政府根据生产安全事故应急工作的实际需要，加强化工园区危险化学品专业应急救援力量建设，可以依托有条件的生产经营单位、社会组织共同建立危险化学品专业应急救援队伍，配备必要的应急救援器材、装备、设备和物资，并定期组织训练。"},{"i":93,"n":"第九十三条","txt":"发生危险化学品事故，事故单位主要负责人应当立即按照本单位危险化学品事故应急预案组织救援，并向当地应急管理、生态环境、公安、卫生健康、市场监督管理部门报告，及时通知可能受影响的单位和人员；道路运输、水路运输过程中发生危险化学品事故的，驾驶人员、船员或者押运人员还应当向事故发生地交通运输主管部门报告。"},{"i":94,"n":"第九十四条","txt":"危险化学品单位发生直接危及人身安全的紧急情况时，在确保安全的前提下，作业现场带班人员、班组长、调度人员有权立即下达停产撤人命令，指挥有关遇险人员撤离。"},{"i":95,"n":"第九十五条","txt":"发生危险化学品事故，有关地方人民政府应当立即组织应急管理、生态环境、公安、卫生健康、交通运输等有关部门，按照本地区危险化学品事故应急预案组织实施救援，不得拖延、推诿。"},{"i":96,"n":"第九十六条","txt":"有关危险化学品单位应当为危险化学品事故应急救援提供技术指导和必要的协助。"},{"i":97,"n":"第九十七条","txt":"危险化学品事故造成环境污染和生态破坏的，由履行统一领导职责的人民政府统一发布有关信息。"},{"i":98,"n":"第九十八条","txt":"生产、使用、经营国家禁止生产、使用、经营的危险化学品的，由应急管理部门责令停止生产、使用、经营活动，有违法所得的，没收违法所得，并没收违法生产、使用、经营的危险化学品以及用于违法生产、使用、经营的工具、设备、原料等；违法生产、使用、经营的危险化学品货值金额不足十万元的，并处三十万元以上五十万元以下的罚款；货值金额十万元以上的，并处货值金额五倍以上十倍以下的罚款。"},{"i":99,"n":"第九十九条","txt":"有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令停止建设或者停产停业整顿，限期改正，并处十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；逾期未改正的，处五十万元以上一百万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款："},{"i":100,"n":"第一百条","txt":"未依法取得危险化学品安全生产许可证从事危险化学品生产，或者未依法取得工业产品生产许可证从事危险化学品及其包装物、容器生产的，分别依照有关安全生产许可、工业产品生产许可法律、行政法规的规定处理、处罚。"},{"i":101,"n":"第一百零一条","txt":"有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令限期改正，可以处十万元以下的罚款；逾期未改正的，处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；情节严重的，责令停产停业整顿："},{"i":102,"n":"第一百零二条","txt":"危险化学品包装物、容器生产企业销售未经检验或者经检验不合格的危险化学品包装物、容器的，由市场监督管理部门责令限期改正，处二十万元以上五十万元以下的罚款，有违法所得的，没收违法所得；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款。"},{"i":103,"n":"第一百零三条","txt":"有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令限期改正，处五万元以上十万元以下的罚款；逾期不改正的，责令停产停业整顿直至由原发证机关吊销其相关许可证件，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照："},{"i":104,"n":"第一百零四条","txt":"有下列情形之一的，由公安机关责令限期改正，可以处二万元以上十万元以下的罚款；逾期不改正的，处十万元以上二十万元以下的罚款，对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款："},{"i":105,"n":"第一百零五条","txt":"生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未采取有效措施及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，或者丢弃危险化学品的，由应急管理部门责令限期改正，处十万元以上五十万元以下的罚款。"},{"i":106,"n":"第一百零六条","txt":"危险化学品经营企业向未经许可违法从事危险化学品生产、经营活动的企业采购危险化学品的，由应急管理部门责令限期改正，处二十万元以上五十万元以下的罚款；逾期不改正的，责令停业整顿直至由原发证机关吊销其危险化学品经营许可证，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照。"},{"i":107,"n":"第一百零七条","txt":"危险化学品生产企业、经营企业有下列情形之一的，由应急管理部门责令限期改正，没收违法所得，并处二十万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿直至由原发证机关吊销其危险化学品安全生产许可证、危险化学品经营许可证，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照："},{"i":108,"n":"第一百零八条","txt":"未依法取得危险货物道路运输许可、相应危险货物水路运输许可或者未办理备案手续，从事危险化学品道路运输、水路运输的，分别依照有关道路运输、水路运输的法律、行政法规的规定处理、处罚。"},{"i":109,"n":"第一百零九条","txt":"有下列情形之一的，由交通运输主管部门责令限期改正，处五万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款："},{"i":110,"n":"第一百一十条","txt":"有下列情形之一的，由交通运输主管部门责令限期改正，处二十万元以上三十万元以下的罚款，有违法所得的，没收违法所得；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款："},{"i":111,"n":"第一百一十一条","txt":"有下列情形之一的，由公安机关责令限期改正，处十万元以上二十万元以下的罚款："},{"i":112,"n":"第一百一十二条","txt":"有下列情形之一的，由公安机关责令限期改正，处五万元以上十万元以下的罚款："},{"i":113,"n":"第一百一十三条","txt":"对发生交通事故负有全部责任或者主要责任的危险化学品道路运输企业，由公安机关责令消除安全隐患，未消除安全隐患的危险化学品运输车辆，禁止上道路行驶。"},{"i":114,"n":"第一百一十四条","txt":"有下列情形之一的，由交通运输主管部门责令限期改正，可以处五万元以下的罚款；逾期不改正的，处五万元以上十万元以下的罚款："},{"i":115,"n":"第一百一十五条","txt":"有下列情形之一的，依照有关内河交通安全管理法律、行政法规的规定处理、处罚："},{"i":116,"n":"第一百一十六条","txt":"伪造、变造或者出租、出借、转让危险化学品安全生产许可证、工业产品生产许可证，或者使用伪造、变造的危险化学品安全生产许可证、工业产品生产许可证的，分别依照有关安全生产许可、工业产品生产许可法律、行政法规的规定处理、处罚。"},{"i":117,"n":"第一百一十七条","txt":"危险化学品单位发生危险化学品事故，其主要负责人不立即组织救援或者不立即向有关部门报告的，依照有关生产安全事故报告和调查处理法律、行政法规的规定处理、处罚。"},{"i":118,"n":"第一百一十八条","txt":"发生危险化学品事故，有关地方人民政府及其有关部门不立即组织实施救援，或者不采取必要的应急处置措施减少事故损失，防止事故蔓延、扩大的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":119,"n":"第一百一十九条","txt":"负有危险化学品安全监督管理职责的部门的工作人员，在危险化学品安全监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":120,"n":"第一百二十条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":121,"n":"第一百二十一条","txt":"监控化学品、属于危险化学品的药品和农药的安全管理，依照本法的规定执行；法律、行政法规另有规定的，依照其规定。"},{"i":122,"n":"第一百二十二条","txt":"危险化学品的进出口管理，依照有关对外贸易的法律、行政法规、规章的规定执行；出口危险化学品涉及《中华人民共和国出口管制法》规定的管制物项的，依照有关出口管制的法律、行政法规、规章的规定执行；进口的危险化学品的储存、使用、经营、运输的安全管理，依照本法的规定执行。"},{"i":123,"n":"第一百二十三条","txt":"公众发现、捡拾的无主危险化学品，由公安机关或者应急管理部门接收。有关部门接收或者依法没收的危险化学品，需要进行处置的，交由生态环境主管部门组织其认定的专业单位进行处置，或者交由有关危险化学品生产企业进行处置。处置所需费用由政府负担。"},{"i":124,"n":"第一百二十四条","txt":"化学品的危险特性尚未确定的，由国务院应急管理、生态环境、卫生健康部门分别负责组织对该化学品的物理危险性、生态环境危害性、毒理特性进行鉴定。根据鉴定结果需要调整危险化学品目录的，依照本法第三条第二款的规定办理。"},{"i":125,"n":"第一百二十五条","txt":"港区内危险化学品生产和使用危险化学品的生产装置及相连储罐部分，由应急管理部门负责安全监督管理；仅与危险化学品码头相连的储罐部分，由港口行政管理部门负责安全监督管理。"},{"i":126,"n":"第一百二十六条","txt":"中国人民解放军、中国人民武装警察部队的危险化学品安全管理，依照本法有关规定和中央军事委员会的规定执行。"},{"i":127,"n":"第一百二十七条","txt":"本法自2026年5月1日起施行。"}],"fanjiatingbaolifa":[{"i":1,"n":"第一条","txt":"为了预防和制止家庭暴力，保护家庭成员的合法权益，维护平等、和睦、文明的家庭关系，促进家庭和谐、社会稳定，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称家庭暴力，是指家庭成员之间以殴打、捆绑、残害、限制人身自由以及经常性谩骂、恐吓等方式实施的身体、精神等侵害行为。"},{"i":3,"n":"第三条","txt":"家庭成员之间应当互相帮助，互相关爱，和睦相处，履行家庭义务。"},{"i":4,"n":"第四条","txt":"县级以上人民政府负责妇女儿童工作的机构，负责组织、协调、指导、督促有关部门做好反家庭暴力工作。"},{"i":5,"n":"第五条","txt":"反家庭暴力工作遵循预防为主，教育、矫治与惩处相结合原则。"},{"i":6,"n":"第六条","txt":"国家开展家庭美德宣传教育，普及反家庭暴力知识，增强公民反家庭暴力意识。"},{"i":7,"n":"第七条","txt":"县级以上人民政府有关部门、司法机关、妇女联合会应当将预防和制止家庭暴力纳入业务培训和统计工作。"},{"i":8,"n":"第八条","txt":"乡镇人民政府、街道办事处应当组织开展家庭暴力预防工作，居民委员会、村民委员会、社会工作服务机构应当予以配合协助。"},{"i":9,"n":"第九条","txt":"各级人民政府应当支持社会工作服务机构等社会组织开展心理健康咨询、家庭关系指导、家庭暴力预防知识教育等服务。"},{"i":10,"n":"第十条","txt":"人民调解组织应当依法调解家庭纠纷，预防和减少家庭暴力的发生。"},{"i":11,"n":"第十一条","txt":"用人单位发现本单位人员有家庭暴力情况的，应当给予批评教育，并做好家庭矛盾的调解、化解工作。"},{"i":12,"n":"第十二条","txt":"未成年人的监护人应当以文明的方式进行家庭教育，依法履行监护和教育职责，不得实施家庭暴力。"},{"i":13,"n":"第十三条","txt":"家庭暴力受害人及其法定代理人、近亲属可以向加害人或者受害人所在单位、居民委员会、村民委员会、妇女联合会等单位投诉、反映或者求助。有关单位接到家庭暴力投诉、反映或者求助后，应当给予帮助、处理。"},{"i":14,"n":"第十四条","txt":"学校、幼儿园、医疗机构、居民委员会、村民委员会、社会工作服务机构、救助管理机构、福利机构及其工作人员在工作中发现无民事行为能力人、限制民事行为能力人遭受或者疑似遭受家庭暴力的，应当及时向公安机关报案。公安机关应当对报案人的信息予以保密。"},{"i":15,"n":"第十五条","txt":"公安机关接到家庭暴力报案后应当及时出警，制止家庭暴力，按照有关规定调查取证，协助受害人就医、鉴定伤情。"},{"i":16,"n":"第十六条","txt":"家庭暴力情节较轻，依法不给予治安管理处罚的，由公安机关对加害人给予批评教育或者出具告诫书。"},{"i":17,"n":"第十七条","txt":"公安机关应当将告诫书送交加害人、受害人，并通知居民委员会、村民委员会。"},{"i":18,"n":"第十八条","txt":"县级或者设区的市级人民政府可以单独或者依托救助管理机构设立临时庇护场所，为家庭暴力受害人提供临时生活帮助。"},{"i":19,"n":"第十九条","txt":"法律援助机构应当依法为家庭暴力受害人提供法律援助。"},{"i":20,"n":"第二十条","txt":"人民法院审理涉及家庭暴力的案件，可以根据公安机关出警记录、告诫书、伤情鉴定意见等证据，认定家庭暴力事实。"},{"i":21,"n":"第二十一条","txt":"监护人实施家庭暴力严重侵害被监护人合法权益的，人民法院可以根据被监护人的近亲属、居民委员会、村民委员会、县级人民政府民政部门等有关人员或者单位的申请，依法撤销其监护人资格，另行指定监护人。"},{"i":22,"n":"第二十二条","txt":"工会、共产主义青年团、妇女联合会、残疾人联合会、居民委员会、村民委员会等应当对实施家庭暴力的加害人进行法治教育，必要时可以对加害人、受害人进行心理辅导。"},{"i":23,"n":"第二十三条","txt":"当事人因遭受家庭暴力或者面临家庭暴力的现实危险，向人民法院申请人身安全保护令的，人民法院应当受理。"},{"i":24,"n":"第二十四条","txt":"申请人身安全保护令应当以书面方式提出；书面申请确有困难的，可以口头申请，由人民法院记入笔录。"},{"i":25,"n":"第二十五条","txt":"人身安全保护令案件由申请人或者被申请人居住地、家庭暴力发生地的基层人民法院管辖。"},{"i":26,"n":"第二十六条","txt":"人身安全保护令由人民法院以裁定形式作出。"},{"i":27,"n":"第二十七条","txt":"作出人身安全保护令，应当具备下列条件："},{"i":28,"n":"第二十八条","txt":"人民法院受理申请后，应当在七十二小时内作出人身安全保护令或者驳回申请；情况紧急的，应当在二十四小时内作出。"},{"i":29,"n":"第二十九条","txt":"人身安全保护令可以包括下列措施："},{"i":30,"n":"第三十条","txt":"人身安全保护令的有效期不超过六个月，自作出之日起生效。人身安全保护令失效前，人民法院可以根据申请人的申请撤销、变更或者延长。"},{"i":31,"n":"第三十一条","txt":"申请人对驳回申请不服或者被申请人对人身安全保护令不服的，可以自裁定生效之日起五日内向作出裁定的人民法院申请复议一次。人民法院依法作出人身安全保护令的，复议期间不停止人身安全保护令的执行。"},{"i":32,"n":"第三十二条","txt":"人民法院作出人身安全保护令后，应当送达申请人、被申请人、公安机关以及居民委员会、村民委员会等有关组织。人身安全保护令由人民法院执行，公安机关以及居民委员会、村民委员会等应当协助执行。"},{"i":33,"n":"第三十三条","txt":"加害人实施家庭暴力，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"被申请人违反人身安全保护令，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，人民法院应当给予训诫，可以根据情节轻重处以一千元以下罚款、十五日以下拘留。"},{"i":35,"n":"第三十五条","txt":"学校、幼儿园、医疗机构、居民委员会、村民委员会、社会工作服务机构、救助管理机构、福利机构及其工作人员未依照本法第十四条规定向公安机关报案，造成严重后果的，由上级主管部门或者本单位对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":36,"n":"第三十六条","txt":"负有反家庭暴力职责的国家工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"家庭成员以外共同生活的人之间实施的暴力行为，参照本法规定执行。"},{"i":38,"n":"第三十八条","txt":"本法自2016年3月1日起施行。"}],"jingwaifeizhengfuzuzhijingneihuodongguanlifa":[{"i":1,"n":"第一条","txt":"为了规范、引导境外非政府组织在中国境内的活动，保障其合法权益，促进交流与合作，制定本法。"},{"i":2,"n":"第二条","txt":"境外非政府组织在中国境内开展活动适用本法。"},{"i":3,"n":"第三条","txt":"境外非政府组织依照本法可以在经济、教育、科技、文化、卫生、体育、环保等领域和济困、救灾等方面开展有利于公益事业发展的活动。"},{"i":4,"n":"第四条","txt":"境外非政府组织在中国境内依法开展活动，受法律保护。"},{"i":5,"n":"第五条","txt":"境外非政府组织在中国境内开展活动应当遵守中国法律，不得危害中国的国家统一、安全和民族团结，不得损害中国国家利益、社会公共利益和公民、法人以及其他组织的合法权益。"},{"i":6,"n":"第六条","txt":"国务院公安部门和省级人民政府公安机关，是境外非政府组织在中国境内开展活动的登记管理机关。"},{"i":7,"n":"第七条","txt":"县级以上人民政府公安机关和有关部门在各自职责范围内对境外非政府组织在中国境内开展活动依法实施监督管理、提供服务。"},{"i":8,"n":"第八条","txt":"国家对为中国公益事业发展做出突出贡献的境外非政府组织给予表彰。"},{"i":9,"n":"第九条","txt":"境外非政府组织在中国境内开展活动，应当依法登记设立代表机构；未登记设立代表机构需要在中国境内开展临时活动的，应当依法备案。"},{"i":10,"n":"第十条","txt":"境外非政府组织符合下列条件，根据业务范围、活动地域和开展活动的需要，可以申请在中国境内登记设立代表机构："},{"i":11,"n":"第十一条","txt":"境外非政府组织申请登记设立代表机构，应当经业务主管单位同意。"},{"i":12,"n":"第十二条","txt":"境外非政府组织应当自业务主管单位同意之日起三十日内，向登记管理机关申请设立代表机构登记。申请设立代表机构登记，应当向登记管理机关提交下列文件、材料："},{"i":13,"n":"第十三条","txt":"对准予登记的境外非政府组织代表机构，登记管理机关发给登记证书，并向社会公告。登记事项包括："},{"i":14,"n":"第十四条","txt":"境外非政府组织代表机构需要变更登记事项的，应当自业务主管单位同意之日起三十日内，向登记管理机关申请变更登记。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，境外非政府组织代表机构由登记管理机关注销登记，并向社会公告："},{"i":16,"n":"第十六条","txt":"境外非政府组织未在中国境内设立代表机构，在中国境内开展临时活动的，应当与中国的国家机关、人民团体、事业单位、社会组织（以下称中方合作单位）合作进行。"},{"i":17,"n":"第十七条","txt":"境外非政府组织开展临时活动，中方合作单位应当按照国家规定办理审批手续，并在开展临时活动十五日前向其所在地的登记管理机关备案。备案应当提交下列文件、材料："},{"i":18,"n":"第十八条","txt":"境外非政府组织代表机构应当以登记的名称，在登记的业务范围和活动地域内开展活动。"},{"i":19,"n":"第十九条","txt":"境外非政府组织代表机构应当于每年12月31日前将包含项目实施、资金使用等内容的下一年度活动计划报业务主管单位，业务主管单位同意后十日内报登记管理机关备案。特殊情况下需要调整活动计划的，应当及时向登记管理机关备案。"},{"i":20,"n":"第二十条","txt":"境外非政府组织在中国境内开展活动不得对中方合作单位、受益人附加违反中国法律法规的条件。"},{"i":21,"n":"第二十一条","txt":"境外非政府组织在中国境内活动资金包括："},{"i":22,"n":"第二十二条","txt":"设立代表机构的境外非政府组织应当通过代表机构在登记管理机关备案的银行账户管理用于中国境内的资金。"},{"i":23,"n":"第二十三条","txt":"境外非政府组织应当按照代表机构登记的业务范围、活动地域或者与中方合作单位协议的约定使用资金。"},{"i":24,"n":"第二十四条","txt":"境外非政府组织代表机构应当执行中国统一的会计制度。财务会计报告应当经中国境内会计师事务所审计。"},{"i":25,"n":"第二十五条","txt":"境外非政府组织在中国境内开展活动，应当按照中国有关外汇管理的规定办理外汇收支。"},{"i":26,"n":"第二十六条","txt":"境外非政府组织代表机构应当依法办理税务登记、纳税申报和税款缴纳等事项。"},{"i":27,"n":"第二十七条","txt":"境外非政府组织代表机构在中国境内聘用工作人员应当遵守法律、行政法规，并将聘用的工作人员信息报业务主管单位和登记管理机关备案。"},{"i":28,"n":"第二十八条","txt":"境外非政府组织代表机构、开展临时活动的境外非政府组织不得在中国境内发展会员，国务院另有规定的除外。"},{"i":29,"n":"第二十九条","txt":"境外非政府组织代表机构应当设一名首席代表，可以根据业务需要设一至三名代表。"},{"i":30,"n":"第三十条","txt":"开展临时活动的境外非政府组织，应当以经备案的名称开展活动。"},{"i":31,"n":"第三十一条","txt":"境外非政府组织代表机构应当于每年1月31日前向业务主管单位报送上一年度工作报告，经业务主管单位出具意见后，于3月31日前报送登记管理机关，接受年度检查。"},{"i":32,"n":"第三十二条","txt":"中国境内任何单位和个人不得接受未登记代表机构、开展临时活动未经备案的境外非政府组织的委托、资助，代理或者变相代理境外非政府组织在中国境内开展活动。"},{"i":33,"n":"第三十三条","txt":"国家保障和支持境外非政府组织在中国境内依法开展活动。各级人民政府有关部门应当为境外非政府组织在中国境内依法开展活动提供必要的便利和服务。"},{"i":34,"n":"第三十四条","txt":"国务院公安部门和省级人民政府公安机关会同有关部门制定境外非政府组织活动领域和项目目录，公布业务主管单位名录，为境外非政府组织开展活动提供指引。"},{"i":35,"n":"第三十五条","txt":"县级以上人民政府有关部门应当依法为境外非政府组织提供政策咨询、活动指导服务。"},{"i":36,"n":"第三十六条","txt":"境外非政府组织代表机构依法享受税收优惠等政策。"},{"i":37,"n":"第三十七条","txt":"对境外非政府组织代表机构进行年度检查不得收取费用。"},{"i":38,"n":"第三十八条","txt":"境外非政府组织代表机构首席代表和代表中的境外人员，可以凭登记证书、代表证明文件等依法办理就业等工作手续。"},{"i":39,"n":"第三十九条","txt":"境外非政府组织在中国境内开展活动，应当接受公安机关、有关部门和业务主管单位的监督管理。"},{"i":40,"n":"第四十条","txt":"业务主管单位负责对境外非政府组织设立代表机构、变更登记事项、年度工作报告提出意见，指导、监督境外非政府组织及其代表机构依法开展活动，协助公安机关等部门查处境外非政府组织及其代表机构的违法行为。"},{"i":41,"n":"第四十一条","txt":"公安机关负责境外非政府组织代表机构的登记、年度检查，境外非政府组织临时活动的备案，对境外非政府组织及其代表机构的违法行为进行查处。"},{"i":42,"n":"第四十二条","txt":"公安机关可以查询与被调查事件有关的单位和个人的银行账户，有关金融机构、金融监督管理机构应当予以配合。对涉嫌违法活动的银行账户资金，经设区的市级以上人民政府公安机关负责人批准，可以提请人民法院依法冻结；对涉嫌犯罪的银行账户资金，依照《中华人民共和国刑事诉讼法》的规定采取冻结措施。"},{"i":43,"n":"第四十三条","txt":"国家安全、外交外事、财政、金融监督管理、海关、税务、外国专家等部门按照各自职责对境外非政府组织及其代表机构依法实施监督管理。"},{"i":44,"n":"第四十四条","txt":"国务院反洗钱行政主管部门依法对境外非政府组织代表机构、中方合作单位以及接受境外非政府组织资金的中国境内单位和个人开立、使用银行账户过程中遵守反洗钱和反恐怖主义融资法律规定的情况进行监督管理。"},{"i":45,"n":"第四十五条","txt":"境外非政府组织代表机构、开展临时活动的境外非政府组织或者中方合作单位有下列情形之一的，由设区的市级以上人民政府公安机关给予警告或者责令限期停止活动；没收非法财物和违法所得；情节严重的，由登记管理机关吊销登记证书、取缔临时活动："},{"i":46,"n":"第四十六条","txt":"有下列情形之一的，由设区的市级以上人民政府公安机关予以取缔或者责令停止违法行为；没收非法财物和违法所得；对直接责任人员给予警告，情节严重的，处十日以下拘留："},{"i":47,"n":"第四十七条","txt":"境外非政府组织、境外非政府组织代表机构有下列情形之一的，由登记管理机关吊销登记证书或者取缔临时活动；尚不构成犯罪的，由设区的市级以上人民政府公安机关对直接责任人员处十五日以下拘留："},{"i":48,"n":"第四十八条","txt":"境外非政府组织、境外非政府组织代表机构违反本法规定被撤销登记、吊销登记证书或者临时活动被取缔的，自被撤销、吊销、取缔之日起五年内，不得在中国境内再设立代表机构或者开展临时活动。"},{"i":49,"n":"第四十九条","txt":"境外非政府组织代表机构被责令限期停止活动的，由登记管理机关封存其登记证书、印章和财务凭证。对被撤销登记、吊销登记证书的，由登记管理机关收缴其登记证书、印章并公告作废。"},{"i":50,"n":"第五十条","txt":"境外人员违反本法规定的，有关机关可以依法限期出境、遣送出境或者驱逐出境。"},{"i":51,"n":"第五十一条","txt":"公安机关、有关部门和业务主管单位及其工作人员在境外非政府组织监督管理工作中，不履行职责或者滥用职权、玩忽职守、徇私舞弊的，依法追究法律责任。"},{"i":52,"n":"第五十二条","txt":"违反本法规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"境外学校、医院、自然科学和工程技术的研究机构或者学术组织与境内学校、医院、自然科学和工程技术的研究机构或者学术组织开展交流合作，按照国家有关规定办理。"},{"i":54,"n":"第五十四条","txt":"本法自2017年1月1日起施行。"}],"funvquanyibaozhangfa":[{"i":1,"n":"第一条","txt":"为了保障妇女的合法权益，促进男女平等和妇女全面发展，充分发挥妇女在全面建设社会主义现代化国家中的作用，弘扬社会主义核心价值观，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"男女平等是国家的基本国策。妇女在政治的、经济的、文化的、社会的和家庭的生活等各方面享有同男子平等的权利。"},{"i":3,"n":"第三条","txt":"坚持中国共产党对妇女权益保障工作的领导，建立政府主导、各方协同、社会参与的保障妇女权益工作机制。"},{"i":4,"n":"第四条","txt":"保障妇女的合法权益是全社会的共同责任。国家机关、社会团体、企业事业单位、基层群众性自治组织以及其他组织和个人，应当依法保障妇女的权益。"},{"i":5,"n":"第五条","txt":"国务院制定和组织实施中国妇女发展纲要，将其纳入国民经济和社会发展规划，保障和促进妇女在各领域的全面发展。"},{"i":6,"n":"第六条","txt":"中华全国妇女联合会和地方各级妇女联合会依照法律和中华全国妇女联合会章程，代表和维护各族各界妇女的利益，做好维护妇女权益、促进男女平等和妇女全面发展的工作。"},{"i":7,"n":"第七条","txt":"国家鼓励妇女自尊、自信、自立、自强，运用法律维护自身合法权益。"},{"i":8,"n":"第八条","txt":"有关机关制定或者修改涉及妇女权益的法律、法规、规章和其他规范性文件，应当听取妇女联合会的意见，充分考虑妇女的特殊权益，必要时开展男女平等评估。"},{"i":9,"n":"第九条","txt":"国家建立健全妇女发展状况统计调查制度，完善性别统计监测指标体系，定期开展妇女发展状况和权益保障统计调查和分析，发布有关信息。"},{"i":10,"n":"第十条","txt":"国家将男女平等基本国策纳入国民教育体系，开展宣传教育，增强全社会的男女平等意识，培育尊重和关爱妇女的社会风尚。"},{"i":11,"n":"第十一条","txt":"国家对保障妇女合法权益成绩显著的组织和个人，按照有关规定给予表彰和奖励。"},{"i":12,"n":"第十二条","txt":"国家保障妇女享有与男子平等的政治权利。"},{"i":13,"n":"第十三条","txt":"妇女有权通过各种途径和形式，依法参与管理国家事务、管理经济和文化事业、管理社会事务。"},{"i":14,"n":"第十四条","txt":"妇女享有与男子平等的选举权和被选举权。"},{"i":15,"n":"第十五条","txt":"国家积极培养和选拔女干部，重视培养和选拔少数民族女干部。"},{"i":16,"n":"第十六条","txt":"妇女联合会代表妇女积极参与国家和社会事务的民主协商、民主决策、民主管理和民主监督。"},{"i":17,"n":"第十七条","txt":"对于有关妇女权益保障工作的批评或者合理可行的建议，有关部门应当听取和采纳；对于有关侵害妇女权益的申诉、控告和检举，有关部门应当查清事实，负责处理，任何组织和个人不得压制或者打击报复。"},{"i":18,"n":"第十八条","txt":"国家保障妇女享有与男子平等的人身和人格权益。"},{"i":19,"n":"第十九条","txt":"妇女的人身自由不受侵犯。禁止非法拘禁和以其他非法手段剥夺或者限制妇女的人身自由；禁止非法搜查妇女的身体。"},{"i":20,"n":"第二十条","txt":"妇女的人格尊严不受侵犯。禁止用侮辱、诽谤等方式损害妇女的人格尊严。"},{"i":21,"n":"第二十一条","txt":"妇女的生命权、身体权、健康权不受侵犯。禁止虐待、遗弃、残害、买卖以及其他侵害女性生命健康权益的行为。"},{"i":22,"n":"第二十二条","txt":"禁止拐卖、绑架妇女；禁止收买被拐卖、绑架的妇女；禁止阻碍解救被拐卖、绑架的妇女。"},{"i":23,"n":"第二十三条","txt":"禁止违背妇女意愿，以言语、文字、图像、肢体行为等方式对其实施性骚扰。"},{"i":24,"n":"第二十四条","txt":"学校应当根据女学生的年龄阶段，进行生理卫生、心理健康和自我保护教育，在教育、管理、设施等方面采取措施，提高其防范性侵害、性骚扰的自我保护意识和能力，保障女学生的人身安全和身心健康发展。"},{"i":25,"n":"第二十五条","txt":"用人单位应当采取下列措施预防和制止对妇女的性骚扰："},{"i":26,"n":"第二十六条","txt":"住宿经营者应当及时准确登记住宿人员信息，健全住宿服务规章制度，加强安全保障措施；发现可能侵害妇女权益的违法犯罪行为，应当及时向公安机关报告。"},{"i":27,"n":"第二十七条","txt":"禁止卖淫、嫖娼；禁止组织、强迫、引诱、容留、介绍妇女卖淫或者对妇女进行猥亵活动；禁止组织、强迫、引诱、容留、介绍妇女在任何场所或者利用网络进行淫秽表演活动。"},{"i":28,"n":"第二十八条","txt":"妇女的姓名权、肖像权、名誉权、荣誉权、隐私权和个人信息等人格权益受法律保护。"},{"i":29,"n":"第二十九条","txt":"禁止以恋爱、交友为由或者在终止恋爱关系、离婚之后，纠缠、骚扰妇女，泄露、传播妇女隐私和个人信息。"},{"i":30,"n":"第三十条","txt":"国家建立健全妇女健康服务体系，保障妇女享有基本医疗卫生服务，开展妇女常见病、多发病的预防、筛查和诊疗，提高妇女健康水平。"},{"i":31,"n":"第三十一条","txt":"县级以上地方人民政府应当设立妇幼保健机构，为妇女提供保健以及常见病防治服务。"},{"i":32,"n":"第三十二条","txt":"妇女依法享有生育子女的权利，也有不生育子女的自由。"},{"i":33,"n":"第三十三条","txt":"国家实行婚前、孕前、孕产期和产后保健制度，逐步建立妇女全生育周期系统保健制度。医疗保健机构应当提供安全、有效的医疗保健服务，保障妇女生育安全和健康。"},{"i":34,"n":"第三十四条","txt":"各级人民政府在规划、建设基础设施时，应当考虑妇女的特殊需求，配备满足妇女需要的公共厕所和母婴室等公共设施。"},{"i":35,"n":"第三十五条","txt":"国家保障妇女享有与男子平等的文化教育权利。"},{"i":36,"n":"第三十六条","txt":"父母或者其他监护人应当履行保障适龄女性未成年人接受并完成义务教育的义务。"},{"i":37,"n":"第三十七条","txt":"学校和有关部门应当执行国家有关规定，保障妇女在入学、升学、授予学位、派出留学、就业指导和服务等方面享有与男子平等的权利。"},{"i":38,"n":"第三十八条","txt":"各级人民政府应当依照规定把扫除妇女中的文盲、半文盲工作，纳入扫盲和扫盲后继续教育规划，采取符合妇女特点的组织形式和工作方法，组织、监督有关部门具体实施。"},{"i":39,"n":"第三十九条","txt":"国家健全全民终身学习体系，为妇女终身学习创造条件。"},{"i":40,"n":"第四十条","txt":"国家机关、社会团体和企业事业单位应当执行国家有关规定，保障妇女从事科学、技术、文学、艺术和其他文化活动，享有与男子平等的权利。"},{"i":41,"n":"第四十一条","txt":"国家保障妇女享有与男子平等的劳动权利和社会保障权利。"},{"i":42,"n":"第四十二条","txt":"各级人民政府和有关部门应当完善就业保障政策措施，防止和纠正就业性别歧视，为妇女创造公平的就业创业环境，为就业困难的妇女提供必要的扶持和援助。"},{"i":43,"n":"第四十三条","txt":"用人单位在招录（聘）过程中，除国家另有规定外，不得实施下列行为："},{"i":44,"n":"第四十四条","txt":"用人单位在录（聘）用女职工时，应当依法与其签订劳动（聘用）合同或者服务协议，劳动（聘用）合同或者服务协议中应当具备女职工特殊保护条款，并不得规定限制女职工结婚、生育等内容。"},{"i":45,"n":"第四十五条","txt":"实行男女同工同酬。妇女在享受福利待遇方面享有与男子平等的权利。"},{"i":46,"n":"第四十六条","txt":"在晋职、晋级、评聘专业技术职称和职务、培训等方面，应当坚持男女平等的原则，不得歧视妇女。"},{"i":47,"n":"第四十七条","txt":"用人单位应当根据妇女的特点，依法保护妇女在工作和劳动时的安全、健康以及休息的权利。"},{"i":48,"n":"第四十八条","txt":"用人单位不得因结婚、怀孕、产假、哺乳等情形，降低女职工的工资和福利待遇，限制女职工晋职、晋级、评聘专业技术职称和职务，辞退女职工，单方解除劳动（聘用）合同或者服务协议。"},{"i":49,"n":"第四十九条","txt":"人力资源和社会保障部门应当将招聘、录取、晋职、晋级、评聘专业技术职称和职务、培训、辞退等过程中的性别歧视行为纳入劳动保障监察范围。"},{"i":50,"n":"第五十条","txt":"国家发展社会保障事业，保障妇女享有社会保险、社会救助和社会福利等权益。"},{"i":51,"n":"第五十一条","txt":"国家实行生育保险制度，建立健全婴幼儿托育服务等与生育相关的其他保障制度。"},{"i":52,"n":"第五十二条","txt":"各级人民政府和有关部门应当采取必要措施，加强贫困妇女、老龄妇女、残疾妇女等困难妇女的权益保障，按照有关规定为其提供生活帮扶、就业创业支持等关爱服务。"},{"i":53,"n":"第五十三条","txt":"国家保障妇女享有与男子平等的财产权利。"},{"i":54,"n":"第五十四条","txt":"在夫妻共同财产、家庭共有财产关系中，不得侵害妇女依法享有的权益。"},{"i":55,"n":"第五十五条","txt":"妇女在农村集体经济组织成员身份确认、土地承包经营、集体经济组织收益分配、土地征收补偿安置或者征用补偿以及宅基地使用等方面，享有与男子平等的权利。"},{"i":56,"n":"第五十六条","txt":"村民自治章程、村规民约，村民会议、村民代表会议的决定以及其他涉及村民利益事项的决定，不得以妇女未婚、结婚、离婚、丧偶、户无男性等为由，侵害妇女在农村集体经济组织中的各项权益。"},{"i":57,"n":"第五十七条","txt":"国家保护妇女在城镇集体所有财产关系中的权益。妇女依照法律、法规的规定享有相关权益。"},{"i":58,"n":"第五十八条","txt":"妇女享有与男子平等的继承权。妇女依法行使继承权，不受歧视。"},{"i":59,"n":"第五十九条","txt":"丧偶儿媳对公婆尽了主要赡养义务的，作为第一顺序继承人，其继承权不受子女代位继承的影响。"},{"i":60,"n":"第六十条","txt":"国家保障妇女享有与男子平等的婚姻家庭权利。"},{"i":61,"n":"第六十一条","txt":"国家保护妇女的婚姻自主权。禁止干涉妇女的结婚、离婚自由。"},{"i":62,"n":"第六十二条","txt":"国家鼓励男女双方在结婚登记前，共同进行医学检查或者相关健康体检。"},{"i":63,"n":"第六十三条","txt":"婚姻登记机关应当提供婚姻家庭辅导服务，引导当事人建立平等、和睦、文明的婚姻家庭关系。"},{"i":64,"n":"第六十四条","txt":"女方在怀孕期间、分娩后一年内或者终止妊娠后六个月内，男方不得提出离婚；但是，女方提出离婚或者人民法院认为确有必要受理男方离婚请求的除外。"},{"i":65,"n":"第六十五条","txt":"禁止对妇女实施家庭暴力。"},{"i":66,"n":"第六十六条","txt":"妇女对夫妻共同财产享有与其配偶平等的占有、使用、收益和处分的权利，不受双方收入状况等情形的影响。"},{"i":67,"n":"第六十七条","txt":"离婚诉讼期间，夫妻一方申请查询登记在对方名下财产状况且确因客观原因不能自行收集的，人民法院应当进行调查取证，有关部门和单位应当予以协助。"},{"i":68,"n":"第六十八条","txt":"夫妻双方应当共同负担家庭义务，共同照顾家庭生活。"},{"i":69,"n":"第六十九条","txt":"离婚时，分割夫妻共有的房屋或者处理夫妻共同租住的房屋，由双方协议解决；协议不成的，可以向人民法院提起诉讼。"},{"i":70,"n":"第七十条","txt":"父母双方对未成年子女享有平等的监护权。"},{"i":71,"n":"第七十一条","txt":"女方丧失生育能力的，在离婚处理子女抚养问题时，应当在最有利于未成年子女的条件下，优先考虑女方的抚养要求。"},{"i":72,"n":"第七十二条","txt":"对侵害妇女合法权益的行为，任何组织和个人都有权予以劝阻、制止或者向有关部门提出控告或者检举。有关部门接到控告或者检举后，应当依法及时处理，并为控告人、检举人保密。"},{"i":73,"n":"第七十三条","txt":"妇女的合法权益受到侵害的，可以向妇女联合会等妇女组织求助。妇女联合会等妇女组织应当维护被侵害妇女的合法权益，有权要求并协助有关部门或者单位查处。有关部门或者单位应当依法查处，并予以答复；不予处理或者处理不当的，县级以上人民政府负责妇女儿童工作的机构、妇女联合会可以向其提出督促处理意见，必要时可以提请同级人民政府开展督查。"},{"i":74,"n":"第七十四条","txt":"用人单位侵害妇女劳动和社会保障权益的，人力资源和社会保障部门可以联合工会、妇女联合会约谈用人单位，依法进行监督并要求其限期纠正。"},{"i":75,"n":"第七十五条","txt":"妇女在农村集体经济组织成员身份确认等方面权益受到侵害的，可以申请乡镇人民政府等进行协调，或者向人民法院起诉。"},{"i":76,"n":"第七十六条","txt":"县级以上人民政府应当开通全国统一的妇女权益保护服务热线，及时受理、移送有关侵害妇女合法权益的投诉、举报；有关部门或者单位接到投诉、举报后，应当及时予以处置。"},{"i":77,"n":"第七十七条","txt":"侵害妇女合法权益，导致社会公共利益受损的，检察机关可以发出检察建议；有下列情形之一的，检察机关可以依法提起公益诉讼："},{"i":78,"n":"第七十八条","txt":"国家机关、社会团体、企业事业单位对侵害妇女权益的行为，可以支持受侵害的妇女向人民法院起诉。"},{"i":79,"n":"第七十九条","txt":"违反本法第二十二条第二款规定，未履行报告义务的，依法对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":80,"n":"第八十条","txt":"违反本法规定，对妇女实施性骚扰的，由公安机关给予批评教育或者出具告诫书，并由所在单位依法给予处分。"},{"i":81,"n":"第八十一条","txt":"违反本法第二十六条规定，未履行报告等义务的，依法给予警告、责令停业整顿或者吊销营业执照、吊销相关许可证，并处一万元以上五万元以下罚款。"},{"i":82,"n":"第八十二条","txt":"违反本法规定，通过大众传播媒介或者其他方式贬低损害妇女人格的，由公安、网信、文化旅游、广播电视、新闻出版或者其他有关部门依据各自的职权责令改正，并依法给予行政处罚。"},{"i":83,"n":"第八十三条","txt":"用人单位违反本法第四十三条和第四十八条规定的，由人力资源和社会保障部门责令改正；拒不改正或者情节严重的，处一万元以上五万元以下罚款。"},{"i":84,"n":"第八十四条","txt":"违反本法规定，对侵害妇女权益的申诉、控告、检举，推诿、拖延、压制不予查处，或者对提出申诉、控告、检举的人进行打击报复的，依法责令改正，并对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":85,"n":"第八十五条","txt":"违反本法规定，侵害妇女的合法权益，其他法律、法规规定行政处罚的，从其规定；造成财产损失或者人身损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":86,"n":"第八十六条","txt":"本法自2023年1月1日起施行。"}],"anquanshengchanfa":[{"i":1,"n":"第一条","txt":"为了加强安全生产工作，防止和减少生产安全事故，保障人民群众生命和财产安全，促进经济社会持续健康发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域内从事生产经营活动的单位（以下统称生产经营单位）的安全生产，适用本法；有关法律、行政法规对消防安全和道路交通安全、铁路交通安全、水上交通安全、民用航空安全以及核与辐射安全、特种设备安全另有规定的，适用其规定。"},{"i":3,"n":"第三条","txt":"安全生产工作坚持中国共产党的领导。"},{"i":4,"n":"第四条","txt":"生产经营单位必须遵守本法和其他有关安全生产的法律、法规，加强安全生产管理，建立健全全员安全生产责任制和安全生产规章制度，加大对安全生产资金、物资、技术、人员的投入保障力度，改善安全生产条件，加强安全生产标准化、信息化建设，构建安全风险分级管控和隐患排查治理双重预防机制，健全风险防范化解机制，提高安全生产水平，确保安全生产。"},{"i":5,"n":"第五条","txt":"生产经营单位的主要负责人是本单位安全生产第一责任人，对本单位的安全生产工作全面负责。其他负责人对职责范围内的安全生产工作负责。"},{"i":6,"n":"第六条","txt":"生产经营单位的从业人员有依法获得安全生产保障的权利，并应当依法履行安全生产方面的义务。"},{"i":7,"n":"第七条","txt":"工会依法对安全生产工作进行监督。"},{"i":8,"n":"第八条","txt":"国务院和县级以上地方各级人民政府应当根据国民经济和社会发展规划制定安全生产规划，并组织实施。安全生产规划应当与国土空间规划等相关规划相衔接。"},{"i":9,"n":"第九条","txt":"国务院和县级以上地方各级人民政府应当加强对安全生产工作的领导，建立健全安全生产工作协调机制，支持、督促各有关部门依法履行安全生产监督管理职责，及时协调、解决安全生产监督管理中存在的重大问题。"},{"i":10,"n":"第十条","txt":"国务院应急管理部门依照本法，对全国安全生产工作实施综合监督管理；县级以上地方各级人民政府应急管理部门依照本法，对本行政区域内安全生产工作实施综合监督管理。"},{"i":11,"n":"第十一条","txt":"国务院有关部门应当按照保障安全生产的要求，依法及时制定有关的国家标准或者行业标准，并根据科技进步和经济发展适时修订。"},{"i":12,"n":"第十二条","txt":"国务院有关部门按照职责分工负责安全生产强制性国家标准的项目提出、组织起草、征求意见、技术审查。国务院应急管理部门统筹提出安全生产强制性国家标准的立项计划。国务院标准化行政主管部门负责安全生产强制性国家标准的立项、编号、对外通报和授权批准发布工作。国务院标准化行政主管部门、有关部门依据法定职责对安全生产强制性国家标准的实施进行监督检查。"},{"i":13,"n":"第十三条","txt":"各级人民政府及其有关部门应当采取多种形式，加强对有关安全生产的法律、法规和安全生产知识的宣传，增强全社会的安全生产意识。"},{"i":14,"n":"第十四条","txt":"有关协会组织依照法律、行政法规和章程，为生产经营单位提供安全生产方面的信息、培训等服务，发挥自律作用，促进生产经营单位加强安全生产管理。"},{"i":15,"n":"第十五条","txt":"依法设立的为安全生产提供技术、管理服务的机构，依照法律、行政法规和执业准则，接受生产经营单位的委托为其安全生产工作提供技术、管理服务。"},{"i":16,"n":"第十六条","txt":"国家实行生产安全事故责任追究制度，依照本法和有关法律、法规的规定，追究生产安全事故责任单位和责任人员的法律责任。"},{"i":17,"n":"第十七条","txt":"县级以上各级人民政府应当组织负有安全生产监督管理职责的部门依法编制安全生产权力和责任清单，公开并接受社会监督。"},{"i":18,"n":"第十八条","txt":"国家鼓励和支持安全生产科学技术研究和安全生产先进技术的推广应用，提高安全生产水平。"},{"i":19,"n":"第十九条","txt":"国家对在改善安全生产条件、防止生产安全事故、参加抢险救护等方面取得显著成绩的单位和个人，给予奖励。"},{"i":20,"n":"第二十条","txt":"生产经营单位应当具备本法和有关法律、行政法规和国家标准或者行业标准规定的安全生产条件；不具备安全生产条件的，不得从事生产经营活动。"},{"i":21,"n":"第二十一条","txt":"生产经营单位的主要负责人对本单位安全生产工作负有下列职责："},{"i":22,"n":"第二十二条","txt":"生产经营单位的全员安全生产责任制应当明确各岗位的责任人员、责任范围和考核标准等内容。"},{"i":23,"n":"第二十三条","txt":"生产经营单位应当具备的安全生产条件所必需的资金投入，由生产经营单位的决策机构、主要负责人或者个人经营的投资人予以保证，并对由于安全生产所必需的资金投入不足导致的后果承担责任。"},{"i":24,"n":"第二十四条","txt":"矿山、金属冶炼、建筑施工、运输单位和危险物品的生产、经营、储存、装卸单位，应当设置安全生产管理机构或者配备专职安全生产管理人员。"},{"i":25,"n":"第二十五条","txt":"生产经营单位的安全生产管理机构以及安全生产管理人员履行下列职责："},{"i":26,"n":"第二十六条","txt":"生产经营单位的安全生产管理机构以及安全生产管理人员应当恪尽职守，依法履行职责。"},{"i":27,"n":"第二十七条","txt":"生产经营单位的主要负责人和安全生产管理人员必须具备与本单位所从事的生产经营活动相应的安全生产知识和管理能力。"},{"i":28,"n":"第二十八条","txt":"生产经营单位应当对从业人员进行安全生产教育和培训，保证从业人员具备必要的安全生产知识，熟悉有关的安全生产规章制度和安全操作规程，掌握本岗位的安全操作技能，了解事故应急处理措施，知悉自身在安全生产方面的权利和义务。未经安全生产教育和培训合格的从业人员，不得上岗作业。"},{"i":29,"n":"第二十九条","txt":"生产经营单位采用新工艺、新技术、新材料或者使用新设备，必须了解、掌握其安全技术特性，采取有效的安全防护措施，并对从业人员进行专门的安全生产教育和培训。"},{"i":30,"n":"第三十条","txt":"生产经营单位的特种作业人员必须按照国家有关规定经专门的安全作业培训，取得相应资格，方可上岗作业。"},{"i":31,"n":"第三十一条","txt":"生产经营单位新建、改建、扩建工程项目（以下统称建设项目）的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。"},{"i":32,"n":"第三十二条","txt":"矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目，应当按照国家有关规定进行安全评价。"},{"i":33,"n":"第三十三条","txt":"建设项目安全设施的设计人、设计单位应当对安全设施设计负责。"},{"i":34,"n":"第三十四条","txt":"矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的施工单位必须按照批准的安全设施设计施工，并对安全设施的工程质量负责。"},{"i":35,"n":"第三十五条","txt":"生产经营单位应当在有较大危险因素的生产经营场所和有关设施、设备上，设置明显的安全警示标志。"},{"i":36,"n":"第三十六条","txt":"安全设备的设计、制造、安装、使用、检测、维修、改造和报废，应当符合国家标准或者行业标准。"},{"i":37,"n":"第三十七条","txt":"生产经营单位使用的危险物品的容器、运输工具，以及涉及人身安全、危险性较大的海洋石油开采特种设备和矿山井下特种设备，必须按照国家有关规定，由专业生产单位生产，并经具有专业资质的检测、检验机构检测、检验合格，取得安全使用证或者安全标志，方可投入使用。检测、检验机构对检测、检验结果负责。"},{"i":38,"n":"第三十八条","txt":"国家对严重危及生产安全的工艺、设备实行淘汰制度，具体目录由国务院应急管理部门会同国务院有关部门制定并公布。法律、行政法规对目录的制定另有规定的，适用其规定。"},{"i":39,"n":"第三十九条","txt":"生产、经营、运输、储存、使用危险物品或者处置废弃危险物品的，由有关主管部门依照有关法律、法规的规定和国家标准或者行业标准审批并实施监督管理。"},{"i":40,"n":"第四十条","txt":"生产经营单位对重大危险源应当登记建档，进行定期检测、评估、监控，并制定应急预案，告知从业人员和相关人员在紧急情况下应当采取的应急措施。"},{"i":41,"n":"第四十一条","txt":"生产经营单位应当建立安全风险分级管控制度，按照安全风险分级采取相应的管控措施。"},{"i":42,"n":"第四十二条","txt":"生产、经营、储存、使用危险物品的车间、商店、仓库不得与员工宿舍在同一座建筑物内，并应当与员工宿舍保持安全距离。"},{"i":43,"n":"第四十三条","txt":"生产经营单位进行爆破、吊装、动火、临时用电以及国务院应急管理部门会同国务院有关部门规定的其他危险作业，应当安排专门人员进行现场安全管理，确保操作规程的遵守和安全措施的落实。"},{"i":44,"n":"第四十四条","txt":"生产经营单位应当教育和督促从业人员严格执行本单位的安全生产规章制度和安全操作规程；并向从业人员如实告知作业场所和工作岗位存在的危险因素、防范措施以及事故应急措施。"},{"i":45,"n":"第四十五条","txt":"生产经营单位必须为从业人员提供符合国家标准或者行业标准的劳动防护用品，并监督、教育从业人员按照使用规则佩戴、使用。"},{"i":46,"n":"第四十六条","txt":"生产经营单位的安全生产管理人员应当根据本单位的生产经营特点，对安全生产状况进行经常性检查；对检查中发现的安全问题，应当立即处理；不能处理的，应当及时报告本单位有关负责人，有关负责人应当及时处理。检查及处理情况应当如实记录在案。"},{"i":47,"n":"第四十七条","txt":"生产经营单位应当安排用于配备劳动防护用品、进行安全生产培训的经费。"},{"i":48,"n":"第四十八条","txt":"两个以上生产经营单位在同一作业区域内进行生产经营活动，可能危及对方生产安全的，应当签订安全生产管理协议，明确各自的安全生产管理职责和应当采取的安全措施，并指定专职安全生产管理人员进行安全检查与协调。"},{"i":49,"n":"第四十九条","txt":"生产经营单位不得将生产经营项目、场所、设备发包或者出租给不具备安全生产条件或者相应资质的单位或者个人。"},{"i":50,"n":"第五十条","txt":"生产经营单位发生生产安全事故时，单位的主要负责人应当立即组织抢救，并不得在事故调查处理期间擅离职守。"},{"i":51,"n":"第五十一条","txt":"生产经营单位必须依法参加工伤保险，为从业人员缴纳保险费。"},{"i":52,"n":"第五十二条","txt":"生产经营单位与从业人员订立的劳动合同，应当载明有关保障从业人员劳动安全、防止职业危害的事项，以及依法为从业人员办理工伤保险的事项。"},{"i":53,"n":"第五十三条","txt":"生产经营单位的从业人员有权了解其作业场所和工作岗位存在的危险因素、防范措施及事故应急措施，有权对本单位的安全生产工作提出建议。"},{"i":54,"n":"第五十四条","txt":"从业人员有权对本单位安全生产工作中存在的问题提出批评、检举、控告；有权拒绝违章指挥和强令冒险作业。"},{"i":55,"n":"第五十五条","txt":"从业人员发现直接危及人身安全的紧急情况时，有权停止作业或者在采取可能的应急措施后撤离作业场所。"},{"i":56,"n":"第五十六条","txt":"生产经营单位发生生产安全事故后，应当及时采取措施救治有关人员。"},{"i":57,"n":"第五十七条","txt":"从业人员在作业过程中，应当严格落实岗位安全责任，遵守本单位的安全生产规章制度和操作规程，服从管理，正确佩戴和使用劳动防护用品。"},{"i":58,"n":"第五十八条","txt":"从业人员应当接受安全生产教育和培训，掌握本职工作所需的安全生产知识，提高安全生产技能，增强事故预防和应急处理能力。"},{"i":59,"n":"第五十九条","txt":"从业人员发现事故隐患或者其他不安全因素，应当立即向现场安全生产管理人员或者本单位负责人报告；接到报告的人员应当及时予以处理。"},{"i":60,"n":"第六十条","txt":"工会有权对建设项目的安全设施与主体工程同时设计、同时施工、同时投入生产和使用进行监督，提出意见。"},{"i":61,"n":"第六十一条","txt":"生产经营单位使用被派遣劳动者的，被派遣劳动者享有本法规定的从业人员的权利，并应当履行本法规定的从业人员的义务。"},{"i":62,"n":"第六十二条","txt":"县级以上地方各级人民政府应当根据本行政区域内的安全生产状况，组织有关部门按照职责分工，对本行政区域内容易发生重大生产安全事故的生产经营单位进行严格检查。"},{"i":63,"n":"第六十三条","txt":"负有安全生产监督管理职责的部门依照有关法律、法规的规定，对涉及安全生产的事项需要审查批准（包括批准、核准、许可、注册、认证、颁发证照等，下同）或者验收的，必须严格依照有关法律、法规和国家标准或者行业标准规定的安全生产条件和程序进行审查；不符合有关法律、法规和国家标准或者行业标准规定的安全生产条件的，不得批准或者验收通过。对未依法取得批准或者验收合格的单位擅自从事有关活动的，负责行政审批的部门发现或者接到举报后应当立即予以取缔，并依法予以处理。对已经依法取得批准的单位，负责行政审批的部门发现其不再具备安全生产条件的，应当撤销原批准。"},{"i":64,"n":"第六十四条","txt":"负有安全生产监督管理职责的部门对涉及安全生产的事项进行审查、验收，不得收取费用；不得要求接受审查、验收的单位购买其指定品牌或者指定生产、销售单位的安全设备、器材或者其他产品。"},{"i":65,"n":"第六十五条","txt":"应急管理部门和其他负有安全生产监督管理职责的部门依法开展安全生产行政执法工作，对生产经营单位执行有关安全生产的法律、法规和国家标准或者行业标准的情况进行监督检查，行使以下职权："},{"i":66,"n":"第六十六条","txt":"生产经营单位对负有安全生产监督管理职责的部门的监督检查人员（以下统称安全生产监督检查人员）依法履行监督检查职责，应当予以配合，不得拒绝、阻挠。"},{"i":67,"n":"第六十七条","txt":"安全生产监督检查人员应当忠于职守，坚持原则，秉公执法。"},{"i":68,"n":"第六十八条","txt":"安全生产监督检查人员应当将检查的时间、地点、内容、发现的问题及其处理情况，作出书面记录，并由检查人员和被检查单位的负责人签字；被检查单位的负责人拒绝签字的，检查人员应当将情况记录在案，并向负有安全生产监督管理职责的部门报告。"},{"i":69,"n":"第六十九条","txt":"负有安全生产监督管理职责的部门在监督检查中，应当互相配合，实行联合检查；确需分别进行检查的，应当互通情况，发现存在的安全问题应当由其他有关部门进行处理的，应当及时移送其他有关部门并形成记录备查，接受移送的部门应当及时进行处理。"},{"i":70,"n":"第七十条","txt":"负有安全生产监督管理职责的部门依法对存在重大事故隐患的生产经营单位作出停产停业、停止施工、停止使用相关设施或者设备的决定，生产经营单位应当依法执行，及时消除事故隐患。生产经营单位拒不执行，有发生生产安全事故的现实危险的，在保证安全的前提下，经本部门主要负责人批准，负有安全生产监督管理职责的部门可以采取通知有关单位停止供电、停止供应民用爆炸物品等措施，强制生产经营单位履行决定。通知应当采用书面形式，有关单位应当予以配合。"},{"i":71,"n":"第七十一条","txt":"监察机关依照监察法的规定，对负有安全生产监督管理职责的部门及其工作人员履行安全生产监督管理职责实施监察。"},{"i":72,"n":"第七十二条","txt":"承担安全评价、认证、检测、检验职责的机构应当具备国家规定的资质条件，并对其作出的安全评价、认证、检测、检验结果的合法性、真实性负责。资质条件由国务院应急管理部门会同国务院有关部门制定。"},{"i":73,"n":"第七十三条","txt":"负有安全生产监督管理职责的部门应当建立举报制度，公开举报电话、信箱或者电子邮件地址等网络举报平台，受理有关安全生产的举报；受理的举报事项经调查核实后，应当形成书面材料；需要落实整改措施的，报经有关负责人签字并督促落实。对不属于本部门职责，需要由其他有关部门进行调查处理的，转交其他有关部门处理。"},{"i":74,"n":"第七十四条","txt":"任何单位或者个人对事故隐患或者安全生产违法行为，均有权向负有安全生产监督管理职责的部门报告或者举报。"},{"i":75,"n":"第七十五条","txt":"居民委员会、村民委员会发现其所在区域内的生产经营单位存在事故隐患或者安全生产违法行为时，应当向当地人民政府或者有关部门报告。"},{"i":76,"n":"第七十六条","txt":"县级以上各级人民政府及其有关部门对报告重大事故隐患或者举报安全生产违法行为的有功人员，给予奖励。具体奖励办法由国务院应急管理部门会同国务院财政部门制定。"},{"i":77,"n":"第七十七条","txt":"新闻、出版、广播、电影、电视等单位有进行安全生产公益宣传教育的义务，有对违反安全生产法律、法规的行为进行舆论监督的权利。"},{"i":78,"n":"第七十八条","txt":"负有安全生产监督管理职责的部门应当建立安全生产违法行为信息库，如实记录生产经营单位及其有关从业人员的安全生产违法行为信息；对违法行为情节严重的生产经营单位及其有关从业人员，应当及时向社会公告，并通报行业主管部门、投资主管部门、自然资源主管部门、生态环境主管部门、证券监督管理机构以及有关金融机构。有关部门和机构应当对存在失信行为的生产经营单位及其有关从业人员采取加大执法检查频次、暂停项目审批、上调有关保险费率、行业或者职业禁入等联合惩戒措施，并向社会公示。"},{"i":79,"n":"第七十九条","txt":"国家加强生产安全事故应急能力建设，在重点行业、领域建立应急救援基地和应急救援队伍，并由国家安全生产应急救援机构统一协调指挥；鼓励生产经营单位和其他社会力量建立应急救援队伍，配备相应的应急救援装备和物资，提高应急救援的专业化水平。"},{"i":80,"n":"第八十条","txt":"县级以上地方各级人民政府应当组织有关部门制定本行政区域内生产安全事故应急救援预案，建立应急救援体系。"},{"i":81,"n":"第八十一条","txt":"生产经营单位应当制定本单位生产安全事故应急救援预案，与所在地县级以上地方人民政府组织制定的生产安全事故应急救援预案相衔接，并定期组织演练。"},{"i":82,"n":"第八十二条","txt":"危险物品的生产、经营、储存单位以及矿山、金属冶炼、城市轨道交通运营、建筑施工单位应当建立应急救援组织；生产经营规模较小的，可以不建立应急救援组织，但应当指定兼职的应急救援人员。"},{"i":83,"n":"第八十三条","txt":"生产经营单位发生生产安全事故后，事故现场有关人员应当立即报告本单位负责人。"},{"i":84,"n":"第八十四条","txt":"负有安全生产监督管理职责的部门接到事故报告后，应当立即按照国家有关规定上报事故情况。负有安全生产监督管理职责的部门和有关地方人民政府对事故情况不得隐瞒不报、谎报或者迟报。"},{"i":85,"n":"第八十五条","txt":"有关地方人民政府和负有安全生产监督管理职责的部门的负责人接到生产安全事故报告后，应当按照生产安全事故应急救援预案的要求立即赶到事故现场，组织事故抢救。"},{"i":86,"n":"第八十六条","txt":"事故调查处理应当按照科学严谨、依法依规、实事求是、注重实效的原则，及时、准确地查清事故原因，查明事故性质和责任，评估应急处置工作，总结事故教训，提出整改措施，并对事故责任单位和人员提出处理建议。事故调查报告应当依法及时向社会公布。事故调查和处理的具体办法由国务院制定。"},{"i":87,"n":"第八十七条","txt":"生产经营单位发生生产安全事故，经调查确定为责任事故的，除了应当查明事故单位的责任并依法予以追究外，还应当查明对安全生产的有关事项负有审查批准和监督职责的行政部门的责任，对有失职、渎职行为的，依照本法第九十条的规定追究法律责任。"},{"i":88,"n":"第八十八条","txt":"任何单位和个人不得阻挠和干涉对事故的依法调查处理。"},{"i":89,"n":"第八十九条","txt":"县级以上地方各级人民政府应急管理部门应当定期统计分析本行政区域内发生生产安全事故的情况，并定期向社会公布。"},{"i":90,"n":"第九十条","txt":"负有安全生产监督管理职责的部门的工作人员，有下列行为之一的，给予降级或者撤职的处分；构成犯罪的，依照刑法有关规定追究刑事责任："},{"i":91,"n":"第九十一条","txt":"负有安全生产监督管理职责的部门，要求被审查、验收的单位购买其指定的安全设备、器材或者其他产品的，在对安全生产事项的审查、验收中收取费用的，由其上级机关或者监察机关责令改正，责令退还收取的费用；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":92,"n":"第九十二条","txt":"承担安全评价、认证、检测、检验职责的机构出具失实报告的，责令停业整顿，并处三万元以上十万元以下的罚款；给他人造成损害的，依法承担赔偿责任。"},{"i":93,"n":"第九十三条","txt":"生产经营单位的决策机构、主要负责人或者个人经营的投资人不依照本法规定保证安全生产所必需的资金投入，致使生产经营单位不具备安全生产条件的，责令限期改正，提供必需的资金；逾期未改正的，责令生产经营单位停产停业整顿。"},{"i":94,"n":"第九十四条","txt":"生产经营单位的主要负责人未履行本法规定的安全生产管理职责的，责令限期改正，处二万元以上五万元以下的罚款；逾期未改正的，处五万元以上十万元以下的罚款，责令生产经营单位停产停业整顿。"},{"i":95,"n":"第九十五条","txt":"生产经营单位的主要负责人未履行本法规定的安全生产管理职责，导致发生生产安全事故的，由应急管理部门依照下列规定处以罚款："},{"i":96,"n":"第九十六条","txt":"生产经营单位的其他负责人和安全生产管理人员未履行本法规定的安全生产管理职责的，责令限期改正，处一万元以上三万元以下的罚款；导致发生生产安全事故的，暂停或者吊销其与安全生产有关的资格，并处上一年年收入百分之二十以上百分之五十以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":97,"n":"第九十七条","txt":"生产经营单位有下列行为之一的，责令限期改正，处十万元以下的罚款；逾期未改正的，责令停产停业整顿，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款："},{"i":98,"n":"第九十八条","txt":"生产经营单位有下列行为之一的，责令停止建设或者停产停业整顿，限期改正，并处十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；逾期未改正的，处五十万元以上一百万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任："},{"i":99,"n":"第九十九条","txt":"生产经营单位有下列行为之一的，责令限期改正，处五万元以下的罚款；逾期未改正的，处五万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；情节严重的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任："},{"i":100,"n":"第一百条","txt":"未经依法批准，擅自生产、经营、运输、储存、使用危险物品或者处置废弃危险物品的，依照有关危险物品安全管理的法律、行政法规的规定予以处罚；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":101,"n":"第一百零一条","txt":"生产经营单位有下列行为之一的，责令限期改正，处十万元以下的罚款；逾期未改正的，责令停产停业整顿，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任："},{"i":102,"n":"第一百零二条","txt":"生产经营单位未采取措施消除事故隐患的，责令立即消除或者限期消除，处五万元以下的罚款；生产经营单位拒不执行的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":103,"n":"第一百零三条","txt":"生产经营单位将生产经营项目、场所、设备发包或者出租给不具备安全生产条件或者相应资质的单位或者个人的，责令限期改正，没收违法所得；违法所得十万元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足十万元的，单处或者并处十万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；导致发生生产安全事故给他人造成损害的，与承包方、承租方承担连带赔偿责任。"},{"i":104,"n":"第一百零四条","txt":"两个以上生产经营单位在同一作业区域内进行可能危及对方安全生产的生产经营活动，未签订安全生产管理协议或者未指定专职安全生产管理人员进行安全检查与协调的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业。"},{"i":105,"n":"第一百零五条","txt":"生产经营单位有下列行为之一的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任："},{"i":106,"n":"第一百零六条","txt":"生产经营单位与从业人员订立协议，免除或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议无效；对生产经营单位的主要负责人、个人经营的投资人处二万元以上十万元以下的罚款。"},{"i":107,"n":"第一百零七条","txt":"生产经营单位的从业人员不落实岗位安全责任，不服从管理，违反安全生产规章制度或者操作规程的，由生产经营单位给予批评教育，依照有关规章制度给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":108,"n":"第一百零八条","txt":"违反本法规定，生产经营单位拒绝、阻碍负有安全生产监督管理职责的部门依法实施监督检查的，责令改正；拒不改正的，处二万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":109,"n":"第一百零九条","txt":"高危行业、领域的生产经营单位未按照国家规定投保安全生产责任保险的，责令限期改正，处五万元以上十万元以下的罚款；逾期未改正的，处十万元以上二十万元以下的罚款。"},{"i":110,"n":"第一百一十条","txt":"生产经营单位的主要负责人在本单位发生生产安全事故时，不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的，给予降级、撤职的处分，并由应急管理部门处上一年年收入百分之六十至百分之一百的罚款；对逃匿的处十五日以下拘留；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":111,"n":"第一百一十一条","txt":"有关地方人民政府、负有安全生产监督管理职责的部门，对生产安全事故隐瞒不报、谎报或者迟报的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。"},{"i":112,"n":"第一百一十二条","txt":"生产经营单位违反本法规定，被责令改正且受到罚款处罚，拒不改正的，负有安全生产监督管理职责的部门可以自作出责令改正之日的次日起，按照原处罚数额按日连续处罚。"},{"i":113,"n":"第一百一十三条","txt":"生产经营单位存在下列情形之一的，负有安全生产监督管理职责的部门应当提请地方人民政府予以关闭，有关部门应当依法吊销其有关证照。生产经营单位主要负责人五年内不得担任任何生产经营单位的主要负责人；情节严重的，终身不得担任本行业生产经营单位的主要负责人："},{"i":114,"n":"第一百一十四条","txt":"发生生产安全事故，对负有责任的生产经营单位除要求其依法承担相应的赔偿等责任外，由应急管理部门依照下列规定处以罚款："},{"i":115,"n":"第一百一十五条","txt":"本法规定的行政处罚，由应急管理部门和其他负有安全生产监督管理职责的部门按照职责分工决定；其中，根据本法第九十五条、第一百一十条、第一百一十四条的规定应当给予民航、铁路、电力行业的生产经营单位及其主要负责人行政处罚的，也可以由主管的负有安全生产监督管理职责的部门进行处罚。予以关闭的行政处罚，由负有安全生产监督管理职责的部门报请县级以上人民政府按照国务院规定的权限决定；给予拘留的行政处罚，由公安机关依照治安管理处罚的规定决定。"},{"i":116,"n":"第一百一十六条","txt":"生产经营单位发生生产安全事故造成人员伤亡、他人财产损失的，应当依法承担赔偿责任；拒不承担或者其负责人逃匿的，由人民法院依法强制执行。"},{"i":117,"n":"第一百一十七条","txt":"本法下列用语的含义："},{"i":118,"n":"第一百一十八条","txt":"本法规定的生产安全一般事故、较大事故、重大事故、特别重大事故的划分标准由国务院规定。"},{"i":119,"n":"第一百一十九条","txt":"本法自2002年11月1日起施行。"}],"jiatingjiaoyucujinfa":[{"i":1,"n":"第一条","txt":"为了发扬中华民族重视家庭教育的优良传统，引导全社会注重家庭、家教、家风，增进家庭幸福与社会和谐，培养德智体美劳全面发展的社会主义建设者和接班人，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称家庭教育，是指父母或者其他监护人为促进未成年人全面健康成长，对其实施的道德品质、身体素质、生活技能、文化修养、行为习惯等方面的培育、引导和影响。"},{"i":3,"n":"第三条","txt":"家庭教育以立德树人为根本任务，培育和践行社会主义核心价值观，弘扬中华民族优秀传统文化、革命文化、社会主义先进文化，促进未成年人健康成长。"},{"i":4,"n":"第四条","txt":"未成年人的父母或者其他监护人负责实施家庭教育。"},{"i":5,"n":"第五条","txt":"家庭教育应当符合以下要求："},{"i":6,"n":"第六条","txt":"各级人民政府指导家庭教育工作，建立健全家庭学校社会协同育人机制。县级以上人民政府负责妇女儿童工作的机构，组织、协调、指导、督促有关部门做好家庭教育工作。"},{"i":7,"n":"第七条","txt":"县级以上人民政府应当制定家庭教育工作专项规划，将家庭教育指导服务纳入城乡公共服务体系和政府购买服务目录，将相关经费列入财政预算，鼓励和支持以政府购买服务的方式提供家庭教育指导。"},{"i":8,"n":"第八条","txt":"人民法院、人民检察院发挥职能作用，配合同级人民政府及其有关部门建立家庭教育工作联动机制，共同做好家庭教育工作。"},{"i":9,"n":"第九条","txt":"工会、共产主义青年团、残疾人联合会、科学技术协会、关心下一代工作委员会以及居民委员会、村民委员会等应当结合自身工作，积极开展家庭教育工作，为家庭教育提供社会支持。"},{"i":10,"n":"第十条","txt":"国家鼓励和支持企业事业单位、社会组织及个人依法开展公益性家庭教育服务活动。"},{"i":11,"n":"第十一条","txt":"国家鼓励开展家庭教育研究，鼓励高等学校开设家庭教育专业课程，支持师范院校和有条件的高等学校加强家庭教育学科建设，培养家庭教育服务专业人才，开展家庭教育服务人员培训。"},{"i":12,"n":"第十二条","txt":"国家鼓励和支持自然人、法人和非法人组织为家庭教育事业进行捐赠或者提供志愿服务，对符合条件的，依法给予税收优惠。"},{"i":13,"n":"第十三条","txt":"每年5月15日国际家庭日所在周为全国家庭教育宣传周。"},{"i":14,"n":"第十四条","txt":"父母或者其他监护人应当树立家庭是第一个课堂、家长是第一任老师的责任意识，承担对未成年人实施家庭教育的主体责任，用正确思想、方法和行为教育未成年人养成良好思想、品行和习惯。"},{"i":15,"n":"第十五条","txt":"未成年人的父母或者其他监护人及其他家庭成员应当注重家庭建设，培育积极健康的家庭文化，树立和传承优良家风，弘扬中华民族家庭美德，共同构建文明、和睦的家庭关系，为未成年人健康成长营造良好的家庭环境。"},{"i":16,"n":"第十六条","txt":"未成年人的父母或者其他监护人应当针对不同年龄段未成年人的身心发展特点，以下列内容为指引，开展家庭教育："},{"i":17,"n":"第十七条","txt":"未成年人的父母或者其他监护人实施家庭教育，应当关注未成年人的生理、心理、智力发展状况，尊重其参与相关家庭事务和发表意见的权利，合理运用以下方式方法："},{"i":18,"n":"第十八条","txt":"未成年人的父母或者其他监护人应当树立正确的家庭教育理念，自觉学习家庭教育知识，在孕期和未成年人进入婴幼儿照护服务机构、幼儿园、中小学校等重要时段进行有针对性的学习，掌握科学的家庭教育方法，提高家庭教育的能力。"},{"i":19,"n":"第十九条","txt":"未成年人的父母或者其他监护人应当与中小学校、幼儿园、婴幼儿照护服务机构、社区密切配合，积极参加其提供的公益性家庭教育指导和实践活动，共同促进未成年人健康成长。"},{"i":20,"n":"第二十条","txt":"未成年人的父母分居或者离异的，应当相互配合履行家庭教育责任，任何一方不得拒绝或者怠于履行；除法律另有规定外，不得阻碍另一方实施家庭教育。"},{"i":21,"n":"第二十一条","txt":"未成年人的父母或者其他监护人依法委托他人代为照护未成年人的，应当与被委托人、未成年人保持联系，定期了解未成年人学习、生活情况和心理状况，与被委托人共同履行家庭教育责任。"},{"i":22,"n":"第二十二条","txt":"未成年人的父母或者其他监护人应当合理安排未成年人学习、休息、娱乐和体育锻炼的时间，避免加重未成年人学习负担，预防未成年人沉迷网络。"},{"i":23,"n":"第二十三条","txt":"未成年人的父母或者其他监护人不得因性别、身体状况、智力等歧视未成年人，不得实施家庭暴力，不得胁迫、引诱、教唆、纵容、利用未成年人从事违反法律法规和社会公德的活动。"},{"i":24,"n":"第二十四条","txt":"国务院应当组织有关部门制定、修订并及时颁布全国家庭教育指导大纲。"},{"i":25,"n":"第二十五条","txt":"省级以上人民政府应当组织有关部门统筹建设家庭教育信息化共享服务平台，开设公益性网上家长学校和网络课程，开通服务热线，提供线上家庭教育指导服务。"},{"i":26,"n":"第二十六条","txt":"县级以上地方人民政府应当加强监督管理，减轻义务教育阶段学生作业负担和校外培训负担，畅通学校家庭沟通渠道，推进学校教育和家庭教育相互配合。"},{"i":27,"n":"第二十七条","txt":"县级以上地方人民政府及有关部门组织建立家庭教育指导服务专业队伍，加强对专业人员的培养，鼓励社会工作者、志愿者参与家庭教育指导服务工作。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府可以结合当地实际情况和需要，通过多种途径和方式确定家庭教育指导机构。"},{"i":29,"n":"第二十九条","txt":"家庭教育指导机构应当及时向有需求的家庭提供服务。"},{"i":30,"n":"第三十条","txt":"设区的市、县、乡级人民政府应当结合当地实际采取措施，对留守未成年人和困境未成年人家庭建档立卡，提供生活帮扶、创业就业支持等关爱服务，为留守未成年人和困境未成年人的父母或者其他监护人实施家庭教育创造条件。"},{"i":31,"n":"第三十一条","txt":"家庭教育指导机构开展家庭教育指导服务活动，不得组织或者变相组织营利性教育培训。"},{"i":32,"n":"第三十二条","txt":"婚姻登记机构和收养登记机构应当通过现场咨询辅导、播放宣传教育片等形式，向办理婚姻登记、收养登记的当事人宣传家庭教育知识，提供家庭教育指导。"},{"i":33,"n":"第三十三条","txt":"儿童福利机构、未成年人救助保护机构应当对本机构安排的寄养家庭、接受救助保护的未成年人的父母或者其他监护人提供家庭教育指导。"},{"i":34,"n":"第三十四条","txt":"人民法院在审理离婚案件时，应当对有未成年子女的夫妻双方提供家庭教育指导。"},{"i":35,"n":"第三十五条","txt":"妇女联合会发挥妇女在弘扬中华民族家庭美德、树立良好家风等方面的独特作用，宣传普及家庭教育知识，通过家庭教育指导机构、社区家长学校、文明家庭建设等多种渠道组织开展家庭教育实践活动，提供家庭教育指导服务。"},{"i":36,"n":"第三十六条","txt":"自然人、法人和非法人组织可以依法设立非营利性家庭教育服务机构。"},{"i":37,"n":"第三十七条","txt":"国家机关、企业事业单位、群团组织、社会组织应当将家风建设纳入单位文化建设，支持职工参加相关的家庭教育服务活动。"},{"i":38,"n":"第三十八条","txt":"居民委员会、村民委员会可以依托城乡社区公共服务设施，设立社区家长学校等家庭教育指导服务站点，配合家庭教育指导机构组织面向居民、村民的家庭教育知识宣传，为未成年人的父母或者其他监护人提供家庭教育指导服务。"},{"i":39,"n":"第三十九条","txt":"中小学校、幼儿园应当将家庭教育指导服务纳入工作计划，作为教师业务培训的内容。"},{"i":40,"n":"第四十条","txt":"中小学校、幼儿园可以采取建立家长学校等方式，针对不同年龄段未成年人的特点，定期组织公益性家庭教育指导服务和实践活动，并及时联系、督促未成年人的父母或者其他监护人参加。"},{"i":41,"n":"第四十一条","txt":"中小学校、幼儿园应当根据家长的需求，邀请有关人员传授家庭教育理念、知识和方法，组织开展家庭教育指导服务和实践活动，促进家庭与学校共同教育。"},{"i":42,"n":"第四十二条","txt":"具备条件的中小学校、幼儿园应当在教育行政部门的指导下，为家庭教育指导服务站点开展公益性家庭教育指导服务活动提供支持。"},{"i":43,"n":"第四十三条","txt":"中小学校发现未成年学生严重违反校规校纪的，应当及时制止、管教，告知其父母或者其他监护人，并为其父母或者其他监护人提供有针对性的家庭教育指导服务；发现未成年学生有不良行为或者严重不良行为的，按照有关法律规定处理。"},{"i":44,"n":"第四十四条","txt":"婴幼儿照护服务机构、早期教育服务机构应当为未成年人的父母或者其他监护人提供科学养育指导等家庭教育指导服务。"},{"i":45,"n":"第四十五条","txt":"医疗保健机构在开展婚前保健、孕产期保健、儿童保健、预防接种等服务时，应当对有关成年人、未成年人的父母或者其他监护人开展科学养育知识和婴幼儿早期发展的宣传和指导。"},{"i":46,"n":"第四十六条","txt":"图书馆、博物馆、文化馆、纪念馆、美术馆、科技馆、体育场馆、青少年宫、儿童活动中心等公共文化服务机构和爱国主义教育基地每年应当定期开展公益性家庭教育宣传、家庭教育指导服务和实践活动，开发家庭教育类公共文化服务产品。"},{"i":47,"n":"第四十七条","txt":"家庭教育服务机构应当加强自律管理，制定家庭教育服务规范，组织从业人员培训，提高从业人员的业务素质和能力。"},{"i":48,"n":"第四十八条","txt":"未成年人住所地的居民委员会、村民委员会、妇女联合会，未成年人的父母或者其他监护人所在单位，以及中小学校、幼儿园等有关密切接触未成年人的单位，发现父母或者其他监护人拒绝、怠于履行家庭教育责任，或者非法阻碍其他监护人实施家庭教育的，应当予以批评教育、劝诫制止，必要时督促其接受家庭教育指导。"},{"i":49,"n":"第四十九条","txt":"公安机关、人民检察院、人民法院在办理案件过程中，发现未成年人存在严重不良行为或者实施犯罪行为，或者未成年人的父母或者其他监护人不正确实施家庭教育侵害未成年人合法权益的，根据情况对父母或者其他监护人予以训诫，并可以责令其接受家庭教育指导。"},{"i":50,"n":"第五十条","txt":"负有家庭教育工作职责的政府部门、机构有下列情形之一的，由其上级机关或者主管单位责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法予以处分："},{"i":51,"n":"第五十一条","txt":"家庭教育指导机构、中小学校、幼儿园、婴幼儿照护服务机构、早期教育服务机构违反本法规定，不履行或者不正确履行家庭教育指导服务职责的，由主管部门责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法予以处分。"},{"i":52,"n":"第五十二条","txt":"家庭教育服务机构有下列情形之一的，由主管部门责令限期改正；拒不改正或者情节严重的，由主管部门责令停业整顿、吊销营业执照或者撤销登记："},{"i":53,"n":"第五十三条","txt":"未成年人的父母或者其他监护人在家庭教育过程中对未成年人实施家庭暴力的，依照《中华人民共和国未成年人保护法》、《中华人民共和国反家庭暴力法》等法律的规定追究法律责任。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，构成违反治安管理行为的，由公安机关依法予以治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":55,"n":"第五十五条","txt":"本法自2022年1月1日起施行。"}],"jiuyecujinfa":[{"i":1,"n":"第一条","txt":"为了促进就业，促进经济发展与扩大就业相协调，促进社会和谐稳定，制定本法。"},{"i":2,"n":"第二条","txt":"国家把扩大就业放在经济社会发展的突出位置，实施积极的就业政策，坚持劳动者自主择业、市场调节就业、政府促进就业的方针，多渠道扩大就业。"},{"i":3,"n":"第三条","txt":"劳动者依法享有平等就业和自主择业的权利。"},{"i":4,"n":"第四条","txt":"县级以上人民政府把扩大就业作为经济和社会发展的重要目标，纳入国民经济和社会发展规划，并制定促进就业的中长期规划和年度工作计划。"},{"i":5,"n":"第五条","txt":"县级以上人民政府通过发展经济和调整产业结构、规范人力资源市场、完善就业服务、加强职业教育和培训、提供就业援助等措施，创造就业条件，扩大就业。"},{"i":6,"n":"第六条","txt":"国务院建立全国促进就业工作协调机制，研究就业工作中的重大问题，协调推动全国的促进就业工作。国务院劳动行政部门具体负责全国的促进就业工作。"},{"i":7,"n":"第七条","txt":"国家倡导劳动者树立正确的择业观念，提高就业能力和创业能力；鼓励劳动者自主创业、自谋职业。"},{"i":8,"n":"第八条","txt":"用人单位依法享有自主用人的权利。"},{"i":9,"n":"第九条","txt":"工会、共产主义青年团、妇女联合会、残疾人联合会以及其他社会组织，协助人民政府开展促进就业工作，依法维护劳动者的劳动权利。"},{"i":10,"n":"第十条","txt":"各级人民政府和有关部门对在促进就业工作中作出显著成绩的单位和个人，给予表彰和奖励。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府应当把扩大就业作为重要职责，统筹协调产业政策与就业政策。"},{"i":12,"n":"第十二条","txt":"国家鼓励各类企业在法律、法规规定的范围内，通过兴办产业或者拓展经营，增加就业岗位。"},{"i":13,"n":"第十三条","txt":"国家发展国内外贸易和国际经济合作，拓宽就业渠道。"},{"i":14,"n":"第十四条","txt":"县级以上人民政府在安排政府投资和确定重大建设项目时，应当发挥投资和重大建设项目带动就业的作用，增加就业岗位。"},{"i":15,"n":"第十五条","txt":"国家实行有利于促进就业的财政政策，加大资金投入，改善就业环境，扩大就业。"},{"i":16,"n":"第十六条","txt":"国家建立健全失业保险制度，依法确保失业人员的基本生活，并促进其实现就业。"},{"i":17,"n":"第十七条","txt":"国家鼓励企业增加就业岗位，扶持失业人员和残疾人就业，对下列企业、人员依法给予税收优惠："},{"i":18,"n":"第十八条","txt":"对本法第十七条第四项、第五项规定的人员，有关部门应当在经营场地等方面给予照顾，免除行政事业性收费。"},{"i":19,"n":"第十九条","txt":"国家实行有利于促进就业的金融政策，增加中小企业的融资渠道；鼓励金融机构改进金融服务，加大对中小企业的信贷支持，并对自主创业人员在一定期限内给予小额信贷等扶持。"},{"i":20,"n":"第二十条","txt":"国家实行城乡统筹的就业政策，建立健全城乡劳动者平等就业的制度，引导农业富余劳动力有序转移就业。"},{"i":21,"n":"第二十一条","txt":"国家支持区域经济发展，鼓励区域协作，统筹协调不同地区就业的均衡增长。"},{"i":22,"n":"第二十二条","txt":"各级人民政府统筹做好城镇新增劳动力就业、农业富余劳动力转移就业和失业人员就业工作。"},{"i":23,"n":"第二十三条","txt":"各级人民政府采取措施，逐步完善和实施与非全日制用工等灵活就业相适应的劳动和社会保险政策，为灵活就业人员提供帮助和服务。"},{"i":24,"n":"第二十四条","txt":"地方各级人民政府和有关部门应当加强对失业人员从事个体经营的指导，提供政策咨询、就业培训和开业指导等服务。"},{"i":25,"n":"第二十五条","txt":"各级人民政府创造公平就业的环境，消除就业歧视，制定政策并采取措施对就业困难人员给予扶持和援助。"},{"i":26,"n":"第二十六条","txt":"用人单位招用人员、职业中介机构从事职业中介活动，应当向劳动者提供平等的就业机会和公平的就业条件，不得实施就业歧视。"},{"i":27,"n":"第二十七条","txt":"国家保障妇女享有与男子平等的劳动权利。"},{"i":28,"n":"第二十八条","txt":"各民族劳动者享有平等的劳动权利。"},{"i":29,"n":"第二十九条","txt":"国家保障残疾人的劳动权利。"},{"i":30,"n":"第三十条","txt":"用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国务院卫生行政部门规定禁止从事的易使传染病扩散的工作。"},{"i":31,"n":"第三十一条","txt":"农村劳动者进城就业享有与城镇劳动者平等的劳动权利，不得对农村劳动者进城就业设置歧视性限制。"},{"i":32,"n":"第三十二条","txt":"县级以上人民政府培育和完善统一开放、竞争有序的人力资源市场，为劳动者就业提供服务。"},{"i":33,"n":"第三十三条","txt":"县级以上人民政府鼓励社会各方面依法开展就业服务活动，加强对公共就业服务和职业中介服务的指导和监督，逐步完善覆盖城乡的就业服务体系。"},{"i":34,"n":"第三十四条","txt":"县级以上人民政府加强人力资源市场信息网络及相关设施建设，建立健全人力资源市场信息服务体系，完善市场信息发布制度。"},{"i":35,"n":"第三十五条","txt":"县级以上人民政府建立健全公共就业服务体系，设立公共就业服务机构，为劳动者免费提供下列服务："},{"i":36,"n":"第三十六条","txt":"县级以上地方人民政府对职业中介机构提供公益性就业服务的，按照规定给予补贴。"},{"i":37,"n":"第三十七条","txt":"地方各级人民政府和有关部门不得举办或者与他人联合举办经营性的职业中介机构。"},{"i":38,"n":"第三十八条","txt":"县级以上人民政府和有关部门加强对职业中介机构的管理，鼓励其提高服务质量，发挥其在促进就业中的作用。"},{"i":39,"n":"第三十九条","txt":"从事职业中介活动，应当遵循合法、诚实信用、公平、公开的原则。"},{"i":40,"n":"第四十条","txt":"设立职业中介机构应当具备下列条件："},{"i":41,"n":"第四十一条","txt":"职业中介机构不得有下列行为："},{"i":42,"n":"第四十二条","txt":"县级以上人民政府建立失业预警制度，对可能出现的较大规模的失业，实施预防、调节和控制。"},{"i":43,"n":"第四十三条","txt":"国家建立劳动力调查统计制度和就业登记、失业登记制度，开展劳动力资源和就业、失业状况调查统计，并公布调查统计结果。"},{"i":44,"n":"第四十四条","txt":"国家依法发展职业教育，鼓励开展职业培训，促进劳动者提高职业技能，增强就业能力和创业能力。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府根据经济社会发展和市场需求，制定并实施职业能力开发计划。"},{"i":46,"n":"第四十六条","txt":"县级以上人民政府加强统筹协调，鼓励和支持各类职业院校、职业技能培训机构和用人单位依法开展就业前培训、在职培训、再就业培训和创业培训；鼓励劳动者参加各种形式的培训。"},{"i":47,"n":"第四十七条","txt":"县级以上地方人民政府和有关部门根据市场需求和产业发展方向，鼓励、指导企业加强职业教育和培训。"},{"i":48,"n":"第四十八条","txt":"国家采取措施建立健全劳动预备制度，县级以上地方人民政府对有就业要求的初高中毕业生实行一定期限的职业教育和培训，使其取得相应的职业资格或者掌握一定的职业技能。"},{"i":49,"n":"第四十九条","txt":"地方各级人民政府鼓励和支持开展就业培训，帮助失业人员提高职业技能，增强其就业能力和创业能力。失业人员参加就业培训的，按照有关规定享受政府培训补贴。"},{"i":50,"n":"第五十条","txt":"地方各级人民政府采取有效措施，组织和引导进城就业的农村劳动者参加技能培训，鼓励各类培训机构为进城就业的农村劳动者提供技能培训，增强其就业能力和创业能力。"},{"i":51,"n":"第五十一条","txt":"国家对从事涉及公共安全、人身健康、生命财产安全等特殊工种的劳动者，实行职业资格证书制度，具体办法由国务院规定。"},{"i":52,"n":"第五十二条","txt":"各级人民政府建立健全就业援助制度，采取税费减免、贷款贴息、社会保险补贴、岗位补贴等办法，通过公益性岗位安置等途径，对就业困难人员实行优先扶持和重点帮助。"},{"i":53,"n":"第五十三条","txt":"政府投资开发的公益性岗位，应当优先安排符合岗位要求的就业困难人员。被安排在公益性岗位工作的，按照国家规定给予岗位补贴。"},{"i":54,"n":"第五十四条","txt":"地方各级人民政府加强基层就业援助服务工作，对就业困难人员实施重点帮助，提供有针对性的就业服务和公益性岗位援助。"},{"i":55,"n":"第五十五条","txt":"各级人民政府采取特别扶助措施，促进残疾人就业。"},{"i":56,"n":"第五十六条","txt":"县级以上地方人民政府采取多种就业形式，拓宽公益性岗位范围，开发就业岗位，确保城市有就业需求的家庭至少有一人实现就业。"},{"i":57,"n":"第五十七条","txt":"国家鼓励资源开采型城市和独立工矿区发展与市场需求相适应的产业，引导劳动者转移就业。"},{"i":58,"n":"第五十八条","txt":"各级人民政府和有关部门应当建立促进就业的目标责任制度。县级以上人民政府按照促进就业目标责任制的要求，对所属的有关部门和下一级人民政府进行考核和监督。"},{"i":59,"n":"第五十九条","txt":"审计机关、财政部门应当依法对就业专项资金的管理和使用情况进行监督检查。"},{"i":60,"n":"第六十条","txt":"劳动行政部门应当对本法实施情况进行监督检查，建立举报制度，受理对违反本法行为的举报，并及时予以核实、处理。"},{"i":61,"n":"第六十一条","txt":"违反本法规定，劳动行政等有关部门及其工作人员滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，实施就业歧视的，劳动者可以向人民法院提起诉讼。"},{"i":63,"n":"第六十三条","txt":"违反本法规定，地方各级人民政府和有关部门、公共就业服务机构举办经营性的职业中介机构，从事经营性职业中介活动，向劳动者收取费用的，由上级主管机关责令限期改正，将违法收取的费用退还劳动者，并对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":64,"n":"第六十四条","txt":"违反本法规定，未经许可和登记，擅自从事职业中介活动的，由劳动行政部门或者其他主管部门依法予以关闭；有违法所得的，没收违法所得，并处一万元以上五万元以下的罚款。"},{"i":65,"n":"第六十五条","txt":"违反本法规定，职业中介机构提供虚假就业信息，为无合法证照的用人单位提供职业中介服务，伪造、涂改、转让职业中介许可证的，由劳动行政部门或者其他主管部门责令改正；有违法所得的，没收违法所得，并处一万元以上五万元以下的罚款；情节严重的，吊销职业中介许可证。"},{"i":66,"n":"第六十六条","txt":"违反本法规定，职业中介机构扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者，并依照有关法律规定给予处罚。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，企业未按照国家规定提取职工教育经费，或者挪用职工教育经费的，由劳动行政部门责令改正，并依法给予处罚。"},{"i":68,"n":"第六十八条","txt":"违反本法规定，侵害劳动者合法权益，造成财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":69,"n":"第六十九条","txt":"本法自2008年1月1日起施行。"}],"gonghuifa":[{"i":1,"n":"第一条","txt":"为保障工会在国家政治、经济和社会生活中的地位，确定工会的权利与义务，发挥工会在社会主义现代化建设事业中的作用，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"工会是中国共产党领导的职工自愿结合的工人阶级群众组织，是中国共产党联系职工群众的桥梁和纽带。"},{"i":3,"n":"第三条","txt":"在中国境内的企业、事业单位、机关、社会组织（以下统称用人单位）中以工资收入为主要生活来源的劳动者，不分民族、种族、性别、职业、宗教信仰、教育程度，都有依法参加和组织工会的权利。任何组织和个人不得阻挠和限制。"},{"i":4,"n":"第四条","txt":"工会必须遵守和维护宪法，以宪法为根本的活动准则，以经济建设为中心，坚持社会主义道路，坚持人民民主专政，坚持中国共产党的领导，坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想，坚持改革开放，保持和增强政治性、先进性、群众性，依照工会章程独立自主地开展工作。"},{"i":5,"n":"第五条","txt":"工会组织和教育职工依照宪法和法律的规定行使民主权利，发挥国家主人翁的作用，通过各种途径和形式，参与管理国家事务、管理经济和文化事业、管理社会事务；协助人民政府开展工作，维护工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家政权。"},{"i":6,"n":"第六条","txt":"维护职工合法权益、竭诚服务职工群众是工会的基本职责。工会在维护全国人民总体利益的同时，代表和维护职工的合法权益。"},{"i":7,"n":"第七条","txt":"工会动员和组织职工积极参加经济建设，努力完成生产任务和工作任务。教育职工不断提高思想道德、技术业务和科学文化素质，建设有理想、有道德、有文化、有纪律的职工队伍。"},{"i":8,"n":"第八条","txt":"工会推动产业工人队伍建设改革，提高产业工人队伍整体素质，发挥产业工人骨干作用，维护产业工人合法权益，保障产业工人主人翁地位，造就一支有理想守信念、懂技术会创新、敢担当讲奉献的宏大产业工人队伍。"},{"i":9,"n":"第九条","txt":"中华全国总工会根据独立、平等、互相尊重、互不干涉内部事务的原则，加强同各国工会组织的友好合作关系。"},{"i":10,"n":"第十条","txt":"工会各级组织按照民主集中制原则建立。"},{"i":11,"n":"第十一条","txt":"用人单位有会员二十五人以上的，应当建立基层工会委员会；不足二十五人的，可以单独建立基层工会委员会，也可以由两个以上单位的会员联合建立基层工会委员会，也可以选举组织员一人，组织会员开展活动。女职工人数较多的，可以建立工会女职工委员会，在同级工会领导下开展工作；女职工人数较少的，可以在工会委员会中设女职工委员。"},{"i":12,"n":"第十二条","txt":"基层工会、地方各级总工会、全国或者地方产业工会组织的建立，必须报上一级工会批准。"},{"i":13,"n":"第十三条","txt":"任何组织和个人不得随意撤销、合并工会组织。"},{"i":14,"n":"第十四条","txt":"职工二百人以上的企业、事业单位、社会组织的工会，可以设专职工会主席。工会专职工作人员的人数由工会与企业、事业单位、社会组织协商确定。"},{"i":15,"n":"第十五条","txt":"中华全国总工会、地方总工会、产业工会具有社会团体法人资格。"},{"i":16,"n":"第十六条","txt":"基层工会委员会每届任期三年或者五年。各级地方总工会委员会和产业工会委员会每届任期五年。"},{"i":17,"n":"第十七条","txt":"基层工会委员会定期召开会员大会或者会员代表大会，讨论决定工会工作的重大问题。经基层工会委员会或者三分之一以上的工会会员提议，可以临时召开会员大会或者会员代表大会。"},{"i":18,"n":"第十八条","txt":"工会主席、副主席任期未满时，不得随意调动其工作。因工作需要调动时，应当征得本级工会委员会和上一级工会的同意。"},{"i":19,"n":"第十九条","txt":"基层工会专职主席、副主席或者委员自任职之日起，其劳动合同期限自动延长，延长期限相当于其任职期间；非专职主席、副主席或者委员自任职之日起，其尚未履行的劳动合同期限短于任期的，劳动合同期限自动延长至任期期满。但是，任职期间个人严重过失或者达到法定退休年龄的除外。"},{"i":20,"n":"第二十条","txt":"企业、事业单位、社会组织违反职工代表大会制度和其他民主管理制度，工会有权要求纠正，保障职工依法行使民主管理的权利。"},{"i":21,"n":"第二十一条","txt":"工会帮助、指导职工与企业、实行企业化管理的事业单位、社会组织签订劳动合同。"},{"i":22,"n":"第二十二条","txt":"企业、事业单位、社会组织处分职工，工会认为不适当的，有权提出意见。"},{"i":23,"n":"第二十三条","txt":"企业、事业单位、社会组织违反劳动法律法规规定，有下列侵犯职工劳动权益情形，工会应当代表职工与企业、事业单位、社会组织交涉，要求企业、事业单位、社会组织采取措施予以改正；企业、事业单位、社会组织应当予以研究处理，并向工会作出答复；企业、事业单位、社会组织拒不改正的，工会可以提请当地人民政府依法作出处理："},{"i":24,"n":"第二十四条","txt":"工会依照国家规定对新建、扩建企业和技术改造工程中的劳动条件和安全卫生设施与主体工程同时设计、同时施工、同时投产使用进行监督。对工会提出的意见，企业或者主管部门应当认真处理，并将处理结果书面通知工会。"},{"i":25,"n":"第二十五条","txt":"工会发现企业违章指挥、强令工人冒险作业，或者生产过程中发现明显重大事故隐患和职业危害，有权提出解决的建议，企业应当及时研究答复；发现危及职工生命安全的情况时，工会有权向企业建议组织职工撤离危险现场，企业必须及时作出处理决定。"},{"i":26,"n":"第二十六条","txt":"工会有权对企业、事业单位、社会组织侵犯职工合法权益的问题进行调查，有关单位应当予以协助。"},{"i":27,"n":"第二十七条","txt":"职工因工伤亡事故和其他严重危害职工健康问题的调查处理，必须有工会参加。工会应当向有关部门提出处理意见，并有权要求追究直接负责的主管人员和有关责任人员的责任。对工会提出的意见，应当及时研究，给予答复。"},{"i":28,"n":"第二十八条","txt":"企业、事业单位、社会组织发生停工、怠工事件，工会应当代表职工同企业、事业单位、社会组织或者有关方面协商，反映职工的意见和要求并提出解决意见。对于职工的合理要求，企业、事业单位、社会组织应当予以解决。工会协助企业、事业单位、社会组织做好工作，尽快恢复生产、工作秩序。"},{"i":29,"n":"第二十九条","txt":"工会参加企业的劳动争议调解工作。"},{"i":30,"n":"第三十条","txt":"县级以上各级总工会依法为所属工会和职工提供法律援助等法律服务。"},{"i":31,"n":"第三十一条","txt":"工会协助用人单位办好职工集体福利事业，做好工资、劳动安全卫生和社会保险工作。"},{"i":32,"n":"第三十二条","txt":"工会会同用人单位加强对职工的思想政治引领，教育职工以国家主人翁态度对待劳动，爱护国家和单位的财产；组织职工开展群众性的合理化建议、技术革新、劳动和技能竞赛活动，进行业余文化技术学习和职工培训，参加职业教育和文化体育活动，推进职业安全健康教育和劳动保护工作。"},{"i":33,"n":"第三十三条","txt":"根据政府委托，工会与有关部门共同做好劳动模范和先进生产（工作）者的评选、表彰、培养和管理工作。"},{"i":34,"n":"第三十四条","txt":"国家机关在组织起草或者修改直接涉及职工切身利益的法律、法规、规章时，应当听取工会意见。"},{"i":35,"n":"第三十五条","txt":"县级以上地方各级人民政府可以召开会议或者采取适当方式，向同级工会通报政府的重要的工作部署和与工会工作有关的行政措施，研究解决工会反映的职工群众的意见和要求。"},{"i":36,"n":"第三十六条","txt":"国有企业职工代表大会是企业实行民主管理的基本形式，是职工行使民主管理权力的机构，依照法律规定行使职权。"},{"i":37,"n":"第三十七条","txt":"集体企业的工会委员会，应当支持和组织职工参加民主管理和民主监督，维护职工选举和罢免管理人员、决定经营管理的重大问题的权力。"},{"i":38,"n":"第三十八条","txt":"本法第三十六条、第三十七条规定以外的其他企业、事业单位的工会委员会，依照法律规定组织职工采取与企业、事业单位相适应的形式，参与企业、事业单位民主管理。"},{"i":39,"n":"第三十九条","txt":"企业、事业单位、社会组织研究经营管理和发展的重大问题应当听取工会的意见；召开会议讨论有关工资、福利、劳动安全卫生、工作时间、休息休假、女职工保护和社会保险等涉及职工切身利益的问题，必须有工会代表参加。"},{"i":40,"n":"第四十条","txt":"公司的董事会、监事会中职工代表的产生，依照公司法有关规定执行。"},{"i":41,"n":"第四十一条","txt":"基层工会委员会召开会议或者组织职工活动，应当在生产或者工作时间以外进行，需要占用生产或者工作时间的，应当事先征得企业、事业单位、社会组织的同意。"},{"i":42,"n":"第四十二条","txt":"用人单位工会委员会的专职工作人员的工资、奖励、补贴，由所在单位支付。社会保险和其他福利待遇等，享受本单位职工同等待遇。"},{"i":43,"n":"第四十三条","txt":"工会经费的来源："},{"i":44,"n":"第四十四条","txt":"企业、事业单位、社会组织无正当理由拖延或者拒不拨缴工会经费，基层工会或者上级工会可以向当地人民法院申请支付令；拒不执行支付令的，工会可以依法申请人民法院强制执行。"},{"i":45,"n":"第四十五条","txt":"工会应当根据经费独立原则，建立预算、决算和经费审查监督制度。"},{"i":46,"n":"第四十六条","txt":"各级人民政府和用人单位应当为工会办公和开展活动，提供必要的设施和活动场所等物质条件。"},{"i":47,"n":"第四十七条","txt":"工会的财产、经费和国家拨给工会使用的不动产，任何组织和个人不得侵占、挪用和任意调拨。"},{"i":48,"n":"第四十八条","txt":"工会所属的为职工服务的企业、事业单位，其隶属关系不得随意改变。"},{"i":49,"n":"第四十九条","txt":"县级以上各级工会的离休、退休人员的待遇，与国家机关工作人员同等对待。"},{"i":50,"n":"第五十条","txt":"工会对违反本法规定侵犯其合法权益的，有权提请人民政府或者有关部门予以处理，或者向人民法院提起诉讼。"},{"i":51,"n":"第五十一条","txt":"违反本法第三条、第十二条规定，阻挠职工依法参加和组织工会或者阻挠上级工会帮助、指导职工筹建工会的，由劳动行政部门责令其改正；拒不改正的，由劳动行政部门提请县级以上人民政府处理；以暴力、威胁等手段阻挠造成严重后果，构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"违反本法规定，对依法履行职责的工会工作人员无正当理由调动工作岗位，进行打击报复的，由劳动行政部门责令改正、恢复原工作；造成损失的，给予赔偿。"},{"i":53,"n":"第五十三条","txt":"违反本法规定，有下列情形之一的，由劳动行政部门责令恢复其工作，并补发被解除劳动合同期间应得的报酬，或者责令给予本人年收入二倍的赔偿："},{"i":54,"n":"第五十四条","txt":"违反本法规定，有下列情形之一的，由县级以上人民政府责令改正，依法处理："},{"i":55,"n":"第五十五条","txt":"违反本法第四十七条规定，侵占工会经费和财产拒不返还的，工会可以向人民法院提起诉讼，要求返还，并赔偿损失。"},{"i":56,"n":"第五十六条","txt":"工会工作人员违反本法规定，损害职工或者工会权益的，由同级工会或者上级工会责令改正，或者予以处分；情节严重的，依照《中国工会章程》予以罢免；造成损失的，应当承担赔偿责任；构成犯罪的，依法追究刑事责任。"},{"i":57,"n":"第五十七条","txt":"中华全国总工会会同有关国家机关制定机关工会实施本法的具体办法。"},{"i":58,"n":"第五十八条","txt":"本法自公布之日起施行。1950年6月29日中央人民政府颁布的《中华人民共和国工会法》同时废止。"}],"guiqiaoqiaojuanquanyibaohufa":[{"i":1,"n":"第一条","txt":"为了保护归侨、侨眷的合法的权利和利益，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"归侨是指回国定居的华侨。华侨是指定居在国外的中国公民。"},{"i":3,"n":"第三条","txt":"归侨、侨眷享有宪法和法律规定的公民的权利，并履行宪法和法律规定的公民的义务，任何组织或者个人不得歧视。"},{"i":4,"n":"第四条","txt":"县级以上各级人民政府及其负责侨务工作的机构，组织协调有关部门做好保护归侨、侨眷的合法权益的工作。"},{"i":5,"n":"第五条","txt":"国家对回国定居的华侨给予安置。"},{"i":6,"n":"第六条","txt":"全国人民代表大会和归侨人数较多地区的地方人民代表大会应当有适当名额的归侨代表。"},{"i":7,"n":"第七条","txt":"归侨、侨眷有权依法申请成立社会团体，进行适合归侨、侨眷需要的合法的社会活动。"},{"i":8,"n":"第八条","txt":"中华全国归国华侨联合会和地方归国华侨联合会代表归侨、侨眷的利益，依法维护归侨、侨眷的合法权益。"},{"i":9,"n":"第九条","txt":"国家对安置归侨的农场、林场等企业给予扶持，任何组织或者个人不得侵占其合法使用的土地，不得侵犯其合法权益。"},{"i":10,"n":"第十条","txt":"国家依法维护归侨、侨眷职工的社会保障权益。用人单位及归侨、侨眷职工应当依法参加当地的社会保险，缴纳社会保险费用。"},{"i":11,"n":"第十一条","txt":"国家鼓励和引导归侨、侨眷依法投资兴办产业，特别是兴办高新技术企业，各级人民政府应当给予支持，其合法权益受法律保护。"},{"i":12,"n":"第十二条","txt":"归侨、侨眷在国内兴办公益事业，各级人民政府应当给予支持，其合法权益受法律保护。"},{"i":13,"n":"第十三条","txt":"国家依法保护归侨、侨眷在国内私有房屋的所有权。"},{"i":14,"n":"第十四条","txt":"各级人民政府应当对归侨、侨眷就业给予照顾，提供必要的指导和服务。"},{"i":15,"n":"第十五条","txt":"国家保护归侨、侨眷的侨汇收入。"},{"i":16,"n":"第十六条","txt":"归侨、侨眷有权接受境外亲友的遗赠或者赠与。"},{"i":17,"n":"第十七条","txt":"归侨、侨眷与境外亲友的往来和通讯受法律保护。"},{"i":18,"n":"第十八条","txt":"归侨、侨眷申请出境，有关主管部门应当在规定期限内办理手续。"},{"i":19,"n":"第十九条","txt":"国家保障归侨、侨眷出境探亲的权利。"},{"i":20,"n":"第二十条","txt":"归侨、侨眷可以按照国家有关规定申请出境定居，经批准出境定居的，任何组织或者个人不得损害其合法权益。"},{"i":21,"n":"第二十一条","txt":"归侨、侨眷申请自费出境学习、讲学的，或者因经商出境的，其所在单位和有关部门应当提供便利。"},{"i":22,"n":"第二十二条","txt":"国家对归侨、侨眷在境外的正当权益，根据中华人民共和国缔结或者参加的国际条约或者国际惯例，给予保护。"},{"i":23,"n":"第二十三条","txt":"归侨、侨眷合法权益受到侵害时，被侵害人有权要求有关主管部门依法处理，或者向人民法院提起诉讼。归国华侨联合会应当给予支持和帮助。"},{"i":24,"n":"第二十四条","txt":"国家机关工作人员玩忽职守或者滥用职权，致使归侨、侨眷合法权益受到损害的，其所在单位或者上级主管机关应当责令改正或者给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"任何组织或者个人侵害归侨、侨眷的合法权益，造成归侨、侨眷财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"违反本法第九条第一款规定，非法占用安置归侨的农场、林场合法使用的土地，有关主管部门应当责令退还；造成损失的，依法承担赔偿责任。"},{"i":27,"n":"第二十七条","txt":"违反本法第十三条规定，非法侵占归侨、侨眷在国内私有房屋的，有关主管部门应当责令退还；造成损失的，依法承担赔偿责任。"},{"i":28,"n":"第二十八条","txt":"违反本法第二十条第二款规定，停发、扣发、侵占或者挪用出境定居的归侨、侨眷的离休金、退休金、退职金、养老金的，有关单位或者有关主管部门应当责令补发，并依法给予赔偿；对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"国务院根据本法制定实施办法。"},{"i":30,"n":"第三十条","txt":"本法自1991年1月1日起施行。"}],"cishanfa":[{"i":1,"n":"第一条","txt":"为了发展慈善事业，弘扬慈善文化，规范慈善活动，保护慈善组织、捐赠人、志愿者、受益人等慈善活动参与者的合法权益，促进社会进步，共享发展成果，制定本法。"},{"i":2,"n":"第二条","txt":"自然人、法人和非法人组织开展慈善活动以及与慈善有关的活动，适用本法。其他法律有特别规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"本法所称慈善活动，是指自然人、法人和非法人组织以捐赠财产或者提供服务等方式，自愿开展的下列公益活动："},{"i":4,"n":"第四条","txt":"慈善工作坚持中国共产党的领导。"},{"i":5,"n":"第五条","txt":"国家鼓励和支持自然人、法人和非法人组织践行社会主义核心价值观，弘扬中华民族传统美德，依法开展慈善活动。"},{"i":6,"n":"第六条","txt":"县级以上人民政府应当统筹、协调、督促和指导有关部门在各自职责范围内做好慈善事业的扶持发展和规范管理工作。"},{"i":7,"n":"第七条","txt":"每年9月5日为“中华慈善日”。"},{"i":8,"n":"第八条","txt":"本法所称慈善组织，是指依法成立、符合本法规定，以面向社会开展慈善活动为宗旨的非营利性组织。"},{"i":9,"n":"第九条","txt":"慈善组织应当符合下列条件："},{"i":10,"n":"第十条","txt":"设立慈善组织，应当向县级以上人民政府民政部门申请登记，民政部门应当自受理申请之日起三十日内作出决定。符合本法规定条件的，准予登记并向社会公告；不符合本法规定条件的，不予登记并书面说明理由。"},{"i":11,"n":"第十一条","txt":"慈善组织的章程，应当符合法律法规的规定，并载明下列事项："},{"i":12,"n":"第十二条","txt":"慈善组织应当根据法律法规以及章程的规定，建立健全内部治理结构，明确决策、执行、监督等方面的职责权限，开展慈善活动。"},{"i":13,"n":"第十三条","txt":"慈善组织应当每年向办理其登记的民政部门报送年度工作报告和财务会计报告。报告应当包括年度开展募捐和接受捐赠、慈善财产的管理使用、慈善项目实施、募捐成本、慈善组织工作人员工资福利以及与境外组织或者个人开展合作等情况。"},{"i":14,"n":"第十四条","txt":"慈善组织的发起人、主要捐赠人以及管理人员，不得利用其关联关系损害慈善组织、受益人的利益和社会公共利益。"},{"i":15,"n":"第十五条","txt":"慈善组织不得从事、资助危害国家安全和社会公共利益的活动，不得接受附加违反法律法规和违背社会公德条件的捐赠，不得对受益人附加违反法律法规和违背社会公德的条件。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，不得担任慈善组织的负责人："},{"i":17,"n":"第十七条","txt":"慈善组织有下列情形之一的，应当终止："},{"i":18,"n":"第十八条","txt":"慈善组织终止，应当进行清算。"},{"i":19,"n":"第十九条","txt":"慈善组织依法成立行业组织。"},{"i":20,"n":"第二十条","txt":"慈善组织的组织形式、登记管理的具体办法由国务院制定。"},{"i":21,"n":"第二十一条","txt":"本法所称慈善募捐，是指慈善组织基于慈善宗旨募集财产的活动。"},{"i":22,"n":"第二十二条","txt":"慈善组织开展公开募捐，应当取得公开募捐资格。依法登记满一年的慈善组织，可以向办理其登记的民政部门申请公开募捐资格。民政部门应当自受理申请之日起二十日内作出决定。慈善组织符合内部治理结构健全、运作规范的条件的，发给公开募捐资格证书；不符合条件的，不发给公开募捐资格证书并书面说明理由。"},{"i":23,"n":"第二十三条","txt":"开展公开募捐，可以采取下列方式："},{"i":24,"n":"第二十四条","txt":"开展公开募捐，应当制定募捐方案。募捐方案包括募捐目的、起止时间和地域、活动负责人姓名和办公地址、接受捐赠方式、银行账户、受益人、募得款物用途、募捐成本、剩余财产的处理等。"},{"i":25,"n":"第二十五条","txt":"开展公开募捐，应当在募捐活动现场或者募捐活动载体的显著位置，公布募捐组织名称、公开募捐资格证书、募捐方案、联系方式、募捐信息查询方法等。"},{"i":26,"n":"第二十六条","txt":"不具有公开募捐资格的组织或者个人基于慈善目的，可以与具有公开募捐资格的慈善组织合作，由该慈善组织开展公开募捐，合作方不得以任何形式自行开展公开募捐。具有公开募捐资格的慈善组织应当对合作方进行评估，依法签订书面协议，在募捐方案中载明合作方的相关信息，并对合作方的相关行为进行指导和监督。"},{"i":27,"n":"第二十七条","txt":"慈善组织通过互联网开展公开募捐的，应当在国务院民政部门指定的互联网公开募捐服务平台进行，并可以同时在其网站进行。"},{"i":28,"n":"第二十八条","txt":"广播、电视、报刊以及网络服务提供者、电信运营商，应当对利用其平台开展公开募捐的慈善组织的登记证书、公开募捐资格证书进行验证。"},{"i":29,"n":"第二十九条","txt":"慈善组织自登记之日起可以开展定向募捐。"},{"i":30,"n":"第三十条","txt":"开展定向募捐，不得采取或者变相采取本法第二十三条规定的方式。"},{"i":31,"n":"第三十一条","txt":"开展募捐活动，应当尊重和维护募捐对象的合法权益，保障募捐对象的知情权，不得通过虚构事实等方式欺骗、诱导募捐对象实施捐赠。"},{"i":32,"n":"第三十二条","txt":"开展募捐活动，不得摊派或者变相摊派，不得妨碍公共秩序、企业生产经营和居民生活。"},{"i":33,"n":"第三十三条","txt":"禁止任何组织或者个人假借慈善名义或者假冒慈善组织开展募捐活动，骗取财产。"},{"i":34,"n":"第三十四条","txt":"本法所称慈善捐赠，是指自然人、法人和非法人组织基于慈善目的，自愿、无偿赠与财产的活动。"},{"i":35,"n":"第三十五条","txt":"捐赠人可以通过慈善组织捐赠，也可以直接向受益人捐赠。"},{"i":36,"n":"第三十六条","txt":"捐赠人捐赠的财产应当是其有权处分的合法财产。捐赠财产包括货币、实物、房屋、有价证券、股权、知识产权等有形和无形财产。"},{"i":37,"n":"第三十七条","txt":"自然人、法人和非法人组织开展演出、比赛、销售、拍卖等经营性活动，承诺将全部或者部分所得用于慈善目的的，应当在举办活动前与慈善组织或者其他接受捐赠的人签订捐赠协议，活动结束后按照捐赠协议履行捐赠义务，并将捐赠情况向社会公开。"},{"i":38,"n":"第三十八条","txt":"慈善组织接受捐赠，应当向捐赠人开具由财政部门统一监（印）制的捐赠票据。捐赠票据应当载明捐赠人、捐赠财产的种类及数量、慈善组织名称和经办人姓名、票据日期等。捐赠人匿名或者放弃接受捐赠票据的，慈善组织应当做好相关记录。"},{"i":39,"n":"第三十九条","txt":"慈善组织接受捐赠，捐赠人要求签订书面捐赠协议的，慈善组织应当与捐赠人签订书面捐赠协议。"},{"i":40,"n":"第四十条","txt":"捐赠人与慈善组织约定捐赠财产的用途和受益人时，不得指定或者变相指定捐赠人的利害关系人作为受益人。"},{"i":41,"n":"第四十一条","txt":"捐赠人应当按照捐赠协议履行捐赠义务。捐赠人违反捐赠协议逾期未交付捐赠财产，有下列情形之一的，慈善组织或者其他接受捐赠的人可以要求交付；捐赠人拒不交付的，慈善组织和其他接受捐赠的人可以依法向人民法院申请支付令或者提起诉讼："},{"i":42,"n":"第四十二条","txt":"捐赠人有权查询、复制其捐赠财产管理使用的有关资料，慈善组织应当及时主动向捐赠人反馈有关情况。"},{"i":43,"n":"第四十三条","txt":"国有企业实施慈善捐赠应当遵守有关国有资产管理的规定，履行批准和备案程序。"},{"i":44,"n":"第四十四条","txt":"本法所称慈善信托属于公益信托，是指委托人基于慈善目的，依法将其财产委托给受托人，由受托人按照委托人意愿以受托人名义进行管理和处分，开展慈善活动的行为。"},{"i":45,"n":"第四十五条","txt":"设立慈善信托、确定受托人和监察人，应当采取书面形式。受托人应当在慈善信托文件签订之日起七日内，将相关文件向受托人所在地县级以上人民政府民政部门备案。"},{"i":46,"n":"第四十六条","txt":"慈善信托的委托人不得指定或者变相指定其利害关系人作为受益人。"},{"i":47,"n":"第四十七条","txt":"慈善信托的受托人，可以由委托人确定其信赖的慈善组织或者信托公司担任。"},{"i":48,"n":"第四十八条","txt":"慈善信托的受托人违反信托义务或者难以履行职责的，委托人可以变更受托人。变更后的受托人应当自变更之日起七日内，将变更情况报原备案的民政部门重新备案。"},{"i":49,"n":"第四十九条","txt":"慈善信托的受托人管理和处分信托财产，应当按照信托目的，恪尽职守，履行诚信、谨慎管理的义务。"},{"i":50,"n":"第五十条","txt":"慈善信托的委托人根据需要，可以确定信托监察人。"},{"i":51,"n":"第五十一条","txt":"慈善信托的设立、信托财产的管理、信托当事人、信托的终止和清算等事项，本章未规定的，适用本法其他有关规定；本法未规定的，适用《中华人民共和国信托法》的有关规定。"},{"i":52,"n":"第五十二条","txt":"慈善组织的财产包括："},{"i":53,"n":"第五十三条","txt":"慈善组织的财产应当根据章程和捐赠协议的规定全部用于慈善目的，不得在发起人、捐赠人以及慈善组织成员中分配。"},{"i":54,"n":"第五十四条","txt":"慈善组织对募集的财产，应当登记造册，严格管理，专款专用。"},{"i":55,"n":"第五十五条","txt":"慈善组织为实现财产保值、增值进行投资的，应当遵循合法、安全、有效的原则，投资取得的收益应当全部用于慈善目的。慈善组织的重大投资方案应当经决策机构组成人员三分之二以上同意。政府资助的财产和捐赠协议约定不得投资的财产，不得用于投资。慈善组织的负责人和工作人员不得在慈善组织投资的企业兼职或者领取报酬。"},{"i":56,"n":"第五十六条","txt":"慈善组织开展慈善活动，应当依照法律法规和章程的规定，按照募捐方案或者捐赠协议使用捐赠财产。慈善组织确需变更募捐方案规定的捐赠财产用途的，应当报原备案的民政部门备案；确需变更捐赠协议约定的捐赠财产用途的，应当征得捐赠人同意。"},{"i":57,"n":"第五十七条","txt":"慈善组织应当合理设计慈善项目，优化实施流程，降低运行成本，提高慈善财产使用效益。"},{"i":58,"n":"第五十八条","txt":"慈善项目终止后捐赠财产有剩余的，按照募捐方案或者捐赠协议处理；募捐方案未规定或者捐赠协议未约定的，慈善组织应当将剩余财产用于目的相同或者相近的其他慈善项目，并向社会公开。"},{"i":59,"n":"第五十九条","txt":"慈善组织确定慈善受益人，应当坚持公开、公平、公正的原则，不得指定或者变相指定慈善组织管理人员的利害关系人作为受益人。"},{"i":60,"n":"第六十条","txt":"慈善组织根据需要可以与受益人签订协议，明确双方权利义务，约定慈善财产的用途、数额和使用方式等内容。"},{"i":61,"n":"第六十一条","txt":"慈善组织应当积极开展慈善活动，遵循管理费用、募捐成本等最必要原则，厉行节约，减少不必要的开支，充分、高效运用慈善财产。具有公开募捐资格的基金会开展慈善活动的年度支出，不得低于上一年总收入的百分之七十或者前三年收入平均数额的百分之七十；年度管理费用不得超过当年总支出的百分之十；特殊情况下，年度支出和管理费用难以符合前述规定的，应当报告办理其登记的民政部门并向社会公开说明情况。"},{"i":62,"n":"第六十二条","txt":"本法所称慈善服务，是指慈善组织和其他组织以及个人基于慈善目的，向社会或者他人提供的志愿无偿服务以及其他非营利服务。"},{"i":63,"n":"第六十三条","txt":"开展慈善服务，应当尊重受益人、志愿者的人格尊严，不得侵害受益人、志愿者的隐私。"},{"i":64,"n":"第六十四条","txt":"开展医疗康复、教育培训等慈善服务，需要专门技能的，应当执行国家或者行业组织制定的标准和规程。"},{"i":65,"n":"第六十五条","txt":"慈善组织招募志愿者参与慈善服务，应当公示与慈善服务有关的全部信息，告知服务过程中可能发生的风险。"},{"i":66,"n":"第六十六条","txt":"慈善组织应当对志愿者实名登记，记录志愿者的服务时间、内容、评价等信息。根据志愿者的要求，慈善组织应当无偿、如实出具志愿服务记录证明。"},{"i":67,"n":"第六十七条","txt":"慈善组织安排志愿者参与慈善服务，应当与志愿者的年龄、文化程度、技能和身体状况相适应。"},{"i":68,"n":"第六十八条","txt":"志愿者接受慈善组织安排参与慈善服务的，应当服从管理，接受必要的培训。"},{"i":69,"n":"第六十九条","txt":"慈善组织应当为志愿者参与慈善服务提供必要条件，保障志愿者的合法权益。"},{"i":70,"n":"第七十条","txt":"发生重大突发事件需要迅速开展救助时，履行统一领导职责或者组织处置突发事件的人民政府应当依法建立协调机制，明确专门机构、人员，提供需求信息，及时有序引导慈善组织、志愿者等社会力量开展募捐和救助活动。"},{"i":71,"n":"第七十一条","txt":"国家鼓励慈善组织、慈善行业组织建立应急机制，加强信息共享、协商合作，提高慈善组织运行和慈善资源使用的效率。"},{"i":72,"n":"第七十二条","txt":"为应对重大突发事件开展公开募捐的，应当及时分配或者使用募得款物，在应急处置与救援阶段至少每五日公开一次募得款物的接收情况，及时公开分配、使用情况。"},{"i":73,"n":"第七十三条","txt":"为应对重大突发事件开展公开募捐，无法在募捐活动前办理募捐方案备案的，应当在活动开始后十日内补办备案手续。"},{"i":74,"n":"第七十四条","txt":"县级以上人民政府及其有关部门应当为捐赠款物分配送达提供便利条件。乡级人民政府、街道办事处和村民委员会、居民委员会，应当为捐赠款物分配送达、信息统计等提供力所能及的帮助。"},{"i":75,"n":"第七十五条","txt":"国家建立健全慈善信息统计和发布制度。"},{"i":76,"n":"第七十六条","txt":"县级以上人民政府民政部门和其他有关部门应当及时向社会公开下列慈善信息："},{"i":77,"n":"第七十七条","txt":"慈善组织、慈善信托的受托人应当依法履行信息公开义务。信息公开应当真实、完整、及时。"},{"i":78,"n":"第七十八条","txt":"慈善组织应当向社会公开组织章程和决策、执行、监督机构成员信息以及国务院民政部门要求公开的其他信息。上述信息有重大变更的，慈善组织应当及时向社会公开。"},{"i":79,"n":"第七十九条","txt":"具有公开募捐资格的慈善组织应当定期向社会公开其募捐情况和慈善项目实施情况。"},{"i":80,"n":"第八十条","txt":"慈善组织开展定向募捐的，应当及时向捐赠人告知募捐情况、募得款物的管理使用情况。"},{"i":81,"n":"第八十一条","txt":"慈善组织、慈善信托的受托人应当向受益人告知其资助标准、工作流程和工作规范等信息。"},{"i":82,"n":"第八十二条","txt":"涉及国家秘密、商业秘密、个人隐私的信息以及捐赠人、慈善信托的委托人不同意公开的姓名、名称、住所、通讯方式等信息，不得公开。"},{"i":83,"n":"第八十三条","txt":"县级以上人民政府应当将慈善事业纳入国民经济和社会发展规划，制定促进慈善事业发展的政策和措施。"},{"i":84,"n":"第八十四条","txt":"县级以上人民政府民政部门应当建立与其他部门之间的慈善信息共享机制。"},{"i":85,"n":"第八十五条","txt":"国家鼓励、引导、支持有意愿有能力的自然人、法人和非法人组织积极参与慈善事业。"},{"i":86,"n":"第八十六条","txt":"慈善组织及其取得的收入依法享受税收优惠。"},{"i":87,"n":"第八十七条","txt":"自然人、法人和非法人组织捐赠财产用于慈善活动的，依法享受税收优惠。企业慈善捐赠支出超过法律规定的准予在计算企业所得税应纳税所得额时当年扣除的部分，允许结转以后三年内在计算应纳税所得额时扣除。"},{"i":88,"n":"第八十八条","txt":"自然人、法人和非法人组织设立慈善信托开展慈善活动的，依法享受税收优惠。"},{"i":89,"n":"第八十九条","txt":"受益人接受慈善捐赠，依法享受税收优惠。"},{"i":90,"n":"第九十条","txt":"慈善组织、捐赠人、受益人依法享受税收优惠的，有关部门应当及时办理相关手续。"},{"i":91,"n":"第九十一条","txt":"捐赠人向慈善组织捐赠实物、有价证券、股权和知识产权的，依法免征权利转让的相关行政事业性费用。"},{"i":92,"n":"第九十二条","txt":"国家对开展扶贫济困、参与重大突发事件应对、参与重大国家战略的慈善活动，实行特殊的优惠政策。"},{"i":93,"n":"第九十三条","txt":"慈善组织开展本法第三条第一项、第二项规定的慈善活动需要慈善服务设施用地的，可以依法申请使用国有划拨土地或者农村集体建设用地。慈善服务设施用地非经法定程序不得改变用途。"},{"i":94,"n":"第九十四条","txt":"国家为慈善事业提供金融政策支持，鼓励金融机构为慈善组织、慈善信托提供融资和结算等金融服务。"},{"i":95,"n":"第九十五条","txt":"各级人民政府及其有关部门可以依法通过购买服务等方式，支持符合条件的慈善组织向社会提供服务，并依照有关政府采购的法律法规向社会公开相关情况。"},{"i":96,"n":"第九十六条","txt":"国家鼓励有条件的地方设立社区慈善组织，加强社区志愿者队伍建设，发展社区慈善事业。"},{"i":97,"n":"第九十七条","txt":"国家采取措施弘扬慈善文化，培育公民慈善意识。"},{"i":98,"n":"第九十八条","txt":"国家鼓励企业事业单位和其他组织为开展慈善活动提供场所和其他便利条件。"},{"i":99,"n":"第九十九条","txt":"经受益人同意，捐赠人对其捐赠的慈善项目可以冠名纪念，法律法规规定需要批准的，从其规定。"},{"i":100,"n":"第一百条","txt":"国家建立慈善表彰制度，对在慈善事业发展中做出突出贡献的自然人、法人和非法人组织，由县级以上人民政府或者有关部门予以表彰。"},{"i":101,"n":"第一百零一条","txt":"县级以上人民政府民政等有关部门将慈善捐赠、志愿服务记录等信息纳入相关主体信用记录，健全信用激励制度。"},{"i":102,"n":"第一百零二条","txt":"国家鼓励开展慈善国际交流与合作。"},{"i":103,"n":"第一百零三条","txt":"县级以上人民政府民政部门应当依法履行职责，对慈善活动进行监督检查，对慈善行业组织进行指导。"},{"i":104,"n":"第一百零四条","txt":"县级以上人民政府民政部门对涉嫌违反本法规定的慈善组织、慈善信托的受托人，有权采取下列措施："},{"i":105,"n":"第一百零五条","txt":"县级以上人民政府民政部门对慈善组织、有关单位和个人进行检查或者调查时，检查人员或者调查人员不得少于二人，并应当出示合法证件和检查、调查通知书。"},{"i":106,"n":"第一百零六条","txt":"县级以上人民政府民政部门应当建立慈善组织及其负责人、慈善信托的受托人信用记录制度，并向社会公布。"},{"i":107,"n":"第一百零七条","txt":"慈善行业组织应当建立健全行业规范，加强行业自律。"},{"i":108,"n":"第一百零八条","txt":"任何单位和个人发现慈善组织、慈善信托有违法行为的，可以向县级以上人民政府民政部门、其他有关部门或者慈善行业组织投诉、举报。民政部门、其他有关部门或者慈善行业组织接到投诉、举报后，应当及时调查处理。"},{"i":109,"n":"第一百零九条","txt":"慈善组织有下列情形之一的，由县级以上人民政府民政部门责令限期改正，予以警告或者责令限期停止活动，并没收违法所得；情节严重的，吊销登记证书并予以公告："},{"i":110,"n":"第一百一十条","txt":"慈善组织有下列情形之一的，由县级以上人民政府民政部门责令限期改正，予以警告，并没收违法所得；逾期不改正的，责令限期停止活动并进行整改："},{"i":111,"n":"第一百一十一条","txt":"慈善组织开展募捐活动有下列情形之一的，由县级以上人民政府民政部门予以警告，责令停止募捐活动；责令退还违法募集的财产，无法退还的，由民政部门予以收缴，转给其他慈善组织用于慈善目的；情节严重的，吊销公开募捐资格证书或者登记证书并予以公告，公开募捐资格证书被吊销的，五年内不得再次申请："},{"i":112,"n":"第一百一十二条","txt":"慈善组织有本法第一百零九条、第一百一十条、第一百一十一条规定情形的，由县级以上人民政府民政部门对直接负责的主管人员和其他直接责任人员处二万元以上二十万元以下罚款，并没收违法所得；情节严重的，禁止其一年至五年内担任慈善组织的管理人员。"},{"i":113,"n":"第一百一十三条","txt":"不具有公开募捐资格的组织或者个人擅自开展公开募捐的，由县级以上人民政府民政部门予以警告，责令停止募捐活动；责令退还违法募集的财产，无法退还的，由民政部门予以收缴，转给慈善组织用于慈善目的；情节严重的，对有关组织或者个人处二万元以上二十万元以下罚款。"},{"i":114,"n":"第一百一十四条","txt":"互联网公开募捐服务平台违反本法第二十七条规定的，由省级以上人民政府民政部门责令限期改正；逾期不改正的，由国务院民政部门取消指定。"},{"i":115,"n":"第一百一十五条","txt":"慈善组织不依法向捐赠人开具捐赠票据、不依法向志愿者出具志愿服务记录证明或者不及时主动向捐赠人反馈有关情况的，由县级以上人民政府民政部门予以警告，责令限期改正；逾期不改正的，责令限期停止活动。"},{"i":116,"n":"第一百一十六条","txt":"慈善组织弄虚作假骗取税收优惠的，由税务机关依法查处；情节严重的，由县级以上人民政府民政部门吊销登记证书并予以公告。"},{"i":117,"n":"第一百一十七条","txt":"慈善组织从事、资助危害国家安全或者社会公共利益活动的，由有关机关依法查处，由县级以上人民政府民政部门吊销登记证书并予以公告。"},{"i":118,"n":"第一百一十八条","txt":"慈善信托的委托人、受托人有下列情形之一的，由县级以上人民政府民政部门责令限期改正，予以警告，并没收违法所得；对直接负责的主管人员和其他直接责任人员处二万元以上二十万元以下罚款："},{"i":119,"n":"第一百一十九条","txt":"慈善服务过程中，因慈善组织或者志愿者过错造成受益人、第三人损害的，慈善组织依法承担赔偿责任；损害是由志愿者故意或者重大过失造成的，慈善组织可以向其追偿。"},{"i":120,"n":"第一百二十条","txt":"县级以上人民政府民政部门和其他有关部门及其工作人员有下列情形之一的，由上级机关或者监察机关责令改正；依法应当给予处分的，由任免机关或者监察机关对直接负责的主管人员和其他直接责任人员给予处分："},{"i":121,"n":"第一百二十一条","txt":"违反本法规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":122,"n":"第一百二十二条","txt":"城乡社区组织、单位可以在本社区、单位内部开展群众性互助互济活动。"},{"i":123,"n":"第一百二十三条","txt":"慈善组织以外的其他组织可以开展力所能及的慈善活动。"},{"i":124,"n":"第一百二十四条","txt":"个人因疾病等原因导致家庭经济困难，向社会发布求助信息的，求助人和信息发布人应当对信息真实性负责，不得通过虚构、隐瞒事实等方式骗取救助。"},{"i":125,"n":"第一百二十五条","txt":"本法自2016年9月1日起施行。"}],"wuzhangaihuanjingjianshefa":[{"i":1,"n":"第一条","txt":"为了加强无障碍环境建设，保障残疾人、老年人平等、充分、便捷地参与和融入社会生活，促进社会全体人员共享经济社会发展成果，弘扬社会主义核心价值观，根据宪法和有关法律，制定本法。"},{"i":2,"n":"第二条","txt":"国家采取措施推进无障碍环境建设，为残疾人、老年人自主安全地通行道路、出入建筑物以及使用其附属设施、搭乘公共交通运输工具，获取、使用和交流信息，获得社会服务等提供便利。"},{"i":3,"n":"第三条","txt":"无障碍环境建设应当坚持中国共产党的领导，发挥政府主导作用，调动市场主体积极性，引导社会组织和公众广泛参与，推动全社会共建共治共享。"},{"i":4,"n":"第四条","txt":"无障碍环境建设应当与适老化改造相结合，遵循安全便利、实用易行、广泛受益的原则。"},{"i":5,"n":"第五条","txt":"无障碍环境建设应当与经济社会发展水平相适应，统筹城镇和农村发展，逐步缩小城乡无障碍环境建设的差距。"},{"i":6,"n":"第六条","txt":"县级以上人民政府应当将无障碍环境建设纳入国民经济和社会发展规划，将所需经费纳入本级预算，建立稳定的经费保障机制。"},{"i":7,"n":"第七条","txt":"县级以上人民政府应当统筹协调和督促指导有关部门在各自职责范围内做好无障碍环境建设工作。"},{"i":8,"n":"第八条","txt":"残疾人联合会、老龄协会等组织依照法律、法规以及各自章程，协助各级人民政府及其有关部门做好无障碍环境建设工作。"},{"i":9,"n":"第九条","txt":"制定或者修改涉及无障碍环境建设的法律、法规、规章、规划和其他规范性文件，应当征求残疾人、老年人代表以及残疾人联合会、老龄协会等组织的意见。"},{"i":10,"n":"第十条","txt":"国家鼓励和支持企业事业单位、社会组织、个人等社会力量，通过捐赠、志愿服务等方式参与无障碍环境建设。"},{"i":11,"n":"第十一条","txt":"对在无障碍环境建设工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":12,"n":"第十二条","txt":"新建、改建、扩建的居住建筑、居住区、公共建筑、公共场所、交通运输设施、城乡道路等，应当符合无障碍设施工程建设标准。"},{"i":13,"n":"第十三条","txt":"国家鼓励工程建设、设计、施工等单位采用先进的理念和技术，建设人性化、系统化、智能化并与周边环境相协调的无障碍设施。"},{"i":14,"n":"第十四条","txt":"工程建设单位应当将无障碍设施建设经费纳入工程建设项目概预算。"},{"i":15,"n":"第十五条","txt":"工程设计单位应当按照无障碍设施工程建设标准进行设计。"},{"i":16,"n":"第十六条","txt":"工程施工、监理单位应当按照施工图设计文件以及相关标准进行无障碍设施施工和监理。"},{"i":17,"n":"第十七条","txt":"国家鼓励工程建设单位在新建、改建、扩建建设项目的规划、设计和竣工验收等环节，邀请残疾人、老年人代表以及残疾人联合会、老龄协会等组织，参加意见征询和体验试用等活动。"},{"i":18,"n":"第十八条","txt":"对既有的不符合无障碍设施工程建设标准的居住建筑、居住区、公共建筑、公共场所、交通运输设施、城乡道路等，县级以上人民政府应当根据实际情况，制定有针对性的无障碍设施改造计划并组织实施。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府应当支持、指导家庭无障碍设施改造。对符合条件的残疾人、老年人家庭应当给予适当补贴。"},{"i":20,"n":"第二十条","txt":"残疾人集中就业单位应当按照有关标准和要求，建设和改造无障碍设施。"},{"i":21,"n":"第二十一条","txt":"新建、改建、扩建公共建筑、公共场所、交通运输设施以及居住区的公共服务设施，应当按照无障碍设施工程建设标准，配套建设无障碍设施；既有的上述建筑、场所和设施不符合无障碍设施工程建设标准的，应当进行必要的改造。"},{"i":22,"n":"第二十二条","txt":"国家支持城镇老旧小区既有多层住宅加装电梯或者其他无障碍设施，为残疾人、老年人提供便利。"},{"i":23,"n":"第二十三条","txt":"新建、改建、扩建和具备改造条件的城市主干路、主要商业区和大型居住区的人行天桥和人行地下通道，应当按照无障碍设施工程建设标准，建设或者改造无障碍设施。"},{"i":24,"n":"第二十四条","txt":"停车场应当按照无障碍设施工程建设标准，设置无障碍停车位，并设置显著标志标识。"},{"i":25,"n":"第二十五条","txt":"新投入运营的民用航空器、客运列车、客运船舶、公共汽电车、城市轨道交通车辆等公共交通运输工具，应当确保一定比例符合无障碍标准。"},{"i":26,"n":"第二十六条","txt":"无障碍设施所有权人或者管理人应当对无障碍设施履行以下维护和管理责任，保障无障碍设施功能正常和使用安全："},{"i":27,"n":"第二十七条","txt":"因特殊情况设置的临时无障碍设施，应当符合无障碍设施工程建设标准。"},{"i":28,"n":"第二十八条","txt":"任何单位和个人不得擅自改变无障碍设施的用途或者非法占用、损坏无障碍设施。"},{"i":29,"n":"第二十九条","txt":"各级人民政府及其有关部门应当为残疾人、老年人获取公共信息提供便利；发布涉及自然灾害、事故灾难、公共卫生事件、社会安全事件等突发事件信息时，条件具备的同步采取语音、大字、盲文、手语等无障碍信息交流方式。"},{"i":30,"n":"第三十条","txt":"利用财政资金设立的电视台应当在播出电视节目时配备同步字幕，条件具备的每天至少播放一次配播手语的新闻节目，并逐步扩大配播手语的节目范围。"},{"i":31,"n":"第三十一条","txt":"国家鼓励公开出版发行的图书、报刊配备有声、大字、盲文、电子等无障碍格式版本，方便残疾人、老年人阅读。"},{"i":32,"n":"第三十二条","txt":"利用财政资金建立的互联网网站、服务平台、移动互联网应用程序，应当逐步符合无障碍网站设计标准和国家信息无障碍标准。"},{"i":33,"n":"第三十三条","txt":"音视频以及多媒体设备、移动智能终端设备、电信终端设备制造者提供的产品，应当逐步具备语音、大字等无障碍功能。"},{"i":34,"n":"第三十四条","txt":"电信业务经营者提供基础电信服务时，应当为残疾人、老年人提供必要的语音、大字信息服务或者人工服务。"},{"i":35,"n":"第三十五条","txt":"政务服务便民热线和报警求助、消防应急、交通事故、医疗急救等紧急呼叫系统，应当逐步具备语音、大字、盲文、一键呼叫等无障碍功能。"},{"i":36,"n":"第三十六条","txt":"提供公共文化服务的图书馆、博物馆、文化馆、科技馆等应当考虑残疾人、老年人的特点，积极创造条件，提供适合其需要的文献信息、无障碍设施设备和服务等。"},{"i":37,"n":"第三十七条","txt":"国务院有关部门应当完善药品标签、说明书的管理规范，要求药品生产经营者提供语音、大字、盲文、电子等无障碍格式版本的标签、说明书。"},{"i":38,"n":"第三十八条","txt":"国家推广和使用国家通用手语、国家通用盲文。"},{"i":39,"n":"第三十九条","txt":"公共服务场所应当配备必要的无障碍设备和辅助器具，标注指引无障碍设施，为残疾人、老年人提供无障碍服务。"},{"i":40,"n":"第四十条","txt":"行政服务机构、社区服务机构以及供水、供电、供气、供热等公共服务机构，应当设置低位服务台或者无障碍服务窗口，配备电子信息显示屏、手写板、语音提示等设备，为残疾人、老年人提供无障碍服务。"},{"i":41,"n":"第四十一条","txt":"司法机关、仲裁机构、法律援助机构应当依法为残疾人、老年人参加诉讼、仲裁活动和获得法律援助提供无障碍服务。"},{"i":42,"n":"第四十二条","txt":"交通运输设施和公共交通运输工具的运营单位应当根据各类运输方式的服务特点，结合设施设备条件和所提供的服务内容，为残疾人、老年人设置无障碍服务窗口、专用等候区域、绿色通道和优先坐席，提供辅助器具、咨询引导、字幕报站、语音提示、预约定制等无障碍服务。"},{"i":43,"n":"第四十三条","txt":"教育行政部门和教育机构应当加强教育场所的无障碍环境建设，为有残疾的师生、员工提供无障碍服务。"},{"i":44,"n":"第四十四条","txt":"医疗卫生机构应当结合所提供的服务内容，为残疾人、老年人就医提供便利。"},{"i":45,"n":"第四十五条","txt":"国家鼓励文化、旅游、体育、金融、邮政、电信、交通、商业、餐饮、住宿、物业管理等服务场所结合所提供的服务内容，为残疾人、老年人提供辅助器具、咨询引导等无障碍服务。"},{"i":46,"n":"第四十六条","txt":"公共场所经营管理单位、交通运输设施和公共交通运输工具的运营单位应当为残疾人携带导盲犬、导听犬、辅助犬等服务犬提供便利。"},{"i":47,"n":"第四十七条","txt":"应急避难场所的管理人在制定以及实施工作预案时，应当考虑残疾人、老年人的无障碍需求，视情况设置语音、大字、闪光等提示装置，完善无障碍服务功能。"},{"i":48,"n":"第四十八条","txt":"组织选举的部门和单位应当采取措施，为残疾人、老年人选民参加投票提供便利和必要协助。"},{"i":49,"n":"第四十九条","txt":"国家鼓励和支持无障碍信息服务平台建设，为残疾人、老年人提供远程实时无障碍信息服务。"},{"i":50,"n":"第五十条","txt":"国家开展无障碍环境理念的宣传教育，普及无障碍环境知识，传播无障碍环境文化，提升全社会的无障碍环境意识。"},{"i":51,"n":"第五十一条","txt":"国家推广通用设计理念，建立健全国家标准、行业标准、地方标准，鼓励发展具有引领性的团体标准、企业标准，加强标准之间的衔接配合，构建无障碍环境建设标准体系。"},{"i":52,"n":"第五十二条","txt":"制定或者修改涉及无障碍环境建设的标准，应当征求残疾人、老年人代表以及残疾人联合会、老龄协会等组织的意见。残疾人联合会、老龄协会等组织可以依法提出制定或者修改无障碍环境建设标准的建议。"},{"i":53,"n":"第五十三条","txt":"国家建立健全无障碍设计、设施、产品、服务的认证和无障碍信息的评测制度，并推动结果采信应用。"},{"i":54,"n":"第五十四条","txt":"国家通过经费支持、政府采购、税收优惠等方式，促进新科技成果在无障碍环境建设中的运用，鼓励无障碍技术、产品和服务的研发、生产、应用和推广，支持无障碍设施、信息和服务的融合发展。"},{"i":55,"n":"第五十五条","txt":"国家建立无障碍环境建设相关领域人才培养机制。"},{"i":56,"n":"第五十六条","txt":"国家鼓励机关、企业事业单位、社会团体以及其他社会组织，对工作人员进行无障碍服务知识与技能培训。"},{"i":57,"n":"第五十七条","txt":"文明城市、文明村镇、文明单位、文明社区、文明校园等创建活动，应当将无障碍环境建设情况作为重要内容。"},{"i":58,"n":"第五十八条","txt":"县级以上人民政府及其有关主管部门依法对无障碍环境建设进行监督检查，根据工作需要开展联合监督检查。"},{"i":59,"n":"第五十九条","txt":"国家实施无障碍环境建设目标责任制和考核评价制度。县级以上地方人民政府根据本地区实际，制定具体考核办法。"},{"i":60,"n":"第六十条","txt":"县级以上地方人民政府有关主管部门定期委托第三方机构开展无障碍环境建设评估，并将评估结果向社会公布，接受社会监督。"},{"i":61,"n":"第六十一条","txt":"县级以上人民政府建立无障碍环境建设信息公示制度，定期发布无障碍环境建设情况。"},{"i":62,"n":"第六十二条","txt":"任何组织和个人有权向政府有关主管部门提出加强和改进无障碍环境建设的意见和建议，对违反本法规定的行为进行投诉、举报。县级以上人民政府有关主管部门接到涉及无障碍环境建设的投诉和举报，应当及时处理并予以答复。"},{"i":63,"n":"第六十三条","txt":"对违反本法规定损害社会公共利益的行为，人民检察院可以提出检察建议或者提起公益诉讼。"},{"i":64,"n":"第六十四条","txt":"工程建设、设计、施工、监理单位未按照本法规定进行建设、设计、施工、监理的，由住房和城乡建设、民政、交通运输等相关主管部门责令限期改正；逾期未改正的，依照相关法律法规的规定进行处罚。"},{"i":65,"n":"第六十五条","txt":"违反本法规定，有下列情形之一的，由住房和城乡建设、民政、交通运输等相关主管部门责令限期改正；逾期未改正的，对单位处一万元以上三万元以下罚款，对个人处一百元以上五百元以下罚款："},{"i":66,"n":"第六十六条","txt":"违反本法规定，不依法履行无障碍信息交流义务的，由网信、工业和信息化、电信、广播电视、新闻出版等相关主管部门责令限期改正；逾期未改正的，予以通报批评。"},{"i":67,"n":"第六十七条","txt":"电信业务经营者不依法提供无障碍信息服务的，由电信主管部门责令限期改正；逾期未改正的，处一万元以上十万元以下罚款。"},{"i":68,"n":"第六十八条","txt":"负有公共服务职责的部门和单位未依法提供无障碍社会服务的，由本级人民政府或者上级主管部门责令限期改正；逾期未改正的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":69,"n":"第六十九条","txt":"考试举办者、组织者未依法向有残疾的考生提供便利服务的，由本级人民政府或者上级主管部门予以批评并责令改正；拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":70,"n":"第七十条","txt":"无障碍环境建设相关主管部门、有关组织的工作人员滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":71,"n":"第七十一条","txt":"违反本法规定，造成人身损害、财产损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":72,"n":"第七十二条","txt":"本法自2023年9月1日起施行。"}],"weichengnianrenbaohufa":[{"i":1,"n":"第一条","txt":"为了保护未成年人身心健康，保障未成年人合法权益，促进未成年人德智体美劳全面发展，培养有理想、有道德、有文化、有纪律的社会主义建设者和接班人，培养担当民族复兴大任的时代新人，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称未成年人是指未满十八周岁的公民。"},{"i":3,"n":"第三条","txt":"国家保障未成年人的生存权、发展权、受保护权、参与权等权利。"},{"i":4,"n":"第四条","txt":"保护未成年人，应当坚持最有利于未成年人的原则。处理涉及未成年人事项，应当符合下列要求："},{"i":5,"n":"第五条","txt":"国家、社会、学校和家庭应当对未成年人进行理想教育、道德教育、科学教育、文化教育、法治教育、国家安全教育、健康教育、劳动教育，加强爱国主义、集体主义和中国特色社会主义的教育，培养爱祖国、爱人民、爱劳动、爱科学、爱社会主义的公德，抵制资本主义、封建主义和其他腐朽思想的侵蚀，引导未成年人树立和践行社会主义核心价值观。"},{"i":6,"n":"第六条","txt":"保护未成年人，是国家机关、武装力量、政党、人民团体、企业事业单位、社会组织、城乡基层群众性自治组织、未成年人的监护人以及其他成年人的共同责任。"},{"i":7,"n":"第七条","txt":"未成年人的父母或者其他监护人依法对未成年人承担监护职责。"},{"i":8,"n":"第八条","txt":"县级以上人民政府应当将未成年人保护工作纳入国民经济和社会发展规划，相关经费纳入本级政府预算。"},{"i":9,"n":"第九条","txt":"各级人民政府应当重视和加强未成年人保护工作。县级以上人民政府负责妇女儿童工作的机构，负责未成年人保护工作的组织、协调、指导、督促，有关部门在各自职责范围内做好相关工作。"},{"i":10,"n":"第十条","txt":"共产主义青年团、妇女联合会、工会、残疾人联合会、关心下一代工作委员会、青年联合会、学生联合会、少年先锋队以及其他人民团体、有关社会组织，应当协助各级人民政府及其有关部门、人民检察院、人民法院做好未成年人保护工作，维护未成年人合法权益。"},{"i":11,"n":"第十一条","txt":"任何组织或者个人发现不利于未成年人身心健康或者侵犯未成年人合法权益的情形，都有权劝阻、制止或者向公安、民政、教育等有关部门提出检举、控告。"},{"i":12,"n":"第十二条","txt":"国家鼓励和支持未成年人保护方面的科学研究，建设相关学科、设置相关专业，加强人才培养。"},{"i":13,"n":"第十三条","txt":"国家建立健全未成年人统计调查制度，开展未成年人健康、受教育等状况的统计、调查和分析，发布未成年人保护的有关信息。"},{"i":14,"n":"第十四条","txt":"国家对保护未成年人有显著成绩的组织和个人给予表彰和奖励。"},{"i":15,"n":"第十五条","txt":"未成年人的父母或者其他监护人应当学习家庭教育知识，接受家庭教育指导，创造良好、和睦、文明的家庭环境。"},{"i":16,"n":"第十六条","txt":"未成年人的父母或者其他监护人应当履行下列监护职责："},{"i":17,"n":"第十七条","txt":"未成年人的父母或者其他监护人不得实施下列行为："},{"i":18,"n":"第十八条","txt":"未成年人的父母或者其他监护人应当为未成年人提供安全的家庭生活环境，及时排除引发触电、烫伤、跌落等伤害的安全隐患；采取配备儿童安全座椅、教育未成年人遵守交通规则等措施，防止未成年人受到交通事故的伤害；提高户外安全保护意识，避免未成年人发生溺水、动物伤害等事故。"},{"i":19,"n":"第十九条","txt":"未成年人的父母或者其他监护人应当根据未成年人的年龄和智力发展状况，在作出与未成年人权益有关的决定前，听取未成年人的意见，充分考虑其真实意愿。"},{"i":20,"n":"第二十条","txt":"未成年人的父母或者其他监护人发现未成年人身心健康受到侵害、疑似受到侵害或者其他合法权益受到侵犯的，应当及时了解情况并采取保护措施；情况严重的，应当立即向公安、民政、教育等部门报告。"},{"i":21,"n":"第二十一条","txt":"未成年人的父母或者其他监护人不得使未满八周岁或者由于身体、心理原因需要特别照顾的未成年人处于无人看护状态，或者将其交由无民事行为能力、限制民事行为能力、患有严重传染性疾病或者其他不适宜的人员临时照护。"},{"i":22,"n":"第二十二条","txt":"未成年人的父母或者其他监护人因外出务工等原因在一定期限内不能完全履行监护职责的，应当委托具有照护能力的完全民事行为能力人代为照护；无正当理由的，不得委托他人代为照护。"},{"i":23,"n":"第二十三条","txt":"未成年人的父母或者其他监护人应当及时将委托照护情况书面告知未成年人所在学校、幼儿园和实际居住地的居民委员会、村民委员会，加强和未成年人所在学校、幼儿园的沟通；与未成年人、被委托人至少每周联系和交流一次，了解未成年人的生活、学习、心理等情况，并给予未成年人亲情关爱。"},{"i":24,"n":"第二十四条","txt":"未成年人的父母离婚时，应当妥善处理未成年子女的抚养、教育、探望、财产等事宜，听取有表达意愿能力未成年人的意见。不得以抢夺、藏匿未成年子女等方式争夺抚养权。"},{"i":25,"n":"第二十五条","txt":"学校应当全面贯彻国家教育方针，坚持立德树人，实施素质教育，提高教育质量，注重培养未成年学生认知能力、合作能力、创新能力和实践能力，促进未成年学生全面发展。"},{"i":26,"n":"第二十六条","txt":"幼儿园应当做好保育、教育工作，遵循幼儿身心发展规律，实施启蒙教育，促进幼儿在体质、智力、品德等方面和谐发展。"},{"i":27,"n":"第二十七条","txt":"学校、幼儿园的教职员工应当尊重未成年人人格尊严，不得对未成年人实施体罚、变相体罚或者其他侮辱人格尊严的行为。"},{"i":28,"n":"第二十八条","txt":"学校应当保障未成年学生受教育的权利，不得违反国家规定开除、变相开除未成年学生。"},{"i":29,"n":"第二十九条","txt":"学校应当关心、爱护未成年学生，不得因家庭、身体、心理、学习能力等情况歧视学生。对家庭困难、身心有障碍的学生，应当提供关爱；对行为异常、学习有困难的学生，应当耐心帮助。"},{"i":30,"n":"第三十条","txt":"学校应当根据未成年学生身心发展特点，进行社会生活指导、心理健康辅导、青春期教育和生命教育。"},{"i":31,"n":"第三十一条","txt":"学校应当组织未成年学生参加与其年龄相适应的日常生活劳动、生产劳动和服务性劳动，帮助未成年学生掌握必要的劳动知识和技能，养成良好的劳动习惯。"},{"i":32,"n":"第三十二条","txt":"学校、幼儿园应当开展勤俭节约、反对浪费、珍惜粮食、文明饮食等宣传教育活动，帮助未成年人树立浪费可耻、节约为荣的意识，养成文明健康、绿色环保的生活习惯。"},{"i":33,"n":"第三十三条","txt":"学校应当与未成年学生的父母或者其他监护人互相配合，合理安排未成年学生的学习时间，保障其休息、娱乐和体育锻炼的时间。"},{"i":34,"n":"第三十四条","txt":"学校、幼儿园应当提供必要的卫生保健条件，协助卫生健康部门做好在校、在园未成年人的卫生保健工作。"},{"i":35,"n":"第三十五条","txt":"学校、幼儿园应当建立安全管理制度，对未成年人进行安全教育，完善安保设施、配备安保人员，保障未成年人在校、在园期间的人身和财产安全。"},{"i":36,"n":"第三十六条","txt":"使用校车的学校、幼儿园应当建立健全校车安全管理制度，配备安全管理人员，定期对校车进行安全检查，对校车驾驶人进行安全教育，并向未成年人讲解校车安全乘坐知识，培养未成年人校车安全事故应急处理技能。"},{"i":37,"n":"第三十七条","txt":"学校、幼儿园应当根据需要，制定应对自然灾害、事故灾难、公共卫生事件等突发事件和意外伤害的预案，配备相应设施并定期进行必要的演练。"},{"i":38,"n":"第三十八条","txt":"学校、幼儿园不得安排未成年人参加商业性活动，不得向未成年人及其父母或者其他监护人推销或者要求其购买指定的商品和服务。"},{"i":39,"n":"第三十九条","txt":"学校应当建立学生欺凌防控工作制度，对教职员工、学生等开展防治学生欺凌的教育和培训。"},{"i":40,"n":"第四十条","txt":"学校、幼儿园应当建立预防性侵害、性骚扰未成年人工作制度。对性侵害、性骚扰未成年人等违法犯罪行为，学校、幼儿园不得隐瞒，应当及时向公安机关、教育行政部门报告，并配合相关部门依法处理。"},{"i":41,"n":"第四十一条","txt":"婴幼儿照护服务机构、早期教育服务机构、校外培训机构、校外托管机构等应当参照本章有关规定，根据不同年龄阶段未成年人的成长特点和规律，做好未成年人保护工作。"},{"i":42,"n":"第四十二条","txt":"全社会应当树立关心、爱护未成年人的良好风尚。"},{"i":43,"n":"第四十三条","txt":"居民委员会、村民委员会应当设置专人专岗负责未成年人保护工作，协助政府有关部门宣传未成年人保护方面的法律法规，指导、帮助和监督未成年人的父母或者其他监护人依法履行监护职责，建立留守未成年人、困境未成年人的信息档案并给予关爱帮扶。"},{"i":44,"n":"第四十四条","txt":"爱国主义教育基地、图书馆、青少年宫、儿童活动中心、儿童之家应当对未成年人免费开放；博物馆、纪念馆、科技馆、展览馆、美术馆、文化馆、社区公益性互联网上网服务场所以及影剧院、体育场馆、动物园、植物园、公园等场所，应当按照有关规定对未成年人免费或者优惠开放。"},{"i":45,"n":"第四十五条","txt":"城市公共交通以及公路、铁路、水路、航空客运等应当按照有关规定对未成年人实施免费或者优惠票价。"},{"i":46,"n":"第四十六条","txt":"国家鼓励大型公共场所、公共交通工具、旅游景区景点等设置母婴室、婴儿护理台以及方便幼儿使用的坐便器、洗手台等卫生设施，为未成年人提供便利。"},{"i":47,"n":"第四十七条","txt":"任何组织或者个人不得违反有关规定，限制未成年人应当享有的照顾或者优惠。"},{"i":48,"n":"第四十八条","txt":"国家鼓励创作、出版、制作和传播有利于未成年人健康成长的图书、报刊、电影、广播电视节目、舞台艺术作品、音像制品、电子出版物和网络信息等。"},{"i":49,"n":"第四十九条","txt":"新闻媒体应当加强未成年人保护方面的宣传，对侵犯未成年人合法权益的行为进行舆论监督。新闻媒体采访报道涉及未成年人事件应当客观、审慎和适度，不得侵犯未成年人的名誉、隐私和其他合法权益。"},{"i":50,"n":"第五十条","txt":"禁止制作、复制、出版、发布、传播含有宣扬淫秽、色情、暴力、邪教、迷信、赌博、引诱自杀、恐怖主义、分裂主义、极端主义等危害未成年人身心健康内容的图书、报刊、电影、广播电视节目、舞台艺术作品、音像制品、电子出版物和网络信息等。"},{"i":51,"n":"第五十一条","txt":"任何组织或者个人出版、发布、传播的图书、报刊、电影、广播电视节目、舞台艺术作品、音像制品、电子出版物或者网络信息，包含可能影响未成年人身心健康内容的，应当以显著方式作出提示。"},{"i":52,"n":"第五十二条","txt":"禁止制作、复制、发布、传播或者持有有关未成年人的淫秽色情物品和网络信息。"},{"i":53,"n":"第五十三条","txt":"任何组织或者个人不得刊登、播放、张贴或者散发含有危害未成年人身心健康内容的广告；不得在学校、幼儿园播放、张贴或者散发商业广告；不得利用校服、教材等发布或者变相发布商业广告。"},{"i":54,"n":"第五十四条","txt":"禁止拐卖、绑架、虐待、非法收养未成年人，禁止对未成年人实施性侵害、性骚扰。"},{"i":55,"n":"第五十五条","txt":"生产、销售用于未成年人的食品、药品、玩具、用具和游戏游艺设备、游乐设施等，应当符合国家或者行业标准，不得危害未成年人的人身安全和身心健康。上述产品的生产者应当在显著位置标明注意事项，未标明注意事项的不得销售。"},{"i":56,"n":"第五十六条","txt":"未成年人集中活动的公共场所应当符合国家或者行业安全标准，并采取相应安全保护措施。对可能存在安全风险的设施，应当定期进行维护，在显著位置设置安全警示标志并标明适龄范围和注意事项；必要时应当安排专门人员看管。"},{"i":57,"n":"第五十七条","txt":"旅馆、宾馆、酒店等住宿经营者接待未成年人入住，或者接待未成年人和成年人共同入住时，应当询问父母或者其他监护人的联系方式、入住人员的身份关系等有关情况；发现有违法犯罪嫌疑的，应当立即向公安机关报告，并及时联系未成年人的父母或者其他监护人。"},{"i":58,"n":"第五十八条","txt":"学校、幼儿园周边不得设置营业性娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动的场所。营业性歌舞娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动场所的经营者，不得允许未成年人进入；游艺娱乐场所设置的电子游戏设备，除国家法定节假日外，不得向未成年人提供。经营者应当在显著位置设置未成年人禁入、限入标志；对难以判明是否是未成年人的，应当要求其出示身份证件。"},{"i":59,"n":"第五十九条","txt":"学校、幼儿园周边不得设置烟、酒、彩票销售网点。禁止向未成年人销售烟、酒、彩票或者兑付彩票奖金。烟、酒和彩票经营者应当在显著位置设置不向未成年人销售烟、酒或者彩票的标志；对难以判明是否是未成年人的，应当要求其出示身份证件。"},{"i":60,"n":"第六十条","txt":"禁止向未成年人提供、销售管制刀具或者其他可能致人严重伤害的器具等物品。经营者难以判明购买者是否是未成年人的，应当要求其出示身份证件。"},{"i":61,"n":"第六十一条","txt":"任何组织或者个人不得招用未满十六周岁未成年人，国家另有规定的除外。"},{"i":62,"n":"第六十二条","txt":"密切接触未成年人的单位招聘工作人员时，应当向公安机关、人民检察院查询应聘者是否具有性侵害、虐待、拐卖、暴力伤害等违法犯罪记录；发现其具有前述行为记录的，不得录用。"},{"i":63,"n":"第六十三条","txt":"任何组织或者个人不得隐匿、毁弃、非法删除未成年人的信件、日记、电子邮件或者其他网络通讯内容。"},{"i":64,"n":"第六十四条","txt":"国家、社会、学校和家庭应当加强未成年人网络素养宣传教育，培养和提高未成年人的网络素养，增强未成年人科学、文明、安全、合理使用网络的意识和能力，保障未成年人在网络空间的合法权益。"},{"i":65,"n":"第六十五条","txt":"国家鼓励和支持有利于未成年人健康成长的网络内容的创作与传播，鼓励和支持专门以未成年人为服务对象、适合未成年人身心健康特点的网络技术、产品、服务的研发、生产和使用。"},{"i":66,"n":"第六十六条","txt":"网信部门及其他有关部门应当加强对未成年人网络保护工作的监督检查，依法惩处利用网络从事危害未成年人身心健康的活动，为未成年人提供安全、健康的网络环境。"},{"i":67,"n":"第六十七条","txt":"网信部门会同公安、文化和旅游、新闻出版、电影、广播电视等部门根据保护不同年龄阶段未成年人的需要，确定可能影响未成年人身心健康网络信息的种类、范围和判断标准。"},{"i":68,"n":"第六十八条","txt":"新闻出版、教育、卫生健康、文化和旅游、网信等部门应当定期开展预防未成年人沉迷网络的宣传教育，监督网络产品和服务提供者履行预防未成年人沉迷网络的义务，指导家庭、学校、社会组织互相配合，采取科学、合理的方式对未成年人沉迷网络进行预防和干预。"},{"i":69,"n":"第六十九条","txt":"学校、社区、图书馆、文化馆、青少年宫等场所为未成年人提供的互联网上网服务设施，应当安装未成年人网络保护软件或者采取其他安全保护技术措施。"},{"i":70,"n":"第七十条","txt":"学校应当合理使用网络开展教学活动。未经学校允许，未成年学生不得将手机等智能终端产品带入课堂，带入学校的应当统一管理。"},{"i":71,"n":"第七十一条","txt":"未成年人的父母或者其他监护人应当提高网络素养，规范自身使用网络的行为，加强对未成年人使用网络行为的引导和监督。"},{"i":72,"n":"第七十二条","txt":"信息处理者通过网络处理未成年人个人信息的，应当遵循合法、正当和必要的原则。处理不满十四周岁未成年人个人信息的，应当征得未成年人的父母或者其他监护人同意，但法律、行政法规另有规定的除外。"},{"i":73,"n":"第七十三条","txt":"网络服务提供者发现未成年人通过网络发布私密信息的，应当及时提示，并采取必要的保护措施。"},{"i":74,"n":"第七十四条","txt":"网络产品和服务提供者不得向未成年人提供诱导其沉迷的产品和服务。"},{"i":75,"n":"第七十五条","txt":"网络游戏经依法审批后方可运营。"},{"i":76,"n":"第七十六条","txt":"网络直播服务提供者不得为未满十六周岁的未成年人提供网络直播发布者账号注册服务；为年满十六周岁的未成年人提供网络直播发布者账号注册服务时，应当对其身份信息进行认证，并征得其父母或者其他监护人同意。"},{"i":77,"n":"第七十七条","txt":"任何组织或者个人不得通过网络以文字、图片、音视频等形式，对未成年人实施侮辱、诽谤、威胁或者恶意损害形象等网络欺凌行为。"},{"i":78,"n":"第七十八条","txt":"网络产品和服务提供者应当建立便捷、合理、有效的投诉和举报渠道，公开投诉、举报方式等信息，及时受理并处理涉及未成年人的投诉、举报。"},{"i":79,"n":"第七十九条","txt":"任何组织或者个人发现网络产品、服务含有危害未成年人身心健康的信息，有权向网络产品和服务提供者或者网信、公安等部门投诉、举报。"},{"i":80,"n":"第八十条","txt":"网络服务提供者发现用户发布、传播可能影响未成年人身心健康的信息且未作显著提示的，应当作出提示或者通知用户予以提示；未作出提示的，不得传输相关信息。"},{"i":81,"n":"第八十一条","txt":"县级以上人民政府承担未成年人保护协调机制具体工作的职能部门应当明确相关内设机构或者专门人员，负责承担未成年人保护工作。"},{"i":82,"n":"第八十二条","txt":"各级人民政府应当将家庭教育指导服务纳入城乡公共服务体系，开展家庭教育知识宣传，鼓励和支持有关人民团体、企业事业单位、社会组织开展家庭教育指导服务。"},{"i":83,"n":"第八十三条","txt":"各级人民政府应当保障未成年人受教育的权利，并采取措施保障留守未成年人、困境未成年人、残疾未成年人接受义务教育。"},{"i":84,"n":"第八十四条","txt":"各级人民政府应当发展托育、学前教育事业，办好婴幼儿照护服务机构、幼儿园，支持社会力量依法兴办母婴室、婴幼儿照护服务机构、幼儿园。"},{"i":85,"n":"第八十五条","txt":"各级人民政府应当发展职业教育，保障未成年人接受职业教育或者职业技能培训，鼓励和支持人民团体、企业事业单位、社会组织为未成年人提供职业技能培训服务。"},{"i":86,"n":"第八十六条","txt":"各级人民政府应当保障具有接受普通教育能力、能适应校园生活的残疾未成年人就近在普通学校、幼儿园接受教育；保障不具有接受普通教育能力的残疾未成年人在特殊教育学校、幼儿园接受学前教育、义务教育和职业教育。"},{"i":87,"n":"第八十七条","txt":"地方人民政府及其有关部门应当保障校园安全，监督、指导学校、幼儿园等单位落实校园安全责任，建立突发事件的报告、处置和协调机制。"},{"i":88,"n":"第八十八条","txt":"公安机关和其他有关部门应当依法维护校园周边的治安和交通秩序，设置监控设备和交通安全设施，预防和制止侵害未成年人的违法犯罪行为。"},{"i":89,"n":"第八十九条","txt":"地方人民政府应当建立和改善适合未成年人的活动场所和设施，支持公益性未成年人活动场所和设施的建设和运行，鼓励社会力量兴办适合未成年人的活动场所和设施，并加强管理。"},{"i":90,"n":"第九十条","txt":"各级人民政府及其有关部门应当对未成年人进行卫生保健和营养指导，提供卫生保健服务。"},{"i":91,"n":"第九十一条","txt":"各级人民政府及其有关部门对困境未成年人实施分类保障，采取措施满足其生活、教育、安全、医疗康复、住房等方面的基本需要。"},{"i":92,"n":"第九十二条","txt":"具有下列情形之一的，民政部门应当依法对未成年人进行临时监护："},{"i":93,"n":"第九十三条","txt":"对临时监护的未成年人，民政部门可以采取委托亲属抚养、家庭寄养等方式进行安置，也可以交由未成年人救助保护机构或者儿童福利机构进行收留、抚养。"},{"i":94,"n":"第九十四条","txt":"具有下列情形之一的，民政部门应当依法对未成年人进行长期监护："},{"i":95,"n":"第九十五条","txt":"民政部门进行收养评估后，可以依法将其长期监护的未成年人交由符合条件的申请人收养。收养关系成立后，民政部门与未成年人的监护关系终止。"},{"i":96,"n":"第九十六条","txt":"民政部门承担临时监护或者长期监护职责的，财政、教育、卫生健康、公安等部门应当根据各自职责予以配合。"},{"i":97,"n":"第九十七条","txt":"县级以上人民政府应当开通全国统一的未成年人保护热线，及时受理、转介侵犯未成年人合法权益的投诉、举报；鼓励和支持人民团体、企业事业单位、社会组织参与建设未成年人保护服务平台、服务热线、服务站点，提供未成年人保护方面的咨询、帮助。"},{"i":98,"n":"第九十八条","txt":"国家建立性侵害、虐待、拐卖、暴力伤害等违法犯罪人员信息查询系统，向密切接触未成年人的单位提供免费查询服务。"},{"i":99,"n":"第九十九条","txt":"地方人民政府应当培育、引导和规范有关社会组织、社会工作者参与未成年人保护工作，开展家庭教育指导服务，为未成年人的心理辅导、康复救助、监护及收养评估等提供专业服务。"},{"i":100,"n":"第一百条","txt":"公安机关、人民检察院、人民法院和司法行政部门应当依法履行职责，保障未成年人合法权益。"},{"i":101,"n":"第一百零一条","txt":"公安机关、人民检察院、人民法院和司法行政部门应当确定专门机构或者指定专门人员，负责办理涉及未成年人案件。办理涉及未成年人案件的人员应当经过专门培训，熟悉未成年人身心特点。专门机构或者专门人员中，应当有女性工作人员。"},{"i":102,"n":"第一百零二条","txt":"公安机关、人民检察院、人民法院和司法行政部门办理涉及未成年人案件，应当考虑未成年人身心特点和健康成长的需要，使用未成年人能够理解的语言和表达方式，听取未成年人的意见。"},{"i":103,"n":"第一百零三条","txt":"公安机关、人民检察院、人民法院、司法行政部门以及其他组织和个人不得披露有关案件中未成年人的姓名、影像、住所、就读学校以及其他可能识别出其身份的信息，但查找失踪、被拐卖未成年人等情形除外。"},{"i":104,"n":"第一百零四条","txt":"对需要法律援助或者司法救助的未成年人，法律援助机构或者公安机关、人民检察院、人民法院和司法行政部门应当给予帮助，依法为其提供法律援助或者司法救助。"},{"i":105,"n":"第一百零五条","txt":"人民检察院通过行使检察权，对涉及未成年人的诉讼活动等依法进行监督。"},{"i":106,"n":"第一百零六条","txt":"未成年人合法权益受到侵犯，相关组织和个人未代为提起诉讼的，人民检察院可以督促、支持其提起诉讼；涉及公共利益的，人民检察院有权提起公益诉讼。"},{"i":107,"n":"第一百零七条","txt":"人民法院审理继承案件，应当依法保护未成年人的继承权和受遗赠权。"},{"i":108,"n":"第一百零八条","txt":"未成年人的父母或者其他监护人不依法履行监护职责或者严重侵犯被监护的未成年人合法权益的，人民法院可以根据有关人员或者单位的申请，依法作出人身安全保护令或者撤销监护人资格。"},{"i":109,"n":"第一百零九条","txt":"人民法院审理离婚、抚养、收养、监护、探望等案件涉及未成年人的，可以自行或者委托社会组织对未成年人的相关情况进行社会调查。"},{"i":110,"n":"第一百一十条","txt":"公安机关、人民检察院、人民法院讯问未成年犯罪嫌疑人、被告人，询问未成年被害人、证人，应当依法通知其法定代理人或者其成年亲属、所在学校的代表等合适成年人到场，并采取适当方式，在适当场所进行，保障未成年人的名誉权、隐私权和其他合法权益。"},{"i":111,"n":"第一百一十一条","txt":"公安机关、人民检察院、人民法院应当与其他有关政府部门、人民团体、社会组织互相配合，对遭受性侵害或者暴力伤害的未成年被害人及其家庭实施必要的心理干预、经济救助、法律援助、转学安置等保护措施。"},{"i":112,"n":"第一百一十二条","txt":"公安机关、人民检察院、人民法院办理未成年人遭受性侵害或者暴力伤害案件，在询问未成年被害人、证人时，应当采取同步录音录像等措施，尽量一次完成；未成年被害人、证人是女性的，应当由女性工作人员进行。"},{"i":113,"n":"第一百一十三条","txt":"对违法犯罪的未成年人，实行教育、感化、挽救的方针，坚持教育为主、惩罚为辅的原则。"},{"i":114,"n":"第一百一十四条","txt":"公安机关、人民检察院、人民法院和司法行政部门发现有关单位未尽到未成年人教育、管理、救助、看护等保护职责的，应当向该单位提出建议。被建议单位应当在一个月内作出书面回复。"},{"i":115,"n":"第一百一十五条","txt":"公安机关、人民检察院、人民法院和司法行政部门应当结合实际，根据涉及未成年人案件的特点，开展未成年人法治宣传教育工作。"},{"i":116,"n":"第一百一十六条","txt":"国家鼓励和支持社会组织、社会工作者参与涉及未成年人案件中未成年人的心理干预、法律援助、社会调查、社会观护、教育矫治、社区矫正等工作。"},{"i":117,"n":"第一百一十七条","txt":"违反本法第十一条第二款规定，未履行报告义务造成严重后果的，由上级主管部门或者所在单位对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":118,"n":"第一百一十八条","txt":"未成年人的父母或者其他监护人不依法履行监护职责或者侵犯未成年人合法权益的，由其居住地的居民委员会、村民委员会予以劝诫、制止；情节严重的，居民委员会、村民委员会应当及时向公安机关报告。"},{"i":119,"n":"第一百一十九条","txt":"学校、幼儿园、婴幼儿照护服务等机构及其教职员工违反本法第二十七条、第二十八条、第三十九条规定的，由公安、教育、卫生健康、市场监督管理等部门按照职责分工责令改正；拒不改正或者情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":120,"n":"第一百二十条","txt":"违反本法第四十四条、第四十五条、第四十七条规定，未给予未成年人免费或者优惠待遇的，由市场监督管理、文化和旅游、交通运输等部门按照职责分工责令限期改正，给予警告；拒不改正的，处一万元以上十万元以下罚款。"},{"i":121,"n":"第一百二十一条","txt":"违反本法第五十条、第五十一条规定的，由新闻出版、广播电视、电影、网信等部门按照职责分工责令限期改正，给予警告，没收违法所得，可以并处十万元以下罚款；拒不改正或者情节严重的，责令暂停相关业务、停产停业或者吊销营业执照、吊销相关许可证，违法所得一百万元以上的，并处违法所得一倍以上十倍以下的罚款，没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款。"},{"i":122,"n":"第一百二十二条","txt":"场所运营单位违反本法第五十六条第二款规定、住宿经营者违反本法第五十七条规定的，由市场监督管理、应急管理、公安等部门按照职责分工责令限期改正，给予警告；拒不改正或者造成严重后果的，责令停业整顿或者吊销营业执照、吊销相关许可证，并处一万元以上十万元以下罚款。"},{"i":123,"n":"第一百二十三条","txt":"相关经营者违反本法第五十八条、第五十九条第一款、第六十条规定的，由文化和旅游、市场监督管理、烟草专卖、公安等部门按照职责分工责令限期改正，给予警告，没收违法所得，可以并处五万元以下罚款；拒不改正或者情节严重的，责令停业整顿或者吊销营业执照、吊销相关许可证，可以并处五万元以上五十万元以下罚款。"},{"i":124,"n":"第一百二十四条","txt":"违反本法第五十九条第二款规定，在学校、幼儿园和其他未成年人集中活动的公共场所吸烟、饮酒的，由卫生健康、教育、市场监督管理等部门按照职责分工责令改正，给予警告，可以并处五百元以下罚款；场所管理者未及时制止的，由卫生健康、教育、市场监督管理等部门按照职责分工给予警告，并处一万元以下罚款。"},{"i":125,"n":"第一百二十五条","txt":"违反本法第六十一条规定的，由文化和旅游、人力资源和社会保障、市场监督管理等部门按照职责分工责令限期改正，给予警告，没收违法所得，可以并处十万元以下罚款；拒不改正或者情节严重的，责令停产停业或者吊销营业执照、吊销相关许可证，并处十万元以上一百万元以下罚款。"},{"i":126,"n":"第一百二十六条","txt":"密切接触未成年人的单位违反本法第六十二条规定，未履行查询义务，或者招用、继续聘用具有相关违法犯罪记录人员的，由教育、人力资源和社会保障、市场监督管理等部门按照职责分工责令限期改正，给予警告，并处五万元以下罚款；拒不改正或者造成严重后果的，责令停业整顿或者吊销营业执照、吊销相关许可证，并处五万元以上五十万元以下罚款，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":127,"n":"第一百二十七条","txt":"信息处理者违反本法第七十二条规定，或者网络产品和服务提供者违反本法第七十三条、第七十四条、第七十五条、第七十六条、第七十七条、第八十条规定的，由公安、网信、电信、新闻出版、广播电视、文化和旅游等有关部门按照职责分工责令改正，给予警告，没收违法所得，违法所得一百万元以上的，并处违法所得一倍以上十倍以下罚款，没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款，对直接负责的主管人员和其他责任人员处一万元以上十万元以下罚款；拒不改正或者情节严重的，并可以责令暂停相关业务、停业整顿、关闭网站、吊销营业执照或者吊销相关许可证。"},{"i":128,"n":"第一百二十八条","txt":"国家机关工作人员玩忽职守、滥用职权、徇私舞弊，损害未成年人合法权益的，依法给予处分。"},{"i":129,"n":"第一百二十九条","txt":"违反本法规定，侵犯未成年人合法权益，造成人身、财产或者其他损害的，依法承担民事责任。"},{"i":130,"n":"第一百三十条","txt":"本法中下列用语的含义："},{"i":131,"n":"第一百三十一条","txt":"对中国境内未满十八周岁的外国人、无国籍人，依照本法有关规定予以保护。"},{"i":132,"n":"第一百三十二条","txt":"本法自2021年6月1日起施行。"}],"canjirenbaozhangfa":[{"i":1,"n":"第一条","txt":"为了维护残疾人的合法权益，发展残疾人事业，保障残疾人平等地充分参与社会生活，共享社会物质文化成果，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"残疾人是指在心理、生理、人体结构上，某种组织、功能丧失或者不正常，全部或者部分丧失以正常方式从事某种活动能力的人。"},{"i":3,"n":"第三条","txt":"残疾人在政治、经济、文化、社会和家庭生活等方面享有同其他公民平等的权利。"},{"i":4,"n":"第四条","txt":"国家采取辅助方法和扶持措施，对残疾人给予特别扶助，减轻或者消除残疾影响和外界障碍，保障残疾人权利的实现。"},{"i":5,"n":"第五条","txt":"县级以上人民政府应当将残疾人事业纳入国民经济和社会发展规划，加强领导，综合协调，并将残疾人事业经费列入财政预算，建立稳定的经费保障机制。"},{"i":6,"n":"第六条","txt":"国家采取措施，保障残疾人依照法律规定，通过各种途径和形式，管理国家事务，管理经济和文化事业，管理社会事务。"},{"i":7,"n":"第七条","txt":"全社会应当发扬人道主义精神，理解、尊重、关心、帮助残疾人，支持残疾人事业。"},{"i":8,"n":"第八条","txt":"中国残疾人联合会及其地方组织，代表残疾人的共同利益，维护残疾人的合法权益，团结教育残疾人，为残疾人服务。"},{"i":9,"n":"第九条","txt":"残疾人的扶养人必须对残疾人履行扶养义务。"},{"i":10,"n":"第十条","txt":"国家鼓励残疾人自尊、自信、自强、自立，为社会主义建设贡献力量。"},{"i":11,"n":"第十一条","txt":"国家有计划地开展残疾预防工作，加强对残疾预防工作的领导，宣传、普及母婴保健和预防残疾的知识，建立健全出生缺陷预防和早期发现、早期治疗机制，针对遗传、疾病、药物、事故、灾害、环境污染和其他致残因素，组织和动员社会力量，采取措施，预防残疾的发生，减轻残疾程度。"},{"i":12,"n":"第十二条","txt":"国家和社会对残疾军人、因公致残人员以及其他为维护国家和人民利益致残的人员实行特别保障，给予抚恤和优待。"},{"i":13,"n":"第十三条","txt":"对在社会主义建设中做出显著成绩的残疾人，对维护残疾人合法权益、发展残疾人事业、为残疾人服务做出显著成绩的单位和个人，各级人民政府和有关部门给予表彰和奖励。"},{"i":14,"n":"第十四条","txt":"每年5月的第三个星期日为全国助残日。"},{"i":15,"n":"第十五条","txt":"国家保障残疾人享有康复服务的权利。"},{"i":16,"n":"第十六条","txt":"康复工作应当从实际出发，将现代康复技术与我国传统康复技术相结合；以社区康复为基础，康复机构为骨干，残疾人家庭为依托；以实用、易行、受益广的康复内容为重点，优先开展残疾儿童抢救性治疗和康复；发展符合康复要求的科学技术，鼓励自主创新，加强康复新技术的研究、开发和应用，为残疾人提供有效的康复服务。"},{"i":17,"n":"第十七条","txt":"各级人民政府鼓励和扶持社会力量兴办残疾人康复机构。"},{"i":18,"n":"第十八条","txt":"地方各级人民政府和有关部门应当根据需要有计划地在医疗机构设立康复医学科室，举办残疾人康复机构，开展康复医疗与训练、人员培训、技术指导、科学研究等工作。"},{"i":19,"n":"第十九条","txt":"医学院校和其他有关院校应当有计划地开设康复课程，设置相关专业，培养各类康复专业人才。"},{"i":20,"n":"第二十条","txt":"政府有关部门应当组织和扶持残疾人康复器械、辅助器具的研制、生产、供应、维修服务。"},{"i":21,"n":"第二十一条","txt":"国家保障残疾人享有平等接受教育的权利。"},{"i":22,"n":"第二十二条","txt":"残疾人教育，实行普及与提高相结合、以普及为重点的方针，保障义务教育，着重发展职业教育，积极开展学前教育，逐步发展高级中等以上教育。"},{"i":23,"n":"第二十三条","txt":"残疾人教育应当根据残疾人的身心特性和需要，按照下列要求实施："},{"i":24,"n":"第二十四条","txt":"县级以上人民政府应当根据残疾人的数量、分布状况和残疾类别等因素，合理设置残疾人教育机构，并鼓励社会力量办学、捐资助学。"},{"i":25,"n":"第二十五条","txt":"普通教育机构对具有接受普通教育能力的残疾人实施教育，并为其学习提供便利和帮助。"},{"i":26,"n":"第二十六条","txt":"残疾幼儿教育机构、普通幼儿教育机构附设的残疾儿童班、特殊教育机构的学前班、残疾儿童福利机构、残疾儿童家庭，对残疾儿童实施学前教育。"},{"i":27,"n":"第二十七条","txt":"政府有关部门、残疾人所在单位和有关社会组织应当对残疾人开展扫除文盲、职业培训、创业培训和其他成人教育，鼓励残疾人自学成才。"},{"i":28,"n":"第二十八条","txt":"国家有计划地举办各级各类特殊教育师范院校、专业，在普通师范院校附设特殊教育班，培养、培训特殊教育师资。普通师范院校开设特殊教育课程或者讲授有关内容，使普通教师掌握必要的特殊教育知识。"},{"i":29,"n":"第二十九条","txt":"政府有关部门应当组织和扶持盲文、手语的研究和应用，特殊教育教材的编写和出版，特殊教育教学用具及其他辅助用品的研制、生产和供应。"},{"i":30,"n":"第三十条","txt":"国家保障残疾人劳动的权利。"},{"i":31,"n":"第三十一条","txt":"残疾人劳动就业，实行集中与分散相结合的方针，采取优惠政策和扶持保护措施，通过多渠道、多层次、多种形式，使残疾人劳动就业逐步普及、稳定、合理。"},{"i":32,"n":"第三十二条","txt":"政府和社会举办残疾人福利企业、盲人按摩机构和其他福利性单位，集中安排残疾人就业。"},{"i":33,"n":"第三十三条","txt":"国家实行按比例安排残疾人就业制度。"},{"i":34,"n":"第三十四条","txt":"国家鼓励和扶持残疾人自主择业、自主创业。"},{"i":35,"n":"第三十五条","txt":"地方各级人民政府和农村基层组织，应当组织和扶持农村残疾人从事种植业、养殖业、手工业和其他形式的生产劳动。"},{"i":36,"n":"第三十六条","txt":"国家对安排残疾人就业达到、超过规定比例或者集中安排残疾人就业的用人单位和从事个体经营的残疾人，依法给予税收优惠，并在生产、经营、技术、资金、物资、场地等方面给予扶持。国家对从事个体经营的残疾人，免除行政事业性收费。"},{"i":37,"n":"第三十七条","txt":"政府有关部门设立的公共就业服务机构，应当为残疾人免费提供就业服务。"},{"i":38,"n":"第三十八条","txt":"国家保护残疾人福利性单位的财产所有权和经营自主权，其合法权益不受侵犯。"},{"i":39,"n":"第三十九条","txt":"残疾职工所在单位应当对残疾职工进行岗位技术培训，提高其劳动技能和技术水平。"},{"i":40,"n":"第四十条","txt":"任何单位和个人不得以暴力、威胁或者非法限制人身自由的手段强迫残疾人劳动。"},{"i":41,"n":"第四十一条","txt":"国家保障残疾人享有平等参与文化生活的权利。"},{"i":42,"n":"第四十二条","txt":"残疾人文化、体育、娱乐活动应当面向基层，融于社会公共文化生活，适应各类残疾人的不同特点和需要，使残疾人广泛参与。"},{"i":43,"n":"第四十三条","txt":"政府和社会采取下列措施，丰富残疾人的精神文化生活："},{"i":44,"n":"第四十四条","txt":"政府和社会鼓励、帮助残疾人从事文学、艺术、教育、科学、技术和其他有益于人民的创造性劳动。"},{"i":45,"n":"第四十五条","txt":"政府和社会促进残疾人与其他公民之间的相互理解和交流，宣传残疾人事业和扶助残疾人的事迹，弘扬残疾人自强不息的精神，倡导团结、友爱、互助的社会风尚。"},{"i":46,"n":"第四十六条","txt":"国家保障残疾人享有各项社会保障的权利。"},{"i":47,"n":"第四十七条","txt":"残疾人及其所在单位应当按照国家有关规定参加社会保险。"},{"i":48,"n":"第四十八条","txt":"各级人民政府对生活确有困难的残疾人，通过多种渠道给予生活、教育、住房和其他社会救助。"},{"i":49,"n":"第四十九条","txt":"地方各级人民政府对无劳动能力、无扶养人或者扶养人不具有扶养能力、无生活来源的残疾人，按照规定予以供养。"},{"i":50,"n":"第五十条","txt":"县级以上人民政府对残疾人搭乘公共交通工具，应当根据实际情况给予便利和优惠。残疾人可以免费携带随身必备的辅助器具。"},{"i":51,"n":"第五十一条","txt":"政府有关部门和残疾人组织应当建立和完善社会各界为残疾人捐助和服务的渠道，鼓励和支持发展残疾人慈善事业，开展志愿者助残等公益活动。"},{"i":52,"n":"第五十二条","txt":"国家和社会应当采取措施，逐步完善无障碍设施，推进信息交流无障碍，为残疾人平等参与社会生活创造无障碍环境。"},{"i":53,"n":"第五十三条","txt":"无障碍设施的建设和改造，应当符合残疾人的实际需要。"},{"i":54,"n":"第五十四条","txt":"国家采取措施，为残疾人信息交流无障碍创造条件。"},{"i":55,"n":"第五十五条","txt":"公共服务机构和公共场所应当创造条件，为残疾人提供语音和文字提示、手语、盲文等信息交流服务，并提供优先服务和辅助性服务。"},{"i":56,"n":"第五十六条","txt":"组织选举的部门应当为残疾人参加选举提供便利；有条件的，应当为盲人提供盲文选票。"},{"i":57,"n":"第五十七条","txt":"国家鼓励和扶持无障碍辅助设备、无障碍交通工具的研制和开发。"},{"i":58,"n":"第五十八条","txt":"盲人携带导盲犬出入公共场所，应当遵守国家有关规定。"},{"i":59,"n":"第五十九条","txt":"残疾人的合法权益受到侵害的，可以向残疾人组织投诉，残疾人组织应当维护残疾人的合法权益，有权要求有关部门或者单位查处。有关部门或者单位应当依法查处，并予以答复。"},{"i":60,"n":"第六十条","txt":"残疾人的合法权益受到侵害的，有权要求有关部门依法处理，或者依法向仲裁机构申请仲裁，或者依法向人民法院提起诉讼。"},{"i":61,"n":"第六十一条","txt":"违反本法规定，对侵害残疾人权益行为的申诉、控告、检举，推诿、拖延、压制不予查处，或者对提出申诉、控告、检举的人进行打击报复的，由其所在单位、主管部门或者上级机关责令改正，并依法对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":62,"n":"第六十二条","txt":"违反本法规定，通过大众传播媒介或者其他方式贬低损害残疾人人格的，由文化、广播电视、电影、新闻出版或者其他有关主管部门依据各自的职权责令改正，并依法给予行政处罚。"},{"i":63,"n":"第六十三条","txt":"违反本法规定，有关教育机构拒不接收残疾学生入学，或者在国家规定的录取要求以外附加条件限制残疾学生就学的，由有关主管部门责令改正，并依法对直接负责的主管人员和其他直接责任人员给予处分。"},{"i":64,"n":"第六十四条","txt":"违反本法规定，在职工的招用等方面歧视残疾人的，由有关主管部门责令改正；残疾人劳动者可以依法向人民法院提起诉讼。"},{"i":65,"n":"第六十五条","txt":"违反本法规定，供养、托养机构及其工作人员侮辱、虐待、遗弃残疾人的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成违反治安管理行为的，依法给予行政处罚。"},{"i":66,"n":"第六十六条","txt":"违反本法规定，新建、改建和扩建建筑物、道路、交通设施，不符合国家有关无障碍设施工程建设标准，或者对无障碍设施未进行及时维修和保护造成后果的，由有关主管部门依法处理。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，侵害残疾人的合法权益，其他法律、法规规定行政处罚的，从其规定；造成财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"本法自2008年7月1日起施行。"}],"muyingbaojianfa":[{"i":1,"n":"第一条","txt":"为了保障母亲和婴儿健康，提高出生人口素质，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家发展母婴保健事业，提供必要条件和物质帮助，使母亲和婴儿获得医疗保健服务。"},{"i":3,"n":"第三条","txt":"各级人民政府领导母婴保健工作。"},{"i":4,"n":"第四条","txt":"国务院卫生行政部门主管全国母婴保健工作，根据不同地区情况提出分级分类指导原则，并对全国母婴保健工作实施监督管理。"},{"i":5,"n":"第五条","txt":"国家鼓励、支持母婴保健领域的教育和科学研究，推广先进、实用的母婴保健技术，普及母婴保健科学知识。"},{"i":6,"n":"第六条","txt":"对在母婴保健工作中做出显著成绩和在母婴保健科学研究中取得显著成果的组织和个人，应当给予奖励。"},{"i":7,"n":"第七条","txt":"医疗保健机构应当为公民提供婚前保健服务。"},{"i":8,"n":"第八条","txt":"婚前医学检查包括对下列疾病的检查："},{"i":9,"n":"第九条","txt":"经婚前医学检查，对患指定传染病在传染期内或者有关精神病在发病期内的，医师应当提出医学意见；准备结婚的男女双方应当暂缓结婚。"},{"i":10,"n":"第十条","txt":"经婚前医学检查，对诊断患医学上认为不宜生育的严重遗传性疾病的，医师应当向男女双方说明情况，提出医学意见；经男女双方同意，采取长效避孕措施或者施行结扎手术后不生育的，可以结婚。但《中华人民共和国婚姻法》规定禁止结婚的除外。"},{"i":11,"n":"第十一条","txt":"接受婚前医学检查的人员对检查结果持有异议的，可以申请医学技术鉴定，取得医学鉴定证明。"},{"i":12,"n":"第十二条","txt":"男女双方在结婚登记时，应当持有婚前医学检查证明或者医学鉴定证明。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市人民政府根据本地区的实际情况，制定婚前医学检查制度实施办法。"},{"i":14,"n":"第十四条","txt":"医疗保健机构应当为育龄妇女和孕产妇提供孕产期保健服务。"},{"i":15,"n":"第十五条","txt":"对患严重疾病或者接触致畸物质，妊娠可能危及孕妇生命安全或者可能严重影响孕妇健康和胎儿正常发育的，医疗保健机构应当予以医学指导。"},{"i":16,"n":"第十六条","txt":"医师发现或者怀疑患严重遗传性疾病的育龄夫妻，应当提出医学意见。育龄夫妻应当根据医师的医学意见采取相应的措施。"},{"i":17,"n":"第十七条","txt":"经产前检查，医师发现或者怀疑胎儿异常的，应当对孕妇进行产前诊断。"},{"i":18,"n":"第十八条","txt":"经产前诊断，有下列情形之一的，医师应当向夫妻双方说明情况，并提出终止妊娠的医学意见："},{"i":19,"n":"第十九条","txt":"依照本法规定施行终止妊娠或者结扎手术，应当经本人同意，并签署意见。本人无行为能力的，应当经其监护人同意，并签署意见。"},{"i":20,"n":"第二十条","txt":"生育过严重缺陷患儿的妇女再次妊娠前，夫妻双方应当到县级以上医疗保健机构接受医学检查。"},{"i":21,"n":"第二十一条","txt":"医师和助产人员应当严格遵守有关操作规程，提高助产技术和服务质量，预防和减少产伤。"},{"i":22,"n":"第二十二条","txt":"不能住院分娩的孕妇应当由经过培训、具备相应接生能力的接生人员实行消毒接生。"},{"i":23,"n":"第二十三条","txt":"医疗保健机构和从事家庭接生的人员按照国务院卫生行政部门的规定，出具统一制发的新生儿出生医学证明；有产妇和婴儿死亡以及新生儿出生缺陷情况的，应当向卫生行政部门报告。"},{"i":24,"n":"第二十四条","txt":"医疗保健机构为产妇提供科学育儿、合理营养和母乳喂养的指导。"},{"i":25,"n":"第二十五条","txt":"县级以上地方人民政府可以设立医学技术鉴定组织，负责对婚前医学检查、遗传病诊断和产前诊断结果有异议的进行医学技术鉴定。"},{"i":26,"n":"第二十六条","txt":"从事医学技术鉴定的人员，必须具有临床经验和医学遗传学知识，并具有主治医师以上的专业技术职务。"},{"i":27,"n":"第二十七条","txt":"医学技术鉴定实行回避制度。凡与当事人有利害关系，可能影响公正鉴定的人员，应当回避。"},{"i":28,"n":"第二十八条","txt":"各级人民政府应当采取措施，加强母婴保健工作，提高医疗保健服务水平，积极防治由环境因素所致严重危害母亲和婴儿健康的地方性高发性疾病，促进母婴保健事业的发展。"},{"i":29,"n":"第二十九条","txt":"县级以上地方人民政府卫生行政部门管理本行政区域内的母婴保健工作。"},{"i":30,"n":"第三十条","txt":"省、自治区、直辖市人民政府卫生行政部门指定的医疗保健机构负责本行政区域内的母婴保健监测和技术指导。"},{"i":31,"n":"第三十一条","txt":"医疗保健机构按照国务院卫生行政部门的规定，负责其职责范围内的母婴保健工作，建立医疗保健工作规范，提高医学技术水平，采取各种措施方便人民群众，做好母婴保健服务工作。"},{"i":32,"n":"第三十二条","txt":"医疗保健机构依照本法规定开展婚前医学检查、遗传病诊断、产前诊断以及施行结扎手术和终止妊娠手术的，必须符合国务院卫生行政部门规定的条件和技术标准，并经县级以上地方人民政府卫生行政部门许可。"},{"i":33,"n":"第三十三条","txt":"从事本法规定的遗传病诊断、产前诊断的人员，必须经过省、自治区、直辖市人民政府卫生行政部门的考核，并取得相应的合格证书。"},{"i":34,"n":"第三十四条","txt":"从事母婴保健工作的人员应当严格遵守职业道德，为当事人保守秘密。"},{"i":35,"n":"第三十五条","txt":"未取得国家颁发的有关合格证书的，有下列行为之一，县级以上地方人民政府卫生行政部门应当予以制止，并可以根据情节给予警告或者处以罚款："},{"i":36,"n":"第三十六条","txt":"未取得国家颁发的有关合格证书，施行终止妊娠手术或者采取其他方法终止妊娠，致人死亡、残疾、丧失或者基本丧失劳动能力的，依照刑法有关规定追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"从事母婴保健工作的人员违反本法规定，出具有关虚假医学证明或者进行胎儿性别鉴定的，由医疗保健机构或者卫生行政部门根据情节给予行政处分；情节严重的，依法取消执业资格。"},{"i":38,"n":"第三十八条","txt":"本法下列用语的含义："},{"i":39,"n":"第三十九条","txt":"本法自1995年6月1日起施行。"}],"falvyuanzhufa":[{"i":1,"n":"第一条","txt":"为了规范和促进法律援助工作，保障公民和有关当事人的合法权益，保障法律正确实施，维护社会公平正义，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称法律援助，是国家建立的为经济困难公民和符合法定条件的其他当事人无偿提供法律咨询、代理、刑事辩护等法律服务的制度，是公共法律服务体系的组成部分。"},{"i":3,"n":"第三条","txt":"法律援助工作坚持中国共产党领导，坚持以人民为中心，尊重和保障人权，遵循公开、公平、公正的原则，实行国家保障与社会参与相结合。"},{"i":4,"n":"第四条","txt":"县级以上人民政府应当将法律援助工作纳入国民经济和社会发展规划、基本公共服务体系，保障法律援助事业与经济社会协调发展。"},{"i":5,"n":"第五条","txt":"国务院司法行政部门指导、监督全国的法律援助工作。县级以上地方人民政府司法行政部门指导、监督本行政区域的法律援助工作。"},{"i":6,"n":"第六条","txt":"人民法院、人民检察院、公安机关应当在各自职责范围内保障当事人依法获得法律援助，为法律援助人员开展工作提供便利。"},{"i":7,"n":"第七条","txt":"律师协会应当指导和支持律师事务所、律师参与法律援助工作。"},{"i":8,"n":"第八条","txt":"国家鼓励和支持群团组织、事业单位、社会组织在司法行政部门指导下，依法提供法律援助。"},{"i":9,"n":"第九条","txt":"国家鼓励和支持企业事业单位、社会组织和个人等社会力量，依法通过捐赠等方式为法律援助事业提供支持；对符合条件的，给予税收优惠。"},{"i":10,"n":"第十条","txt":"司法行政部门应当开展经常性的法律援助宣传教育，普及法律援助知识。"},{"i":11,"n":"第十一条","txt":"国家对在法律援助工作中做出突出贡献的组织和个人，按照有关规定给予表彰、奖励。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府司法行政部门应当设立法律援助机构。法律援助机构负责组织实施法律援助工作，受理、审查法律援助申请，指派律师、基层法律服务工作者、法律援助志愿者等法律援助人员提供法律援助，支付法律援助补贴。"},{"i":13,"n":"第十三条","txt":"法律援助机构根据工作需要，可以安排本机构具有律师资格或者法律职业资格的工作人员提供法律援助；可以设置法律援助工作站或者联络点，就近受理法律援助申请。"},{"i":14,"n":"第十四条","txt":"法律援助机构可以在人民法院、人民检察院和看守所等场所派驻值班律师，依法为没有辩护人的犯罪嫌疑人、被告人提供法律援助。"},{"i":15,"n":"第十五条","txt":"司法行政部门可以通过政府采购等方式，择优选择律师事务所等法律服务机构为受援人提供法律援助。"},{"i":16,"n":"第十六条","txt":"律师事务所、基层法律服务所、律师、基层法律服务工作者负有依法提供法律援助的义务。"},{"i":17,"n":"第十七条","txt":"国家鼓励和规范法律援助志愿服务；支持符合条件的个人作为法律援助志愿者，依法提供法律援助。"},{"i":18,"n":"第十八条","txt":"国家建立健全法律服务资源依法跨区域流动机制，鼓励和支持律师事务所、律师、法律援助志愿者等在法律服务资源相对短缺地区提供法律援助。"},{"i":19,"n":"第十九条","txt":"法律援助人员应当依法履行职责，及时为受援人提供符合标准的法律援助服务，维护受援人的合法权益。"},{"i":20,"n":"第二十条","txt":"法律援助人员应当恪守职业道德和执业纪律，不得向受援人收取任何财物。"},{"i":21,"n":"第二十一条","txt":"法律援助机构、法律援助人员对提供法律援助过程中知悉的国家秘密、商业秘密和个人隐私应当予以保密。"},{"i":22,"n":"第二十二条","txt":"法律援助机构可以组织法律援助人员依法提供下列形式的法律援助服务："},{"i":23,"n":"第二十三条","txt":"法律援助机构应当通过服务窗口、电话、网络等多种方式提供法律咨询服务；提示当事人享有依法申请法律援助的权利，并告知申请法律援助的条件和程序。"},{"i":24,"n":"第二十四条","txt":"刑事案件的犯罪嫌疑人、被告人因经济困难或者其他原因没有委托辩护人的，本人及其近亲属可以向法律援助机构申请法律援助。"},{"i":25,"n":"第二十五条","txt":"刑事案件的犯罪嫌疑人、被告人属于下列人员之一，没有委托辩护人的，人民法院、人民检察院、公安机关应当通知法律援助机构指派律师担任辩护人："},{"i":26,"n":"第二十六条","txt":"对可能被判处无期徒刑、死刑的人，以及死刑复核案件的被告人，法律援助机构收到人民法院、人民检察院、公安机关通知后，应当指派具有三年以上相关执业经历的律师担任辩护人。"},{"i":27,"n":"第二十七条","txt":"人民法院、人民检察院、公安机关通知法律援助机构指派律师担任辩护人时，不得限制或者损害犯罪嫌疑人、被告人委托辩护人的权利。"},{"i":28,"n":"第二十八条","txt":"强制医疗案件的被申请人或者被告人没有委托诉讼代理人的，人民法院应当通知法律援助机构指派律师为其提供法律援助。"},{"i":29,"n":"第二十九条","txt":"刑事公诉案件的被害人及其法定代理人或者近亲属，刑事自诉案件的自诉人及其法定代理人，刑事附带民事诉讼案件的原告人及其法定代理人，因经济困难没有委托诉讼代理人的，可以向法律援助机构申请法律援助。"},{"i":30,"n":"第三十条","txt":"值班律师应当依法为没有辩护人的犯罪嫌疑人、被告人提供法律咨询、程序选择建议、申请变更强制措施、对案件处理提出意见等法律帮助。"},{"i":31,"n":"第三十一条","txt":"下列事项的当事人，因经济困难没有委托代理人的，可以向法律援助机构申请法律援助："},{"i":32,"n":"第三十二条","txt":"有下列情形之一，当事人申请法律援助的，不受经济困难条件的限制："},{"i":33,"n":"第三十三条","txt":"当事人不服司法机关生效裁判或者决定提出申诉或者申请再审，人民法院决定、裁定再审或者人民检察院提出抗诉，因经济困难没有委托辩护人或者诉讼代理人的，本人及其近亲属可以向法律援助机构申请法律援助。"},{"i":34,"n":"第三十四条","txt":"经济困难的标准，由省、自治区、直辖市人民政府根据本行政区域经济发展状况和法律援助工作需要确定，并实行动态调整。"},{"i":35,"n":"第三十五条","txt":"人民法院、人民检察院、公安机关和有关部门在办理案件或者相关事务中，应当及时告知有关当事人有权依法申请法律援助。"},{"i":36,"n":"第三十六条","txt":"人民法院、人民检察院、公安机关办理刑事案件，发现有本法第二十五条第一款、第二十八条规定情形的，应当在三日内通知法律援助机构指派律师。法律援助机构收到通知后，应当在三日内指派律师并通知人民法院、人民检察院、公安机关。"},{"i":37,"n":"第三十七条","txt":"人民法院、人民检察院、公安机关应当保障值班律师依法提供法律帮助，告知没有辩护人的犯罪嫌疑人、被告人有权约见值班律师，并依法为值班律师了解案件有关情况、阅卷、会见等提供便利。"},{"i":38,"n":"第三十八条","txt":"对诉讼事项的法律援助，由申请人向办案机关所在地的法律援助机构提出申请；对非诉讼事项的法律援助，由申请人向争议处理机关所在地或者事由发生地的法律援助机构提出申请。"},{"i":39,"n":"第三十九条","txt":"被羁押的犯罪嫌疑人、被告人、服刑人员，以及强制隔离戒毒人员等提出法律援助申请的，办案机关、监管场所应当在二十四小时内将申请转交法律援助机构。"},{"i":40,"n":"第四十条","txt":"无民事行为能力人或者限制民事行为能力人需要法律援助的，可以由其法定代理人代为提出申请。法定代理人侵犯无民事行为能力人、限制民事行为能力人合法权益的，其他法定代理人或者近亲属可以代为提出法律援助申请。"},{"i":41,"n":"第四十一条","txt":"因经济困难申请法律援助的，申请人应当如实说明经济困难状况。"},{"i":42,"n":"第四十二条","txt":"法律援助申请人有材料证明属于下列人员之一的，免予核查经济困难状况："},{"i":43,"n":"第四十三条","txt":"法律援助机构应当自收到法律援助申请之日起七日内进行审查，作出是否给予法律援助的决定。决定给予法律援助的，应当自作出决定之日起三日内指派法律援助人员为受援人提供法律援助；决定不给予法律援助的，应当书面告知申请人，并说明理由。"},{"i":44,"n":"第四十四条","txt":"法律援助机构收到法律援助申请后，发现有下列情形之一的，可以决定先行提供法律援助："},{"i":45,"n":"第四十五条","txt":"法律援助机构为老年人、残疾人提供法律援助服务的，应当根据实际情况提供无障碍设施设备和服务。"},{"i":46,"n":"第四十六条","txt":"法律援助人员接受指派后，无正当理由不得拒绝、拖延或者终止提供法律援助服务。"},{"i":47,"n":"第四十七条","txt":"受援人应当向法律援助人员如实陈述与法律援助事项有关的情况，及时提供证据材料，协助、配合办理法律援助事项。"},{"i":48,"n":"第四十八条","txt":"有下列情形之一的，法律援助机构应当作出终止法律援助的决定："},{"i":49,"n":"第四十九条","txt":"申请人、受援人对法律援助机构不予法律援助、终止法律援助的决定有异议的，可以向设立该法律援助机构的司法行政部门提出。"},{"i":50,"n":"第五十条","txt":"法律援助事项办理结束后，法律援助人员应当及时向法律援助机构报告，提交有关法律文书的副本或者复印件、办理情况报告等材料。"},{"i":51,"n":"第五十一条","txt":"国家加强法律援助信息化建设，促进司法行政部门与司法机关及其他有关部门实现信息共享和工作协同。"},{"i":52,"n":"第五十二条","txt":"法律援助机构应当依照有关规定及时向法律援助人员支付法律援助补贴。"},{"i":53,"n":"第五十三条","txt":"人民法院应当根据情况对受援人缓收、减收或者免收诉讼费用；对法律援助人员复制相关材料等费用予以免收或者减收。"},{"i":54,"n":"第五十四条","txt":"县级以上人民政府司法行政部门应当有计划地对法律援助人员进行培训，提高法律援助人员的专业素质和服务能力。"},{"i":55,"n":"第五十五条","txt":"受援人有权向法律援助机构、法律援助人员了解法律援助事项办理情况；法律援助机构、法律援助人员未依法履行职责的，受援人可以向司法行政部门投诉，并可以请求法律援助机构更换法律援助人员。"},{"i":56,"n":"第五十六条","txt":"司法行政部门应当建立法律援助工作投诉查处制度；接到投诉后，应当依照有关规定受理和调查处理，并及时向投诉人告知处理结果。"},{"i":57,"n":"第五十七条","txt":"司法行政部门应当加强对法律援助服务的监督，制定法律援助服务质量标准，通过第三方评估等方式定期进行质量考核。"},{"i":58,"n":"第五十八条","txt":"司法行政部门、法律援助机构应当建立法律援助信息公开制度，定期向社会公布法律援助资金使用、案件办理、质量考核结果等情况，接受社会监督。"},{"i":59,"n":"第五十九条","txt":"法律援助机构应当综合运用庭审旁听、案卷检查、征询司法机关意见和回访受援人等措施，督促法律援助人员提升服务质量。"},{"i":60,"n":"第六十条","txt":"律师协会应当将律师事务所、律师履行法律援助义务的情况纳入年度考核内容，对拒不履行或者怠于履行法律援助义务的律师事务所、律师，依照有关规定进行惩戒。"},{"i":61,"n":"第六十一条","txt":"法律援助机构及其工作人员有下列情形之一的，由设立该法律援助机构的司法行政部门责令限期改正；有违法所得的，责令退还或者没收违法所得；对直接负责的主管人员和其他直接责任人员，依法给予处分："},{"i":62,"n":"第六十二条","txt":"律师事务所、基层法律服务所有下列情形之一的，由司法行政部门依法给予处罚："},{"i":63,"n":"第六十三条","txt":"律师、基层法律服务工作者有下列情形之一的，由司法行政部门依法给予处罚："},{"i":64,"n":"第六十四条","txt":"受援人以欺骗或者其他不正当手段获得法律援助的，由司法行政部门责令其支付已实施法律援助的费用，并处三千元以下罚款。"},{"i":65,"n":"第六十五条","txt":"违反本法规定，冒用法律援助名义提供法律服务并谋取利益的，由司法行政部门责令改正，没收违法所得，并处违法所得一倍以上三倍以下罚款。"},{"i":66,"n":"第六十六条","txt":"国家机关及其工作人员在法律援助工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"工会、共产主义青年团、妇女联合会、残疾人联合会等群团组织开展法律援助工作，参照适用本法的相关规定。"},{"i":69,"n":"第六十九条","txt":"对外国人和无国籍人提供法律援助，我国法律有规定的，适用法律规定；我国法律没有规定的，可以根据我国缔结或者参加的国际条约，或者按照互惠原则，参照适用本法的相关规定。"},{"i":70,"n":"第七十条","txt":"对军人军属提供法律援助的具体办法，由国务院和中央军事委员会有关部门制定。"},{"i":71,"n":"第七十一条","txt":"本法自2022年1月1日起施行。"}],"tezhongshebeianquanfa":[{"i":1,"n":"第一条","txt":"为了加强特种设备安全工作，预防特种设备事故，保障人身和财产安全，促进经济社会发展，制定本法。"},{"i":2,"n":"第二条","txt":"特种设备的生产（包括设计、制造、安装、改造、修理）、经营、使用、检验、检测和特种设备安全的监督管理，适用本法。"},{"i":3,"n":"第三条","txt":"特种设备安全工作应当坚持安全第一、预防为主、节能环保、综合治理的原则。"},{"i":4,"n":"第四条","txt":"国家对特种设备的生产、经营、使用，实施分类的、全过程的安全监督管理。"},{"i":5,"n":"第五条","txt":"国务院负责特种设备安全监督管理的部门对全国特种设备安全实施监督管理。县级以上地方各级人民政府负责特种设备安全监督管理的部门对本行政区域内特种设备安全实施监督管理。"},{"i":6,"n":"第六条","txt":"国务院和地方各级人民政府应当加强对特种设备安全工作的领导，督促各有关部门依法履行监督管理职责。"},{"i":7,"n":"第七条","txt":"特种设备生产、经营、使用单位应当遵守本法和其他有关法律、法规，建立、健全特种设备安全和节能责任制度，加强特种设备安全和节能管理，确保特种设备生产、经营、使用安全，符合节能要求。"},{"i":8,"n":"第八条","txt":"特种设备生产、经营、使用、检验、检测应当遵守有关特种设备安全技术规范及相关标准。"},{"i":9,"n":"第九条","txt":"特种设备行业协会应当加强行业自律，推进行业诚信体系建设，提高特种设备安全管理水平。"},{"i":10,"n":"第十条","txt":"国家支持有关特种设备安全的科学技术研究，鼓励先进技术和先进管理方法的推广应用，对做出突出贡献的单位和个人给予奖励。"},{"i":11,"n":"第十一条","txt":"负责特种设备安全监督管理的部门应当加强特种设备安全宣传教育，普及特种设备安全知识，增强社会公众的特种设备安全意识。"},{"i":12,"n":"第十二条","txt":"任何单位和个人有权向负责特种设备安全监督管理的部门和有关部门举报涉及特种设备安全的违法行为，接到举报的部门应当及时处理。"},{"i":13,"n":"第十三条","txt":"特种设备生产、经营、使用单位及其主要负责人对其生产、经营、使用的特种设备安全负责。"},{"i":14,"n":"第十四条","txt":"特种设备安全管理人员、检测人员和作业人员应当按照国家有关规定取得相应资格，方可从事相关工作。特种设备安全管理人员、检测人员和作业人员应当严格执行安全技术规范和管理制度，保证特种设备安全。"},{"i":15,"n":"第十五条","txt":"特种设备生产、经营、使用单位对其生产、经营、使用的特种设备应当进行自行检测和维护保养，对国家规定实行检验的特种设备应当及时申报并接受检验。"},{"i":16,"n":"第十六条","txt":"特种设备采用新材料、新技术、新工艺，与安全技术规范的要求不一致，或者安全技术规范未作要求、可能对安全性能有重大影响的，应当向国务院负责特种设备安全监督管理的部门申报，由国务院负责特种设备安全监督管理的部门及时委托安全技术咨询机构或者相关专业机构进行技术评审，评审结果经国务院负责特种设备安全监督管理的部门批准，方可投入生产、使用。"},{"i":17,"n":"第十七条","txt":"国家鼓励投保特种设备安全责任保险。"},{"i":18,"n":"第十八条","txt":"国家按照分类监督管理的原则对特种设备生产实行许可制度。特种设备生产单位应当具备下列条件，并经负责特种设备安全监督管理的部门许可，方可从事生产活动："},{"i":19,"n":"第十九条","txt":"特种设备生产单位应当保证特种设备生产符合安全技术规范及相关标准的要求，对其生产的特种设备的安全性能负责。不得生产不符合安全性能要求和能效指标以及国家明令淘汰的特种设备。"},{"i":20,"n":"第二十条","txt":"锅炉、气瓶、氧舱、客运索道、大型游乐设施的设计文件，应当经负责特种设备安全监督管理的部门核准的检验机构鉴定，方可用于制造。"},{"i":21,"n":"第二十一条","txt":"特种设备出厂时，应当随附安全技术规范要求的设计文件、产品质量合格证明、安装及使用维护保养说明、监督检验证明等相关技术资料和文件，并在特种设备显著位置设置产品铭牌、安全警示标志及其说明。"},{"i":22,"n":"第二十二条","txt":"电梯的安装、改造、修理，必须由电梯制造单位或者其委托的依照本法取得相应许可的单位进行。电梯制造单位委托其他单位进行电梯安装、改造、修理的，应当对其安装、改造、修理进行安全指导和监控，并按照安全技术规范的要求进行校验和调试。电梯制造单位对电梯安全性能负责。"},{"i":23,"n":"第二十三条","txt":"特种设备安装、改造、修理的施工单位应当在施工前将拟进行的特种设备安装、改造、修理情况书面告知直辖市或者设区的市级人民政府负责特种设备安全监督管理的部门。"},{"i":24,"n":"第二十四条","txt":"特种设备安装、改造、修理竣工后，安装、改造、修理的施工单位应当在验收后三十日内将相关技术资料和文件移交特种设备使用单位。特种设备使用单位应当将其存入该特种设备的安全技术档案。"},{"i":25,"n":"第二十五条","txt":"锅炉、压力容器、压力管道元件等特种设备的制造过程和锅炉、压力容器、压力管道、电梯、起重机械、客运索道、大型游乐设施的安装、改造、重大修理过程，应当经特种设备检验机构按照安全技术规范的要求进行监督检验；未经监督检验或者监督检验不合格的，不得出厂或者交付使用。"},{"i":26,"n":"第二十六条","txt":"国家建立缺陷特种设备召回制度。因生产原因造成特种设备存在危及安全的同一性缺陷的，特种设备生产单位应当立即停止生产，主动召回。"},{"i":27,"n":"第二十七条","txt":"特种设备销售单位销售的特种设备，应当符合安全技术规范及相关标准的要求，其设计文件、产品质量合格证明、安装及使用维护保养说明、监督检验证明等相关技术资料和文件应当齐全。"},{"i":28,"n":"第二十八条","txt":"特种设备出租单位不得出租未取得许可生产的特种设备或者国家明令淘汰和已经报废的特种设备，以及未按照安全技术规范的要求进行维护保养和未经检验或者检验不合格的特种设备。"},{"i":29,"n":"第二十九条","txt":"特种设备在出租期间的使用管理和维护保养义务由特种设备出租单位承担，法律另有规定或者当事人另有约定的除外。"},{"i":30,"n":"第三十条","txt":"进口的特种设备应当符合我国安全技术规范的要求，并经检验合格；需要取得我国特种设备生产许可的，应当取得许可。"},{"i":31,"n":"第三十一条","txt":"进口特种设备，应当向进口地负责特种设备安全监督管理的部门履行提前告知义务。"},{"i":32,"n":"第三十二条","txt":"特种设备使用单位应当使用取得许可生产并经检验合格的特种设备。"},{"i":33,"n":"第三十三条","txt":"特种设备使用单位应当在特种设备投入使用前或者投入使用后三十日内，向负责特种设备安全监督管理的部门办理使用登记，取得使用登记证书。登记标志应当置于该特种设备的显著位置。"},{"i":34,"n":"第三十四条","txt":"特种设备使用单位应当建立岗位责任、隐患治理、应急救援等安全管理制度，制定操作规程，保证特种设备安全运行。"},{"i":35,"n":"第三十五条","txt":"特种设备使用单位应当建立特种设备安全技术档案。安全技术档案应当包括以下内容："},{"i":36,"n":"第三十六条","txt":"电梯、客运索道、大型游乐设施等为公众提供服务的特种设备的运营使用单位，应当对特种设备的使用安全负责，设置特种设备安全管理机构或者配备专职的特种设备安全管理人员；其他特种设备使用单位，应当根据情况设置特种设备安全管理机构或者配备专职、兼职的特种设备安全管理人员。"},{"i":37,"n":"第三十七条","txt":"特种设备的使用应当具有规定的安全距离、安全防护措施。"},{"i":38,"n":"第三十八条","txt":"特种设备属于共有的，共有人可以委托物业服务单位或者其他管理人管理特种设备，受托人履行本法规定的特种设备使用单位的义务，承担相应责任。共有人未委托的，由共有人或者实际管理人履行管理义务，承担相应责任。"},{"i":39,"n":"第三十九条","txt":"特种设备使用单位应当对其使用的特种设备进行经常性维护保养和定期自行检查，并作出记录。"},{"i":40,"n":"第四十条","txt":"特种设备使用单位应当按照安全技术规范的要求，在检验合格有效期届满前一个月向特种设备检验机构提出定期检验要求。"},{"i":41,"n":"第四十一条","txt":"特种设备安全管理人员应当对特种设备使用状况进行经常性检查，发现问题应当立即处理；情况紧急时，可以决定停止使用特种设备并及时报告本单位有关负责人。"},{"i":42,"n":"第四十二条","txt":"特种设备出现故障或者发生异常情况，特种设备使用单位应当对其进行全面检查，消除事故隐患，方可继续使用。"},{"i":43,"n":"第四十三条","txt":"客运索道、大型游乐设施在每日投入使用前，其运营使用单位应当进行试运行和例行安全检查，并对安全附件和安全保护装置进行检查确认。"},{"i":44,"n":"第四十四条","txt":"锅炉使用单位应当按照安全技术规范的要求进行锅炉水（介）质处理，并接受特种设备检验机构的定期检验。"},{"i":45,"n":"第四十五条","txt":"电梯的维护保养应当由电梯制造单位或者依照本法取得许可的安装、改造、修理单位进行。"},{"i":46,"n":"第四十六条","txt":"电梯投入使用后，电梯制造单位应当对其制造的电梯的安全运行情况进行跟踪调查和了解，对电梯的维护保养单位或者使用单位在维护保养和安全运行方面存在的问题，提出改进建议，并提供必要的技术帮助；发现电梯存在严重事故隐患时，应当及时告知电梯使用单位，并向负责特种设备安全监督管理的部门报告。电梯制造单位对调查和了解的情况，应当作出记录。"},{"i":47,"n":"第四十七条","txt":"特种设备进行改造、修理，按照规定需要变更使用登记的，应当办理变更登记，方可继续使用。"},{"i":48,"n":"第四十八条","txt":"特种设备存在严重事故隐患，无改造、修理价值，或者达到安全技术规范规定的其他报废条件的，特种设备使用单位应当依法履行报废义务，采取必要措施消除该特种设备的使用功能，并向原登记的负责特种设备安全监督管理的部门办理使用登记证书注销手续。"},{"i":49,"n":"第四十九条","txt":"移动式压力容器、气瓶充装单位，应当具备下列条件，并经负责特种设备安全监督管理的部门许可，方可从事充装活动："},{"i":50,"n":"第五十条","txt":"从事本法规定的监督检验、定期检验的特种设备检验机构，以及为特种设备生产、经营、使用提供检测服务的特种设备检测机构，应当具备下列条件，并经负责特种设备安全监督管理的部门核准，方可从事检验、检测工作："},{"i":51,"n":"第五十一条","txt":"特种设备检验、检测机构的检验、检测人员应当经考核，取得检验、检测人员资格，方可从事检验、检测工作。"},{"i":52,"n":"第五十二条","txt":"特种设备检验、检测工作应当遵守法律、行政法规的规定，并按照安全技术规范的要求进行。"},{"i":53,"n":"第五十三条","txt":"特种设备检验、检测机构及其检验、检测人员应当客观、公正、及时地出具检验、检测报告，并对检验、检测结果和鉴定结论负责。"},{"i":54,"n":"第五十四条","txt":"特种设备生产、经营、使用单位应当按照安全技术规范的要求向特种设备检验、检测机构及其检验、检测人员提供特种设备相关资料和必要的检验、检测条件，并对资料的真实性负责。"},{"i":55,"n":"第五十五条","txt":"特种设备检验、检测机构及其检验、检测人员对检验、检测过程中知悉的商业秘密，负有保密义务。"},{"i":56,"n":"第五十六条","txt":"特种设备检验机构及其检验人员利用检验工作故意刁难特种设备生产、经营、使用单位的，特种设备生产、经营、使用单位有权向负责特种设备安全监督管理的部门投诉，接到投诉的部门应当及时进行调查处理。"},{"i":57,"n":"第五十七条","txt":"负责特种设备安全监督管理的部门依照本法规定，对特种设备生产、经营、使用单位和检验、检测机构实施监督检查。"},{"i":58,"n":"第五十八条","txt":"负责特种设备安全监督管理的部门实施本法规定的许可工作，应当依照本法和其他有关法律、行政法规规定的条件和程序以及安全技术规范的要求进行审查；不符合规定的，不得许可。"},{"i":59,"n":"第五十九条","txt":"负责特种设备安全监督管理的部门在办理本法规定的许可时，其受理、审查、许可的程序必须公开，并应当自受理申请之日起三十日内，作出许可或者不予许可的决定；不予许可的，应当书面向申请人说明理由。"},{"i":60,"n":"第六十条","txt":"负责特种设备安全监督管理的部门对依法办理使用登记的特种设备应当建立完整的监督管理档案和信息查询系统；对达到报废条件的特种设备，应当及时督促特种设备使用单位依法履行报废义务。"},{"i":61,"n":"第六十一条","txt":"负责特种设备安全监督管理的部门在依法履行监督检查职责时，可以行使下列职权："},{"i":62,"n":"第六十二条","txt":"负责特种设备安全监督管理的部门在依法履行职责过程中，发现违反本法规定和安全技术规范要求的行为或者特种设备存在事故隐患时，应当以书面形式发出特种设备安全监察指令，责令有关单位及时采取措施予以改正或者消除事故隐患。紧急情况下要求有关单位采取紧急处置措施的，应当随后补发特种设备安全监察指令。"},{"i":63,"n":"第六十三条","txt":"负责特种设备安全监督管理的部门在依法履行职责过程中，发现重大违法行为或者特种设备存在严重事故隐患时，应当责令有关单位立即停止违法行为、采取措施消除事故隐患，并及时向上级负责特种设备安全监督管理的部门报告。接到报告的负责特种设备安全监督管理的部门应当采取必要措施，及时予以处理。"},{"i":64,"n":"第六十四条","txt":"地方各级人民政府负责特种设备安全监督管理的部门不得要求已经依照本法规定在其他地方取得许可的特种设备生产单位重复取得许可，不得要求对已经依照本法规定在其他地方检验合格的特种设备重复进行检验。"},{"i":65,"n":"第六十五条","txt":"负责特种设备安全监督管理的部门的安全监察人员应当熟悉相关法律、法规，具有相应的专业知识和工作经验，取得特种设备安全行政执法证件。"},{"i":66,"n":"第六十六条","txt":"负责特种设备安全监督管理的部门对特种设备生产、经营、使用单位和检验、检测机构实施监督检查，应当对每次监督检查的内容、发现的问题及处理情况作出记录，并由参加监督检查的特种设备安全监察人员和被检查单位的有关负责人签字后归档。被检查单位的有关负责人拒绝签字的，特种设备安全监察人员应当将情况记录在案。"},{"i":67,"n":"第六十七条","txt":"负责特种设备安全监督管理的部门及其工作人员不得推荐或者监制、监销特种设备；对履行职责过程中知悉的商业秘密负有保密义务。"},{"i":68,"n":"第六十八条","txt":"国务院负责特种设备安全监督管理的部门和省、自治区、直辖市人民政府负责特种设备安全监督管理的部门应当定期向社会公布特种设备安全总体状况。"},{"i":69,"n":"第六十九条","txt":"国务院负责特种设备安全监督管理的部门应当依法组织制定特种设备重特大事故应急预案，报国务院批准后纳入国家突发事件应急预案体系。"},{"i":70,"n":"第七十条","txt":"特种设备发生事故后，事故发生单位应当按照应急预案采取措施，组织抢救，防止事故扩大，减少人员伤亡和财产损失，保护事故现场和有关证据，并及时向事故发生地县级以上人民政府负责特种设备安全监督管理的部门和有关部门报告。"},{"i":71,"n":"第七十一条","txt":"事故发生地人民政府接到事故报告，应当依法启动应急预案，采取应急处置措施，组织应急救援。"},{"i":72,"n":"第七十二条","txt":"特种设备发生特别重大事故，由国务院或者国务院授权有关部门组织事故调查组进行调查。"},{"i":73,"n":"第七十三条","txt":"组织事故调查的部门应当将事故调查报告报本级人民政府，并报上一级人民政府负责特种设备安全监督管理的部门备案。有关部门和单位应当依照法律、行政法规的规定，追究事故责任单位和人员的责任。"},{"i":74,"n":"第七十四条","txt":"违反本法规定，未经许可从事特种设备生产活动的，责令停止生产，没收违法制造的特种设备，处十万元以上五十万元以下罚款；有违法所得的，没收违法所得；已经实施安装、改造、修理的，责令恢复原状或者责令限期由取得许可的单位重新安装、改造、修理。"},{"i":75,"n":"第七十五条","txt":"违反本法规定，特种设备的设计文件未经鉴定，擅自用于制造的，责令改正，没收违法制造的特种设备，处五万元以上五十万元以下罚款。"},{"i":76,"n":"第七十六条","txt":"违反本法规定，未进行型式试验的，责令限期改正；逾期未改正的，处三万元以上三十万元以下罚款。"},{"i":77,"n":"第七十七条","txt":"违反本法规定，特种设备出厂时，未按照安全技术规范的要求随附相关技术资料和文件的，责令限期改正；逾期未改正的，责令停止制造、销售，处二万元以上二十万元以下罚款；有违法所得的，没收违法所得。"},{"i":78,"n":"第七十八条","txt":"违反本法规定，特种设备安装、改造、修理的施工单位在施工前未书面告知负责特种设备安全监督管理的部门即行施工的，或者在验收后三十日内未将相关技术资料和文件移交特种设备使用单位的，责令限期改正；逾期未改正的，处一万元以上十万元以下罚款。"},{"i":79,"n":"第七十九条","txt":"违反本法规定，特种设备的制造、安装、改造、重大修理以及锅炉清洗过程，未经监督检验的，责令限期改正；逾期未改正的，处五万元以上二十万元以下罚款；有违法所得的，没收违法所得；情节严重的，吊销生产许可证。"},{"i":80,"n":"第八十条","txt":"违反本法规定，电梯制造单位有下列情形之一的，责令限期改正；逾期未改正的，处一万元以上十万元以下罚款："},{"i":81,"n":"第八十一条","txt":"违反本法规定，特种设备生产单位有下列行为之一的，责令限期改正；逾期未改正的，责令停止生产，处五万元以上五十万元以下罚款；情节严重的，吊销生产许可证："},{"i":82,"n":"第八十二条","txt":"违反本法规定，特种设备经营单位有下列行为之一的，责令停止经营，没收违法经营的特种设备，处三万元以上三十万元以下罚款；有违法所得的，没收违法所得："},{"i":83,"n":"第八十三条","txt":"违反本法规定，特种设备使用单位有下列行为之一的，责令限期改正；逾期未改正的，责令停止使用有关特种设备，处一万元以上十万元以下罚款："},{"i":84,"n":"第八十四条","txt":"违反本法规定，特种设备使用单位有下列行为之一的，责令停止使用有关特种设备，处三万元以上三十万元以下罚款："},{"i":85,"n":"第八十五条","txt":"违反本法规定，移动式压力容器、气瓶充装单位有下列行为之一的，责令改正，处二万元以上二十万元以下罚款；情节严重的，吊销充装许可证："},{"i":86,"n":"第八十六条","txt":"违反本法规定，特种设备生产、经营、使用单位有下列情形之一的，责令限期改正；逾期未改正的，责令停止使用有关特种设备或者停产停业整顿，处一万元以上五万元以下罚款："},{"i":87,"n":"第八十七条","txt":"违反本法规定，电梯、客运索道、大型游乐设施的运营使用单位有下列情形之一的，责令限期改正；逾期未改正的，责令停止使用有关特种设备或者停产停业整顿，处二万元以上十万元以下罚款："},{"i":88,"n":"第八十八条","txt":"违反本法规定，未经许可，擅自从事电梯维护保养的，责令停止违法行为，处一万元以上十万元以下罚款；有违法所得的，没收违法所得。"},{"i":89,"n":"第八十九条","txt":"发生特种设备事故，有下列情形之一的，对单位处五万元以上二十万元以下罚款；对主要负责人处一万元以上五万元以下罚款；主要负责人属于国家工作人员的，并依法给予处分："},{"i":90,"n":"第九十条","txt":"发生事故，对负有责任的单位除要求其依法承担相应的赔偿等责任外，依照下列规定处以罚款："},{"i":91,"n":"第九十一条","txt":"对事故发生负有责任的单位的主要负责人未依法履行职责或者负有领导责任的，依照下列规定处以罚款；属于国家工作人员的，并依法给予处分："},{"i":92,"n":"第九十二条","txt":"违反本法规定，特种设备安全管理人员、检测人员和作业人员不履行岗位职责，违反操作规程和有关安全规章制度，造成事故的，吊销相关人员的资格。"},{"i":93,"n":"第九十三条","txt":"违反本法规定，特种设备检验、检测机构及其检验、检测人员有下列行为之一的，责令改正，对机构处五万元以上二十万元以下罚款，对直接负责的主管人员和其他直接责任人员处五千元以上五万元以下罚款；情节严重的，吊销机构资质和有关人员的资格："},{"i":94,"n":"第九十四条","txt":"违反本法规定，负责特种设备安全监督管理的部门及其工作人员有下列行为之一的，由上级机关责令改正；对直接负责的主管人员和其他直接责任人员，依法给予处分："},{"i":95,"n":"第九十五条","txt":"违反本法规定，特种设备生产、经营、使用单位或者检验、检测机构拒不接受负责特种设备安全监督管理的部门依法实施的监督检查的，责令限期改正；逾期未改正的，责令停产停业整顿，处二万元以上二十万元以下罚款。"},{"i":96,"n":"第九十六条","txt":"违反本法规定，被依法吊销许可证的，自吊销许可证之日起三年内，负责特种设备安全监督管理的部门不予受理其新的许可申请。"},{"i":97,"n":"第九十七条","txt":"违反本法规定，造成人身、财产损害的，依法承担民事责任。"},{"i":98,"n":"第九十八条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":99,"n":"第九十九条","txt":"特种设备行政许可、检验的收费，依照法律、行政法规的规定执行。"},{"i":100,"n":"第一百条","txt":"军事装备、核设施、航空航天器使用的特种设备安全的监督管理不适用本法。"},{"i":101,"n":"第一百零一条","txt":"本法自2014年1月1日起施行。"}],"kuangshananquanfa":[{"i":1,"n":"第一条","txt":"为了保障矿山生产安全，防止矿山事故，保护矿山职工人身安全，促进采矿业的发展，制定本法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域和中华人民共和国管辖的其他海域从事矿产资源开采活动，必须遵守本法。"},{"i":3,"n":"第三条","txt":"矿山企业必须具有保障安全生产的设施，建立、健全安全管理制度，采取有效措施改善职工劳动条件，加强矿山安全管理工作，保证安全生产。"},{"i":4,"n":"第四条","txt":"国务院劳动行政主管部门对全国矿山安全工作实施统一监督。"},{"i":5,"n":"第五条","txt":"国家鼓励矿山安全科学技术研究，推广先进技术，改进安全设施，提高矿山安全生产水平。"},{"i":6,"n":"第六条","txt":"对坚持矿山安全生产，防止矿山事故，参加矿山抢险救护，进行矿山安全科学技术研究等方面取得显著成绩的单位和个人，给予奖励。"},{"i":7,"n":"第七条","txt":"矿山建设工程的安全设施必须和主体工程同时设计、同时施工、同时投入生产和使用。"},{"i":8,"n":"第八条","txt":"矿山建设工程的设计文件，必须符合矿山安全规程和行业技术规范，并按照国家规定经管理矿山企业的主管部门批准；不符合矿山安全规程和行业技术规范的，不得批准。"},{"i":9,"n":"第九条","txt":"矿山设计下列项目必须符合矿山安全规程和行业技术规范："},{"i":10,"n":"第十条","txt":"每个矿井必须有两个以上能行人的安全出口，出口之间的直线水平距离必须符合矿山安全规程和行业技术规范。"},{"i":11,"n":"第十一条","txt":"矿山必须有与外界相通的、符合安全要求的运输和通讯设施。"},{"i":12,"n":"第十二条","txt":"矿山建设工程必须按照管理矿山企业的主管部门批准的设计文件施工。"},{"i":13,"n":"第十三条","txt":"矿山开采必须具备保障安全生产的条件，执行开采不同矿种的矿山安全规程和行业技术规范。"},{"i":14,"n":"第十四条","txt":"矿山设计规定保留的矿柱、岩柱，在规定的期限内，应当予以保护，不得开采或者毁坏。"},{"i":15,"n":"第十五条","txt":"矿山使用的有特殊安全要求的设备、器材、防护用品和安全检测仪器，必须符合国家安全标准或者行业安全标准；不符合国家安全标准或者行业安全标准的，不得使用。"},{"i":16,"n":"第十六条","txt":"矿山企业必须对机电设备及其防护装置、安全检测仪器，定期检查、维修，保证使用安全。"},{"i":17,"n":"第十七条","txt":"矿山企业必须对作业场所中的有毒有害物质和井下空气含氧量进行检测，保证符合安全要求。"},{"i":18,"n":"第十八条","txt":"矿山企业必须对下列危害安全的事故隐患采取预防措施："},{"i":19,"n":"第十九条","txt":"矿山企业对使用机械、电气设备，排土场、矸石山、尾矿库与矿山闭坑后可能引起的危害，应当采取预防措施。"},{"i":20,"n":"第二十条","txt":"矿山企业必须建立、健全安全生产责任制。"},{"i":21,"n":"第二十一条","txt":"矿长应当定期向职工代表大会或者职工大会报告安全生产工作，发挥职工代表大会的监督作用。"},{"i":22,"n":"第二十二条","txt":"矿山企业职工必须遵守有关矿山安全的法律、法规和企业规章制度。"},{"i":23,"n":"第二十三条","txt":"矿山企业工会依法维护职工生产安全的合法权益，组织职工对矿山安全工作进行监督。"},{"i":24,"n":"第二十四条","txt":"矿山企业违反有关安全的法律、法规，工会有权要求企业行政方面或者有关部门认真处理。"},{"i":25,"n":"第二十五条","txt":"矿山企业工会发现企业行政方面违章指挥、强令工人冒险作业或者生产过程中发现明显重大事故隐患和职业危害，有权提出解决的建议；发现危及职工生命安全的情况时，有权向矿山企业行政方面建议组织职工撤离危险现场，矿山企业行政方面必须及时作出处理决定。"},{"i":26,"n":"第二十六条","txt":"矿山企业必须对职工进行安全教育、培训；未经安全教育、培训的，不得上岗作业。"},{"i":27,"n":"第二十七条","txt":"矿长必须经过考核，具备安全专业知识，具有领导安全生产和处理矿山事故的能力。"},{"i":28,"n":"第二十八条","txt":"矿山企业必须向职工发放保障安全生产所需的劳动防护用品。"},{"i":29,"n":"第二十九条","txt":"矿山企业不得录用未成年人从事矿山井下劳动。"},{"i":30,"n":"第三十条","txt":"矿山企业必须制定矿山事故防范措施，并组织落实。"},{"i":31,"n":"第三十一条","txt":"矿山企业应当建立由专职或者兼职人员组成的救护和医疗急救组织，配备必要的装备、器材和药物。"},{"i":32,"n":"第三十二条","txt":"矿山企业必须从矿产品销售额中按照国家规定提取安全技术措施专项费用。安全技术措施专项费用必须全部用于改善矿山安全生产条件，不得挪作他用。"},{"i":33,"n":"第三十三条","txt":"县级以上各级人民政府劳动行政主管部门对矿山安全工作行使下列监督职责："},{"i":34,"n":"第三十四条","txt":"县级以上人民政府管理矿山企业的主管部门对矿山安全工作行使下列管理职责："},{"i":35,"n":"第三十五条","txt":"劳动行政主管部门的矿山安全监督人员有权进入矿山企业，在现场检查安全状况；发现有危及职工安全的紧急险情时，应当要求矿山企业立即处理。"},{"i":36,"n":"第三十六条","txt":"发生矿山事故，矿山企业必须立即组织抢救，防止事故扩大，减少人员伤亡和财产损失，对伤亡事故必须立即如实报告劳动行政主管部门和管理矿山企业的主管部门。"},{"i":37,"n":"第三十七条","txt":"发生一般矿山事故，由矿山企业负责调查和处理。"},{"i":38,"n":"第三十八条","txt":"矿山企业对矿山事故中伤亡的职工按照国家规定给予抚恤或者补偿。"},{"i":39,"n":"第三十九条","txt":"矿山事故发生后，应当尽快消除现场危险，查明事故原因，提出防范措施。现场危险消除后，方可恢复生产。"},{"i":40,"n":"第四十条","txt":"违反本法规定，有下列行为之一的，由劳动行政主管部门责令改正，可以并处罚款；情节严重的，提请县级以上人民政府决定责令停产整顿；对主管人员和直接责任人员由其所在单位或者上级主管机关给予行政处分："},{"i":41,"n":"第四十一条","txt":"矿长不具备安全专业知识的，安全生产的特种作业人员未取得操作资格证书上岗作业的，由劳动行政主管部门责令限期改正；逾期不改正的，提请县级以上人民政府决定责令停产，调整配备合格人员后，方可恢复生产。"},{"i":42,"n":"第四十二条","txt":"矿山建设工程安全设施的设计未经批准擅自施工的，由管理矿山企业的主管部门责令停止施工；拒不执行的，由管理矿山企业的主管部门提请县级以上人民政府决定由有关主管部门吊销其采矿许可证和营业执照。"},{"i":43,"n":"第四十三条","txt":"矿山建设工程的安全设施未经验收或者验收不合格擅自投入生产的，由劳动行政主管部门会同管理矿山企业的主管部门责令停止生产，并由劳动行政主管部门处以罚款；拒不停止生产的，由劳动行政主管部门提请县级以上人民政府决定由有关主管部门吊销其采矿许可证和营业执照。"},{"i":44,"n":"第四十四条","txt":"已经投入生产的矿山企业，不具备安全生产条件而强行开采的，由劳动行政主管部门会同管理矿山企业的主管部门责令限期改进；逾期仍不具备安全生产条件的，由劳动行政主管部门提请县级以上人民政府决定责令停产整顿或者由有关主管部门吊销其采矿许可证和营业执照。"},{"i":45,"n":"第四十五条","txt":"当事人对行政处罚决定不服的，可以在接到处罚决定通知之日起十五日内向作出处罚决定的机关的上一级机关申请复议；当事人也可以在接到处罚决定通知之日起十五日内直接向人民法院起诉。"},{"i":46,"n":"第四十六条","txt":"矿山企业主管人员违章指挥、强令工人冒险作业，因而发生重大伤亡事故的，依照刑法有关规定追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"矿山企业主管人员对矿山事故隐患不采取措施，因而发生重大伤亡事故的，依照刑法有关规定追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"矿山安全监督人员和安全管理人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。"},{"i":49,"n":"第四十九条","txt":"国务院劳动行政主管部门根据本法制定实施条例，报国务院批准施行。"},{"i":50,"n":"第五十条","txt":"本法自1993年5月1日起施行。"}],"shehuibaoxianfa":[{"i":1,"n":"第一条","txt":"为了规范社会保险关系，维护公民参加社会保险和享受社会保险待遇的合法权益，使公民共享发展成果，促进社会和谐稳定，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家建立基本养老保险、基本医疗保险、工伤保险、失业保险、生育保险等社会保险制度，保障公民在年老、疾病、工伤、失业、生育等情况下依法从国家和社会获得物质帮助的权利。"},{"i":3,"n":"第三条","txt":"社会保险制度坚持广覆盖、保基本、多层次、可持续的方针，社会保险水平应当与经济社会发展水平相适应。"},{"i":4,"n":"第四条","txt":"中华人民共和国境内的用人单位和个人依法缴纳社会保险费，有权查询缴费记录、个人权益记录，要求社会保险经办机构提供社会保险咨询等相关服务。"},{"i":5,"n":"第五条","txt":"县级以上人民政府将社会保险事业纳入国民经济和社会发展规划。"},{"i":6,"n":"第六条","txt":"国家对社会保险基金实行严格监管。"},{"i":7,"n":"第七条","txt":"国务院社会保险行政部门负责全国的社会保险管理工作，国务院其他有关部门在各自的职责范围内负责有关的社会保险工作。"},{"i":8,"n":"第八条","txt":"社会保险经办机构提供社会保险服务，负责社会保险登记、个人权益记录、社会保险待遇支付等工作。"},{"i":9,"n":"第九条","txt":"工会依法维护职工的合法权益，有权参与社会保险重大事项的研究，参加社会保险监督委员会，对与职工社会保险权益有关的事项进行监督。"},{"i":10,"n":"第十条","txt":"职工应当参加基本养老保险，由用人单位和职工共同缴纳基本养老保险费。"},{"i":11,"n":"第十一条","txt":"基本养老保险实行社会统筹与个人账户相结合。"},{"i":12,"n":"第十二条","txt":"用人单位应当按照国家规定的本单位职工工资总额的比例缴纳基本养老保险费，记入基本养老保险统筹基金。"},{"i":13,"n":"第十三条","txt":"国有企业、事业单位职工参加基本养老保险前，视同缴费年限期间应当缴纳的基本养老保险费由政府承担。"},{"i":14,"n":"第十四条","txt":"个人账户不得提前支取，记账利率不得低于银行定期存款利率，免征利息税。个人死亡的，个人账户余额可以继承。"},{"i":15,"n":"第十五条","txt":"基本养老金由统筹养老金和个人账户养老金组成。"},{"i":16,"n":"第十六条","txt":"参加基本养老保险的个人，达到法定退休年龄时累计缴费满十五年的，按月领取基本养老金。"},{"i":17,"n":"第十七条","txt":"参加基本养老保险的个人，因病或者非因工死亡的，其遗属可以领取丧葬补助金和抚恤金；在未达到法定退休年龄时因病或者非因工致残完全丧失劳动能力的，可以领取病残津贴。所需资金从基本养老保险基金中支付。"},{"i":18,"n":"第十八条","txt":"国家建立基本养老金正常调整机制。根据职工平均工资增长、物价上涨情况，适时提高基本养老保险待遇水平。"},{"i":19,"n":"第十九条","txt":"个人跨统筹地区就业的，其基本养老保险关系随本人转移，缴费年限累计计算。个人达到法定退休年龄时，基本养老金分段计算、统一支付。具体办法由国务院规定。"},{"i":20,"n":"第二十条","txt":"国家建立和完善新型农村社会养老保险制度。"},{"i":21,"n":"第二十一条","txt":"新型农村社会养老保险待遇由基础养老金和个人账户养老金组成。"},{"i":22,"n":"第二十二条","txt":"国家建立和完善城镇居民社会养老保险制度。"},{"i":23,"n":"第二十三条","txt":"职工应当参加职工基本医疗保险，由用人单位和职工按照国家规定共同缴纳基本医疗保险费。"},{"i":24,"n":"第二十四条","txt":"国家建立和完善新型农村合作医疗制度。"},{"i":25,"n":"第二十五条","txt":"国家建立和完善城镇居民基本医疗保险制度。"},{"i":26,"n":"第二十六条","txt":"职工基本医疗保险、新型农村合作医疗和城镇居民基本医疗保险的待遇标准按照国家规定执行。"},{"i":27,"n":"第二十七条","txt":"参加职工基本医疗保险的个人，达到法定退休年龄时累计缴费达到国家规定年限的，退休后不再缴纳基本医疗保险费，按照国家规定享受基本医疗保险待遇；未达到国家规定年限的，可以缴费至国家规定年限。"},{"i":28,"n":"第二十八条","txt":"符合基本医疗保险药品目录、诊疗项目、医疗服务设施标准以及急诊、抢救的医疗费用，按照国家规定从基本医疗保险基金中支付。"},{"i":29,"n":"第二十九条","txt":"参保人员医疗费用中应当由基本医疗保险基金支付的部分，由社会保险经办机构与医疗机构、药品经营单位直接结算。"},{"i":30,"n":"第三十条","txt":"下列医疗费用不纳入基本医疗保险基金支付范围："},{"i":31,"n":"第三十一条","txt":"社会保险经办机构根据管理服务的需要，可以与医疗机构、药品经营单位签订服务协议，规范医疗服务行为。"},{"i":32,"n":"第三十二条","txt":"个人跨统筹地区就业的，其基本医疗保险关系随本人转移，缴费年限累计计算。"},{"i":33,"n":"第三十三条","txt":"职工应当参加工伤保险，由用人单位缴纳工伤保险费，职工不缴纳工伤保险费。"},{"i":34,"n":"第三十四条","txt":"国家根据不同行业的工伤风险程度确定行业的差别费率，并根据使用工伤保险基金、工伤发生率等情况在每个行业内确定费率档次。行业差别费率和行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。"},{"i":35,"n":"第三十五条","txt":"用人单位应当按照本单位职工工资总额，根据社会保险经办机构确定的费率缴纳工伤保险费。"},{"i":36,"n":"第三十六条","txt":"职工因工作原因受到事故伤害或者患职业病，且经工伤认定的，享受工伤保险待遇；其中，经劳动能力鉴定丧失劳动能力的，享受伤残待遇。"},{"i":37,"n":"第三十七条","txt":"职工因下列情形之一导致本人在工作中伤亡的，不认定为工伤："},{"i":38,"n":"第三十八条","txt":"因工伤发生的下列费用，按照国家规定从工伤保险基金中支付："},{"i":39,"n":"第三十九条","txt":"因工伤发生的下列费用，按照国家规定由用人单位支付："},{"i":40,"n":"第四十条","txt":"工伤职工符合领取基本养老金条件的，停发伤残津贴，享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，从工伤保险基金中补足差额。"},{"i":41,"n":"第四十一条","txt":"职工所在用人单位未依法缴纳工伤保险费，发生工伤事故的，由用人单位支付工伤保险待遇。用人单位不支付的，从工伤保险基金中先行支付。"},{"i":42,"n":"第四十二条","txt":"由于第三人的原因造成工伤，第三人不支付工伤医疗费用或者无法确定第三人的，由工伤保险基金先行支付。工伤保险基金先行支付后，有权向第三人追偿。"},{"i":43,"n":"第四十三条","txt":"工伤职工有下列情形之一的，停止享受工伤保险待遇："},{"i":44,"n":"第四十四条","txt":"职工应当参加失业保险，由用人单位和职工按照国家规定共同缴纳失业保险费。"},{"i":45,"n":"第四十五条","txt":"失业人员符合下列条件的，从失业保险基金中领取失业保险金："},{"i":46,"n":"第四十六条","txt":"失业人员失业前用人单位和本人累计缴费满一年不足五年的，领取失业保险金的期限最长为十二个月；累计缴费满五年不足十年的，领取失业保险金的期限最长为十八个月；累计缴费十年以上的，领取失业保险金的期限最长为二十四个月。重新就业后，再次失业的，缴费时间重新计算，领取失业保险金的期限与前次失业应当领取而尚未领取的失业保险金的期限合并计算，最长不超过二十四个月。"},{"i":47,"n":"第四十七条","txt":"失业保险金的标准，由省、自治区、直辖市人民政府确定，不得低于城市居民最低生活保障标准。"},{"i":48,"n":"第四十八条","txt":"失业人员在领取失业保险金期间，参加职工基本医疗保险，享受基本医疗保险待遇。"},{"i":49,"n":"第四十九条","txt":"失业人员在领取失业保险金期间死亡的，参照当地对在职职工死亡的规定，向其遗属发给一次性丧葬补助金和抚恤金。所需资金从失业保险基金中支付。"},{"i":50,"n":"第五十条","txt":"用人单位应当及时为失业人员出具终止或者解除劳动关系的证明，并将失业人员的名单自终止或者解除劳动关系之日起十五日内告知社会保险经办机构。"},{"i":51,"n":"第五十一条","txt":"失业人员在领取失业保险金期间有下列情形之一的，停止领取失业保险金，并同时停止享受其他失业保险待遇："},{"i":52,"n":"第五十二条","txt":"职工跨统筹地区就业的，其失业保险关系随本人转移，缴费年限累计计算。"},{"i":53,"n":"第五十三条","txt":"职工应当参加生育保险，由用人单位按照国家规定缴纳生育保险费，职工不缴纳生育保险费。"},{"i":54,"n":"第五十四条","txt":"用人单位已经缴纳生育保险费的，其职工享受生育保险待遇；职工未就业配偶按照国家规定享受生育医疗费用待遇。所需资金从生育保险基金中支付。"},{"i":55,"n":"第五十五条","txt":"生育医疗费用包括下列各项："},{"i":56,"n":"第五十六条","txt":"职工有下列情形之一的，可以按照国家规定享受生育津贴："},{"i":57,"n":"第五十七条","txt":"用人单位应当自成立之日起三十日内凭营业执照、登记证书或者单位印章，向当地社会保险经办机构申请办理社会保险登记。社会保险经办机构应当自收到申请之日起十五日内予以审核，发给社会保险登记证件。"},{"i":58,"n":"第五十八条","txt":"用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。未办理社会保险登记的，由社会保险经办机构核定其应当缴纳的社会保险费。"},{"i":59,"n":"第五十九条","txt":"县级以上人民政府加强社会保险费的征收工作。"},{"i":60,"n":"第六十条","txt":"用人单位应当自行申报、按时足额缴纳社会保险费，非因不可抗力等法定事由不得缓缴、减免。职工应当缴纳的社会保险费由用人单位代扣代缴，用人单位应当按月将缴纳社会保险费的明细情况告知本人。"},{"i":61,"n":"第六十一条","txt":"社会保险费征收机构应当依法按时足额征收社会保险费，并将缴费情况定期告知用人单位和个人。"},{"i":62,"n":"第六十二条","txt":"用人单位未按规定申报应当缴纳的社会保险费数额的，按照该单位上月缴费额的百分之一百一十确定应当缴纳数额；缴费单位补办申报手续后，由社会保险费征收机构按照规定结算。"},{"i":63,"n":"第六十三条","txt":"用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令其限期缴纳或者补足。"},{"i":64,"n":"第六十四条","txt":"社会保险基金包括基本养老保险基金、基本医疗保险基金、工伤保险基金、失业保险基金和生育保险基金。除基本医疗保险基金与生育保险基金合并建账及核算外，其他各项社会保险基金按照社会保险险种分别建账，分账核算。社会保险基金执行国家统一的会计制度。"},{"i":65,"n":"第六十五条","txt":"社会保险基金通过预算实现收支平衡。"},{"i":66,"n":"第六十六条","txt":"社会保险基金按照统筹层次设立预算。除基本医疗保险基金与生育保险基金预算合并编制外，其他社会保险基金预算按照社会保险项目分别编制。"},{"i":67,"n":"第六十七条","txt":"社会保险基金预算、决算草案的编制、审核和批准，依照法律和国务院规定执行。"},{"i":68,"n":"第六十八条","txt":"社会保险基金存入财政专户，具体管理办法由国务院规定。"},{"i":69,"n":"第六十九条","txt":"社会保险基金在保证安全的前提下，按照国务院规定投资运营实现保值增值。"},{"i":70,"n":"第七十条","txt":"社会保险经办机构应当定期向社会公布参加社会保险情况以及社会保险基金的收入、支出、结余和收益情况。"},{"i":71,"n":"第七十一条","txt":"国家设立全国社会保障基金，由中央财政预算拨款以及国务院批准的其他方式筹集的资金构成，用于社会保障支出的补充、调剂。全国社会保障基金由全国社会保障基金管理运营机构负责管理运营，在保证安全的前提下实现保值增值。"},{"i":72,"n":"第七十二条","txt":"统筹地区设立社会保险经办机构。社会保险经办机构根据工作需要，经所在地的社会保险行政部门和机构编制管理机关批准，可以在本统筹地区设立分支机构和服务网点。"},{"i":73,"n":"第七十三条","txt":"社会保险经办机构应当建立健全业务、财务、安全和风险管理制度。"},{"i":74,"n":"第七十四条","txt":"社会保险经办机构通过业务经办、统计、调查获取社会保险工作所需的数据，有关单位和个人应当及时、如实提供。"},{"i":75,"n":"第七十五条","txt":"全国社会保险信息系统按照国家统一规划，由县级以上人民政府按照分级负责的原则共同建设。"},{"i":76,"n":"第七十六条","txt":"各级人民代表大会常务委员会听取和审议本级人民政府对社会保险基金的收支、管理、投资运营以及监督检查情况的专项工作报告，组织对本法实施情况的执法检查等，依法行使监督职权。"},{"i":77,"n":"第七十七条","txt":"县级以上人民政府社会保险行政部门应当加强对用人单位和个人遵守社会保险法律、法规情况的监督检查。"},{"i":78,"n":"第七十八条","txt":"财政部门、审计机关按照各自职责，对社会保险基金的收支、管理和投资运营情况实施监督。"},{"i":79,"n":"第七十九条","txt":"社会保险行政部门对社会保险基金的收支、管理和投资运营情况进行监督检查，发现存在问题的，应当提出整改建议，依法作出处理决定或者向有关行政部门提出处理建议。社会保险基金检查结果应当定期向社会公布。"},{"i":80,"n":"第八十条","txt":"统筹地区人民政府成立由用人单位代表、参保人员代表，以及工会代表、专家等组成的社会保险监督委员会，掌握、分析社会保险基金的收支、管理和投资运营情况，对社会保险工作提出咨询意见和建议，实施社会监督。"},{"i":81,"n":"第八十一条","txt":"社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员，应当依法为用人单位和个人的信息保密，不得以任何形式泄露。"},{"i":82,"n":"第八十二条","txt":"任何组织或者个人有权对违反社会保险法律、法规的行为进行举报、投诉。"},{"i":83,"n":"第八十三条","txt":"用人单位或者个人认为社会保险费征收机构的行为侵害自己合法权益的，可以依法申请行政复议或者提起行政诉讼。"},{"i":84,"n":"第八十四条","txt":"用人单位不办理社会保险登记的，由社会保险行政部门责令限期改正；逾期不改正的，对用人单位处应缴社会保险费数额一倍以上三倍以下的罚款，对其直接负责的主管人员和其他直接责任人员处五百元以上三千元以下的罚款。"},{"i":85,"n":"第八十五条","txt":"用人单位拒不出具终止或者解除劳动关系证明的，依照《中华人民共和国劳动合同法》的规定处理。"},{"i":86,"n":"第八十六条","txt":"用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令限期缴纳或者补足，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，由有关行政部门处欠缴数额一倍以上三倍以下的罚款。"},{"i":87,"n":"第八十七条","txt":"社会保险经办机构以及医疗机构、药品经营单位等社会保险服务机构以欺诈、伪造证明材料或者其他手段骗取社会保险基金支出的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款；属于社会保险服务机构的，解除服务协议；直接负责的主管人员和其他直接责任人员有执业资格的，依法吊销其执业资格。"},{"i":88,"n":"第八十八条","txt":"以欺诈、伪造证明材料或者其他手段骗取社会保险待遇的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款。"},{"i":89,"n":"第八十九条","txt":"社会保险经办机构及其工作人员有下列行为之一的，由社会保险行政部门责令改正；给社会保险基金、用人单位或者个人造成损失的，依法承担赔偿责任；对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":90,"n":"第九十条","txt":"社会保险费征收机构擅自更改社会保险费缴费基数、费率，导致少收或者多收社会保险费的，由有关行政部门责令其追缴应当缴纳的社会保险费或者退还不应当缴纳的社会保险费；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":91,"n":"第九十一条","txt":"违反本法规定，隐匿、转移、侵占、挪用社会保险基金或者违规投资运营的，由社会保险行政部门、财政部门、审计机关责令追回；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":92,"n":"第九十二条","txt":"社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员泄露用人单位和个人信息的，对直接负责的主管人员和其他直接责任人员依法给予处分；给用人单位或者个人造成损失的，应当承担赔偿责任。"},{"i":93,"n":"第九十三条","txt":"国家工作人员在社会保险管理、监督工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":94,"n":"第九十四条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":95,"n":"第九十五条","txt":"进城务工的农村居民依照本法规定参加社会保险。"},{"i":96,"n":"第九十六条","txt":"征收农村集体所有的土地，应当足额安排被征地农民的社会保险费，按照国务院规定将被征地农民纳入相应的社会保险制度。"},{"i":97,"n":"第九十七条","txt":"外国人在中国境内就业的，参照本法规定参加社会保险。"},{"i":98,"n":"第九十八条","txt":"本法自2011年7月1日起施行。"}],"shehuijiuzhufa":[{"i":1,"n":"第一条","txt":"为了保障公民基本生活，让人民共享改革发展成果，健全社会救助体系，促进社会公平，维护社会和谐稳定，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"国家建立和完善社会救助制度，依法保障公民从国家和社会获得物质帮助和救助服务的权利。"},{"i":3,"n":"第三条","txt":"社会救助坚持中国共产党的领导，坚持以人民为中心，践行全心全意为人民服务的宗旨。"},{"i":4,"n":"第四条","txt":"社会救助实行党委领导、政府负责、民政牵头、部门协同、社会参与的工作机制。"},{"i":5,"n":"第五条","txt":"乡镇人民政府、街道办事处依法做好社会救助受理、审核、动态管理等工作。"},{"i":6,"n":"第六条","txt":"县级以上人民政府应当将社会救助工作列入国民经济和社会发展规划。"},{"i":7,"n":"第七条","txt":"国家鼓励和支持公民、法人及其他组织依法参与社会救助。"},{"i":8,"n":"第八条","txt":"各级人民政府、县级以上人民政府社会救助管理部门和村民委员会、居民委员会，应当通过各种形式，开展社会救助法律、法规、规章和政策的宣传。"},{"i":9,"n":"第九条","txt":"各级人民政府应当采取措施，鼓励、支持和引导有劳动能力的社会救助对象自助自立、解困脱困。"},{"i":10,"n":"第十条","txt":"国家推进社会救助信息化工作，加强低收入人口动态监测信息平台建设，实现对低收入人口的精准识别和常态化救助帮扶，提升社会救助管理服务能力和水平。"},{"i":11,"n":"第十一条","txt":"社会救助工作应当依法保护个人隐私和个人信息。"},{"i":12,"n":"第十二条","txt":"对在社会救助工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":13,"n":"第十三条","txt":"社会救助对象包括特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭、受灾人员、基本生活暂时出现严重困难的人员、需要疾病应急救助人员以及生活无着的流散人员等。"},{"i":14,"n":"第十四条","txt":"国家建立健全分层分类的社会救助体系，科学认定社会救助对象，根据救助对象类型、困难程度等及时有针对性地给予社会救助。"},{"i":15,"n":"第十五条","txt":"社会救助分为基本生活救助、专项社会救助和急难社会救助。"},{"i":16,"n":"第十六条","txt":"对无劳动能力、无生活来源且无法定赡养、抚养、扶养义务人，或者其法定义务人无履行义务能力的老年人、未成年人、残疾人等特困人员，由社会救助管理部门给予特困人员供养，提供基本生活条件、必要的照料服务、疾病治疗，办理丧葬事宜等。"},{"i":17,"n":"第十七条","txt":"特困人员供养的基本生活标准和照料护理标准，由省、自治区、直辖市人民政府或者设区的市级人民政府确定并公布。"},{"i":18,"n":"第十八条","txt":"对家庭人均收入低于当地最低生活保障标准且财产状况符合规定的最低生活保障家庭，由社会救助管理部门给予最低生活保障，按月发放最低生活保障金。"},{"i":19,"n":"第十九条","txt":"省、自治区、直辖市人民政府根据当地经济社会发展状况和人民生活水平，综合考虑居民人均消费支出或者人均可支配收入等因素，制定并适时调整本行政区域内最低生活保障标准或者最低生活保障指导标准。省、自治区、直辖市人民政府制定最低生活保障指导标准的，设区的市级人民政府可以制定本行政区域内最低生活保障标准，所制定标准不得低于本省、自治区、直辖市人民政府制定的最低生活保障指导标准。"},{"i":20,"n":"第二十条","txt":"对领取最低生活保障金后生活仍有特殊困难的老年人、未成年人、重度残疾人、重病患者等，县级以上地方人民政府应当采取措施给予必要的生活保障。"},{"i":21,"n":"第二十一条","txt":"对家庭人均收入低于当地最低生活保障边缘家庭标准且财产状况符合规定的最低生活保障边缘家庭，由社会救助管理部门根据实际需要给予相应的医疗、教育、住房、就业等社会救助。"},{"i":22,"n":"第二十二条","txt":"对家庭人均收入低于上年度当地居民人均可支配收入，财产状况符合当地规定，且医疗、教育等必需支出占家庭总收入比例超过所在地设区的市级以上地方人民政府规定比例的刚性支出困难家庭，由社会救助管理部门根据实际需要给予必要的医疗、教育等社会救助。"},{"i":23,"n":"第二十三条","txt":"特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭的收入、财产等状况认定办法，由省、自治区、直辖市人民政府按照国家有关规定，根据当地经济社会发展状况和人民生活水平制定。"},{"i":24,"n":"第二十四条","txt":"对特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭，由社会救助管理部门给予相应的医疗救助。"},{"i":25,"n":"第二十五条","txt":"对特困人员，最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭成员，由社会救助管理部门在学前教育、义务教育、高中阶段教育（含中等职业教育）、普通高等教育阶段，按照规定采取减免相关费用，发放助学金、生活补助，提供勤工助学岗位、助学贷款等方式，给予教育救助。"},{"i":26,"n":"第二十六条","txt":"对符合规定标准的住房困难的分散供养特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭，由社会救助管理部门给予住房救助。属于城镇住房救助对象的，优先配租公租房或者发放公租房租赁补贴；属于农村住房救助对象的，通过农村危房改造等方式优先给予住房救助。"},{"i":27,"n":"第二十七条","txt":"对最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭中有劳动能力且处于失业状态的成员，由社会救助管理部门通过鼓励企业吸纳就业等途径，给予就业救助。对通过上述途径仍然无法就业且符合就业困难人员条件的，按照规定通过公益性岗位安置等方式，给予就业救助。"},{"i":28,"n":"第二十八条","txt":"对基本生活受到自然灾害严重影响的人员，由社会救助管理部门给予必要的应急救助、生活救助和因灾倒损住房恢复重建救助等。"},{"i":29,"n":"第二十九条","txt":"对遭遇突发性、紧迫性、灾难性等困难导致基本生活暂时出现严重困难的人员，由社会救助管理部门采取发放救助金或者配发实物等方式给予临时救助。"},{"i":30,"n":"第三十条","txt":"对需要急救但身份不明或者无力支付急救费用且符合规定的急危重伤病患者，由社会救助管理部门给予疾病应急救助。"},{"i":31,"n":"第三十一条","txt":"对生活无着的流散人员，由社会救助管理部门给予照料服务、急病救治、身份查询、协助返回、寻亲安置等救助。"},{"i":32,"n":"第三十二条","txt":"县级以上地方人民政府应当根据物价上涨情况，及时发放价格临时补贴。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市人民政府可以根据地方实际将其他特殊困难家庭或者人员纳入社会救助对象范围。"},{"i":34,"n":"第三十四条","txt":"国家积极发展服务类社会救助，为社会救助对象提供必要的照护服务、生活服务、关爱服务等。"},{"i":35,"n":"第三十五条","txt":"社会救助对象遇有紧急情况的，社会救助管理部门依法及时给予救助。"},{"i":36,"n":"第三十六条","txt":"对遭受犯罪侵害或者民事侵权，获得司法救助仍然面临生活困难的当事人，符合社会救助条件的，纳入社会救助对象范围。"},{"i":37,"n":"第三十七条","txt":"申请特困人员供养、最低生活保障、医疗救助、住房救助、就业救助，由本人或者与其共同生活的家庭成员向户籍所在地乡镇人民政府、街道办事处提出。有条件的地方可以有序推进持有居住证人员在居住地申请。"},{"i":38,"n":"第三十八条","txt":"申请教育救助，向就读学校提出，由学校按照国家有关规定实施。"},{"i":39,"n":"第三十九条","txt":"村民委员会、居民委员会和其他基层单位在工作中发现需要救助的家庭和人员，应当及时向乡镇人民政府、街道办事处或者县级人民政府社会救助管理部门报告。"},{"i":40,"n":"第四十条","txt":"申请社会救助，应当如实报告共同生活的家庭成员个人基本信息和家庭收入、财产、刚性支出等与申请社会救助相关的情况，并同意社会救助管理部门进行核查。"},{"i":41,"n":"第四十一条","txt":"县级人民政府民政部门可以向户籍管理、税务、社会保险、不动产登记、市场监督管理、住房公积金管理、车船管理等单位，银行、保险、证券等金融机构以及提供货币资金转移服务的非银行支付机构，核对社会救助家庭收入、财产等状况；必要时，经共同生活的家庭成员以外的法定赡养、抚养、扶养义务人同意，可以对其收入、财产等状况进行核对。有关单位和机构应当予以配合。"},{"i":42,"n":"第四十二条","txt":"县级以上人民政府民政部门应当牵头健全社会救助家庭经济状况核对机制，促进跨部门信息共享，提高社会救助审核确认效率和准确度。"},{"i":43,"n":"第四十三条","txt":"乡镇人民政府、街道办事处受理社会救助申请后，可以通过入户调查、邻里访问、信函索证等方式，对申请家庭或者个人的情况进行调查核实，也可以提请县级人民政府民政部门核对社会救助申请对象收入、财产等状况。"},{"i":44,"n":"第四十四条","txt":"乡镇人民政府、街道办事处根据调查核实结果，提出审核意见，报请县级人民政府社会救助管理部门作出社会救助确认决定。"},{"i":45,"n":"第四十五条","txt":"县级人民政府社会救助管理部门或者乡镇人民政府、街道办事处决定给予社会救助的，应当按照规定在申请家庭或者个人所在的村、社区等范围内公布社会救助确认决定；决定不给予社会救助的，应当书面告知申请人并说明理由。"},{"i":46,"n":"第四十六条","txt":"已经获得社会救助的对象，其共同生活的家庭成员、收入、财产等状况发生变化的，应当及时告知社会救助管理部门或者乡镇人民政府、街道办事处。"},{"i":47,"n":"第四十七条","txt":"社会救助管理部门或者乡镇人民政府、街道办事处，可以根据社会救助对象家庭成员、经济状况等变化情况作出相应调整、终止社会救助决定。"},{"i":48,"n":"第四十八条","txt":"社会救助管理部门或者乡镇人民政府、街道办事处作出调减、终止社会救助决定前应当听取社会救助对象的意见，作出决定后应当书面告知社会救助对象并说明理由。"},{"i":49,"n":"第四十九条","txt":"自然灾害发生后，受灾地区人民政府按照职责及时给予受灾人员救助。"},{"i":50,"n":"第五十条","txt":"对申请临时救助，情况紧急、救助金额较小、需立即采取救助措施的，应当先行救助。紧急情况解除后，应当按照规定补充说明情况。"},{"i":51,"n":"第五十一条","txt":"对急危重伤病患者给予疾病应急救助的，由医疗机构实施紧急救治。符合规定的紧急救治费用，由疾病应急救助基金予以补助。"},{"i":52,"n":"第五十二条","txt":"申请生活无着的流散人员救助，向急难发生地县级以上地方人民政府有关救助管理机构提出，也可以向急难发生地乡镇人民政府、街道办事处提出。救助管理机构对生活无着的流散人员实施救助。"},{"i":53,"n":"第五十三条","txt":"社会救助管理部门应当结合社会救助工作实际情况，依法优化工作流程，提高便民化水平。"},{"i":54,"n":"第五十四条","txt":"建立和完善社会力量参与社会救助机制，加强政府救助与社会力量参与有效衔接和协同，动员和引导社会力量积极参与社会救助。"},{"i":55,"n":"第五十五条","txt":"鼓励社会工作专业力量参与社会救助。通过购买服务、开发岗位、政策引导、提供工作场所、设立基层社工站等方式，鼓励社会工作服务机构和社会工作者协助社会救助管理部门开展家庭经济状况调查评估、建档访视、需求分析等事务，提供访视照料、心理疏导、资源链接、能力提升、社会融入等服务。"},{"i":56,"n":"第五十六条","txt":"社会救助管理部门和乡镇人民政府、街道办事处可以将社会救助中属于政府职责范围且适合通过市场化方式提供的服务事项，通过政府购买服务方式实施。"},{"i":57,"n":"第五十七条","txt":"鼓励和支持公民、法人及其他组织以捐赠财产、设立项目、提供服务等方式自愿开展帮扶活动，动员和引导慈善组织等社会力量加大社会救助方面的帮扶力度。"},{"i":58,"n":"第五十八条","txt":"促进社会救助领域志愿服务发展，支持和引导志愿服务组织、志愿者开展志愿服务，发挥志愿服务在汇聚社会资源、提供救助帮扶等方面的作用。"},{"i":59,"n":"第五十九条","txt":"县级以上人民政府及其社会救助管理部门应当建立社会力量参与社会救助的机制和渠道，依法做好信息发布、政策咨询、业务指导、项目指引、志愿服务记录或者证明等工作，为社会力量参与社会救助创造条件、提供便利。"},{"i":60,"n":"第六十条","txt":"县级以上人民政府应当开通社会救助服务热线，受理和转介咨询、举报投诉，接受社会监督。"},{"i":61,"n":"第六十一条","txt":"社会救助工作人员应当客观公正、履职尽责。"},{"i":62,"n":"第六十二条","txt":"国家依法完善社会救助统计制度，实现社会救助信息准确完整、统一汇集、互通共享。"},{"i":63,"n":"第六十三条","txt":"县级以上地方人民政府及其社会救助管理部门应当加强互联网等信息技术在社会救助工作中的应用，并推动社会救助服务向移动端延伸，为需要救助的家庭和人员提供方便快捷的在线申请、办理查询、举报投诉等服务。"},{"i":64,"n":"第六十四条","txt":"县级人民政府应当建立社会救助“一门受理、协同办理”机制。乡镇人民政府、街道办事处应当设立统一受理社会救助申请的窗口，及时受理、转办申请事项。"},{"i":65,"n":"第六十五条","txt":"县级以上人民政府社会救助管理部门和乡镇人民政府、街道办事处在履行社会救助职责过程中，可以查阅、复制与社会救助事项相关的资料，询问与社会救助事项相关的单位、个人，要求其对相关情况作出说明或者提供相关材料。有关单位、个人应当配合。"},{"i":66,"n":"第六十六条","txt":"县级以上人民政府财政部门依法对社会救助资金、物资的管理和使用情况实施监督。"},{"i":67,"n":"第六十七条","txt":"县级人民政府及其社会救助管理部门应当及时公开社会救助政策、救助标准以及社会救助资金、物资的管理和使用等情况。"},{"i":68,"n":"第六十八条","txt":"履行社会救助职责的工作人员行使职权，应当接受社会监督。"},{"i":69,"n":"第六十九条","txt":"县级以上人民政府及其社会救助管理部门应当加强对社会救助工作的监督检查，完善相关监督管理制度，将社会救助制度落实情况纳入绩效评价。"},{"i":70,"n":"第七十条","txt":"违反本法规定，有下列情形之一的，责令改正；对存在故意或者重大过失的负有责任的领导人员和直接责任人员依法给予处分，造成恶劣影响或者严重后果的，依法从重给予处分："},{"i":71,"n":"第七十一条","txt":"违反本法规定，截留、挪用、私分社会救助资金、物资的，由有关部门责令限期改正；对负有责任的领导人员和直接责任人员依法给予处分；有违法所得的，没收违法所得；对有关组织、个人可以处违法所得二倍以下的罚款。"},{"i":72,"n":"第七十二条","txt":"对出具虚假证明材料的单位或者人员，社会救助管理部门应当建议有关单位或者其上级主管机关依法对有关责任人予以处理。"},{"i":73,"n":"第七十三条","txt":"采取虚报、隐瞒、伪造等手段，骗取社会救助资金、物资或者服务的，社会救助管理部门可以责令退回非法获取的财物和利益，处非法获取的财物和利益价值二倍以下的罚款；对社会救助对象可以决定调减、停止社会救助。违反其他法律、行政法规的，由有关主管部门依法处理。"},{"i":74,"n":"第七十四条","txt":"拒不履行社会救助管理部门或者乡镇人民政府、街道办事处作出的调减、终止社会救助决定，非法占有社会救助财物等的，社会救助管理部门应当责令其限期退回。"},{"i":75,"n":"第七十五条","txt":"以暴力、威胁等方式干扰社会救助工作开展，扰乱社会救助工作秩序的，依法给予处罚。"},{"i":76,"n":"第七十六条","txt":"对社会救助管理部门或者乡镇人民政府、街道办事处作出的关于社会救助的行政行为不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":77,"n":"第七十七条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"本法自2026年7月1日起施行。"}],"kexuejishupujifa":[{"i":1,"n":"第一条","txt":"为了实施科教兴国战略、人才强国战略和创新驱动发展战略，全面促进科学技术普及，加强国家科学技术普及能力建设，提高公民的科学文化素质，推进实现高水平科技自立自强，推动经济发展和社会进步，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于国家和社会普及科学技术知识、倡导科学方法、传播科学思想、弘扬科学精神的活动。"},{"i":3,"n":"第三条","txt":"坚持中国共产党对科普事业的全面领导。"},{"i":4,"n":"第四条","txt":"科普是国家创新体系的重要组成部分，是实现创新发展的基础性工作。国家把科普放在与科技创新同等重要的位置，加强科普工作总体布局、统筹部署，推动科普与科技创新紧密协同，充分发挥科普在一体推进教育科技人才事业发展中的作用。"},{"i":5,"n":"第五条","txt":"科普是公益事业，是社会主义物质文明和精神文明建设的重要内容。发展科普事业是国家的长期任务，国家推动科普全面融入经济、政治、文化、社会、生态文明建设，构建政府、社会、市场等协同推进的科普发展格局。"},{"i":6,"n":"第六条","txt":"科普工作应当践行社会主义核心价值观，弘扬科学精神和科学家精神，遵守科技伦理，反对和抵制伪科学。"},{"i":7,"n":"第七条","txt":"国家机关、武装力量、社会团体、企业事业单位、基层群众性自治组织及其他组织应当开展科普工作，可以通过多种形式广泛开展科普活动。"},{"i":8,"n":"第八条","txt":"国家保护科普组织和科普人员的合法权益，鼓励科普组织和科普人员自主开展科普活动，依法兴办科普事业。"},{"i":9,"n":"第九条","txt":"国家支持社会力量兴办科普事业。社会力量兴办科普事业可以按照市场机制运行。"},{"i":10,"n":"第十条","txt":"科普工作应当坚持群众性、社会性和经常性，结合实际，因地制宜，采取多种方式。"},{"i":11,"n":"第十一条","txt":"国家实施全民科学素质行动，制定全民科学素质行动规划，引导公民培育科学和理性思维，树立科学的世界观和方法论，养成文明、健康、绿色、环保的科学生活方式，提高劳动、生产、创新创造的技能。"},{"i":12,"n":"第十二条","txt":"国家支持和促进科普对外合作与交流。"},{"i":13,"n":"第十三条","txt":"对在科普工作中做出突出贡献的组织和个人，按照国家有关规定给予表彰、奖励。"},{"i":14,"n":"第十四条","txt":"各级人民政府领导科普工作，应当将科普工作纳入国民经济和社会发展相关规划，为开展科普工作创造良好的环境和条件。"},{"i":15,"n":"第十五条","txt":"国务院科学技术行政部门负责制定全国科普工作规划，实行政策引导，进行督促检查，加强统筹协调，推动科普工作发展。"},{"i":16,"n":"第十六条","txt":"行业主管部门应当结合本行业特点和实际情况，组织开展相关科普活动。"},{"i":17,"n":"第十七条","txt":"科学技术协会是科普工作的主要社会力量，牵头实施全民科学素质行动，组织开展群众性、社会性和经常性的科普活动，加强国际科技人文交流，支持有关组织和企业事业单位开展科普活动，协助政府制定科普工作规划，为政府科普工作决策提供建议和咨询服务。"},{"i":18,"n":"第十八条","txt":"工会、共产主义青年团、妇女联合会等群团组织应当结合各自工作对象的特点组织开展科普活动。"},{"i":19,"n":"第十九条","txt":"科普是全社会的共同责任。社会各界都应当组织、参加各类科普活动。"},{"i":20,"n":"第二十条","txt":"各级各类学校及其他教育机构，应当把科普作为素质教育的重要内容，加强科学教育，提升师生科学文化素质，支持和组织师生开展多种形式的科普活动。"},{"i":21,"n":"第二十一条","txt":"开放大学、老年大学、老年科技大学、社区学院等应当普及卫生健康、网络通信、智能技术、应急安全等知识技能，提升老年人、残疾人等群体信息获取、识别和应用等能力。"},{"i":22,"n":"第二十二条","txt":"科学研究和技术开发机构、高等学校应当支持和组织科学技术人员、教师开展科普活动，有条件的可以设置专职科普岗位和专门科普场所，使科普成为机构运行的重要内容，为开展科普活动提供必要的支持和保障，促进科技研发、科技成果转化与科普紧密结合。"},{"i":23,"n":"第二十三条","txt":"科技企业应当把科普作为履行社会责任的重要内容，结合科技创新和职工技能培训面向公众开展科普活动。"},{"i":24,"n":"第二十四条","txt":"自然科学和社会科学类社会团体等应当组织开展专业领域科普活动，促进科学技术的普及推广。"},{"i":25,"n":"第二十五条","txt":"新闻出版、电影、广播电视、文化、互联网信息服务等机构和团体应当发挥各自优势做好科普宣传工作。"},{"i":26,"n":"第二十六条","txt":"农村基层群众性自治组织协助当地人民政府根据当地经济与社会发展的需要，围绕科学生产、文明健康生活，发挥农村科普组织、农村学校、基层医疗卫生机构等作用，开展科普工作，提升农民科学文化素质。"},{"i":27,"n":"第二十七条","txt":"城市基层群众性自治组织协助当地人民政府利用当地科技、教育、文化、旅游、医疗卫生等资源，结合居民的生活、学习等需要开展科普活动，完善社区综合服务设施科普功能，提高科普服务质量和水平。"},{"i":28,"n":"第二十八条","txt":"科技馆（站）、科技活动中心和其他科普教育基地，应当组织开展科普教育活动。图书馆、博物馆、文化馆、规划展览馆等文化场所应当发挥科普教育的作用。"},{"i":29,"n":"第二十九条","txt":"国家支持科普产品和服务研究开发，鼓励新颖、独创、科学性强的高质量科普作品创作，提升科普原创能力，依法保护科普成果知识产权。"},{"i":30,"n":"第三十条","txt":"国家发展科普产业，鼓励兴办科普企业，促进科普与文化、旅游、体育、卫生健康、农业、生态环保等产业融合发展。"},{"i":31,"n":"第三十一条","txt":"国家推动新技术、新知识在全社会各类人群中的传播与推广，鼓励各类创新主体围绕新技术、新知识开展科普，鼓励在科普中应用新技术，引导社会正确认识和使用科技成果，为科技成果应用创造良好环境。"},{"i":32,"n":"第三十二条","txt":"国家部署实施新技术领域重大科技任务，在符合保密法律法规的前提下，可以组织开展必要的科普，增进公众理解、认同和支持。"},{"i":33,"n":"第三十三条","txt":"国家加强自然灾害、事故灾难、公共卫生事件等突发事件预防、救援、应急处置等方面的科普工作，加强应急科普资源和平台建设，完善应急科普响应机制，提升公众应急处理能力和自我保护意识。"},{"i":34,"n":"第三十四条","txt":"国家鼓励在职业培训、农民技能培训和干部教育培训中增加科普内容，促进培育高素质产业工人和农民，提高公职人员科学履职能力。"},{"i":35,"n":"第三十五条","txt":"组织和个人提供的科普产品和服务、发布的科普信息应当具有合法性、科学性，不得有虚假错误的内容。"},{"i":36,"n":"第三十六条","txt":"国家加强对科普信息发布和传播的监测与评估。对传播范围广、社会危害大的虚假错误信息，科学技术或者有关主管部门应当按照职责分工及时予以澄清和纠正。"},{"i":37,"n":"第三十七条","txt":"有条件的科普组织和科学技术人员应当结合自身专业特色组织、参与国际科普活动，开展国际科技人文交流，拓展国际科普合作渠道，促进优秀科普成果共享。国家支持开展青少年国际科普交流。"},{"i":38,"n":"第三十八条","txt":"国家完善科普工作评估体系和公民科学素质监测评估体系，开展科普调查统计和公民科学素质测评，监测和评估科普事业发展成效。"},{"i":39,"n":"第三十九条","txt":"国家加强科普工作人员培训和交流，提升科普工作人员思想道德品质、科学文化素质和业务水平，建立专业化科普工作人员队伍。"},{"i":40,"n":"第四十条","txt":"科学技术人员和教师应当发挥自身优势和专长，积极参与和支持科普活动。"},{"i":41,"n":"第四十一条","txt":"国家支持有条件的高等学校、职业学校设置和完善科普相关学科和专业，培养科普专业人才。"},{"i":42,"n":"第四十二条","txt":"国家完善科普志愿服务制度和工作体系，支持志愿者开展科普志愿服务，加强培训与监督。"},{"i":43,"n":"第四十三条","txt":"国家健全科普人员评价、激励机制，鼓励相关单位建立符合科普特点的职称评定、绩效考核等评价制度，为科普人员提供有效激励。"},{"i":44,"n":"第四十四条","txt":"各级人民政府应当将科普经费列入本级预算，完善科普投入经费保障机制，逐步提高科普投入水平，保障科普工作顺利开展。"},{"i":45,"n":"第四十五条","txt":"国家完善科普场馆和科普基地建设布局，扩大科普设施覆盖面，促进城乡科普设施均衡发展。"},{"i":46,"n":"第四十六条","txt":"各级人民政府应当对符合规划的科普场馆、设施建设给予支持，开展财政性资金资助的科普场馆运营绩效评估，保障科普场馆有效运行。"},{"i":47,"n":"第四十七条","txt":"国家建设完善开放、共享的国家科普资源库和科普资源公共服务平台，推动全社会科普资源共建共享。"},{"i":48,"n":"第四十八条","txt":"国家鼓励和引导社会资金投入科普事业。国家鼓励境内外的组织和个人设立科普基金，用于资助科普事业。"},{"i":49,"n":"第四十九条","txt":"国家鼓励境内外的组织和个人依法捐赠财产资助科普事业；对捐赠财产用于科普事业或者投资建设科普场馆、设施的，依法给予优惠。"},{"i":50,"n":"第五十条","txt":"国家依法对科普事业实行税收优惠。"},{"i":51,"n":"第五十一条","txt":"利用财政性资金设立科学技术计划项目，除涉密项目外，应当结合任务需求，合理设置科普工作任务，充分发挥社会效益。"},{"i":52,"n":"第五十二条","txt":"科学研究和技术开发机构、学校、企业的主管部门以及科学技术等相关行政部门应当支持开展科普活动，建立有利于促进科普的评价标准和制度机制。"},{"i":53,"n":"第五十三条","txt":"科普经费和组织、个人资助科普事业的财产，应当用于科普事业，任何组织和个人不得克扣、截留、挪用。"},{"i":54,"n":"第五十四条","txt":"违反本法规定，制作、发布、传播虚假错误信息，或者以科普为名损害国家利益、社会公共利益或者他人合法权益的，由有关主管部门责令改正，给予警告或者通报批评，没收违法所得，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":55,"n":"第五十五条","txt":"违反本法规定，克扣、截留、挪用科普款物或者骗取科普优惠政策支持的，由有关主管部门责令限期退还相关款物；对负有责任的领导人员和直接责任人员依法给予处分；情节严重的，禁止一定期限内申请科普优惠政策支持。"},{"i":56,"n":"第五十六条","txt":"擅自将政府投资建设的科普场馆改为他用的，由有关主管部门责令限期改正；情节严重的，给予警告或者通报批评，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":57,"n":"第五十七条","txt":"骗取科普表彰、奖励的，由授予表彰、奖励的部门或者单位撤销其所获荣誉，收回奖章、证书，追回其所获奖金等物质奖励，并由其所在单位或者有关部门依法给予处分。"},{"i":58,"n":"第五十八条","txt":"公职人员在科普工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"},{"i":59,"n":"第五十九条","txt":"违反本法规定，造成人身损害或者财产损失的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":60,"n":"第六十条","txt":"本法自公布之日起施行。"}],"hongshizihuifa":[{"i":1,"n":"第一条","txt":"为了保护人的生命和健康，维护人的尊严，发扬人道主义精神，促进和平进步事业，保障和规范红十字会依法履行职责，制定本法。"},{"i":2,"n":"第二条","txt":"中国红十字会是中华人民共和国统一的红十字组织，是从事人道主义工作的社会救助团体。"},{"i":3,"n":"第三条","txt":"中华人民共和国公民，不分民族、种族、性别、职业、宗教信仰、教育程度，承认中国红十字会章程并缴纳会费的，可以自愿参加中国红十字会。"},{"i":4,"n":"第四条","txt":"中国红十字会应当遵守宪法和法律，遵循国际红十字和红新月运动确立的基本原则，依照中国批准或者加入的日内瓦公约及其附加议定书和中国红十字会章程，独立自主地开展工作。"},{"i":5,"n":"第五条","txt":"各级人民政府对红十字会给予支持和资助，保障红十字会依法履行职责，并对其活动进行监督。"},{"i":6,"n":"第六条","txt":"中国红十字会根据独立、平等、互相尊重的原则，发展同各国红十字会和红新月会的友好合作关系。"},{"i":7,"n":"第七条","txt":"全国建立中国红十字会总会。中国红十字会总会对外代表中国红十字会。"},{"i":8,"n":"第八条","txt":"各级红十字会设立理事会、监事会。理事会、监事会由会员代表大会选举产生，向会员代表大会负责并报告工作，接受其监督。"},{"i":9,"n":"第九条","txt":"中国红十字会总会可以设名誉会长和名誉副会长。名誉会长和名誉副会长由中国红十字会总会理事会聘请。"},{"i":10,"n":"第十条","txt":"中国红十字会总会具有社会团体法人资格；地方各级红十字会、行业红十字会依法取得社会团体法人资格。"},{"i":11,"n":"第十一条","txt":"红十字会履行下列职责："},{"i":12,"n":"第十二条","txt":"在战争、武装冲突和自然灾害、事故灾难、公共卫生事件等突发事件中，执行救援、救助任务并标有红十字标志的人员、物资和交通工具有优先通行的权利。"},{"i":13,"n":"第十三条","txt":"任何组织和个人不得阻碍红十字会工作人员依法履行救援、救助、救护职责。"},{"i":14,"n":"第十四条","txt":"中国红十字会使用白底红十字标志。"},{"i":15,"n":"第十五条","txt":"国家武装力量的医疗卫生机构使用红十字标志，应当符合日内瓦公约及其附加议定书的有关规定。"},{"i":16,"n":"第十六条","txt":"红十字标志和名称受法律保护。禁止利用红十字标志和名称牟利，禁止以任何形式冒用、滥用、篡改红十字标志和名称。"},{"i":17,"n":"第十七条","txt":"红十字会财产的主要来源："},{"i":18,"n":"第十八条","txt":"国家对红十字会兴办的与其宗旨相符的公益事业给予扶持。"},{"i":19,"n":"第十九条","txt":"红十字会可以依法进行募捐活动。募捐活动应当符合《中华人民共和国慈善法》的有关规定。"},{"i":20,"n":"第二十条","txt":"红十字会依法接受自然人、法人以及其他组织捐赠的款物，应当向捐赠人开具由财政部门统一监（印）制的公益事业捐赠票据。捐赠人匿名或者放弃接受捐赠票据的，红十字会应当做好相关记录。"},{"i":21,"n":"第二十一条","txt":"红十字会应当按照募捐方案、捐赠人意愿或者捐赠协议处分其接受的捐赠款物。"},{"i":22,"n":"第二十二条","txt":"红十字会应当建立财务管理、内部控制、审计公开和监督检查制度。"},{"i":23,"n":"第二十三条","txt":"红十字会应当建立健全信息公开制度，规范信息发布，在统一的信息平台及时向社会公布捐赠款物的收入和使用情况，接受社会监督。"},{"i":24,"n":"第二十四条","txt":"红十字会财产的收入和使用情况依法接受人民政府审计等部门的监督。"},{"i":25,"n":"第二十五条","txt":"任何组织和个人不得私分、挪用、截留或者侵占红十字会的财产。"},{"i":26,"n":"第二十六条","txt":"红十字会及其工作人员有下列情形之一的，由同级人民政府审计、民政等部门责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；造成损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任："},{"i":27,"n":"第二十七条","txt":"自然人、法人或者其他组织有下列情形之一，造成损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任："},{"i":28,"n":"第二十八条","txt":"各级人民政府有关部门及其工作人员在实施监督管理中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"本法所称“国际红十字和红新月运动确立的基本原则”，是指一九八六年十月日内瓦国际红十字大会第二十五次会议通过的“国际红十字和红新月运动章程”中确立的人道、公正、中立、独立、志愿服务、统一和普遍七项基本原则。"},{"i":30,"n":"第三十条","txt":"本法自2017年5月8日起施行。"}],"laonianrenquanyibaozhangfa":[{"i":1,"n":"第一条","txt":"为了保障老年人合法权益，发展老龄事业，弘扬中华民族敬老、养老、助老的美德，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称老年人是指六十周岁以上的公民。"},{"i":3,"n":"第三条","txt":"国家保障老年人依法享有的权益。"},{"i":4,"n":"第四条","txt":"积极应对人口老龄化是国家的一项长期战略任务。"},{"i":5,"n":"第五条","txt":"国家建立多层次的社会保障体系，逐步提高对老年人的保障水平。"},{"i":6,"n":"第六条","txt":"各级人民政府应当将老龄事业纳入国民经济和社会发展规划，将老龄事业经费列入财政预算，建立稳定的经费保障机制，并鼓励社会各方面投入，使老龄事业与经济、社会协调发展。"},{"i":7,"n":"第七条","txt":"保障老年人合法权益是全社会的共同责任。"},{"i":8,"n":"第八条","txt":"国家进行人口老龄化国情教育，增强全社会积极应对人口老龄化意识。"},{"i":9,"n":"第九条","txt":"国家支持老龄科学研究，建立老年人状况统计调查和发布制度。"},{"i":10,"n":"第十条","txt":"各级人民政府和有关部门对维护老年人合法权益和敬老、养老、助老成绩显著的组织、家庭或者个人，对参与社会发展做出突出贡献的老年人，按照国家有关规定给予表彰或者奖励。"},{"i":11,"n":"第十一条","txt":"老年人应当遵纪守法，履行法律规定的义务。"},{"i":12,"n":"第十二条","txt":"每年农历九月初九为老年节。"},{"i":13,"n":"第十三条","txt":"老年人养老以居家为基础，家庭成员应当尊重、关心和照料老年人。"},{"i":14,"n":"第十四条","txt":"赡养人应当履行对老年人经济上供养、生活上照料和精神上慰藉的义务，照顾老年人的特殊需要。"},{"i":15,"n":"第十五条","txt":"赡养人应当使患病的老年人及时得到治疗和护理；对经济困难的老年人，应当提供医疗费用。"},{"i":16,"n":"第十六条","txt":"赡养人应当妥善安排老年人的住房，不得强迫老年人居住或者迁居条件低劣的房屋。"},{"i":17,"n":"第十七条","txt":"赡养人有义务耕种或者委托他人耕种老年人承包的田地，照管或者委托他人照管老年人的林木和牲畜等，收益归老年人所有。"},{"i":18,"n":"第十八条","txt":"家庭成员应当关心老年人的精神需求，不得忽视、冷落老年人。"},{"i":19,"n":"第十九条","txt":"赡养人不得以放弃继承权或者其他理由，拒绝履行赡养义务。"},{"i":20,"n":"第二十条","txt":"经老年人同意，赡养人之间可以就履行赡养义务签订协议。赡养协议的内容不得违反法律的规定和老年人的意愿。"},{"i":21,"n":"第二十一条","txt":"老年人的婚姻自由受法律保护。子女或者其他亲属不得干涉老年人离婚、再婚及婚后的生活。"},{"i":22,"n":"第二十二条","txt":"老年人对个人的财产，依法享有占有、使用、收益和处分的权利，子女或者其他亲属不得干涉，不得以窃取、骗取、强行索取等方式侵犯老年人的财产权益。"},{"i":23,"n":"第二十三条","txt":"老年人与配偶有相互扶养的义务。"},{"i":24,"n":"第二十四条","txt":"赡养人、扶养人不履行赡养、扶养义务的，基层群众性自治组织、老年人组织或者赡养人、扶养人所在单位应当督促其履行。"},{"i":25,"n":"第二十五条","txt":"禁止对老年人实施家庭暴力。"},{"i":26,"n":"第二十六条","txt":"具备完全民事行为能力的老年人，可以在近亲属或者其他与自己关系密切、愿意承担监护责任的个人、组织中协商确定自己的监护人。监护人在老年人丧失或者部分丧失民事行为能力时，依法承担监护责任。"},{"i":27,"n":"第二十七条","txt":"国家建立健全家庭养老支持政策，鼓励家庭成员与老年人共同生活或者就近居住，为老年人随配偶或者赡养人迁徙提供条件，为家庭成员照料老年人提供帮助。"},{"i":28,"n":"第二十八条","txt":"国家通过基本养老保险制度，保障老年人的基本生活。"},{"i":29,"n":"第二十九条","txt":"国家通过基本医疗保险制度，保障老年人的基本医疗需要。享受最低生活保障的老年人和符合条件的低收入家庭中的老年人参加新型农村合作医疗和城镇居民基本医疗保险所需个人缴费部分，由政府给予补贴。"},{"i":30,"n":"第三十条","txt":"国家逐步开展长期护理保障工作，保障老年人的护理需求。"},{"i":31,"n":"第三十一条","txt":"国家对经济困难的老年人给予基本生活、医疗、居住或者其他救助。"},{"i":32,"n":"第三十二条","txt":"地方各级人民政府在实施廉租住房、公共租赁住房等住房保障制度或者进行危旧房屋改造时，应当优先照顾符合条件的老年人。"},{"i":33,"n":"第三十三条","txt":"国家建立和完善老年人福利制度，根据经济社会发展水平和老年人的实际需要，增加老年人的社会福利。"},{"i":34,"n":"第三十四条","txt":"老年人依法享有的养老金、医疗待遇和其他待遇应当得到保障，有关机构必须按时足额支付，不得克扣、拖欠或者挪用。"},{"i":35,"n":"第三十五条","txt":"国家鼓励慈善组织以及其他组织和个人为老年人提供物质帮助。"},{"i":36,"n":"第三十六条","txt":"老年人可以与集体经济组织、基层群众性自治组织、养老机构等组织或者个人签订遗赠扶养协议或者其他扶助协议。"},{"i":37,"n":"第三十七条","txt":"地方各级人民政府和有关部门应当采取措施，发展城乡社区养老服务，鼓励、扶持专业服务机构及其他组织和个人，为居家的老年人提供生活照料、紧急救援、医疗护理、精神慰藉、心理咨询等多种形式的服务。"},{"i":38,"n":"第三十八条","txt":"地方各级人民政府和有关部门、基层群众性自治组织，应当将养老服务设施纳入城乡社区配套设施建设规划，建立适应老年人需要的生活服务、文化体育活动、日间照料、疾病护理与康复等服务设施和网点，就近为老年人提供服务。"},{"i":39,"n":"第三十九条","txt":"各级人民政府应当根据经济发展水平和老年人服务需求，逐步增加对养老服务的投入。"},{"i":40,"n":"第四十条","txt":"地方各级人民政府和有关部门应当按照老年人口比例及分布情况，将养老服务设施建设纳入城乡规划和土地利用总体规划，统筹安排养老服务设施建设用地及所需物资。"},{"i":41,"n":"第四十一条","txt":"政府投资兴办的养老机构，应当优先保障经济困难的孤寡、失能、高龄等老年人的服务需求。"},{"i":42,"n":"第四十二条","txt":"国务院有关部门制定养老服务设施建设、养老服务质量和养老服务职业等标准，建立健全养老机构分类管理和养老服务评估制度。"},{"i":43,"n":"第四十三条","txt":"设立公益性养老机构，应当依法办理相应的登记。"},{"i":44,"n":"第四十四条","txt":"地方各级人民政府加强对本行政区域养老机构管理工作的领导，建立养老机构综合监管制度。"},{"i":45,"n":"第四十五条","txt":"县级以上人民政府民政部门依法履行监督检查职责，可以采取以下措施："},{"i":46,"n":"第四十六条","txt":"养老机构变更或者终止的，应当妥善安置收住的老年人，并依照规定到有关部门办理手续。有关部门应当为养老机构妥善安置老年人提供帮助。"},{"i":47,"n":"第四十七条","txt":"国家建立健全养老服务人才培养、使用、评价和激励制度，依法规范用工，促进从业人员劳动报酬合理增长，发展专职、兼职和志愿者相结合的养老服务队伍。"},{"i":48,"n":"第四十八条","txt":"养老机构应当与接受服务的老年人或者其代理人签订服务协议，明确双方的权利、义务。"},{"i":49,"n":"第四十九条","txt":"国家鼓励养老机构投保责任保险，鼓励保险公司承保责任保险。"},{"i":50,"n":"第五十条","txt":"各级人民政府和有关部门应当将老年医疗卫生服务纳入城乡医疗卫生服务规划，将老年人健康管理和常见病预防等纳入国家基本公共卫生服务项目。鼓励为老年人提供保健、护理、临终关怀等服务。"},{"i":51,"n":"第五十一条","txt":"国家采取措施，加强老年医学的研究和人才培养，提高老年病的预防、治疗、科研水平，促进老年病的早期发现、诊断和治疗。"},{"i":52,"n":"第五十二条","txt":"国家采取措施，发展老龄产业，将老龄产业列入国家扶持行业目录。扶持和引导企业开发、生产、经营适应老年人需要的用品和提供相关的服务。"},{"i":53,"n":"第五十三条","txt":"县级以上人民政府及其有关部门根据经济社会发展情况和老年人的特殊需要，制定优待老年人的办法，逐步提高优待水平。"},{"i":54,"n":"第五十四条","txt":"各级人民政府和有关部门应当为老年人及时、便利地领取养老金、结算医疗费和享受其他物质帮助提供条件。"},{"i":55,"n":"第五十五条","txt":"各级人民政府和有关部门办理房屋权属关系变更、户口迁移等涉及老年人权益的重大事项时，应当就办理事项是否为老年人的真实意思表示进行询问，并依法优先办理。"},{"i":56,"n":"第五十六条","txt":"老年人因其合法权益受侵害提起诉讼交纳诉讼费确有困难的，可以缓交、减交或者免交；需要获得律师帮助，但无力支付律师费用的，可以获得法律援助。"},{"i":57,"n":"第五十七条","txt":"医疗机构应当为老年人就医提供方便，对老年人就医予以优先。有条件的地方，可以为老年人设立家庭病床，开展巡回医疗、护理、康复、免费体检等服务。"},{"i":58,"n":"第五十八条","txt":"提倡与老年人日常生活密切相关的服务行业为老年人提供优先、优惠服务。"},{"i":59,"n":"第五十九条","txt":"博物馆、美术馆、科技馆、纪念馆、公共图书馆、文化馆、影剧院、体育场馆、公园、旅游景点等场所，应当对老年人免费或者优惠开放。"},{"i":60,"n":"第六十条","txt":"农村老年人不承担兴办公益事业的筹劳义务。"},{"i":61,"n":"第六十一条","txt":"国家采取措施，推进宜居环境建设，为老年人提供安全、便利和舒适的环境。"},{"i":62,"n":"第六十二条","txt":"各级人民政府在制定城乡规划时，应当根据人口老龄化发展趋势、老年人口分布和老年人的特点，统筹考虑适合老年人的公共基础设施、生活服务设施、医疗卫生设施和文化体育设施建设。"},{"i":63,"n":"第六十三条","txt":"国家制定和完善涉及老年人的工程建设标准体系，在规划、设计、施工、监理、验收、运行、维护、管理等环节加强相关标准的实施与监督。"},{"i":64,"n":"第六十四条","txt":"国家制定无障碍设施工程建设标准。新建、改建和扩建道路、公共交通设施、建筑物、居住区等，应当符合国家无障碍设施工程建设标准。"},{"i":65,"n":"第六十五条","txt":"国家推动老年宜居社区建设，引导、支持老年宜居住宅的开发，推动和扶持老年人家庭无障碍设施的改造，为老年人创造无障碍居住环境。"},{"i":66,"n":"第六十六条","txt":"国家和社会应当重视、珍惜老年人的知识、技能、经验和优良品德，发挥老年人的专长和作用，保障老年人参与经济、政治、文化和社会生活。"},{"i":67,"n":"第六十七条","txt":"老年人可以通过老年人组织，开展有益身心健康的活动。"},{"i":68,"n":"第六十八条","txt":"制定法律、法规、规章和公共政策，涉及老年人权益重大问题的，应当听取老年人和老年人组织的意见。"},{"i":69,"n":"第六十九条","txt":"国家为老年人参与社会发展创造条件。根据社会需要和可能，鼓励老年人在自愿和量力的情况下，从事下列活动："},{"i":70,"n":"第七十条","txt":"老年人参加劳动的合法收入受法律保护。"},{"i":71,"n":"第七十一条","txt":"老年人有继续受教育的权利。"},{"i":72,"n":"第七十二条","txt":"国家和社会采取措施，开展适合老年人的群众性文化、体育、娱乐活动，丰富老年人的精神文化生活。"},{"i":73,"n":"第七十三条","txt":"老年人合法权益受到侵害的，被侵害人或者其代理人有权要求有关部门处理，或者依法向人民法院提起诉讼。"},{"i":74,"n":"第七十四条","txt":"不履行保护老年人合法权益职责的部门或者组织，其上级主管部门应当给予批评教育，责令改正。"},{"i":75,"n":"第七十五条","txt":"老年人与家庭成员因赡养、扶养或者住房、财产等发生纠纷，可以申请人民调解委员会或者其他有关组织进行调解，也可以直接向人民法院提起诉讼。"},{"i":76,"n":"第七十六条","txt":"干涉老年人婚姻自由，对老年人负有赡养义务、扶养义务而拒绝赡养、扶养，虐待老年人或者对老年人实施家庭暴力的，由有关单位给予批评教育；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":77,"n":"第七十七条","txt":"家庭成员盗窃、诈骗、抢夺、侵占、勒索、故意损毁老年人财物，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":78,"n":"第七十八条","txt":"侮辱、诽谤老年人，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":79,"n":"第七十九条","txt":"养老机构及其工作人员侵害老年人人身和财产权益，或者未按照约定提供服务的，依法承担民事责任；有关主管部门依法给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":80,"n":"第八十条","txt":"对养老机构负有管理和监督职责的部门及其工作人员滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":81,"n":"第八十一条","txt":"不按规定履行优待老年人义务的，由有关主管部门责令改正。"},{"i":82,"n":"第八十二条","txt":"涉及老年人的工程不符合国家规定的标准或者无障碍设施所有人、管理人未尽到维护和管理职责的，由有关主管部门责令改正；造成损害的，依法承担民事责任；对有关单位、个人依法给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":83,"n":"第八十三条","txt":"民族自治地方的人民代表大会，可以根据本法的原则，结合当地民族风俗习惯的具体情况，依照法定程序制定变通的或者补充的规定。"},{"i":84,"n":"第八十四条","txt":"本法施行前设立的养老机构不符合本法规定条件的，应当限期整改。具体办法由国务院民政部门制定。"},{"i":85,"n":"第八十五条","txt":"本法自2013年7月1日起施行。"}],"zhiyebingfangzhifa":[{"i":1,"n":"第一条","txt":"为了预防、控制和消除职业病危害，防治职业病，保护劳动者健康及其相关权益，促进经济社会发展，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法适用于中华人民共和国领域内的职业病防治活动。"},{"i":3,"n":"第三条","txt":"职业病防治工作坚持预防为主、防治结合的方针，建立用人单位负责、行政机关监管、行业自律、职工参与和社会监督的机制，实行分类管理、综合治理。"},{"i":4,"n":"第四条","txt":"劳动者依法享有职业卫生保护的权利。"},{"i":5,"n":"第五条","txt":"用人单位应当建立、健全职业病防治责任制，加强对职业病防治的管理，提高职业病防治水平，对本单位产生的职业病危害承担责任。"},{"i":6,"n":"第六条","txt":"用人单位的主要负责人对本单位的职业病防治工作全面负责。"},{"i":7,"n":"第七条","txt":"用人单位必须依法参加工伤保险。"},{"i":8,"n":"第八条","txt":"国家鼓励和支持研制、开发、推广、应用有利于职业病防治和保护劳动者健康的新技术、新工艺、新设备、新材料，加强对职业病的机理和发生规律的基础研究，提高职业病防治科学技术水平；积极采用有效的职业病防治技术、工艺、设备、材料；限制使用或者淘汰职业病危害严重的技术、工艺、设备、材料。"},{"i":9,"n":"第九条","txt":"国家实行职业卫生监督制度。"},{"i":10,"n":"第十条","txt":"国务院和县级以上地方人民政府应当制定职业病防治规划，将其纳入国民经济和社会发展计划，并组织实施。"},{"i":11,"n":"第十一条","txt":"县级以上人民政府职业卫生监督管理部门应当加强对职业病防治的宣传教育，普及职业病防治的知识，增强用人单位的职业病防治观念，提高劳动者的职业健康意识、自我保护意识和行使职业卫生保护权利的能力。"},{"i":12,"n":"第十二条","txt":"有关防治职业病的国家职业卫生标准，由国务院卫生行政部门组织制定并公布。"},{"i":13,"n":"第十三条","txt":"任何单位和个人有权对违反本法的行为进行检举和控告。有关部门收到相关的检举和控告后，应当及时处理。"},{"i":14,"n":"第十四条","txt":"用人单位应当依照法律、法规要求，严格遵守国家职业卫生标准，落实职业病预防措施，从源头上控制和消除职业病危害。"},{"i":15,"n":"第十五条","txt":"产生职业病危害的用人单位的设立除应当符合法律、行政法规规定的设立条件外，其工作场所还应当符合下列职业卫生要求："},{"i":16,"n":"第十六条","txt":"国家建立职业病危害项目申报制度。"},{"i":17,"n":"第十七条","txt":"新建、扩建、改建建设项目和技术改造、技术引进项目（以下统称建设项目）可能产生职业病危害的，建设单位在可行性论证阶段应当进行职业病危害预评价。"},{"i":18,"n":"第十八条","txt":"建设项目的职业病防护设施所需费用应当纳入建设项目工程预算，并与主体工程同时设计，同时施工，同时投入生产和使用。"},{"i":19,"n":"第十九条","txt":"国家对从事放射性、高毒、高危粉尘等作业实行特殊管理。具体管理办法由国务院制定。"},{"i":20,"n":"第二十条","txt":"用人单位应当采取下列职业病防治管理措施："},{"i":21,"n":"第二十一条","txt":"用人单位应当保障职业病防治所需的资金投入，不得挤占、挪用，并对因资金投入不足导致的后果承担责任。"},{"i":22,"n":"第二十二条","txt":"用人单位必须采用有效的职业病防护设施，并为劳动者提供个人使用的职业病防护用品。"},{"i":23,"n":"第二十三条","txt":"用人单位应当优先采用有利于防治职业病和保护劳动者健康的新技术、新工艺、新设备、新材料，逐步替代职业病危害严重的技术、工艺、设备、材料。"},{"i":24,"n":"第二十四条","txt":"产生职业病危害的用人单位，应当在醒目位置设置公告栏，公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施和工作场所职业病危害因素检测结果。"},{"i":25,"n":"第二十五条","txt":"对可能发生急性职业损伤的有毒、有害工作场所，用人单位应当设置报警装置，配置现场急救用品、冲洗设备、应急撤离通道和必要的泄险区。"},{"i":26,"n":"第二十六条","txt":"用人单位应当实施由专人负责的职业病危害因素日常监测，并确保监测系统处于正常运行状态。"},{"i":27,"n":"第二十七条","txt":"职业卫生技术服务机构依法从事职业病危害因素检测、评价工作，接受卫生行政部门的监督检查。卫生行政部门应当依法履行监督职责。"},{"i":28,"n":"第二十八条","txt":"向用人单位提供可能产生职业病危害的设备的，应当提供中文说明书，并在设备的醒目位置设置警示标识和中文警示说明。警示说明应当载明设备性能、可能产生的职业病危害、安全操作和维护注意事项、职业病防护以及应急救治措施等内容。"},{"i":29,"n":"第二十九条","txt":"向用人单位提供可能产生职业病危害的化学品、放射性同位素和含有放射性物质的材料的，应当提供中文说明书。说明书应当载明产品特性、主要成份、存在的有害因素、可能产生的危害后果、安全使用注意事项、职业病防护以及应急救治措施等内容。产品包装应当有醒目的警示标识和中文警示说明。贮存上述材料的场所应当在规定的部位设置危险物品标识或者放射性警示标识。"},{"i":30,"n":"第三十条","txt":"任何单位和个人不得生产、经营、进口和使用国家明令禁止使用的可能产生职业病危害的设备或者材料。"},{"i":31,"n":"第三十一条","txt":"任何单位和个人不得将产生职业病危害的作业转移给不具备职业病防护条件的单位和个人。不具备职业病防护条件的单位和个人不得接受产生职业病危害的作业。"},{"i":32,"n":"第三十二条","txt":"用人单位对采用的技术、工艺、设备、材料，应当知悉其产生的职业病危害，对有职业病危害的技术、工艺、设备、材料隐瞒其危害而采用的，对所造成的职业病危害后果承担责任。"},{"i":33,"n":"第三十三条","txt":"用人单位与劳动者订立劳动合同（含聘用合同，下同）时，应当将工作过程中可能产生的职业病危害及其后果、职业病防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。"},{"i":34,"n":"第三十四条","txt":"用人单位的主要负责人和职业卫生管理人员应当接受职业卫生培训，遵守职业病防治法律、法规，依法组织本单位的职业病防治工作。"},{"i":35,"n":"第三十五条","txt":"对从事接触职业病危害的作业的劳动者，用人单位应当按照国务院卫生行政部门的规定组织上岗前、在岗期间和离岗时的职业健康检查，并将检查结果书面告知劳动者。职业健康检查费用由用人单位承担。"},{"i":36,"n":"第三十六条","txt":"用人单位应当为劳动者建立职业健康监护档案，并按照规定的期限妥善保存。"},{"i":37,"n":"第三十七条","txt":"发生或者可能发生急性职业病危害事故时，用人单位应当立即采取应急救援和控制措施，并及时报告所在地卫生行政部门和有关部门。卫生行政部门接到报告后，应当及时会同有关部门组织调查处理；必要时，可以采取临时控制措施。卫生行政部门应当组织做好医疗救治工作。"},{"i":38,"n":"第三十八条","txt":"用人单位不得安排未成年工从事接触职业病危害的作业；不得安排孕期、哺乳期的女职工从事对本人和胎儿、婴儿有危害的作业。"},{"i":39,"n":"第三十九条","txt":"劳动者享有下列职业卫生保护权利："},{"i":40,"n":"第四十条","txt":"工会组织应当督促并协助用人单位开展职业卫生宣传教育和培训，有权对用人单位的职业病防治工作提出意见和建议，依法代表劳动者与用人单位签订劳动安全卫生专项集体合同，与用人单位就劳动者反映的有关职业病防治的问题进行协调并督促解决。"},{"i":41,"n":"第四十一条","txt":"用人单位按照职业病防治要求，用于预防和治理职业病危害、工作场所卫生检测、健康监护和职业卫生培训等费用，按照国家有关规定，在生产成本中据实列支。"},{"i":42,"n":"第四十二条","txt":"职业卫生监督管理部门应当按照职责分工，加强对用人单位落实职业病防护管理措施情况的监督检查，依法行使职权，承担责任。"},{"i":43,"n":"第四十三条","txt":"职业病诊断应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业病诊断工作的规范管理，具体管理办法由国务院卫生行政部门制定。"},{"i":44,"n":"第四十四条","txt":"劳动者可以在用人单位所在地、本人户籍所在地或者经常居住地依法承担职业病诊断的医疗卫生机构进行职业病诊断。"},{"i":45,"n":"第四十五条","txt":"职业病诊断标准和职业病诊断、鉴定办法由国务院卫生行政部门制定。职业病伤残等级的鉴定办法由国务院劳动保障行政部门会同国务院卫生行政部门制定。"},{"i":46,"n":"第四十六条","txt":"职业病诊断，应当综合分析下列因素："},{"i":47,"n":"第四十七条","txt":"用人单位应当如实提供职业病诊断、鉴定所需的劳动者职业史和职业病危害接触史、工作场所职业病危害因素检测结果等资料；卫生行政部门应当监督检查和督促用人单位提供上述资料；劳动者和有关机构也应当提供与职业病诊断、鉴定有关的资料。"},{"i":48,"n":"第四十八条","txt":"职业病诊断、鉴定过程中，用人单位不提供工作场所职业病危害因素检测结果等资料的，诊断、鉴定机构应当结合劳动者的临床表现、辅助检查结果和劳动者的职业史、职业病危害接触史，并参考劳动者的自述、卫生行政部门提供的日常监督检查信息等，作出职业病诊断、鉴定结论。"},{"i":49,"n":"第四十九条","txt":"职业病诊断、鉴定过程中，在确认劳动者职业史、职业病危害接触史时，当事人对劳动关系、工种、工作岗位或者在岗时间有争议的，可以向当地的劳动人事争议仲裁委员会申请仲裁；接到申请的劳动人事争议仲裁委员会应当受理，并在三十日内作出裁决。"},{"i":50,"n":"第五十条","txt":"用人单位和医疗卫生机构发现职业病病人或者疑似职业病病人时，应当及时向所在地卫生行政部门报告。确诊为职业病的，用人单位还应当向所在地劳动保障行政部门报告。接到报告的部门应当依法作出处理。"},{"i":51,"n":"第五十一条","txt":"县级以上地方人民政府卫生行政部门负责本行政区域内的职业病统计报告的管理工作，并按照规定上报。"},{"i":52,"n":"第五十二条","txt":"当事人对职业病诊断有异议的，可以向作出诊断的医疗卫生机构所在地地方人民政府卫生行政部门申请鉴定。"},{"i":53,"n":"第五十三条","txt":"职业病诊断鉴定委员会由相关专业的专家组成。"},{"i":54,"n":"第五十四条","txt":"职业病诊断鉴定委员会组成人员应当遵守职业道德，客观、公正地进行诊断鉴定，并承担相应的责任。职业病诊断鉴定委员会组成人员不得私下接触当事人，不得收受当事人的财物或者其他好处，与当事人有利害关系的，应当回避。"},{"i":55,"n":"第五十五条","txt":"医疗卫生机构发现疑似职业病病人时，应当告知劳动者本人并及时通知用人单位。"},{"i":56,"n":"第五十六条","txt":"用人单位应当保障职业病病人依法享受国家规定的职业病待遇。"},{"i":57,"n":"第五十七条","txt":"职业病病人的诊疗、康复费用，伤残以及丧失劳动能力的职业病病人的社会保障，按照国家有关工伤保险的规定执行。"},{"i":58,"n":"第五十八条","txt":"职业病病人除依法享有工伤保险外，依照有关民事法律，尚有获得赔偿的权利的，有权向用人单位提出赔偿要求。"},{"i":59,"n":"第五十九条","txt":"劳动者被诊断患有职业病，但用人单位没有依法参加工伤保险的，其医疗和生活保障由该用人单位承担。"},{"i":60,"n":"第六十条","txt":"职业病病人变动工作单位，其依法享有的待遇不变。"},{"i":61,"n":"第六十一条","txt":"用人单位已经不存在或者无法确认劳动关系的职业病病人，可以向地方人民政府医疗保障、民政部门申请医疗救助和生活等方面的救助。"},{"i":62,"n":"第六十二条","txt":"县级以上人民政府职业卫生监督管理部门依照职业病防治法律、法规、国家职业卫生标准和卫生要求，依据职责划分，对职业病防治工作进行监督检查。"},{"i":63,"n":"第六十三条","txt":"卫生行政部门履行监督检查职责时，有权采取下列措施："},{"i":64,"n":"第六十四条","txt":"发生职业病危害事故或者有证据证明危害状态可能导致职业病危害事故发生时，卫生行政部门可以采取下列临时控制措施："},{"i":65,"n":"第六十五条","txt":"职业卫生监督执法人员依法执行职务时，应当出示监督执法证件。"},{"i":66,"n":"第六十六条","txt":"职业卫生监督执法人员依法执行职务时，被检查单位应当接受检查并予以支持配合，不得拒绝和阻碍。"},{"i":67,"n":"第六十七条","txt":"卫生行政部门及其职业卫生监督执法人员履行职责时，不得有下列行为："},{"i":68,"n":"第六十八条","txt":"职业卫生监督执法人员应当依法经过资格认定。"},{"i":69,"n":"第六十九条","txt":"建设单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以上五十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令停建、关闭："},{"i":70,"n":"第七十条","txt":"违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以下的罚款："},{"i":71,"n":"第七十一条","txt":"用人单位违反本法规定，有下列行为之一的，由卫生行政部门责令限期改正，给予警告，可以并处五万元以上十万元以下的罚款："},{"i":72,"n":"第七十二条","txt":"用人单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正，逾期不改正的，处五万元以上二十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭："},{"i":73,"n":"第七十三条","txt":"向用人单位提供可能产生职业病危害的设备、材料，未按照规定提供中文说明书或者设置警示标识和中文警示说明的，由卫生行政部门责令限期改正，给予警告，并处五万元以上二十万元以下的罚款。"},{"i":74,"n":"第七十四条","txt":"用人单位和医疗卫生机构未按照规定报告职业病、疑似职业病的，由有关主管部门依据职责分工责令限期改正，给予警告，可以并处一万元以下的罚款；弄虚作假的，并处二万元以上五万元以下的罚款；对直接负责的主管人员和其他直接责任人员，可以依法给予降级或者撤职的处分。"},{"i":75,"n":"第七十五条","txt":"违反本法规定，有下列情形之一的，由卫生行政部门责令限期治理，并处五万元以上三十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭："},{"i":76,"n":"第七十六条","txt":"生产、经营或者进口国家明令禁止使用的可能产生职业病危害的设备或者材料的，依照有关法律、行政法规的规定给予处罚。"},{"i":77,"n":"第七十七条","txt":"用人单位违反本法规定，已经对劳动者生命健康造成严重损害的，由卫生行政部门责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭，并处十万元以上五十万元以下的罚款。"},{"i":78,"n":"第七十八条","txt":"用人单位违反本法规定，造成重大职业病危害事故或者其他严重后果，构成犯罪的，对直接负责的主管人员和其他直接责任人员，依法追究刑事责任。"},{"i":79,"n":"第七十九条","txt":"未取得职业卫生技术服务资质认可擅自从事职业卫生技术服务的，由卫生行政部门责令立即停止违法行为，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上五万元以下的罚款；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分。"},{"i":80,"n":"第八十条","txt":"从事职业卫生技术服务的机构和承担职业病诊断的医疗卫生机构违反本法规定，有下列行为之一的，由卫生行政部门责令立即停止违法行为，给予警告，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上二万元以下的罚款；情节严重的，由原认可或者登记机关取消其相应的资格；对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分；构成犯罪的，依法追究刑事责任："},{"i":81,"n":"第八十一条","txt":"职业病诊断鉴定委员会组成人员收受职业病诊断争议当事人的财物或者其他好处的，给予警告，没收收受的财物，可以并处三千元以上五万元以下的罚款，取消其担任职业病诊断鉴定委员会组成人员的资格，并从省、自治区、直辖市人民政府卫生行政部门设立的专家库中予以除名。"},{"i":82,"n":"第八十二条","txt":"卫生行政部门不按照规定报告职业病和职业病危害事故的，由上一级行政部门责令改正，通报批评，给予警告；虚报、瞒报的，对单位负责人、直接负责的主管人员和其他直接责任人员依法给予降级、撤职或者开除的处分。"},{"i":83,"n":"第八十三条","txt":"县级以上地方人民政府在职业病防治工作中未依照本法履行职责，本行政区域出现重大职业病危害事故、造成严重社会影响的，依法对直接负责的主管人员和其他直接责任人员给予记大过直至开除的处分。"},{"i":84,"n":"第八十四条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":85,"n":"第八十五条","txt":"本法下列用语的含义："},{"i":86,"n":"第八十六条","txt":"本法第二条规定的用人单位以外的单位，产生职业病危害的，其职业病防治活动可以参照本法执行。"},{"i":87,"n":"第八十七条","txt":"对医疗机构放射性职业病危害控制的监督管理，由卫生行政部门依照本法的规定实施。"},{"i":88,"n":"第八十八条","txt":"本法自2002年5月1日起施行。"}],"tuiyijunrenbaozhangfa":[{"i":1,"n":"第一条","txt":"为了加强退役军人保障工作，维护退役军人合法权益，让军人成为全社会尊崇的职业，根据宪法，制定本法。"},{"i":2,"n":"第二条","txt":"本法所称退役军人，是指从中国人民解放军依法退出现役的军官、军士和义务兵等人员。"},{"i":3,"n":"第三条","txt":"退役军人为国防和军队建设做出了重要贡献，是社会主义现代化建设的重要力量。"},{"i":4,"n":"第四条","txt":"退役军人保障工作坚持中国共产党的领导，坚持为经济社会发展服务、为国防和军队建设服务的方针，遵循以人为本、分类保障、服务优先、依法管理的原则。"},{"i":5,"n":"第五条","txt":"退役军人保障应当与经济发展相协调，与社会进步相适应。"},{"i":6,"n":"第六条","txt":"退役军人应当继续发扬人民军队优良传统，模范遵守宪法和法律法规，保守军事秘密，践行社会主义核心价值观，积极参加社会主义现代化建设。"},{"i":7,"n":"第七条","txt":"国务院退役军人工作主管部门负责全国的退役军人保障工作。县级以上地方人民政府退役军人工作主管部门负责本行政区域的退役军人保障工作。"},{"i":8,"n":"第八条","txt":"国家加强退役军人保障工作信息化建设，为退役军人建档立卡，实现有关部门之间信息共享，为提高退役军人保障能力提供支持。"},{"i":9,"n":"第九条","txt":"退役军人保障工作所需经费由中央和地方财政共同负担。退役安置、教育培训、抚恤优待资金主要由中央财政负担。"},{"i":10,"n":"第十条","txt":"国家鼓励和引导企业、社会组织、个人等社会力量依法通过捐赠、设立基金、志愿服务等方式为退役军人提供支持和帮助。"},{"i":11,"n":"第十一条","txt":"对在退役军人保障工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。"},{"i":12,"n":"第十二条","txt":"国务院退役军人工作主管部门、中央军事委员会政治工作部门、中央和国家有关机关应当制定全国退役军人的年度移交接收计划。"},{"i":13,"n":"第十三条","txt":"退役军人原所在部队应当将退役军人移交安置地人民政府退役军人工作主管部门，安置地人民政府退役军人工作主管部门负责接收退役军人。"},{"i":14,"n":"第十四条","txt":"退役军人应当在规定时间内，持军队出具的退役证明到安置地人民政府退役军人工作主管部门报到。"},{"i":15,"n":"第十五条","txt":"安置地人民政府退役军人工作主管部门在接收退役军人时，向退役军人发放退役军人优待证。"},{"i":16,"n":"第十六条","txt":"军人所在部队在军人退役时，应当及时将其人事档案移交安置地人民政府退役军人工作主管部门。"},{"i":17,"n":"第十七条","txt":"安置地人民政府公安机关应当按照国家有关规定，及时为退役军人办理户口登记，同级退役军人工作主管部门应当予以协助。"},{"i":18,"n":"第十八条","txt":"退役军人原所在部队应当按照有关法律法规规定，及时将退役军人及随军未就业配偶的养老、医疗等社会保险关系和相应资金，转入安置地社会保险经办机构。"},{"i":19,"n":"第十九条","txt":"退役军人移交接收过程中，发生与其服现役有关的问题，由原所在部队负责处理；发生与其安置有关的问题，由安置地人民政府负责处理；发生其他移交接收方面问题的，由安置地人民政府负责处理，原所在部队予以配合。"},{"i":20,"n":"第二十条","txt":"地方各级人民政府应当按照移交接收计划，做好退役军人安置工作，完成退役军人安置任务。"},{"i":21,"n":"第二十一条","txt":"对退役的军官，国家采取退休、转业、逐月领取退役金、复员等方式妥善安置。"},{"i":22,"n":"第二十二条","txt":"对退役的军士，国家采取逐月领取退役金、自主就业、安排工作、退休、供养等方式妥善安置。"},{"i":23,"n":"第二十三条","txt":"对退役的义务兵，国家采取自主就业、安排工作、供养等方式妥善安置。"},{"i":24,"n":"第二十四条","txt":"退休、转业、逐月领取退役金、复员、自主就业、安排工作、供养等安置方式的适用条件，按照相关法律法规执行。"},{"i":25,"n":"第二十五条","txt":"转业军官、安排工作的军士和义务兵，由机关、群团组织、事业单位和国有企业接收安置。对下列退役军人，优先安置："},{"i":26,"n":"第二十六条","txt":"机关、群团组织、事业单位接收安置转业军官、安排工作的军士和义务兵的，应当按照国家有关规定给予编制保障。"},{"i":27,"n":"第二十七条","txt":"以逐月领取退役金方式安置的退役军官和军士，被录用为公务员或者聘用为事业单位工作人员的，自被录用、聘用下月起停发退役金，其待遇按照公务员、事业单位工作人员管理相关法律法规执行。"},{"i":28,"n":"第二十八条","txt":"国家建立伤病残退役军人指令性移交安置、收治休养制度。军队有关部门应当及时将伤病残退役军人移交安置地人民政府安置。安置地人民政府应当妥善解决伤病残退役军人的住房、医疗、康复、护理和生活困难。"},{"i":29,"n":"第二十九条","txt":"各级人民政府加强拥军优属工作，为军人和家属排忧解难。"},{"i":30,"n":"第三十条","txt":"军人退役安置的具体办法由国务院、中央军事委员会制定。"},{"i":31,"n":"第三十一条","txt":"退役军人的教育培训应当以提高就业质量为导向，紧密围绕社会需求，为退役军人提供有特色、精细化、针对性强的培训服务。"},{"i":32,"n":"第三十二条","txt":"国家建立学历教育和职业技能培训并行并举的退役军人教育培训体系，建立退役军人教育培训协调机制，统筹规划退役军人教育培训工作。"},{"i":33,"n":"第三十三条","txt":"军人退役前，所在部队在保证完成军事任务的前提下，可以根据部队特点和条件提供职业技能储备培训，组织参加高等教育自学考试和各类高等学校举办的高等学历继续教育，以及知识拓展、技能培训等非学历继续教育。"},{"i":34,"n":"第三十四条","txt":"退役军人在接受学历教育时，按照国家有关规定享受学费和助学金资助等国家教育资助政策。"},{"i":35,"n":"第三十五条","txt":"现役军人入伍前已被普通高等学校录取或者是正在普通高等学校就学的学生，服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学，可以按照国家有关规定转入本校其他专业学习。达到报考研究生条件的，按照国家有关规定享受优惠政策。"},{"i":36,"n":"第三十六条","txt":"国家依托和支持普通高等学校、职业院校（含技工院校）、专业培训机构等教育资源，为退役军人提供职业技能培训。退役军人未达到法定退休年龄需要就业创业的，可以享受职业技能培训补贴等相应扶持政策。"},{"i":37,"n":"第三十七条","txt":"省级人民政府退役军人工作主管部门会同有关部门加强动态管理，定期对为退役军人提供职业技能培训的普通高等学校、职业院校（含技工院校）、专业培训机构的培训质量进行检查和考核，提高职业技能培训质量和水平。"},{"i":38,"n":"第三十八条","txt":"国家采取政府推动、市场引导、社会支持相结合的方式，鼓励和扶持退役军人就业创业。"},{"i":39,"n":"第三十九条","txt":"各级人民政府应当加强对退役军人就业创业的指导和服务。"},{"i":40,"n":"第四十条","txt":"服现役期间因战、因公、因病致残被评定残疾等级和退役后补评或者重新评定残疾等级的残疾退役军人，有劳动能力和就业意愿的，优先享受国家规定的残疾人就业优惠政策。"},{"i":41,"n":"第四十一条","txt":"公共人力资源服务机构应当免费为退役军人提供职业介绍、创业指导等服务。"},{"i":42,"n":"第四十二条","txt":"机关、群团组织、事业单位和国有企业在招录或者招聘人员时，对退役军人的年龄和学历条件可以适当放宽，同等条件下优先招录、招聘退役军人。退役的军士和义务兵服现役经历视为基层工作经历。"},{"i":43,"n":"第四十三条","txt":"各地应当设置一定数量的基层公务员职位，面向服现役满五年的高校毕业生退役军人招考。"},{"i":44,"n":"第四十四条","txt":"退役军人服现役年限计算为工龄，退役后与所在单位工作年限累计计算。"},{"i":45,"n":"第四十五条","txt":"县级以上地方人民政府投资建设或者与社会共建的创业孵化基地和创业园区，应当优先为退役军人创业提供服务。有条件的地区可以建立退役军人创业孵化基地和创业园区，为退役军人提供经营场地、投资融资等方面的优惠服务。"},{"i":46,"n":"第四十六条","txt":"退役军人创办小微企业，可以按照国家有关规定申请创业担保贷款，并享受贷款贴息等融资优惠政策。"},{"i":47,"n":"第四十七条","txt":"用人单位招用退役军人符合国家规定的，依法享受税收优惠等政策。"},{"i":48,"n":"第四十八条","txt":"各级人民政府应当坚持普惠与优待叠加的原则，在保障退役军人享受普惠性政策和公共服务基础上，结合服现役期间所做贡献和各地实际情况给予优待。"},{"i":49,"n":"第四十九条","txt":"国家逐步消除退役军人抚恤优待制度城乡差异、缩小地区差异，建立统筹平衡的抚恤优待量化标准体系。"},{"i":50,"n":"第五十条","txt":"退役军人依法参加养老、医疗、工伤、失业、生育等社会保险，并享受相应待遇。"},{"i":51,"n":"第五十一条","txt":"退役军人符合安置住房优待条件的，实行市场购买与军地集中统建相结合，由安置地人民政府统筹规划、科学实施。"},{"i":52,"n":"第五十二条","txt":"军队医疗机构、公立医疗机构应当为退役军人就医提供优待服务，并对参战退役军人、残疾退役军人给予优惠。"},{"i":53,"n":"第五十三条","txt":"退役军人凭退役军人优待证等有效证件享受公共交通、文化和旅游等优待，具体办法由省级人民政府制定。"},{"i":54,"n":"第五十四条","txt":"县级以上人民政府加强优抚医院、光荣院建设，充分利用现有医疗和养老服务资源，收治或者集中供养孤老、生活不能自理的退役军人。"},{"i":55,"n":"第五十五条","txt":"国家建立退役军人帮扶援助机制，在养老、医疗、住房等方面，对生活困难的退役军人按照国家有关规定给予帮扶援助。"},{"i":56,"n":"第五十六条","txt":"残疾退役军人依法享受抚恤。"},{"i":57,"n":"第五十七条","txt":"国家建立退役军人荣誉激励机制，对在社会主义现代化建设中做出突出贡献的退役军人予以表彰、奖励。退役军人服现役期间获得表彰、奖励的，退役后按照国家有关规定享受相应待遇。"},{"i":58,"n":"第五十八条","txt":"退役军人安置地人民政府在接收退役军人时，应当举行迎接仪式。迎接仪式由安置地人民政府退役军人工作主管部门负责实施。"},{"i":59,"n":"第五十九条","txt":"地方人民政府应当为退役军人家庭悬挂光荣牌，定期开展走访慰问活动。"},{"i":60,"n":"第六十条","txt":"国家、地方和军队举行重大庆典活动时，应当邀请退役军人代表参加。"},{"i":61,"n":"第六十一条","txt":"国家注重发挥退役军人在爱国主义教育和国防教育活动中的积极作用。机关、群团组织、企业事业单位和社会组织可以邀请退役军人协助开展爱国主义教育和国防教育。县级以上人民政府教育行政部门可以邀请退役军人参加学校国防教育培训，学校可以聘请退役军人参与学生军事训练。"},{"i":62,"n":"第六十二条","txt":"县级以上人民政府退役军人工作主管部门应当加强对退役军人先进事迹的宣传，通过制作公益广告、创作主题文艺作品等方式，弘扬爱国主义精神、革命英雄主义精神和退役军人敬业奉献精神。"},{"i":63,"n":"第六十三条","txt":"县级以上地方人民政府负责地方志工作的机构应当将本行政区域内下列退役军人的名录和事迹，编辑录入地方志："},{"i":64,"n":"第六十四条","txt":"国家统筹规划烈士纪念设施建设，通过组织开展英雄烈士祭扫纪念活动等多种形式，弘扬英雄烈士精神。退役军人工作主管部门负责烈士纪念设施的修缮、保护和管理。"},{"i":65,"n":"第六十五条","txt":"国家加强退役军人服务机构建设，建立健全退役军人服务体系。县级以上人民政府设立退役军人服务中心，乡镇、街道、农村和城市社区设立退役军人服务站点，提升退役军人服务保障能力。"},{"i":66,"n":"第六十六条","txt":"退役军人服务中心、服务站点等退役军人服务机构应当加强与退役军人联系沟通，做好退役军人就业创业扶持、优抚帮扶、走访慰问、权益维护等服务保障工作。"},{"i":67,"n":"第六十七条","txt":"县级以上人民政府退役军人工作主管部门应当加强退役军人思想政治教育工作，及时掌握退役军人的思想情况和工作生活状况，指导接收安置单位和其他组织做好退役军人的思想政治工作和有关保障工作。"},{"i":68,"n":"第六十八条","txt":"县级以上人民政府退役军人工作主管部门、接收安置单位和其他组织应当加强对退役军人的保密教育和管理。"},{"i":69,"n":"第六十九条","txt":"县级以上人民政府退役军人工作主管部门应当通过广播、电视、报刊、网络等多种渠道宣传与退役军人相关的法律法规和政策制度。"},{"i":70,"n":"第七十条","txt":"县级以上人民政府退役军人工作主管部门应当建立健全退役军人权益保障机制，畅通诉求表达渠道，为退役军人维护其合法权益提供支持和帮助。退役军人的合法权益受到侵害，应当依法解决。公共法律服务有关机构应当依法为退役军人提供法律援助等必要的帮助。"},{"i":71,"n":"第七十一条","txt":"县级以上人民政府退役军人工作主管部门应当依法指导、督促有关部门和单位做好退役安置、教育培训、就业创业、抚恤优待、褒扬激励、拥军优属等工作，监督检查退役军人保障相关法律法规和政策措施落实情况，推进解决退役军人保障工作中存在的问题。"},{"i":72,"n":"第七十二条","txt":"国家实行退役军人保障工作责任制和考核评价制度。县级以上人民政府应当将退役军人保障工作完成情况，纳入对本级人民政府负责退役军人有关工作的部门及其负责人、下级人民政府及其负责人的考核评价内容。"},{"i":73,"n":"第七十三条","txt":"退役军人工作主管部门及其工作人员履行职责，应当自觉接受社会监督。"},{"i":74,"n":"第七十四条","txt":"对退役军人保障工作中违反本法行为的检举、控告，有关机关和部门应当依法及时处理，并将处理结果告知检举人、控告人。"},{"i":75,"n":"第七十五条","txt":"退役军人工作主管部门及其工作人员有下列行为之一的，由其上级主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分："},{"i":76,"n":"第七十六条","txt":"其他负责退役军人有关工作的部门及其工作人员违反本法有关规定的，由其上级主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":77,"n":"第七十七条","txt":"违反本法规定，拒绝或者无故拖延执行退役军人安置任务的，由安置地人民政府退役军人工作主管部门责令限期改正；逾期不改正的，予以通报批评。对该单位主要负责人和直接责任人员，由有关部门依法给予处分。"},{"i":78,"n":"第七十八条","txt":"退役军人弄虚作假骗取退役相关待遇的，由县级以上地方人民政府退役军人工作主管部门取消相关待遇，追缴非法所得，并由其所在单位或者有关部门依法给予处分。"},{"i":79,"n":"第七十九条","txt":"退役军人违法犯罪的，由省级人民政府退役军人工作主管部门按照国家有关规定中止、降低或者取消其退役相关待遇，报国务院退役军人工作主管部门备案。"},{"i":80,"n":"第八十条","txt":"违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":81,"n":"第八十一条","txt":"中国人民武装警察部队依法退出现役的警官、警士和义务兵等人员，适用本法。"},{"i":82,"n":"第八十二条","txt":"本法有关军官的规定适用于文职干部。"},{"i":83,"n":"第八十三条","txt":"参试退役军人参照本法有关参战退役军人的规定执行。"},{"i":84,"n":"第八十四条","txt":"军官离职休养和军级以上职务军官退休后，按照国务院和中央军事委员会的有关规定安置管理。"},{"i":85,"n":"第八十五条","txt":"本法自2021年1月1日起施行。"}],"yufangweichengnianrenfanzuifa":[{"i":1,"n":"第一条","txt":"为了保障未成年人身心健康，培养未成年人良好品行，有效预防未成年人违法犯罪，制定本法。"},{"i":2,"n":"第二条","txt":"预防未成年人犯罪，立足于教育和保护未成年人相结合，坚持预防为主、提前干预，对未成年人的不良行为和严重不良行为及时进行分级预防、干预和矫治。"},{"i":3,"n":"第三条","txt":"开展预防未成年人犯罪工作，应当尊重未成年人人格尊严，保护未成年人的名誉权、隐私权和个人信息等合法权益。"},{"i":4,"n":"第四条","txt":"预防未成年人犯罪，在各级人民政府组织下，实行综合治理。"},{"i":5,"n":"第五条","txt":"各级人民政府在预防未成年人犯罪方面的工作职责是："},{"i":6,"n":"第六条","txt":"国家加强专门学校建设，对有严重不良行为的未成年人进行专门教育。专门教育是国民教育体系的组成部分，是对有严重不良行为的未成年人进行教育和矫治的重要保护处分措施。"},{"i":7,"n":"第七条","txt":"公安机关、人民检察院、人民法院、司法行政部门应当由专门机构或者经过专业培训、熟悉未成年人身心特点的专门人员负责预防未成年人犯罪工作。"},{"i":8,"n":"第八条","txt":"共产主义青年团、妇女联合会、工会、残疾人联合会、关心下一代工作委员会、青年联合会、学生联合会、少年先锋队以及有关社会组织，应当协助各级人民政府及其有关部门、人民检察院和人民法院做好预防未成年人犯罪工作，为预防未成年人犯罪培育社会力量，提供支持服务。"},{"i":9,"n":"第九条","txt":"国家鼓励、支持和指导社会工作服务机构等社会组织参与预防未成年人犯罪相关工作，并加强监督。"},{"i":10,"n":"第十条","txt":"任何组织或者个人不得教唆、胁迫、引诱未成年人实施不良行为或者严重不良行为，以及为未成年人实施上述行为提供条件。"},{"i":11,"n":"第十一条","txt":"未成年人应当遵守法律法规及社会公共道德规范，树立自尊、自律、自强意识，增强辨别是非和自我保护的能力，自觉抵制各种不良行为以及违法犯罪行为的引诱和侵害。"},{"i":12,"n":"第十二条","txt":"预防未成年人犯罪，应当结合未成年人不同年龄的生理、心理特点，加强青春期教育、心理关爱、心理矫治和预防犯罪对策的研究。"},{"i":13,"n":"第十三条","txt":"国家鼓励和支持预防未成年人犯罪相关学科建设、专业设置、人才培养及科学研究，开展国际交流与合作。"},{"i":14,"n":"第十四条","txt":"国家对预防未成年人犯罪工作有显著成绩的组织和个人，给予表彰和奖励。"},{"i":15,"n":"第十五条","txt":"国家、社会、学校和家庭应当对未成年人加强社会主义核心价值观教育，开展预防犯罪教育，增强未成年人的法治观念，使未成年人树立遵纪守法和防范违法犯罪的意识，提高自我管控能力。"},{"i":16,"n":"第十六条","txt":"未成年人的父母或者其他监护人对未成年人的预防犯罪教育负有直接责任，应当依法履行监护职责，树立优良家风，培养未成年人良好品行；发现未成年人心理或者行为异常的，应当及时了解情况并进行教育、引导和劝诫，不得拒绝或者怠于履行监护职责。"},{"i":17,"n":"第十七条","txt":"教育行政部门、学校应当将预防犯罪教育纳入学校教学计划，指导教职员工结合未成年人的特点，采取多种方式对未成年学生进行有针对性的预防犯罪教育。"},{"i":18,"n":"第十八条","txt":"学校应当聘任从事法治教育的专职或者兼职教师，并可以从司法和执法机关、法学教育和法律服务机构等单位聘请法治副校长、校外法治辅导员。"},{"i":19,"n":"第十九条","txt":"学校应当配备专职或者兼职的心理健康教育教师，开展心理健康教育。学校可以根据实际情况与专业心理健康机构合作，建立心理健康筛查和早期干预机制，预防和解决学生心理、行为异常问题。"},{"i":20,"n":"第二十条","txt":"教育行政部门应当会同有关部门建立学生欺凌防控制度。学校应当加强日常安全管理，完善学生欺凌发现和处置的工作流程，严格排查并及时消除可能导致学生欺凌行为的各种隐患。"},{"i":21,"n":"第二十一条","txt":"教育行政部门鼓励和支持学校聘请社会工作者长期或者定期进驻学校，协助开展道德教育、法治教育、生命教育和心理健康教育，参与预防和处理学生欺凌等行为。"},{"i":22,"n":"第二十二条","txt":"教育行政部门、学校应当通过举办讲座、座谈、培训等活动，介绍科学合理的教育方法，指导教职员工、未成年学生的父母或者其他监护人有效预防未成年人犯罪。"},{"i":23,"n":"第二十三条","txt":"教育行政部门应当将预防犯罪教育的工作效果纳入学校年度考核内容。"},{"i":24,"n":"第二十四条","txt":"各级人民政府及其有关部门、人民检察院、人民法院、共产主义青年团、少年先锋队、妇女联合会、残疾人联合会、关心下一代工作委员会等应当结合实际，组织、举办多种形式的预防未成年人犯罪宣传教育活动。有条件的地方可以建立青少年法治教育基地，对未成年人开展法治教育。"},{"i":25,"n":"第二十五条","txt":"居民委员会、村民委员会应当积极开展有针对性的预防未成年人犯罪宣传活动，协助公安机关维护学校周围治安，及时掌握本辖区内未成年人的监护、就学和就业情况，组织、引导社区社会组织参与预防未成年人犯罪工作。"},{"i":26,"n":"第二十六条","txt":"青少年宫、儿童活动中心等校外活动场所应当把预防犯罪教育作为一项重要的工作内容，开展多种形式的宣传教育活动。"},{"i":27,"n":"第二十七条","txt":"职业培训机构、用人单位在对已满十六周岁准备就业的未成年人进行职业培训时，应当将预防犯罪教育纳入培训内容。"},{"i":28,"n":"第二十八条","txt":"本法所称不良行为，是指未成年人实施的不利于其健康成长的下列行为："},{"i":29,"n":"第二十九条","txt":"未成年人的父母或者其他监护人发现未成年人有不良行为的，应当及时制止并加强管教。"},{"i":30,"n":"第三十条","txt":"公安机关、居民委员会、村民委员会发现本辖区内未成年人有不良行为的，应当及时制止，并督促其父母或者其他监护人依法履行监护职责。"},{"i":31,"n":"第三十一条","txt":"学校对有不良行为的未成年学生，应当加强管理教育，不得歧视；对拒不改正或者情节严重的，学校可以根据情况予以处分或者采取以下管理教育措施："},{"i":32,"n":"第三十二条","txt":"学校和家庭应当加强沟通，建立家校合作机制。学校决定对未成年学生采取管理教育措施的，应当及时告知其父母或者其他监护人；未成年学生的父母或者其他监护人应当支持、配合学校进行管理教育。"},{"i":33,"n":"第三十三条","txt":"未成年学生偷窃少量财物，或者有殴打、辱骂、恐吓、强行索要财物等学生欺凌行为，情节轻微的，可以由学校依照本法第三十一条规定采取相应的管理教育措施。"},{"i":34,"n":"第三十四条","txt":"未成年学生旷课、逃学的，学校应当及时联系其父母或者其他监护人，了解有关情况；无正当理由的，学校和未成年学生的父母或者其他监护人应当督促其返校学习。"},{"i":35,"n":"第三十五条","txt":"未成年人无故夜不归宿、离家出走的，父母或者其他监护人、所在的寄宿制学校应当及时查找，必要时向公安机关报告。"},{"i":36,"n":"第三十六条","txt":"对夜不归宿、离家出走或者流落街头的未成年人，公安机关、公共场所管理机构等发现或者接到报告后，应当及时采取有效保护措施，并通知其父母或者其他监护人、所在的寄宿制学校，必要时应当护送其返回住所、学校；无法与其父母或者其他监护人、学校取得联系的，应当护送未成年人到救助保护机构接受救助。"},{"i":37,"n":"第三十七条","txt":"未成年人的父母或者其他监护人、学校发现未成年人组织或者参加实施不良行为的团伙，应当及时制止；发现该团伙有违法犯罪嫌疑的，应当立即向公安机关报告。"},{"i":38,"n":"第三十八条","txt":"本法所称严重不良行为，是指未成年人实施的有刑法规定、因不满法定刑事责任年龄不予刑事处罚的行为，以及严重危害社会的下列行为："},{"i":39,"n":"第三十九条","txt":"未成年人的父母或者其他监护人、学校、居民委员会、村民委员会发现有人教唆、胁迫、引诱未成年人实施严重不良行为的，应当立即向公安机关报告。公安机关接到报告或者发现有上述情形的，应当及时依法查处；对人身安全受到威胁的未成年人，应当立即采取有效保护措施。"},{"i":40,"n":"第四十条","txt":"公安机关接到举报或者发现未成年人有严重不良行为的，应当及时制止，依法调查处理，并可以责令其父母或者其他监护人消除或者减轻违法后果，采取措施严加管教。"},{"i":41,"n":"第四十一条","txt":"对有严重不良行为的未成年人，公安机关可以根据具体情况，采取以下矫治教育措施："},{"i":42,"n":"第四十二条","txt":"公安机关在对未成年人进行矫治教育时，可以根据需要邀请学校、居民委员会、村民委员会以及社会工作服务机构等社会组织参与。"},{"i":43,"n":"第四十三条","txt":"对有严重不良行为的未成年人，未成年人的父母或者其他监护人、所在学校无力管教或者管教无效的，可以向教育行政部门提出申请，经专门教育指导委员会评估同意后，由教育行政部门决定送入专门学校接受专门教育。"},{"i":44,"n":"第四十四条","txt":"未成年人有下列情形之一的，经专门教育指导委员会评估同意，教育行政部门会同公安机关可以决定将其送入专门学校接受专门教育："},{"i":45,"n":"第四十五条","txt":"未成年人实施刑法规定的行为、因不满法定刑事责任年龄不予刑事处罚的，经专门教育指导委员会评估同意，教育行政部门会同公安机关可以决定对其进行专门矫治教育。"},{"i":46,"n":"第四十六条","txt":"专门学校应当在每个学期适时提请专门教育指导委员会对接受专门教育的未成年学生的情况进行评估。对经评估适合转回普通学校就读的，专门教育指导委员会应当向原决定机关提出书面建议，由原决定机关决定是否将未成年学生转回普通学校就读。"},{"i":47,"n":"第四十七条","txt":"专门学校应当对接受专门教育的未成年人分级分类进行教育和矫治，有针对性地开展道德教育、法治教育、心理健康教育，并根据实际情况进行职业教育；对没有完成义务教育的未成年人，应当保证其继续接受义务教育。"},{"i":48,"n":"第四十八条","txt":"专门学校应当与接受专门教育的未成年人的父母或者其他监护人加强联系，定期向其反馈未成年人的矫治和教育情况，为父母或者其他监护人、亲属等看望未成年人提供便利。"},{"i":49,"n":"第四十九条","txt":"未成年人及其父母或者其他监护人对本章规定的行政决定不服的，可以依法提起行政复议或者行政诉讼。"},{"i":50,"n":"第五十条","txt":"公安机关、人民检察院、人民法院办理未成年人刑事案件，应当根据未成年人的生理、心理特点和犯罪的情况，有针对性地进行法治教育。"},{"i":51,"n":"第五十一条","txt":"公安机关、人民检察院、人民法院办理未成年人刑事案件，可以自行或者委托有关社会组织、机构对未成年犯罪嫌疑人或者被告人的成长经历、犯罪原因、监护、教育等情况进行社会调查；根据实际需要并经未成年犯罪嫌疑人、被告人及其法定代理人同意，可以对未成年犯罪嫌疑人、被告人进行心理测评。"},{"i":52,"n":"第五十二条","txt":"公安机关、人民检察院、人民法院对于无固定住所、无法提供保证人的未成年人适用取保候审的，应当指定合适成年人作为保证人，必要时可以安排取保候审的未成年人接受社会观护。"},{"i":53,"n":"第五十三条","txt":"对被拘留、逮捕以及在未成年犯管教所执行刑罚的未成年人，应当与成年人分别关押、管理和教育。对未成年人的社区矫正，应当与成年人分别进行。"},{"i":54,"n":"第五十四条","txt":"未成年犯管教所、社区矫正机构应当对未成年犯、未成年社区矫正对象加强法治教育，并根据实际情况对其进行职业教育。"},{"i":55,"n":"第五十五条","txt":"社区矫正机构应当告知未成年社区矫正对象安置帮教的有关规定，并配合安置帮教工作部门落实或者解决未成年社区矫正对象的就学、就业等问题。"},{"i":56,"n":"第五十六条","txt":"对刑满释放的未成年人，未成年犯管教所应当提前通知其父母或者其他监护人按时接回，并协助落实安置帮教措施。没有父母或者其他监护人、无法查明其父母或者其他监护人的，未成年犯管教所应当提前通知未成年人原户籍所在地或者居住地的司法行政部门安排人员按时接回，由民政部门或者居民委员会、村民委员会依法对其进行监护。"},{"i":57,"n":"第五十七条","txt":"未成年人的父母或者其他监护人和学校、居民委员会、村民委员会对接受社区矫正、刑满释放的未成年人，应当采取有效的帮教措施，协助司法机关以及有关部门做好安置帮教工作。"},{"i":58,"n":"第五十八条","txt":"刑满释放和接受社区矫正的未成年人，在复学、升学、就业等方面依法享有与其他未成年人同等的权利，任何单位和个人不得歧视。"},{"i":59,"n":"第五十九条","txt":"未成年人的犯罪记录依法被封存的，公安机关、人民检察院、人民法院和司法行政部门不得向任何单位或者个人提供，但司法机关因办案需要或者有关单位根据国家有关规定进行查询的除外。依法进行查询的单位和个人应当对相关记录信息予以保密。"},{"i":60,"n":"第六十条","txt":"人民检察院通过依法行使检察权，对未成年人重新犯罪预防工作等进行监督。"},{"i":61,"n":"第六十一条","txt":"公安机关、人民检察院、人民法院在办理案件过程中发现实施严重不良行为的未成年人的父母或者其他监护人不依法履行监护职责的，应当予以训诫，并可以责令其接受家庭教育指导。"},{"i":62,"n":"第六十二条","txt":"学校及其教职员工违反本法规定，不履行预防未成年人犯罪工作职责，或者虐待、歧视相关未成年人的，由教育行政等部门责令改正，通报批评；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。构成违反治安管理行为的，由公安机关依法予以治安管理处罚。"},{"i":63,"n":"第六十三条","txt":"违反本法规定，在复学、升学、就业等方面歧视相关未成年人的，由所在单位或者教育、人力资源社会保障等部门责令改正；拒不改正的，对直接负责的主管人员或者其他直接责任人员依法给予处分。"},{"i":64,"n":"第六十四条","txt":"有关社会组织、机构及其工作人员虐待、歧视接受社会观护的未成年人，或者出具虚假社会调查、心理测评报告的，由民政、司法行政等部门对直接负责的主管人员或者其他直接责任人员依法给予处分，构成违反治安管理行为的，由公安机关予以治安管理处罚。"},{"i":65,"n":"第六十五条","txt":"教唆、胁迫、引诱未成年人实施不良行为或者严重不良行为，构成违反治安管理行为的，由公安机关依法予以治安管理处罚。"},{"i":66,"n":"第六十六条","txt":"国家机关及其工作人员在预防未成年人犯罪工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":67,"n":"第六十七条","txt":"违反本法规定，构成犯罪的，依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"本法自2021年6月1日起施行。"}],"quanguorenmindaibiaodahuichangwuweiyuanhuiguanyupif83b86":[],"diwujiequanguorenmindaibiaodahuichangwuweiyuanhuigb04d6c":[]};
